A.bYM=new B.dh("\ub450 \uc9c1\uc7a5 \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \ube44\uad50\ud574 \ubcf4\uc138\uc694.","A\ud68c\uc0ac\ub294 \uae09\uc5ec\uac00 \ub192\uc740 \ubc18\uba74\uc5d0 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc774 \uae38\uace0 \uc57c\uadfc\ub3c4 \ub9ce\uc740 \ud3b8\uc785\ub2c8\ub2e4. B\ud68c\uc0ac\ub294 \uae09\uc5ec\ub294 \uc870\uae08 \ub0ae\uc9c0\ub9cc \uc9d1\uc5d0\uc11c \uac00\uae5d\uace0 \uc81c\uac00 \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc5c5\ubb34\ub97c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ub294 \uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc778 \ubc1c\uc804 \uac00\ub2a5\uc131\uacfc \uc0dd\ud65c \uc2dc\uac04\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud604\uc7ac \uc870\uac74\uc774\ub77c\uba74 B\ud68c\uc0ac\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc800\uc5d0\uac8c \ub354 \uc801\ud569\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.nq8=s(["\uc774\ud574\ud558\ub2e4","\ub2e4\ub978 \uc758\uacac","\uc774\uc720","\ubb38\uc81c\uc810","\ub300\uc548"],t.s)
A.bYI=new B.dh("\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc758\uacac\uc5d0 \ubc18\ub300\ud560 \ub54c \ubd80\ub4dc\ub7fd\uac8c \ub9d0\ud574 \ubcf4\uc138\uc694.","\ub9d0\uc500\ud558\uc2e0 \ubc29\ubc95\uc758 \uc7a5\uc810\uc740 \uc774\ud574\ud569\ub2c8\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \uc778\uc6d0\uc73c\ub85c \ubaa8\ub4e0 \uc791\uc5c5\uc744 \ub3d9\uc2dc\uc5d0 \uc9c4\ud589\ud558\ub294 \uac83\uc740 \uc870\uae08 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc791\uc5c5\ub7c9\uc774 \ub9ce\uc544\uc9c0\uba74 \uc2e4\uc218\uac00 \ub298\uc5b4\ub0a0 \uac00\ub2a5\uc131\ub3c4 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \uba3c\uc800 \uc911\uc694\ud55c \uc791\uc5c5\ubd80\ud130 \ucc98\ub9ac\ud558\uace0 \ub098\uba38\uc9c0\ub294 \ub2e4\uc74c \ub2e8\uacc4\ub85c \uc9c4\ud589\ud558\ub294 \ubc29\ubc95\uc744 \ub300\uc548\uc73c\ub85c \uac80\ud1a0\ud558\uba74 \uc5b4\ub5a8\uae4c\uc694?")
A.jTf=s([A.bZ4,A.bYM,A.bYI],t.Pe)
A.nsu=s(["\uc790\uc2e0\uc758 \uc120\ud0dd \uae30\uc900\uc744 \uc4f0\uc138\uc694.","\uae09\uc5ec\uc5d0 \ub300\ud55c \uc0dd\uac01\uc744 \uc4f0\uc138\uc694.","\uadfc\ubb34 \ud658\uacbd\uc774\ub098 \uc2dc\uac04\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubc1c\uc804 \uac00\ub2a5\uc131\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","N\uc5d0 \ube44\ud574\uc11c\uc640 V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7d=new B.ei("\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uc911\uc694\ud55c \uae30\uc900\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc800\ub294 \uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uae09\uc5ec\ub9cc \ubcf4\ub294 \uac83\uc740 \uc88b\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uae09\uc5ec\ub3c4 \uc911\uc694\ud55c \uc870\uac74\uc774\uc9c0\ub9cc \uadfc\ubb34 \uc2dc\uac04, \ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc5c5\ubb34 \ub0b4\uc6a9\uacfc \ubc1c\uc804 \uac00\ub2a5\uc131\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ud68c\uc0ac\ub294 \ub2e4\ub978 \ud68c\uc0ac\uc5d0 \ube44\ud574\uc11c \uae09\uc5ec\uac00 \ub192\uc9c0\ub9cc \uc57c\uadfc\uc774 \ub9ce\uac70\ub098 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc774 \uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uae09\uc5ec\ub294 \uc870\uae08 \ub0ae\ub354\ub77c\ub3c4 \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc77c\uc744 \ud560 \uc218 \uc788\uace0 \uc0dd\ud65c \uc2dc\uac04\uc744 \ud655\ubcf4\ud560 \uc218 \uc788\ub294 \ud68c\uc0ac\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ub294 \ud604\uc7ac \uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc73c\ub85c \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \uc313\uc744 \uc218 \uc788\ub294\uc9c0\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.","T\xf4i ngh\u0129 khi ch\u1ecdn c\xf4ng vi\u1ec7c kh\xf4ng n\xean ch\u1ec9 nh\xecn v\xe0o l\u01b0\u01a1ng. T\u1ea5t nhi\xean l\u01b0\u01a1ng c\u0169ng l\xe0 \u0111i\u1ec1u ki\u1ec7n quan tr\u1ecdng, nh\u01b0ng c\u1ea7n c\xe2n nh\u1eafc c\u1ea3 gi\u1edd l\xe0m, kho\u1ea3ng c\xe1ch \u0111i l\xe0m, n\u1ed9i dung c\xf4ng vi\u1ec7c v\xe0 kh\u1ea3 n\u0103ng ph\xe1t tri\u1ec3n. C\xf3 c\xf4ng ty l\u01b0\u01a1ng cao h\u01a1n c\xf4ng ty kh\xe1c nh\u01b0ng c\xf3 th\u1ec3 t\u0103ng ca nhi\u1ec1u ho\u1eb7c th\u1eddi gian \u0111i l\u1ea1i d\xe0i. Ng\u01b0\u1ee3c l\u1ea1i c\u0169ng c\xf3 c\xf4ng ty l\u01b0\u01a1ng h\u01a1i th\u1ea5p nh\u01b0ng c\xf3 th\u1ec3 l\xe0m c\xf4ng vi\u1ec7c m\xecnh mu\u1ed1n h\u1ecdc v\xe0 c\xf3 th\u1eddi gian cho cu\u1ed9c s\u1ed1ng. Hi\u1ec7n t\u1ea1i t\xf4i coi tr\u1ecdng kh\xf4ng ch\u1ec9 l\u01b0\u01a1ng m\xe0 c\xf2n c\u1ea3 lo\u1ea1i kinh nghi\u1ec7m m\xecnh c\xf3 th\u1ec3 t\xedch l\u0169y trong th\u1eddi gian d\xe0i.")
A.nrz=s(["A\uc548\uacfc B\uc548\uc744 \uc18c\uac1c\ud558\uc138\uc694.","\uac01 \ubc29\ubc95\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uc4f0\uc138\uc694.","\uc790\uc2e0\uc758 \uc120\ud0dd \uae30\uc900\uc744 \uc4f0\uc138\uc694.","\uc5b4\ub290 \ubc29\ubc95\uc744 \uc120\ud0dd\ud560\uc9c0 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\uc640 V-\ub294 \uac83\uc774 \ub0ab\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7n=new B.ei("\ub450 \uac00\uc9c0 \ubc29\ubc95\uc744 \ube44\uad50\ud558\uace0 \uc790\uc2e0\uc758 \uc758\uacac\uc744 \uc368 \ubcf4\uc138\uc694.","\ud68c\uc0ac\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc7a5\ube44\ub97c \uad6c\uc785\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uba74 \ub450 \uac00\uc9c0 \uc120\ud0dd\uc774 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. A\uc81c\ud488\uc740 \uac00\uaca9\uc774 \uc800\ub834\ud55c \ubc18\uba74\uc5d0 \uae30\ub2a5\uc774 \uc801\uace0 \uc720\uc9c0 \uad00\ub9ac\uac00 \uc790\uc8fc \ud544\uc694\ud569\ub2c8\ub2e4. B\uc81c\ud488\uc740 \uac00\uaca9\uc774 \uc870\uae08 \ube44\uc2f8\uc9c0\ub9cc \uc791\uc5c5 \uc18d\ub3c4\uac00 \ube60\ub974\uace0 \uace0\uc7a5\uc774 \uc801\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ucd08\uae30 \ube44\uc6a9\ub9cc \uc0dd\uac01\ud558\uba74 A\uc81c\ud488\uc774 \ub354 \uacbd\uc81c\uc801\uc73c\ub85c \ubcf4\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc7a5\uae30\uac04 \uc0ac\uc6a9\ud560 \uc7a5\ube44\ub77c\uba74 \uc720\uc9c0\ube44\uc640 \uc0dd\uc0b0\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc800\ub294 \ucd08\uae30 \ube44\uc6a9\uc774 \uc870\uae08 \ub354 \ub4e4\ub354\ub77c\ub3c4 B\uc81c\ud488\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \ub0ab\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.","Gi\u1ea3 s\u1eed c\xf4ng ty mua thi\u1ebft b\u1ecb m\u1edbi th\xec c\xf3 th\u1ec3 c\xf3 hai l\u1ef1a ch\u1ecdn. S\u1ea3n ph\u1ea9m A r\u1ebb nh\u01b0ng ng\u01b0\u1ee3c l\u1ea1i \xedt ch\u1ee9c n\u0103ng v\xe0 c\u1ea7n b\u1ea3o tr\xec th\u01b0\u1eddng xuy\xean. S\u1ea3n ph\u1ea9m B h\u01a1i \u0111\u1eaft nh\u01b0ng c\xf3 \u01b0u \u0111i\u1ec3m l\xe0 t\u1ed1c \u0111\u1ed9 l\xe0m vi\u1ec7c nhanh v\xe0 \xedt h\u1ecfng. N\u1ebfu ch\u1ec9 ngh\u0129 \u0111\u1ebfn chi ph\xed ban \u0111\u1ea7u th\xec A c\xf3 th\u1ec3 tr\xf4ng kinh t\u1ebf h\u01a1n. Tuy nhi\xean n\u1ebfu l\xe0 thi\u1ebft b\u1ecb s\u1eed d\u1ee5ng l\xe2u d\xe0i th\xec c\u1ea7n c\xe2n nh\u1eafc c\u1ea3 chi ph\xed duy tr\xec v\xe0 n\u0103ng su\u1ea5t. V\xec v\u1eady t\xf4i ngh\u0129 d\xf9 chi ph\xed ban \u0111\u1ea7u cao h\u01a1n m\u1ed9t ch\xfat th\xec ch\u1ecdn B v\u1eabn t\u1ed1t h\u01a1n.")
A.lnl=s([A.c7d,A.c7n],t.vH)
A.kTw=s(["\uc758\uacac","\uc758\uacac\uc744 \ub9d0\ud558\ub2e4","\uc758\uacac\uc744 \ub098\ub204\ub2e4","\uc0dd\uac01","\ucc2c\uc131\ud558\ub2e4","\ubc18\ub300\ud558\ub2e4","\ub3d9\uc758\ud558\ub2e4","\uc8fc\uc7a5\ud558\ub2e4","\uadfc\uac70","\uadfc\uac70\ub97c \uc81c\uc2dc\ud558\ub2e4","\uc774\uc720","\uc7a5\uc810","\ub2e8\uc810","\ube44\uad50\ud558\ub2e4","\uc120\ud0dd\ud558\ub2e4","\uc120\ud0dd \uae30\uc900","\uace0\ub824\ud558\ub2e4","\ud310\ub2e8\ud558\ub2e4","\uacb0\uc815\ud558\ub2e4","\uacb0\uc815\uc744 \ub0b4\ub9ac\ub2e4","\ub300\uc548","\ub300\uc548\uc744 \uc81c\uc2dc\ud558\ub2e4","\uc81c\uc548\ud558\ub2e4","\uc124\ub4dd\ud558\ub2e4","\uc124\ub4dd\ub825","\uc6b0\uc120\ud558\ub2e4","\uc6b0\uc120\uc21c\uc704","\ud6a8\uc728\uc801\uc774\ub2e4","\uacbd\uc81c\uc801\uc774\ub2e4","\ud604\uc2e4\uc801\uc774\ub2e4","\uc801\ud569\ud558\ub2e4","\uc870\uac74"],t.s)
A.k91=s(["\uc81c \uc0dd\uac01\uc5d0\ub294 / \uc81c\uac00 \ubcf4\uae30\uc5d0\ub294","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","N\uc5d0 \ube44\ud574(\uc11c)","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c","V-\ub294 \uac83\uc774 \ub0ab\ub2e4","V/A-(\uc73c)\u3134/\ub294 \ud3b8\uc774\ub2e4","V-\ub294 \uac8c \uc5b4\ub54c\uc694?","V-(\uc73c)\uba74 \uc5b4\ub5a8\uae4c\uc694?","V/A-\ub354\ub77c\ub3c4","V-\uae30 \ub54c\ubb38\uc5d0"],t.s)
A.lae=s(["\uc758\uacac = \xfd ki\u1ebfn","\ucc2c\uc131\ud558\ub2e4 = t\xe1n th\xe0nh","\ubc18\ub300\ud558\ub2e4 = ph\u1ea3n \u0111\u1ed1i","\ub3d9\uc758\ud558\ub2e4 = \u0111\u1ed3ng \xfd","\uc8fc\uc7a5\ud558\ub2e4 = \u0111\u01b0a ra l\u1eadp lu\u1eadn/quan \u0111i\u1ec3m","\uadfc\uac70 = c\u0103n c\u1ee9","\uc7a5\uc810 = \u01b0u \u0111i\u1ec3m","\ub2e8\uc810 = nh\u01b0\u1ee3c \u0111i\u1ec3m","\ube44\uad50\ud558\ub2e4 = so s\xe1nh","\uc120\ud0dd\ud558\ub2e4 = l\u1ef1a ch\u1ecdn","\uc120\ud0dd \uae30\uc900 = ti\xeau ch\xed l\u1ef1a ch\u1ecdn","\uace0\ub824\ud558\ub2e4 = c\xe2n nh\u1eafc","\ud310\ub2e8\ud558\ub2e4 = ph\xe1n \u0111o\xe1n","\uacb0\uc815\ud558\ub2e4 = quy\u1ebft \u0111\u1ecbnh","\uacb0\uc815\uc744 \ub0b4\ub9ac\ub2e4 = \u0111\u01b0a ra quy\u1ebft \u0111\u1ecbnh","\ub300\uc548 = ph\u01b0\u01a1ng \xe1n thay th\u1ebf","\uc81c\uc548\ud558\ub2e4 = \u0111\u1ec1 xu\u1ea5t","\uc124\ub4dd\ud558\ub2e4 = thuy\u1ebft ph\u1ee5c","\uc6b0\uc120\uc21c\uc704 = th\u1ee9 t\u1ef1 \u01b0u ti\xean","\ud6a8\uc728\uc801\uc774\ub2e4 = hi\u1ec7u qu\u1ea3","\uacbd\uc81c\uc801\uc774\ub2e4 = kinh t\u1ebf/ti\u1ebft ki\u1ec7m","\ud604\uc2e4\uc801\uc774\ub2e4 = th\u1ef1c t\u1ebf","\uc801\ud569\ud558\ub2e4 = ph\xf9 h\u1ee3p","\uc81c \uc0dd\uac01\uc5d0\ub294 = theo t\xf4i","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/ng\u01b0\u1ee3c l\u1ea1i","N\uc5d0 \ube44\ud574\uc11c = so v\u1edbi...","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9... m\xe0 c\xf2n...","V-\ub294 \uac83\uc774 \ub0ab\ub2e4 = l\xe0m... th\xec t\u1ed1t h\u01a1n","V/A-(\uc73c)\u3134/\ub294 \ud3b8\uc774\ub2e4 = c\xf3 xu h\u01b0\u1edbng...","\uc81c \uc0dd\uac01\uc5d0\ub294 \ub450 \ubc88\uc9f8 \ubc29\ubc95\uc774 \ub354 \ud6a8\uc728\uc801\uc778 \uac83 \uac19\uc2b5\ub2c8\ub2e4.","A\uc548\uc740 \ube44\uc6a9\uc774 \uc801\uac8c \ub4dc\ub294 \ubc18\uba74\uc5d0 \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9bd\ub2c8\ub2e4.","\uc774 \uc81c\ud488\uc740 \uac00\uaca9\uc5d0 \ube44\ud574 \ud488\uc9c8\uc774 \uc88b\uc740 \ud3b8\uc785\ub2c8\ub2e4.","\uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubc1c\uc804 \uac00\ub2a5\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud63c\uc790 \uacb0\uc815\ud558\uae30\ubcf4\ub2e4 \ud300\uc6d0\ub4e4\uacfc \uc0c1\uc758\ud558\ub294 \uac83\uc774 \ub098\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.","\ubc18\ub300 \uc758\uacac\uc744 \ub9d0\ud560 \ub54c\ub294 \uc774\uc720\uc640 \ub300\uc548\uc744 \ud568\uaed8 \uc81c\uc2dc\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
