A.lvU=s(["\uc0ac\uc9c4\uc5d0 \uac1c\uc778\uc815\ubcf4\ub098 \ubbfc\uac10\ud55c \uc815\ubcf4\uac00 \ubcf4\uc774\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4.","\uce5c\uad6c\uac00 \uba87 \uba85\uc778\uc9c0 \ud655\uc778\ud55c\ub2e4.","\ud734\ub300\uc804\ud654 \ubc30\ud130\ub9ac\ub9cc \ud655\uc778\ud55c\ub2e4.","\ub313\uae00 \uc218\ub9cc \ud655\uc778\ud55c\ub2e4."],t.s)
A.bTv=new B.ak("SNS\uc5d0 \uc0ac\uc9c4\uc744 \uc62c\ub9ac\uae30 \uc804\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uac83\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.lvU,0,"Tr\u01b0\u1edbc khi \u0111\u0103ng \u1ea3nh n\xean ki\u1ec3m tra th\xf4ng tin c\xe1 nh\xe2n ho\u1eb7c th\xf4ng tin nh\u1ea1y c\u1ea3m c\xf3 b\u1ecb l\u1ed9 kh\xf4ng.","\uac1c\uc778\uc815\ubcf4")
