A.bV5=new B.ak("\uc5c5\ubb34\uac00 \ub108\ubb34 \ub9ce\uc544 \uc815\ud574\uc9c4 \uc2dc\uac04 \uc548\uc5d0 \ub05d\ub0b4\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740?",A.kre,1,"N\xean b\xe1o t\xecnh tr\u1ea1ng th\u1ef1c t\u1ebf v\xe0 trao \u0111\u1ed5i v\u1ec1 \u01b0u ti\xean/h\u1ed7 tr\u1ee3.","\uc2e4\uc81c \uc0c1\ud669")
A.jF6=s(["\ubbfc\uc218 \uc528\ub294 \ub05d\uae4c\uc9c0 \uc544\ubb34\uc5d0\uac8c\ub3c4 \ub9d0\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ub3d9\ub8cc\uc5d0\uac8c \uace0\ubbfc\uc744 \uc774\uc57c\uae30\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ubc14\ub85c \ud68c\uc0ac\ub97c \uadf8\ub9cc\ub480\uc2b5\ub2c8\ub2e4.","\ubaa8\ub4e0 \uc5c5\ubb34\uac00 \ub354 \ub298\uc5c8\uc2b5\ub2c8\ub2e4."],t.s)
A.bW4=new B.ak("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc218 \uc528\ub294 \ucd5c\uadfc \uc5c5\ubb34\uac00 \ub9ce\uc544 \uc2a4\ud2b8\ub808\uc2a4\ub97c \ubc1b\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0 \ud588\uc9c0\ub9cc \uc810\uc810 \ubd80\ub2f4\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub3d9\ub8cc\uc5d0\uac8c \uace0\ubbfc\uc744 \ud138\uc5b4\ub193\uc558\uace0, \ub3d9\ub8cc\uc758 \uc870\uc5b8\uc744 \ub4e3\uace0 \ud300\uc7a5\uc5d0\uac8c \ud604\uc7ac \uc5c5\ubb34 \uc0c1\ud669\uc744 \uc124\uba85\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \uc77c\ubd80 \uc5c5\ubb34\ub97c \ub2e4\ub978 \uc9c1\uc6d0\uacfc \ub098\ub204\uc5b4 \ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.",A.jF6,1,"\u0110o\u1ea1n v\u0103n n\xf3i \ubbfc\uc218 \uc528\uac00 \ub3d9\ub8cc\uc5d0\uac8c \uace0\ubbfc\uc744 \ud138\uc5b4\ub193\uc558\ub2e4.","\uc77d\uae30")
A.kjN=s(["\uc704\ub85c\ud558\ub2e4","\ud658\ubd88\ud558\ub2e4","\uacac\uc778\ud558\ub2e4","\ubc1c\uae09\ud558\ub2e4"],t.s)
A.bTx=new B.ak("\ud798\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \ub530\ub73b\ud55c \ub9d0\uc744 \ud574 \uc8fc\ub294 \uac83\uc744 \ubb34\uc5c7\uc774\ub77c\uace0 \ud569\ub2c8\uae4c?",A.kjN,0,"\uc704\ub85c\ud558\ub2e4 = an \u1ee7i.","\uc5b4\ud718")
A.kZ_=s(["\uadf8\ub7f0 \uc0c1\ud669\uc774\uba74 \ub9ce\uc774 \uc18d\uc0c1\ud588\uc744 \uac83 \uac19\uc544. \ub108\ubb34 \uc790\uc2e0\uac10\uc744 \uc783\uc9c0 \ub9c8.","\uc65c \uadf8\uac83\ub3c4 \ubabb \ud588\uc5b4?","\uadf8\uac74 \ub124 \ubb38\uc81c\uc57c.","\uc544\ubb34 \uc0dd\uac01\ud558\uc9c0 \ub9c8."],t.s)
A.bTW=new B.ak("\uce5c\uad6c\uac00 \uc2dc\ud5d8\uc5d0 \ub5a8\uc5b4\uc838 \ub9e4\uc6b0 \uc18d\uc0c1\ud574\ud569\ub2c8\ub2e4. \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ub9d0\uc740?",A.kZ_,0,"Ph\u1ea3n h\u1ed3i ph\xf9 h\u1ee3p l\xe0 \u0111\u1ed3ng c\u1ea3m tr\u01b0\u1edbc r\u1ed3i \u0111\u1ed9ng vi\xean.","\uc2e4\uc81c \uc0c1\ud669")
A.jTo=s(["\ubb38\uc81c\ub97c \ubb34\uc870\uac74 \uc228\uae34\ub2e4.","\uac10\uc815\uc801\uc73c\ub85c \ubc14\ub85c \uc911\uc694\ud55c \uacb0\uc815\uc744 \ud55c\ub2e4.","\uc0c1\ud669\uc744 \uc815\ub9ac\ud558\uace0 \ud544\uc694\ud558\uba74 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc870\uc5b8\uc744 \uad6c\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubaa8\ub4e0 \ucc45\uc784\uc744 \ub3cc\ub9b0\ub2e4."],t.s)
A.bVa=new B.ak("\uace0\ubbfc\uc774 \uc788\uc744 \ub54c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \ud0dc\ub3c4\ub85c \uc54c\ub9de\uc740 \uac83\uc740?",A.jTo,2,"N\xean s\u1eafp x\u1ebfp t\xecnh hu\u1ed1ng, suy ngh\u0129 v\xe0 xin l\u1eddi khuy\xean khi c\u1ea7n.","\uc885\ud569")
