A.bUK=new B.ak("\uc57d\uc18d \uc2dc\uac04\uc5d0 15\ubd84 \uc815\ub3c4 \ub2a6\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud589\ub3d9\uc740?",A.jt6,0,"Khi c\xf3 kh\u1ea3 n\u0103ng \u0111\u1ebfn mu\u1ed9n n\xean th\xf4ng b\xe1o tr\u01b0\u1edbc v\xe0 n\xeau th\u1eddi gian d\u1ef1 ki\u1ebfn \u0111\u1ebfn.","\uc2e4\uc81c \uc0c1\ud669")
A.l5l=s(["\ubbfc\uc218 \uc528\uc758 \ubcd1\uc6d0 \uc608\uc57d\uc740 \uae08\uc694\uc77c \uc624\ud6c4 4\uc2dc\ub85c \ubcc0\uacbd\ub410\uc2b5\ub2c8\ub2e4.","\ud68c\uc0ac \ud68c\uc758\uac00 \ucde8\uc18c\ub410\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ubcd1\uc6d0 \uc608\uc57d\uc744 \uc644\uc804\ud788 \ucde8\uc18c\ud588\uc2b5\ub2c8\ub2e4.","\ub450 \uc77c\uc815\uc740 \ucc98\uc74c\ubd80\ud130 \uacb9\uce58\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4."],t.s)
A.bVt=new B.ak("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc218 \uc528\ub294 \ub0b4\uc77c \uc624\ud6c4 2\uc2dc\uc5d0 \ubcd1\uc6d0 \uc608\uc57d\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \ud68c\uc0ac \ud68c\uc758 \uc2dc\uac04\uc774 \uc624\ud6c4 2\uc2dc\ub85c \ubcc0\uacbd\ub418\uc5b4 \ub450 \uc77c\uc815\uc774 \uacb9\uce58\uac8c \ub410\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ubcd1\uc6d0\uc5d0 \uc804\ud654\ud574\uc11c \uc608\uc57d\uc744 \uae08\uc694\uc77c \uc624\ud6c4 4\uc2dc\ub85c \ubcc0\uacbd\ud588\uc2b5\ub2c8\ub2e4.",A.l5l,0,"\u0110o\u1ea1n v\u0103n n\xf3i l\u1ecbch b\u1ec7nh vi\u1ec7n \u0111\u01b0\u1ee3c \u0111\u1ed5i sang 4 gi\u1edd chi\u1ec1u th\u1ee9 S\xe1u.","\uc77d\uae30")
A.kEz=s(["\ubd88\ucc38\ud558\ub2e4","\ud655\uc815\ud558\ub2e4","\uc55e\ub2f9\uae30\ub2e4","\ub3c4\ucc29\ud558\ub2e4"],t.s)
A.bU2=new B.ak("\ud68c\uc758\ub098 \uc57d\uc18d\uc5d0 \uac00\uc9c0 \uc54a\ub294 \uac83\uc744 \ubb34\uc5c7\uc774\ub77c\uace0 \ud569\ub2c8\uae4c?",A.kEz,0,"\ubd88\ucc38\ud558\ub2e4 = kh\xf4ng tham d\u1ef1.","\uc5b4\ud718")
A.laM=s(["\ub2e4\ub978 \uc77c\uc815\uacfc \uacb9\uccd0\uc11c \ud639\uc2dc \ud68c\uc758 \uc2dc\uac04\uc744 \uc870\uc815\ud560 \uc218 \uc788\uc744\uae4c\uc694?","\ud68c\uc758 \uc2dc\uac04 \uc2eb\uc5b4\uc694.","\uc2dc\uac04 \ubc14\uafd4\uc694.","\ub098\ub294 \uc548 \uac00\uc694."],t.s)
A.bVy=new B.ak("\ub2e4\ub978 \uc77c\uc815\uacfc \uacb9\uccd0 \ud68c\uc758 \uc2dc\uac04\uc744 \ubc14\uafb8\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud45c\ud604\uc740?",A.laM,0,"C\xe2u \u0111\u1ea7u v\u1eeba n\xeau l\xfd do v\u1eeba y\xeau c\u1ea7u thay \u0111\u1ed5i l\u1ecbch l\u1ecbch s\u1ef1.","\uc2e4\uc81c \uc0c1\ud669")
A.kLc=s(["\uc544\ubb34 \uc5f0\ub77d \uc5c6\uc774 \ub098\ud0c0\ub098\uc9c0 \uc54a\ub294\ub2e4.","\uac00\ub2a5\ud558\uba74 \ubbf8\ub9ac \uc5f0\ub77d\ud55c\ub2e4.","\ubcc0\uacbd \uc774\uc720\ub97c \uac04\ub2e8\ud788 \uc124\uba85\ud55c\ub2e4.","\ub300\uccb4 \uac00\ub2a5\ud55c \uc2dc\uac04\uc744 \uc81c\uc548\ud55c\ub2e4."],t.s)
