A.bZc=new B.dh("\ud68c\uc0ac \ud68c\uc758 \uc2dc\uac04\uc744 \ubcc0\uacbd\ud558\uace0 \uc2f6\uc744 \ub54c \uc5b4\ub5bb\uac8c \ub9d0\ud558\uaca0\uc2b5\ub2c8\uae4c?","\ud300\uc7a5\ub2d8, \uc8c4\uc1a1\ud558\uc9c0\ub9cc \ub0b4\uc77c \uc624\uc804 \ud68c\uc758 \uc2dc\uac04\uc774 \ub2e4\ub978 \uc77c\uc815\uacfc \uacb9\uccd0\uc11c \ub9d0\uc500\ub4dc\ub9ac\ub824\uace0 \ud569\ub2c8\ub2e4. \ud639\uc2dc \ud68c\uc758\ub97c \uc624\ud6c4\ub85c \ubcc0\uacbd\ud560 \uc218 \uc788\uc744\uae4c\uc694? \uc800\ub294 \uc624\ud6c4 2\uc2dc \uc774\ud6c4\uc5d0\ub294 \uac00\ub2a5\ud569\ub2c8\ub2e4. \ub2e4\ub978 \ubd84\ub4e4\uc758 \uc77c\uc815\ub3c4 \uad1c\ucc2e\ub2e4\uba74 \uc624\ud6c4 3\uc2dc\uc5d0 \ud558\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
A.nqo=s(["\uc8c4\uc1a1\ud558\ub2e4","\uad50\ud1b5","10\ubd84","\ub3c4\ucc29 \uc608\uc815","\uc5f0\ub77d"],t.s)
A.bZg=new B.dh("\uc57d\uc18d\uc5d0 \ub2a6\uc744 \uac83 \uac19\uc744 \ub54c \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5f0\ub77d\ud574 \ubcf4\uc138\uc694.","\uc8c4\uc1a1\ud569\ub2c8\ub2e4. \uc9c0\uae08 \ub3c4\ub85c\uac00 \ub9ce\uc774 \ub9c9\ud600\uc11c \uc57d\uc18d \uc2dc\uac04\ubcf4\ub2e4 10\ubd84 \uc815\ub3c4 \ub2a6\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc774\ub3d9 \uc911\uc774\uace0 6\uc2dc 40\ubd84\ucbe4 \ub3c4\ucc29\ud560 \uc608\uc815\uc785\ub2c8\ub2e4. \uae30\ub2e4\ub9ac\uac8c \ud574\uc11c \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \ub3c4\ucc29\ud558\ub294 \ub300\ub85c \ub2e4\uc2dc \uc5f0\ub77d\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.")
A.npb=s(["\uc608\uc57d","\uac1c\uc778 \uc0ac\uc815","\ubcc0\uacbd","\ub2e4\ub978 \ub0a0\uc9dc","\uac00\ub2a5"],t.s)
A.bZ1=new B.dh("\ubcd1\uc6d0 \uc608\uc57d\uc744 \ubcc0\uacbd\ud558\ub294 \uc0c1\ud669\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \ub0b4\uc77c \uc624\ud6c4 2\uc2dc\uc5d0 \uc9c4\ub8cc \uc608\uc57d\uc774 \ub418\uc5b4 \uc788\ub294\ub370 \uac1c\uc778 \uc0ac\uc815\uc774 \uc0dd\uaca8\uc11c \uc608\uc57d \uc2dc\uac04\uc744 \ubcc0\uacbd\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ud639\uc2dc \uc774\ubc88 \uc8fc \uae08\uc694\uc77c \uc624\ud6c4\uc5d0 \uac00\ub2a5\ud55c \uc2dc\uac04\uc774 \uc788\uc744\uae4c\uc694? \uc624\ud6c4 3\uc2dc \uc774\ud6c4\ub77c\uba74 \uc5b8\uc81c\ub4e0\uc9c0 \uac00\ub2a5\ud569\ub2c8\ub2e4.")
A.kwd=s([A.bZc,A.bZg,A.bZ1],t.Pe)
A.nse=s(["\uc0ac\uacfc \ud45c\ud604\uc744 \uc4f0\uc138\uc694.","\ubcc0\uacbd \uc774\uc720\ub97c \uac04\ub2e8\ud788 \uc4f0\uc138\uc694.","\uc6d0\ub798 \uc57d\uc18d \uc2dc\uac04\uc744 \uc4f0\uc138\uc694.","\uc0c8\ub85c\uc6b4 \uc2dc\uac04\uc744 \uc81c\uc548\ud558\uc138\uc694.","V-(\uc73c)\u3139 \uc218 \uc788\uc744\uae4c\uc694?\uc640 V-(\uc73c)\uba74 \uc5b4\ub5a8\uae4c\uc694?\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7K=new B.ei("\uc57d\uc18d \uc2dc\uac04\uc744 \ubcc0\uacbd\ud558\ub294 \uba54\uc2dc\uc9c0\ub97c \uc368 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \uac11\uc790\uae30 \uc5f0\ub77d\ub4dc\ub824 \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \ub0b4\uc77c \uc624\ud6c4 2\uc2dc\uc5d0 \ub9cc\ub098\uae30\ub85c \ud588\ub294\ub370 \ud68c\uc0ac \uc77c\uc815\uc774 \uc0dd\uaca8\uc11c \uadf8 \uc2dc\uac04\uc5d0 \uac00\uae30 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud639\uc2dc \uc57d\uc18d \uc2dc\uac04\uc744 \uc624\ud6c4 5\uc2dc\ub85c \ubcc0\uacbd\ud560 \uc218 \uc788\uc744\uae4c\uc694? \uc624\ud6c4 5\uc2dc\uac00 \uc5b4\ub824\uc6b0\uc2dc\uba74 \uae08\uc694\uc77c \uc624\ud6c4\uc5d0 \ub9cc\ub098\uba74 \uc5b4\ub5a8\uae4c\uc694? \ubd88\ud3b8\uc744 \ub4dc\ub824 \uc8c4\uc1a1\ud569\ub2c8\ub2e4.","Xin ch\xe0o. Xin l\u1ed7i v\xec li\xean l\u1ea1c \u0111\u1ed9t ng\u1ed9t. Ch\xfang ta \u0111\xe3 h\u1eb9n g\u1eb7p l\xfac 2 gi\u1edd chi\u1ec1u mai nh\u01b0ng do ph\xe1t sinh l\u1ecbch c\xf4ng ty n\xean c\xf3 v\u1ebb t\xf4i kh\xf3 \u0111\u1ebfn v\xe0o gi\u1edd \u0111\xf3. Kh\xf4ng bi\u1ebft c\xf3 th\u1ec3 \u0111\u1ed5i gi\u1edd h\u1eb9n sang 5 gi\u1edd chi\u1ec1u kh\xf4ng? N\u1ebfu 5 gi\u1edd chi\u1ec1u kh\xf4ng ti\u1ec7n th\xec g\u1eb7p chi\u1ec1u th\u1ee9 S\xe1u th\xec sao? Xin l\u1ed7i v\xec s\u1ef1 b\u1ea5t ti\u1ec7n.")
A.nq2=s(["\ud68c\uc758 \ub0a0\uc9dc\uc640 \uc2dc\uac04\uc744 \uc4f0\uc138\uc694.","\ucc38\uc11d\ud558\uc9c0 \ubabb\ud558\ub294 \uc774\uc720\ub97c \uc4f0\uc138\uc694.","\ubbf8\ub9ac \uc54c\ub838\ub294\uc9c0 \uc4f0\uc138\uc694.","\ub300\uccb4 \ubc29\ubc95\uc744 \uc81c\uc548\ud558\uc138\uc694.","V-\uac8c \ub418\ub2e4\uc640 V-(\uc73c)\u3139 \uac83 \uac19\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7b=new B.ei("\ud68c\uc0ac \ud68c\uc758\uc5d0 \ucc38\uc11d\ud558\uc9c0 \ubabb\ud558\uac8c \ub41c \uc0c1\ud669\uc744 \uc368 \ubcf4\uc138\uc694.","\uc774\ubc88 \uc8fc \uae08\uc694\uc77c \uc624\ud6c4 3\uc2dc\uc5d0 \ubd80\uc11c \ud68c\uc758\uac00 \uc608\uc815\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uac11\uc790\uae30 \uc678\ubd80 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\uac8c \ub418\uc5b4 \uadf8 \uc2dc\uac04\uc5d0 \ud68c\uc0ac\uc5d0 \ub3cc\uc544\uc624\uae30 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud300\uc7a5\ub2d8\uaed8 \ubbf8\ub9ac \uc0c1\ud669\uc744 \ub9d0\uc500\ub4dc\ub9ac\uace0 \ud68c\uc758\uc5d0 \ucc38\uc11d\ud558\uc9c0 \ubabb\ud560 \uc218\ub3c4 \uc788\ub2e4\uace0 \uc54c\ub824 \ub4dc\ub838\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uacbd\uc6b0 \ud68c\uc758 \uc790\ub8cc\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0 \uc81c \uc758\uacac\uc744 \ubbf8\ub9ac \uc804\ub2ec\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uac00\ub2a5\ud558\ub2e4\uba74 \ud68c\uc758\uac00 \ub05d\ub09c \ud6c4 \uc8fc\uc694 \ub0b4\uc6a9\uc744 \uacf5\uc720\ubc1b\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","Cu\u1ed9c h\u1ecdp b\u1ed9 ph\u1eadn d\u1ef1 ki\u1ebfn di\u1ec5n ra l\xfac 3 gi\u1edd chi\u1ec1u th\u1ee9 S\xe1u tu\u1ea7n n\xe0y. Tuy nhi\xean t\xf4i \u0111\u1ed9t nhi\xean \u0111\u01b0\u1ee3c giao c\xf4ng vi\u1ec7c b\xean ngo\xe0i n\xean c\xf3 v\u1ebb kh\xf3 quay l\u1ea1i c\xf4ng ty v\xe0o th\u1eddi gian \u0111\xf3. V\xec v\u1eady t\xf4i \u0111\xe3 b\xe1o tr\u01b0\u1edbc t\xecnh h\xecnh cho tr\u01b0\u1edfng nh\xf3m v\xe0 cho bi\u1ebft c\xf3 th\u1ec3 t\xf4i kh\xf4ng tham d\u1ef1 \u0111\u01b0\u1ee3c. N\u1ebfu c\u1ea7n, t\xf4i \u0111\u1ecbnh xem t\xe0i li\u1ec7u h\u1ecdp tr\u01b0\u1edbc v\xe0 g\u1eedi \xfd ki\u1ebfn c\u1ee7a m\xecnh tr\u01b0\u1edbc. N\u1ebfu c\xf3 th\u1ec3 t\xf4i mu\u1ed1n \u0111\u01b0\u1ee3c chia s\u1ebb nh\u1eefng n\u1ed9i dung ch\xednh sau khi cu\u1ed9c h\u1ecdp k\u1ebft th\xfac.")
A.l0y=s([A.c7K,A.c7b],t.vH)
