A.ktD=s(["V-\uae30 \uc704\ud574(\uc11c)","V-(\uc73c)\u3139 \ub54c","V-\uc544/\uc5b4 \ubc84\ub9ac\ub2e4","V-\uc558/\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\ub2e4","V-(\uc73c)\u3139\uae4c \ubd10","V-\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud558\ub2e4","V-\uc544/\uc5b4\uc57c \ud558\ub2e4","V-(\uc73c)\uba74 \uc548 \ub418\ub2e4","V-(\uc73c)\u3139 \uacbd\uc6b0","V-\ub294 \uac83\uc774 \uc88b\ub2e4"],t.s)
A.k1N=s(["\uacc4\uc88c = t\xe0i kho\u1ea3n ng\xe2n h\xe0ng","\ud1b5\uc7a5 = s\u1ed5 t\xe0i kho\u1ea3n","\uc794\uc561 = s\u1ed1 d\u01b0","\uc785\uae08\ud558\ub2e4 = n\u1ed9p/chuy\u1ec3n ti\u1ec1n v\xe0o","\ucd9c\uae08\ud558\ub2e4 = r\xfat/tr\u1eeb ti\u1ec1n","\uc774\uccb4\ud558\ub2e4 = chuy\u1ec3n kho\u1ea3n","\uc1a1\uae08\ud558\ub2e4 = g\u1eedi ti\u1ec1n","\ud574\uc678 \uc1a1\uae08 = chuy\u1ec3n ti\u1ec1n qu\u1ed1c t\u1ebf","\uc790\ub3d9\uc774\uccb4 = chuy\u1ec3n kho\u1ea3n t\u1ef1 \u0111\u1ed9ng","\uac70\ub798 \ub0b4\uc5ed = l\u1ecbch s\u1eed giao d\u1ecbch","\uc218\uc218\ub8cc = ph\xed giao d\u1ecbch","\uc774\uccb4 \ud55c\ub3c4 = h\u1ea1n m\u1ee9c chuy\u1ec3n ti\u1ec1n","\ubcf8\uc778 \uc778\uc99d = x\xe1c th\u1ef1c danh t\xednh","\uccb4\ud06c\uce74\ub4dc = th\u1ebb ghi n\u1ee3","\ubd84\uc2e4 \uc2e0\uace0 = b\xe1o m\u1ea5t","\uc0ac\uc6a9 \uc815\uc9c0 = kh\xf3a s\u1eed d\u1ee5ng","\uc7ac\ubc1c\uae09 = c\u1ea5p l\u1ea1i","\ud658\uc728 = t\u1ef7 gi\xe1","\ud658\uc804\ud558\ub2e4 = \u0111\u1ed5i ngo\u1ea1i t\u1ec7","\ubcf4\uc774\uc2a4\ud53c\uc2f1 = l\u1eeba \u0111\u1ea3o qua \u0111i\u1ec7n tho\u1ea1i","\uae08\uc735 \uc0ac\uae30 = l\u1eeba \u0111\u1ea3o t\xe0i ch\xednh","\uc798\ubabb \uc1a1\uae08\ud558\ub2e4 = chuy\u1ec3n nh\u1ea7m ti\u1ec1n","V-\uae30 \uc704\ud574\uc11c = \u0111\u1ec3...","V-(\uc73c)\u3139 \ub54c = khi...","V-\uc544/\uc5b4 \ubc84\ub9ac\ub2e4 = l\u1ee1 l\xe0m m\u1ea5t...","V-\uc558/\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\ub2e4 = x\xe1c nh\u1eadn xem \u0111\xe3... ch\u01b0a","V-(\uc73c)\u3139\uae4c \ubd10 = v\xec lo r\u1eb1ng...","V-\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud558\ub2e4 = ch\xfa \xfd \u0111\u1ec3 kh\xf4ng...","\ub3c8\uc744 \uc774\uccb4\ud560 \ub54c \uacc4\uc88c \ubc88\ud638\ub97c \uaf2d \ud655\uc778\ud558\uc138\uc694.","\ub3c8\uc744 \uc798\ubabb \ubcf4\ub0bc\uae4c \ubd10 \uacc4\uc88c \uc815\ubcf4\ub97c \ub2e4\uc2dc \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\uce74\ub4dc\ub97c \ubd84\uc2e4\ud558\uba74 \ubc14\ub85c \uc0ac\uc6a9\uc744 \uc815\uc9c0\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\ube44\ubc00\ubc88\ud638\ub098 \uc778\uc99d \ubc88\ud638\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc54c\ub824 \uc8fc\uba74 \uc548 \ub429\ub2c8\ub2e4.","\uc758\uc2ec\uc2a4\ub7ec\uc6b4 \uac70\ub798\uac00 \uc788\uc73c\uba74 \uacf5\uc2dd \uace0\uac1d\uc13c\ud130\ub97c \ud1b5\ud574 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.L0=new B.hT(9,"\uae08\uc735 \uc0dd\ud65c","\u0110\u1eddi s\u1ed1ng t\xe0i ch\xednh","\uc758\uc2ec\uc2a4\ub7ec\uc6b4 \uae08\uc735 \uc5f0\ub77d\uc5d0 \ub300\ucc98\ud558\uae30","\uc740\ud589\uc774\ub098 \uacf5\uacf5\uae30\uad00\uc774\ub77c\uace0 \ud558\uba74\uc11c \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \ubc88\ud638\ub97c \uc694\uad6c\ud558\ub294 \uc5f0\ub77d\uc740 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \uc815\uc0c1\uc801\uc778 \uae30\uad00\uc740 \uc804\ud654\ub098 \ubb38\uc790\ub85c \uc911\uc694\ud55c \uae08\uc735 \uc815\ubcf4\ub97c \ubc14\ub85c \uc694\uad6c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ubaa8\ub974\ub294 \uacc4\uc88c\ub85c \ub3c8\uc744 \ubcf4\ub0b4\ub77c\uace0 \ud558\uac70\ub098 \ub9c1\ud06c\ub97c \ub20c\ub7ec \uc571\uc744 \uc124\uce58\ud558\ub77c\uace0 \ud558\uba74 \uba3c\uc800 \uc804\ud654\ub97c \ub04a\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc740\ud589\uc758 \uacf5\uc2dd \ubc88\ud638\ub85c \uc9c1\uc811 \uc5f0\ub77d\ud574\uc11c \uc0ac\uc2e4\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.","C\u1ea7n c\u1ea3nh gi\xe1c v\u1edbi cu\u1ed9c g\u1ecdi ho\u1eb7c tin nh\u1eafn t\u1ef1 x\u01b0ng l\xe0 ng\xe2n h\xe0ng v\xe0 y\xeau c\u1ea7u m\u1eadt kh\u1ea9u, m\xe3 x\xe1c th\u1ef1c, chuy\u1ec3n ti\u1ec1n hay c\xe0i \u1ee9ng d\u1ee5ng. H\xe3y ng\u1eaft li\xean l\u1ea1c r\u1ed3i g\u1ecdi tr\u1ef1c ti\u1ebfp s\u1ed1 ch\xednh th\u1ee9c c\u1ee7a ng\xe2n h\xe0ng \u0111\u1ec3 x\xe1c minh.",A.kJl,A.liv,A.kmE,A.lPO,A.lZL,A.jio,A.kXp,A.kR8,A.l1f,A.jyf,A.kor,A.ktD,A.k1N)
A.lRj=s(["\uc5c5\ubb34 \uc9c0\uc2dc\ub97c \ub193\uce58\ub2e4: \ud574\uc57c \ud560 \uc5c5\ubb34 \ub0b4\uc6a9\uc744 \ub4e3\uc9c0 \ubabb\ud558\uac70\ub098 \uc78a\ub2e4","\uc2b5\uad00\uc744 \ub4e4\uc774\ub2e4: \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uacc4\uc18d \ubc18\ubcf5\ud558\uac8c \ub9cc\ub4e4\ub2e4","\ub2e4\uc74c \ud589\ub3d9\uc5d0 \uc801\uc6a9\ud558\ub2e4: \ubc30\uc6b4 \ub0b4\uc6a9\uc744 \uc774\ud6c4\uc758 \ud589\ub3d9\uc5d0 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud558\ub2e4"],t.s)
A.jCJ=s(["HANNEST 3\uc758 \uc8fc\uc694 \uc0c1\ud669\uacfc \ud45c\ud604\uc744 \uc5f0\uacb0\ud574\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc5b4\uc694.","\ubb38\uc81c\uc758 \uc6d0\uc778\uacfc \uacb0\uacfc\ub97c \ubd84\uc11d\ud558\uace0 \ud574\uacb0\ucc45\uc744 \uc81c\uc548\ud560 \uc218 \uc788\uc5b4\uc694.","\uacbd\ud5d8, \uac10\uc815\uacfc \uc758\uacac\uc744 \uadfc\uac70\ub97c \ud3ec\ud568\ud574\uc11c \ub9d0\ud560 \uc218 \uc788\uc5b4\uc694.","\ud55c\uad6d \uc0dd\ud65c\uc758 \ubb38\uc81c\uc640 \ubc30\uc6b4 \uc810\uc744 \uae34 \uae00\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\uc5b4\uc694.","\xd4n l\u1ea1i c\xe1c ch\u1ee7 \u0111\u1ec1 quan tr\u1ecdng \u0111\xe3 h\u1ecdc t\u1eeb B\xe0i 1 \u0111\u1ebfn B\xe0i 19 c\u1ee7a HANNEST 3.","\xd4n c\xe1ch th\xedch nghi v\u1edbi cu\u1ed9c s\u1ed1ng v\xe0 v\u0103n h\xf3a H\xe0n Qu\u1ed1c.","\xd4n giao ti\u1ebfp n\u01a1i l\xe0m vi\u1ec7c, nh\u1eadn ch\u1ec9 th\u1ecb, b\xe1o c\xe1o v\xe0 x\u1eed l\xfd s\u1ef1 c\u1ed1.","\xd4n t\u1eeb v\u1ef1ng v\u1ec1 s\u1ee9c kh\u1ecfe, nh\xe0 \u1edf, h\u1ee3p \u0111\u1ed3ng, ti\xeau d\xf9ng v\xe0 t\xe0i ch\xednh.","\xd4n c\xe1ch \u0111\u1eb7t l\u1ecbch, thay \u0111\u1ed5i l\u1ecbch v\xe0 x\u1eed l\xfd t\xecnh hu\u1ed1ng \u0111\u1ebfn mu\u1ed9n.","\xd4n c\xe1ch k\u1ec3 kinh nghi\u1ec7m, di\u1ec5n t\u1ea3 h\u1ed1i ti\u1ebfc v\xe0 b\xe0i h\u1ecdc \u0111\xe3 r\xfat ra.","\xd4n c\xe1ch n\xf3i c\u1ea3m x\xfac, n\u1ed7i lo, xin l\u1eddi khuy\xean v\xe0 \u0111\u1ed9ng vi\xean ng\u01b0\u1eddi kh\xe1c.","\xd4n c\xe1ch tr\xecnh b\xe0y \xfd ki\u1ebfn, so s\xe1nh ph\u01b0\u01a1ng \xe1n v\xe0 \u0111\u01b0a ra l\u1ef1a ch\u1ecdn.","\xd4n quy tr\xecnh ph\xe2n t\xedch nguy\xean nh\xe2n v\xe0 \u0111\u1ec1 xu\u1ea5t gi\u1ea3i ph\xe1p.","\xd4n quy t\u1eafc, tr\xe1ch nhi\u1ec7m v\xe0 an to\xe0n t\u1ea1i n\u01a1i l\xe0m vi\u1ec7c.","\xd4n c\xe1ch x\u1eed l\xfd kh\xe1c bi\u1ec7t v\u0103n h\xf3a v\xe0 hi\u1ec3u l\u1ea7m trong giao ti\u1ebfp.","\xd4n k\u1ef9 n\u0103ng ki\u1ec3m tra th\xf4ng tin, ngu\u1ed3n tin v\xe0 b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n."],t.s)
