A.nqy=s(["\ucc98\uc74c","\ub0af\uc124\ub2e4","\ud55c\uad6d\uc5b4","\ubb38\ud654 \ucc28\uc774","\uc801\uc751","\ubc30\uc6b4 \uc810"],t.s)
A.bZw=new B.dh("\ud55c\uad6d \uc0dd\ud65c\uc5d0 \uc801\uc751\ud558\uba74\uc11c \uc5b4\ub824\uc6e0\ub358 \uc810\uacfc \ubc30\uc6b4 \uc810\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","\ud55c\uad6d\uc5d0 \ucc98\uc74c \uc654\uc744 \ub54c\ub294 \uc5b8\uc5b4\uc640 \uc0dd\ud65c \ubc29\uc2dd\uc774 \ubaa8\ub450 \ub0af\uc124\uc5b4\uc11c \uc5b4\ub824\uc6c0\uc774 \ub9ce\uc558\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ud558\uace0 \uc2f6\uc740 \ub9d0\uc774 \uc788\uc5b4\ub3c4 \ud55c\uad6d\uc5b4\ub85c \uc815\ud655\ud558\uac8c \ud45c\ud604\ud558\uc9c0 \ubabb\ud574\uc11c \ub2f5\ub2f5\ud560 \ub54c\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\uc5d0\uc11c\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798 \uc54c\uc544\ub4e3\uc9c0 \ubabb\ud560\uae4c \ubd10 \uac71\uc815\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ubaa8\ub974\ub294 \ud45c\ud604\uc740 \ubc14\ub85c \ubb3c\uc5b4\ubcf4\uace0 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uba54\ubaa8\ud588\uc2b5\ub2c8\ub2e4. \ud55c\uad6d\uc5d0\uc11c \uacc4\uc18d \uc0dd\ud65c\ud558\ub2e4 \ubcf4\ub2c8 \ubb38\ud654\uc640 \ub9d0\ud22c\uc5d0\ub3c4 \ub9ce\uc774 \uc775\uc219\ud574\uc84c\uc2b5\ub2c8\ub2e4. \uc774 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ubaa8\ub974\ub294 \uac83\uc744 \uc228\uae30\uae30\ubcf4\ub2e4\ub294 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4.")
A.nqw=s(["\ubb38\uc81c \ubc1c\uacac","\ubcf4\uace0","\uc6d0\uc778 \ubd84\uc11d","\uc870\uce58","\uacb0\uacfc \ud655\uc778","\uc7ac\ubc1c \ubc29\uc9c0"],t.s)
A.bYK=new B.dh("\ud68c\uc0ac\uc5d0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \ubcf4\uace0\ubd80\ud130 \uc7ac\ubc1c \ubc29\uc9c0\uae4c\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\ud68c\uc0ac\uc5d0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \uba3c\uc800 \ud604\uc7ac \uc0c1\ud669\uacfc \uc601\ud5a5 \ubc94\uc704\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ucd94\uac00 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4\uba74 \ud544\uc694\ud55c \uacbd\uc6b0 \uc791\uc5c5\uc744 \uc911\uc9c0\ud558\uace0 \ub2f4\ub2f9\uc790\ub098 \ud300\uc7a5\uc5d0\uac8c \ubc14\ub85c \ubcf4\uace0\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc7a5\ube44, \uc791\uc5c5 \uc870\uac74\uacfc \uae30\ub85d\uc744 \ud655\uc778\ud574\uc11c \uc6d0\uc778\uc744 \ubd84\uc11d\ud569\ub2c8\ub2e4. \uc6d0\uc778\uc774 \ud655\uc778\ub418\uba74 \ud544\uc694\ud55c \uc870\uce58\ub97c \ud558\uace0 \uc2dc\ud5d8 \uc791\uc5c5\uc774\ub098 \uac80\uc0ac\ub97c \ud1b5\ud574 \uacb0\uacfc\ub97c \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \ucd94\uac00\ud558\uac70\ub098 \uc791\uc5c5\uc790\ub97c \uad50\uc721\ud558\ub294 \ub4f1 \uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc744 \ub9c8\ub828\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.nrp=s(["\uc7a5\uc810","\ub2e8\uc810","\uc120\ud0dd \uae30\uc900","\ube44\uad50","\uc7a5\uae30\uc801\uc778 \uc870\uac74","\uacb0\uc815"],t.s)
A.bYD=new B.dh("\ub450 \uac00\uc9c0 \uc120\ud0dd \uc911 \ud558\ub098\ub97c \uacb0\uc815\ud558\ub294 \ubc29\ubc95\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc800\ub294 \uc911\uc694\ud55c \uc120\ud0dd\uc744 \ud560 \ub54c \ud55c \uac00\uc9c0 \uc870\uac74\ub9cc \ubcf4\uace0 \uacb0\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc785\ub2c8\ub2e4. \uba3c\uc800 \ub450 \uc120\ud0dd\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \uc9c1\uc7a5\uc744 \uc120\ud0dd\ud55c\ub2e4\uba74 \uae09\uc5ec, \uadfc\ubb34 \uc2dc\uac04, \ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc5c5\ubb34 \ub0b4\uc6a9\uacfc \ubc1c\uc804 \uac00\ub2a5\uc131\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc800\uc5d0\uac8c \uac00\uc7a5 \uc911\uc694\ud55c \uc120\ud0dd \uae30\uc900\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud544\uc694\ud558\uba74 \uacbd\ud5d8\uc774 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc870\uc5b8\ub3c4 \uad6c\ud569\ub2c8\ub2e4. \uc5ec\ub7ec \uc870\uac74\uc744 \ucda9\ubd84\ud788 \uace0\ub824\ud55c \ud6c4 \uc7a5\uae30\uc801\uc73c\ub85c \ub354 \uc801\ud569\ud55c \uc120\ud0dd\uc744 \ud558\ub824\uace0 \ud569\ub2c8\ub2e4.")
A.nsx=s(["\ucd9c\ucc98","\ub0a0\uc9dc","\uacf5\uc2dd \uc815\ubcf4","\uac80\uc99d","\ub2e4\ub978 \uc790\ub8cc","\uacf5\uc720"],t.s)
A.bYP=new B.dh("\uc778\ud130\ub137\uc5d0\uc11c \ubcf8 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud558\ub294\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubcf4\uba74 \ubc14\ub85c \ubbff\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \ucd9c\ucc98\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. \ub204\uac00 \uc791\uc131\ud588\ub294\uc9c0, \uc5b8\uc81c \uc791\uc131\ub41c \uc815\ubcf4\uc778\uc9c0\ub3c4 \ubd05\ub2c8\ub2e4. \ud2b9\ud788 \ube44\uc790, \ud589\uc815, \ucde8\uc5c5\uc774\ub098 \ud68c\uc0ac \uaddc\uc815\ucc98\ub7fc \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uae30\uad00\uc774\ub098 \ud68c\uc0ac \ud648\ud398\uc774\uc9c0\uc5d0 \uac19\uc740 \ub0b4\uc6a9\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4. \ud55c \uacf3\uc758 \uc815\ubcf4\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \ub2e4\ub978 \uc790\ub8cc\uc640\ub3c4 \ube44\uad50\ud569\ub2c8\ub2e4. \uc0ac\uc2e4\uc778\uc9c0 \ucda9\ubd84\ud788 \uac80\uc99d\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub77c\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubc14\ub85c \uacf5\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.")
A.jDO=s([A.bZw,A.bYK,A.bYD,A.bYP],t.Pe)
A.nr4=s(["\ucc98\uc74c \uc5b4\ub824\uc6e0\ub358 \uc810\uc744 \uc4f0\uc138\uc694.","\uc5b4\ub5bb\uac8c \ub178\ub825\ud588\ub294\uc9c0 \uc4f0\uc138\uc694.","\ud604\uc7ac \ub2ec\ub77c\uc9c4 \uc810\uc744 \uc4f0\uc138\uc694.","\ubc30\uc6b4 \uc810\uc744 \uc4f0\uc138\uc694.","V-\ub2e4 \ubcf4\ub2c8\uc640 V-(\uc73c)\u3139\uae4c \ubd10\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7c=new B.ei("\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uac00\uc7a5 \ub9ce\uc774 \ubc1c\uc804\ud55c \uc810\uc744 \uc368 \ubcf4\uc138\uc694.","\ud55c\uad6d \uc0dd\ud65c\uc744 \uc2dc\uc791\ud588\uc744 \ub54c \uc81c\uac00 \uac00\uc7a5 \uc5b4\ub824\uc6cc\ud588\ub358 \uac83\uc740 \uc758\uc0ac\uc18c\ud1b5\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\uc5d0\uc11c \uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798\ubabb \uc774\ud574\ud560\uae4c \ubd10 \ud56d\uc0c1 \uae34\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ubaa8\ub974\ub294 \ub2e8\uc5b4\ub098 \ud45c\ud604\uc774 \ub098\uc624\uba74 \ubc14\ub85c \ubb3c\uc5b4\ubcf4\uace0 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uba54\ubaa8\ud588\uc2b5\ub2c8\ub2e4. \ud1f4\uadfc \ud6c4\uc5d0\ub294 \uadf8\ub0a0 \ub4e4\uc5c8\ub358 \ud45c\ud604\uc744 \ub2e4\uc2dc \ucc3e\uc544\ubcf4\uace0 \uc608\ubb38\ub3c4 \ub9cc\ub4e4\uc5b4 \ubd24\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \uc5f0\uc2b5\uc744 \uacc4\uc18d\ud558\ub2e4 \ubcf4\ub2c8 \uc608\uc804\ubcf4\ub2e4 \uc9c1\uc7a5\uc5d0\uc11c \uc774\uc57c\uae30\ud558\ub294 \uac83\uc774 \ud6e8\uc52c \ud3b8\ud574\uc84c\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\ub3c4 \ubaa8\ub974\ub294 \ud45c\ud604\uc740 \ub9ce\uc9c0\ub9cc \ubaa8\ub974\ub294 \uac83\uc744 \ubd80\ub044\ub7ec\uc6cc\ud558\uae30\ubcf4\ub2e4\ub294 \uc815\ud655\ud558\uac8c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.","Khi b\u1eaft \u0111\u1ea7u cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c, \u0111i\u1ec1u t\xf4i th\u1ea5y kh\xf3 nh\u1ea5t l\xe0 giao ti\u1ebfp. T\xf4i lu\xf4n c\u0103ng th\u1eb3ng v\xec s\u1ee3 hi\u1ec3u sai ch\u1ec9 th\u1ecb c\xf4ng vi\u1ec7c \u1edf c\xf4ng ty. V\xec v\u1eady khi xu\u1ea5t hi\u1ec7n t\u1eeb ho\u1eb7c c\xe1ch n\xf3i kh\xf4ng bi\u1ebft, t\xf4i h\u1ecfi ngay v\xe0 ghi l\u1ea1i n\u1ed9i dung quan tr\u1ecdng. Sau khi tan l\xe0m t\xf4i t\xecm l\u1ea1i nh\u1eefng c\xe1ch n\xf3i \u0111\xe3 nghe trong ng\xe0y v\xe0 t\u1ef1 t\u1ea1o v\xed d\u1ee5. Khi ti\u1ebfp t\u1ee5c luy\u1ec7n t\u1eadp nh\u01b0 v\u1eady, vi\u1ec7c n\xf3i chuy\u1ec7n t\u1ea1i n\u01a1i l\xe0m vi\u1ec7c \u0111\xe3 tho\u1ea3i m\xe1i h\u01a1n r\u1ea5t nhi\u1ec1u so v\u1edbi tr\u01b0\u1edbc. Hi\u1ec7n t\xf4i v\u1eabn c\xf3 nhi\u1ec1u c\xe1ch n\xf3i ch\u01b0a bi\u1ebft, nh\u01b0ng thay v\xec x\u1ea5u h\u1ed5 v\xec kh\xf4ng bi\u1ebft, t\xf4i \u0111\xe3 h\xecnh th\xe0nh th\xf3i quen x\xe1c nh\u1eadn ch\xednh x\xe1c.")
A.noO=s(["\ubb38\uc81c \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778\uc744 \uc4f0\uc138\uc694.","\uc870\uce58 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uacb0\uacfc\ub97c \uc4f0\uc138\uc694.","\uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3134 \uacb0\uacfc\uc640 V-\uc9c0 \uc54a\ub3c4\ub85d\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.c7C=new B.ei("\ud68c\uc0ac\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ubb38\uc81c\uc640 \ud574\uacb0 \uacfc\uc815\uc744 \uc885\ud569\uc801\uc73c\ub85c \uc368 \ubcf4\uc138\uc694.","\uc9c0\ub09c\uc8fc \uc0dd\uc0b0 \uc911 \uc81c\ud488 \ud45c\uba74\uc5d0 \uac19\uc740 \ud760\uc9d1\uc774 \ubc18\ubcf5\ud574\uc11c \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4. \uc791\uc5c5\uc790\ub294 \ucd94\uac00 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc0dd\uc0b0\uc744 \uc7a0\uc2dc \uc911\uc9c0\ud558\uace0 \ubd88\ub7c9\ud488\uc744 \uc815\uc0c1 \uc81c\ud488\uacfc \ubd84\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \uc7a5\ube44\uc640 \uc791\uc5c5 \uc870\uac74\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \uc7a5\ube44\ub97c \uc810\uac80\ud55c \uacb0\uacfc \uc81c\ud488\uc744 \uace0\uc815\ud558\ub294 \uac00\uc774\ub4dc \uc704\uce58\uac00 \uae30\uc900\ubcf4\ub2e4 \uc870\uae08 \ud2c0\uc5b4\uc838 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc704\uce58\ub97c \uc815\uc0c1 \uae30\uc900\uc73c\ub85c \uc870\uc815\ud55c \ud6c4 \uc2dc\ud5d8 \uc0dd\uc0b0\uc744 \uc9c4\ud589\ud588\uace0 \uc5f4 \uac1c \uc81c\ud488\uc5d0\uc11c\ub294 \uac19\uc740 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \uc815\uc0c1 \uc0dd\uc0b0\uc744 \uc7ac\uac1c\ud588\uc2b5\ub2c8\ub2e4. \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc791\uc5c5 \uc2dc\uc791 \uc804 \uac00\uc774\ub4dc \uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \ud56d\ubaa9\uc744 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc5d0 \ucd94\uac00\ud588\uace0 \uc791\uc5c5\uc790\ub4e4\uc5d0\uac8c \ubcc0\uacbd\ub41c \uc810\uac80 \uae30\uc900\ub3c4 \ub2e4\uc2dc \uad50\uc721\ud588\uc2b5\ub2c8\ub2e4.","Tu\u1ea7n tr\u01b0\u1edbc trong qu\xe1 tr\xecnh s\u1ea3n xu\u1ea5t, c\xf9ng m\u1ed9t v\u1ebft x\u01b0\u1edbc li\xean t\u1ee5c xu\u1ea5t hi\u1ec7n tr\xean b\u1ec1 m\u1eb7t s\u1ea3n ph\u1ea9m. \u0110\u1ec3 kh\xf4ng ph\xe1t sinh th\xeam l\u1ed7i, c\xf4ng nh\xe2n \u0111\xe3 t\u1ea1m d\u1eebng s\u1ea3n xu\u1ea5t v\xe0 t\xe1ch s\u1ea3n ph\u1ea9m l\u1ed7i kh\u1ecfi s\u1ea3n ph\u1ea9m b\xecnh th\u01b0\u1eddng. Sau \u0111\xf3 ch\xfang t\xf4i ki\u1ec3m tra thi\u1ebft b\u1ecb v\xe0 \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c. K\u1ebft qu\u1ea3 ki\u1ec3m tra thi\u1ebft b\u1ecb cho th\u1ea5y v\u1ecb tr\xed guide gi\u1eef s\u1ea3n ph\u1ea9m b\u1ecb l\u1ec7ch m\u1ed9t ch\xfat so v\u1edbi ti\xeau chu\u1ea9n. Sau khi ch\u1ec9nh v\u1ecb tr\xed v\u1ec1 ti\xeau chu\u1ea9n b\xecnh th\u01b0\u1eddng, ch\xfang t\xf4i ti\u1ebfn h\xe0nh s\u1ea3n xu\u1ea5t th\u1eed v\xe0 trong 10 s\u1ea3n ph\u1ea9m kh\xf4ng xu\u1ea5t hi\u1ec7n l\u1ed7i t\u01b0\u01a1ng t\u1ef1. Sau \u0111\xf3 s\u1ea3n xu\u1ea5t b\xecnh th\u01b0\u1eddng \u0111\u01b0\u1ee3c ti\u1ebfp t\u1ee5c. \u0110\u1ec3 v\u1ea5n \u0111\u1ec1 kh\xf4ng t\xe1i di\u1ec5n, ch\xfang t\xf4i b\u1ed5 sung v\xe0o checklist m\u1ee5c ki\u1ec3m tra v\u1ecb tr\xed guide tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u v\xe0 \u0111\xe0o t\u1ea1o l\u1ea1i c\xf4ng nh\xe2n v\u1ec1 ti\xeau chu\u1ea9n ki\u1ec3m tra \u0111\xe3 thay \u0111\u1ed5i.")
A.ns5=s(["\uc9c1\uc7a5 \ud55c\uad6d\uc5b4\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc0dd\ud65c \ud55c\uad6d\uc5b4\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubb38\uc81c \ud574\uacb0\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubb38\ud654\uc640 \uc815\ubcf4 \ud655\uc778\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc55e\uc73c\ub85c\uc758 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694."],t.s)
A.c7G=new B.ei("HANNEST 3\uc5d0\uc11c \ubc30\uc6b4 \ub0b4\uc6a9\uc744 \uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud560\uc9c0 \uc368 \ubcf4\uc138\uc694.","HANNEST 3\uc5d0\uc11c \ubc30\uc6b4 \ub0b4\uc6a9\uc740 \uc2dc\ud5d8\uc744 \uc704\ud55c \ud55c\uad6d\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2e4\uc81c \uc0dd\ud65c\uacfc \uc9c1\uc7a5\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud45c\ud604\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c \ud68c\uc0ac\uc5d0\uc11c\ub294 \uc9c0\uc2dc \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \ud655\uc778\ud558\uace0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc0c1\ud669, \uc6d0\uc778\uacfc \uc870\uce58 \ub0b4\uc6a9\uc744 \uc21c\uc11c\ub300\ub85c \ubcf4\uace0\ud558\ub294 \uc5f0\uc2b5\uc744 \ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ubcd1\uc6d0, \uc9d1 \uacc4\uc57d, \uc77c\uc815 \ubcc0\uacbd\uacfc \uac19\uc740 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c\ub3c4 \ud544\uc694\ud55c \ud45c\ud604\uc744 \uc9c1\uc811 \uc0ac\uc6a9\ud574 \ubcf4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc758\uacac\uc774 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc874\uc911\ud558\uba74\uc11c \uc774\uc57c\uae30\ud558\uace0 \ubb38\ud654 \ucc28\uc774\ub85c \uc624\ud574\uac00 \uc0dd\uae30\uba74 \ubc14\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \ud655\uc778\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubcfc \ub54c\ub3c4 \ucd9c\ucc98\uc640 \uacf5\uc2dd \uc790\ub8cc\ub97c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \uacc4\uc18d \uc720\uc9c0\ud558\uaca0\uc2b5\ub2c8\ub2e4.","Nh\u1eefng n\u1ed9i dung h\u1ecdc trong HANNEST 3 kh\xf4ng ch\u1ec9 l\xe0 ti\u1ebfng H\xe0n ph\u1ee5c v\u1ee5 thi m\xe0 c\xf2n c\xf3 nhi\u1ec1u c\xe1ch di\u1ec5n \u0111\u1ea1t c\xf3 th\u1ec3 d\xf9ng trong cu\u1ed9c s\u1ed1ng v\xe0 c\xf4ng vi\u1ec7c th\u1ef1c t\u1ebf. T\u1eeb nay \u1edf c\xf4ng ty t\xf4i mu\u1ed1n luy\u1ec7n vi\u1ec7c x\xe1c nh\u1eadn ch\xednh x\xe1c ch\u1ec9 th\u1ecb v\xe0 khi c\xf3 v\u1ea5n \u0111\u1ec1 th\xec b\xe1o c\xe1o theo th\u1ee9 t\u1ef1 t\xecnh h\xecnh, nguy\xean nh\xe2n v\xe0 n\u1ed9i dung x\u1eed l\xfd. Trong nh\u1eefng t\xecnh hu\u1ed1ng \u0111\u1eddi s\u1ed1ng nh\u01b0 b\u1ec7nh vi\u1ec7n, h\u1ee3p \u0111\u1ed3ng nh\xe0 v\xe0 thay \u0111\u1ed5i l\u1ecbch t\xf4i c\u0169ng mu\u1ed1n tr\u1ef1c ti\u1ebfp s\u1eed d\u1ee5ng nh\u1eefng c\xe1ch n\xf3i c\u1ea7n thi\u1ebft. Ngo\xe0i ra d\xf9 \xfd ki\u1ebfn kh\xe1c nhau t\xf4i s\u1ebd c\u1ed1 n\xf3i chuy\u1ec7n trong s\u1ef1 t\xf4n tr\u1ecdng, v\xe0 n\u1ebfu x\u1ea3y ra hi\u1ec3u l\u1ea7m do kh\xe1c bi\u1ec7t v\u0103n h\xf3a th\xec thay v\xec ph\xe1n \u0111o\xe1n ngay t\xf4i s\u1ebd x\xe1c nh\u1eadn tr\u01b0\u1edbc. Khi th\u1ea5y th\xf4ng tin quan tr\u1ecdng tr\xean Internet t\xf4i c\u0169ng s\u1ebd ti\u1ebfp t\u1ee5c gi\u1eef th\xf3i quen ki\u1ec3m tra ngu\u1ed3n v\xe0 t\xe0i li\u1ec7u ch\xednh th\u1ee9c.")
A.klz=s([A.c7c,A.c7C,A.c7G],t.vH)
A.jVQ=s(["\uc801\uc751\ud558\ub2e4","\uc775\uc219\ud574\uc9c0\ub2e4","\ubb38\ud654 \ucc28\uc774","\uc758\uc0ac\uc18c\ud1b5","\uc9c0\uc2dc","\ubcf4\uace0\ud558\ub2e4","\uc9c4\ud589 \uc0c1\ud669","\ubd88\ub7c9","\ubd88\ub7c9\ub960","\uc6d0\uc778","\uc6d0\uc778\uc744 \ud30c\uc545\ud558\ub2e4","\uc6d0\uc778\uc744 \ubd84\uc11d\ud558\ub2e4","\uc870\uce58\ud558\ub2e4","\ud574\uacb0\ucc45","\uac1c\uc120\ud558\ub2e4","\uc7ac\ubc1c \ubc29\uc9c0","\uc99d\uc0c1","\uc9c4\ub8cc\ub97c \ubc1b\ub2e4","\uacc4\uc57d","\uacc4\uc57d \uc870\uac74","\ubcf4\uc99d\uae08","\uc6d4\uc138","\ud658\ubd88\ud558\ub2e4","\uad50\ud658\ud558\ub2e4","\uc77c\uc815","\uc77c\uc815\uc744 \uc870\uc815\ud558\ub2e4","\uacbd\ud5d8","\uacbd\ud5d8\uc744 \uc313\ub2e4","\ud6c4\ud68c\ud558\ub2e4","\uace0\ubbfc\ud558\ub2e4","\ubd80\ub2f4\uc2a4\ub7fd\ub2e4","\uacf5\uac10\ud558\ub2e4","\uc704\ub85c\ud558\ub2e4","\uc758\uacac","\ucc2c\uc131\ud558\ub2e4","\ubc18\ub300\ud558\ub2e4","\uace0\ub824\ud558\ub2e4","\ub300\uc548","\uaddc\uc815","\uc900\uc218\ud558\ub2e4","\ucc45\uc784","\ucc45\uc784\uc744 \uc9c0\ub2e4","\ubc30\ub824\ud558\ub2e4","\uc874\ub313\ub9d0","\ud638\uce6d","\uc624\ud574","\uc624\ud574\ub97c \ud480\ub2e4","\ucd9c\ucc98","\uac80\uc99d\ud558\ub2e4","\uacf5\uc2dd \uc815\ubcf4","\uac1c\uc778\uc815\ubcf4"],t.s)
A.l9U=s(["V-\ub2e4 \ubcf4\ub2c8","V-\ub2e4 \ubcf4\uba74","V-(\uc73c)\u3139\uae4c \ubd10","V-(\uc73c)\u3134 \uc801\uc774 \uc788\ub2e4","V-\uc544/\uc5b4 \ubcf4\ub2e4","V-(\uc73c)\u3139\uac78 \uadf8\ub7ac\ub2e4","V-\uc9c0 \ub9d0\uac78 \uadf8\ub7ac\ub2e4","V-\ub294 \uac8c \uc5b4\ub54c\uc694?","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","N\uc5d0 \ube44\ud574(\uc11c)","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c","V-\ub294 \uac83\uc774 \ub0ab\ub2e4","V-\uae30 \ub54c\ubb38\uc5d0","V-\ub294 \ubc14\ub78c\uc5d0","V-\ub3c4\ub85d \ud558\ub2e4","V-\uc9c0 \uc54a\ub3c4\ub85d","V-(\uc73c)\u3134 \uacb0\uacfc","V-\uc544/\uc5b4\uc57c \ud558\ub2e4","V-(\uc73c)\uba74 \uc548 \ub418\ub2e4","N\uc5d0 \ub530\ub77c","V/A-\ub354\ub77c\ub3c4","V-\uae30\ubcf4\ub2e4\ub294","V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4","V-(\uc73c)\u3139 \uc218\ub3c4 \uc788\ub2e4"],t.s)
A.lJY=s(["HANNEST 3 \ud575\uc2ec \u2460 \ud55c\uad6d \uc0dd\ud65c\uc5d0 \uc801\uc751\ud558\uba74\uc11c \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \ud544\uc694\ud55c \ud45c\ud604\uc744 \uc0ac\uc6a9\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2461 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc740 \ucd94\uce21\ud558\uc9c0 \ub9d0\uace0 \ud655\uc778\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2462 \uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc9c0\uc2dc \u2192 \ud655\uc778 \u2192 \uc791\uc5c5 \u2192 \ubcf4\uace0\uc758 \ud750\ub984\uc744 \uc775\ud78c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2463 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \uc228\uae30\uc9c0 \ub9d0\uace0 \uc0c1\ud669\uc744 \uc815\ud655\ud788 \ubcf4\uace0\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2464 \ubb38\uc81c \u2192 \uc6d0\uc778 \ubd84\uc11d \u2192 \uc870\uce58 \u2192 \uacb0\uacfc \ud655\uc778 \u2192 \uc7ac\ubc1c \ubc29\uc9c0 \uc21c\uc11c\ub85c \uc0dd\uac01\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2465 \ubcd1\uc6d0\uc5d0\uc11c\ub294 \uc99d\uc0c1\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \uc124\uba85\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2466 \uc9d1 \uacc4\uc57d \uc804\uc5d0\ub294 \ubcf4\uc99d\uae08, \uc6d4\uc138, \uad00\ub9ac\ube44\uc640 \uacc4\uc57d \uc870\uac74\uc744 \ud655\uc778\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2467 \uad6c\ub9e4 \uc804\uc5d0\ub294 \uad50\ud658\xb7\ud658\ubd88 \uaddc\uc815\uc744 \ud655\uc778\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2468 \uc77c\uc815\uc774 \ubc14\ub00c\uac70\ub098 \ub2a6\uc744 \uac83 \uac19\uc73c\uba74 \ubbf8\ub9ac \uc5f0\ub77d\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2469 \uacbd\ud5d8\uacfc \uc2e4\uc218\uc5d0\uc11c \ubc30\uc6b4 \uc810\uc744 \ub2e4\uc74c \ud589\ub3d9\uc5d0 \uc5f0\uacb0\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u246a \uace0\ubbfc\uc774 \uc788\uc744 \ub54c \uc0c1\ud669\uc744 \uc815\ub9ac\ud558\uace0 \ud544\uc694\ud558\uba74 \ub3c4\uc6c0\uc774\ub098 \uc870\uc5b8\uc744 \uc694\uccad\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u246b \ub2e4\ub978 \uc758\uacac\uc744 \ub9d0\ud560 \ub54c\ub294 \uc774\uc720\uc640 \uadfc\uac70\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u246c \uc911\uc694\ud55c \uc120\ud0dd\uc740 \uc7a5\ub2e8\uc810\uacfc \uc120\ud0dd \uae30\uc900\uc744 \ube44\uad50\ud55c \ud6c4 \uacb0\uc815\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u246d \uaddc\uc815\uacfc \uc548\uc804 \uc218\uce59\uc744 \uc900\uc218\ud558\uace0 \uc790\uc2e0\uc758 \uc5c5\ubb34\uc5d0 \ucc45\uc784\uc744 \uc9c4\ub2e4.","HANNEST 3 \ud575\uc2ec \u246e \ubb38\ud654\uac00 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc744 \ubc14\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294\ub2e4.","HANNEST 3 \ud575\uc2ec \u246f \uc624\ud574\uac00 \uc0dd\uae30\uba74 \uc9c1\uc811 \ud655\uc778\ud558\uace0 \ub300\ud654\ub97c \ud1b5\ud574 \ud47c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2470 \uc778\ud130\ub137 \uc815\ubcf4\ub294 \ucd9c\ucc98\uc640 \ub0a0\uc9dc\ub97c \ud655\uc778\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2471 \uc911\uc694\ud55c \uc815\ubcf4\ub294 \uacf5\uc2dd \uc790\ub8cc\uc640 \ube44\uad50\ud574\uc11c \uac80\uc99d\ud55c\ub2e4.","HANNEST 3 \ud575\uc2ec \u2472 \uac1c\uc778\uc815\ubcf4\uc640 \ud68c\uc0ac \ub0b4\ubd80 \uc815\ubcf4\ub97c \ud568\ubd80\ub85c \uacf5\uc720\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc801\uc751\ud558\ub2e4 = th\xedch nghi","\uc758\uc0ac\uc18c\ud1b5 = giao ti\u1ebfp","\ubcf4\uace0\ud558\ub2e4 = b\xe1o c\xe1o","\ubd88\ub7c9 = l\u1ed7i s\u1ea3n ph\u1ea9m","\uc6d0\uc778 = nguy\xean nh\xe2n","\uc870\uce58\ud558\ub2e4 = x\u1eed l\xfd","\uc7ac\ubc1c \ubc29\uc9c0 = ph\xf2ng t\xe1i di\u1ec5n","\uc99d\uc0c1 = tri\u1ec7u ch\u1ee9ng","\uacc4\uc57d = h\u1ee3p \u0111\u1ed3ng","\ubcf4\uc99d\uae08 = ti\u1ec1n \u0111\u1eb7t c\u1ecdc","\ud658\ubd88\ud558\ub2e4 = ho\xe0n ti\u1ec1n","\uc77c\uc815 = l\u1ecbch tr\xecnh","\uacbd\ud5d8 = kinh nghi\u1ec7m","\ud6c4\ud68c\ud558\ub2e4 = h\u1ed1i ti\u1ebfc","\uace0\ubbfc\ud558\ub2e4 = b\u0103n kho\u0103n","\uacf5\uac10\ud558\ub2e4 = \u0111\u1ed3ng c\u1ea3m","\uc758\uacac = \xfd ki\u1ebfn","\uace0\ub824\ud558\ub2e4 = c\xe2n nh\u1eafc","\ub300\uc548 = ph\u01b0\u01a1ng \xe1n thay th\u1ebf","\uaddc\uc815 = quy \u0111\u1ecbnh","\ucc45\uc784 = tr\xe1ch nhi\u1ec7m","\ubc30\ub824\ud558\ub2e4 = quan t\xe2m ng\u01b0\u1eddi kh\xe1c","\uc624\ud574 = hi\u1ec3u l\u1ea7m","\ucd9c\ucc98 = ngu\u1ed3n th\xf4ng tin","\uac80\uc99d\ud558\ub2e4 = ki\u1ec3m ch\u1ee9ng","\uac1c\uc778\uc815\ubcf4 = th\xf4ng tin c\xe1 nh\xe2n","V-\ub2e4 \ubcf4\ub2c8 = c\u1ee9 l\xe0m r\u1ed3i d\u1ea7n nh\u1eadn ra","V-(\uc73c)\u3139\uae4c \ubd10 = lo r\u1eb1ng","V-(\uc73c)\u3139\uac78 \uadf8\ub7ac\ub2e4 = gi\xe1 m\xe0 \u0111\xe3...","V-\ub294 \uac8c \uc5b4\ub54c\uc694? = th\u1eed... th\xec sao?","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/ng\u01b0\u1ee3c l\u1ea1i","V-\uc9c0 \uc54a\ub3c4\ub85d = \u0111\u1ec3 kh\xf4ng...","V-(\uc73c)\u3134 \uacb0\uacfc = k\u1ebft qu\u1ea3 sau khi...","V-\uae30\ubcf4\ub2e4\ub294 = thay v\xec...","\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub2e4 \ubcf4\ub2c8 \ud55c\uad6d\uc5b4\uc640 \ubb38\ud654\uc5d0 \ub9ce\uc774 \uc775\uc219\ud574\uc84c\uc2b5\ub2c8\ub2e4.","\uc2e4\uc218\ud560\uae4c \ubd10 \uc791\uc5c5 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\uadf8\ub54c \ub354 \uc5f4\uc2ec\ud788 \uc900\ube44\ud560\uac78 \uadf8\ub7ac\uc2b5\ub2c8\ub2e4.","\ud63c\uc790 \uace0\ubbfc\ud558\uc9c0 \ub9d0\uace0 \uc774\uc57c\uae30\ud574 \ubcf4\ub294 \uac8c \uc5b4\ub54c\uc694?","A\uc548\uc740 \ube44\uc6a9\uc774 \ub0ae\uc740 \ubc18\uba74\uc5d0 \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9bd\ub2c8\ub2e4.","\uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub3c4\ub85d \ub300\ucc45\uc744 \uc138\uc6e0\uc2b5\ub2c8\ub2e4.","\uc7a5\ube44\ub97c \uc810\uac80\ud55c \uacb0\uacfc \uc13c\uc11c\uc5d0 \ubb38\uc81c\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.","\ud63c\uc790 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","HANNEST 3\uc758 \ubaa9\ud45c\ub294 \uc678\uc6b4 \ud55c\uad6d\uc5b4\ub97c \uc2e4\uc81c \uc0dd\ud65c\uacfc \uc9c1\uc7a5\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud55c\uad6d\uc5b4\ub85c \uc5f0\uacb0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4."],t.s)
A.L1=new B.hT(20,"\uc885\ud569 \ubcf5\uc2b5","T\u1ed5ng \xf4n HANNEST 3","\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \ubc30\uc6b4 \ubb38\uc81c \ud574\uacb0 \ubc29\ubc95","\ubbfc \uc528\ub294 \ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\uace0 \uc77c\ud558\uba74\uc11c \uc5ec\ub7ec \uac00\uc9c0 \ubb38\uc81c\ub97c \uacbd\ud5d8\ud588\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub9d0\uc744 \uc798 \uc774\ud574\ud558\uc9c0 \ubabb\ud574 \uc5c5\ubb34 \uc9c0\uc2dc\ub97c \ub193\uce58\uae30\ub3c4 \ud588\uace0, \ubb38\ud654 \ucc28\uc774 \ub54c\ubb38\uc5d0 \ub3d9\ub8cc\uc758 \ud589\ub3d9\uc744 \uc624\ud574\ud55c \uc801\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc608\uc804\uc5d0\ub294 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ud63c\uc790 \ube68\ub9ac \ud574\uacb0\ud558\ub824\uace0 \ud588\uc9c0\ub9cc \uc624\ud788\ub824 \uc0c1\ud669\uc774 \ub354 \ubcf5\uc7a1\ud574\uc9c0\ub294 \uacbd\uc6b0\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \ubbfc \uc528\ub294 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uc9c4\ud589 \uc0c1\ud669\uc744 \ubbf8\ub9ac \ubcf4\uace0\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc600\uc2b5\ub2c8\ub2e4. \uc9d1 \uacc4\uc57d\uc774\ub098 \ud589\uc815 \uc5c5\ubb34\ub97c \ud560 \ub54c\uc5d0\ub294 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc744 \uadf8\ub0e5 \ub118\uae30\uc9c0 \uc54a\uace0 \ud544\uc694\ud55c \uc11c\ub958\uc640 \uc870\uac74\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ubb38\uc81c\uc758 \ud604\uc0c1\uacfc \uc6d0\uc778\uc744 \uad6c\ubd84\ud558\uace0, \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc758\uacac\uc744 \ub4e4\uc740 \ub4a4 \ud574\uacb0\ucc45\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4. \uc2e4\uc218\ub97c \uc804\ud600 \ud558\uc9c0 \uc54a\ub294 \uac83\ubcf4\ub2e4 \uc2e4\uc218\uc5d0\uc11c \ubc30\uc6b4 \ub0b4\uc6a9\uc744 \ub2e4\uc74c \ud589\ub3d9\uc5d0 \uc801\uc6a9\ud558\ub294 \ud0dc\ub3c4\uac00 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4.","Min \u0111\xe3 g\u1eb7p kh\xf3 kh\u0103n v\u1ec1 ch\u1ec9 th\u1ecb c\xf4ng vi\u1ec7c, kh\xe1c bi\u1ec7t v\u0103n h\xf3a, h\u1ee3p \u0111\u1ed3ng, th\u1ee7 t\u1ee5c v\xe0 th\xf4ng tin tr\xean m\u1ea1ng. Sau \u0111\xf3 anh h\xecnh th\xe0nh th\xf3i quen x\xe1c nh\u1eadn, b\xe1o c\xe1o s\u1edbm, ki\u1ec3m tra \u0111i\u1ec1u ki\u1ec7n v\xe0 ngu\u1ed3n tin. \u0110i\u1ec1u quan tr\u1ecdng kh\xf4ng ph\u1ea3i l\xe0 kh\xf4ng bao gi\u1edd sai m\xe0 l\xe0 \xe1p d\u1ee5ng b\xe0i h\u1ecdc v\xe0o h\xe0nh \u0111\u1ed9ng ti\u1ebfp theo.",A.lRj,A.jCJ,A.jlL,A.ll7,A.lAW,A.jja,A.lNn,A.jL9,A.jDO,A.klz,A.jVQ,A.l9U,A.lJY)
A.lcP=s(["\ub208\uc55e\uc758 \ud604\uc0c1: \uc9c0\uae08 \ubc14\ub85c \ubcf4\uc774\ub294 \ubb38\uc81c\uc758 \uc0c1\ud0dc","\uc694\uc18c: \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub294 \ubd80\ubd84","\uc7a5\uae30\uc801\uc73c\ub85c: \uae34 \uc2dc\uac04\uc744 \uae30\uc900\uc73c\ub85c \uc0dd\uac01\ud588\uc744 \ub54c"],t.s)
A.k7S=s(["\ud604\uc0c1, \uc6d0\uc778, \uc870\uce58\uc640 \uacb0\uacfc\ub97c \uad6c\ubd84\ud574\uc11c \ubd84\uc11d\ud560 \uc218 \uc788\uc5b4\uc694.","\uc5ec\ub7ec \uc790\ub8cc\ub97c \uadfc\uac70\ub85c \ubb38\uc81c\uc758 \uc6d0\uc778\uc744 \uc124\uba85\ud560 \uc218 \uc788\uc5b4\uc694.","\uc784\uc2dc \uc870\uce58\uc640 \uc7a5\uae30\uc801\uc778 \uac1c\uc120\ucc45\uc744 \ube44\uad50\ud574\uc11c \uc81c\uc548\ud560 \uc218 \uc788\uc5b4\uc694.","\ud574\uacb0\ucc45\uc758 \ud6a8\uacfc\ub97c \ud3c9\uac00\ud558\uace0 \ub2e4\uc74c \uc870\uce58\ub97c \uacb0\uc815\ud560 \uc218 \uc788\uc5b4\uc694.","H\u1ecdc c\xe1ch m\xf4 t\u1ea3 m\u1ed9t v\u1ea5n \u0111\u1ec1 \u0111\xe3 ph\xe1t sinh trong c\xf4ng vi\u1ec7c v\xe0 cu\u1ed9c s\u1ed1ng.","H\u1ecdc c\xe1ch ph\xe2n bi\u1ec7t hi\u1ec7n t\u01b0\u1ee3ng, nguy\xean nh\xe2n v\xe0 k\u1ebft qu\u1ea3.","H\u1ecdc c\xe1ch t\xecm v\xe0 tr\xecnh b\xe0y nguy\xean nh\xe2n c\u1ee7a m\u1ed9t l\u1ed7i.","H\u1ecdc c\xe1ch b\xe1o c\xe1o v\u1ea5n \u0111\u1ec1 cho c\u1ea5p tr\xean ho\u1eb7c \u0111\u1ed3ng nghi\u1ec7p m\u1ed9t c\xe1ch r\xf5 r\xe0ng.","H\u1ecdc c\xe1ch \u0111\u1ec1 xu\u1ea5t bi\u1ec7n ph\xe1p x\u1eed l\xfd ngay khi v\u1ea5n \u0111\u1ec1 x\u1ea3y ra.","H\u1ecdc c\xe1ch n\xf3i v\u1ec1 bi\u1ec7n ph\xe1p c\u1ea3i ti\u1ebfn \u0111\u1ec3 tr\xe1nh l\u1ed7i l\u1eb7p l\u1ea1i.","H\u1ecdc c\xe1c t\u1eeb th\u01b0\u1eddng d\xf9ng trong nh\xe0 m\xe1y nh\u01b0 \ubd88\ub7c9, \uc6d0\uc778, \uc870\uce58, \uc810\uac80, \uc7ac\ubc1c.","H\u1ecdc c\xe1ch ph\xe2n t\xedch v\u1ea5n \u0111\u1ec1 theo tr\xecnh t\u1ef1: \ubb38\uc81c \u2192 \uc6d0\uc778 \u2192 \uc870\uce58 \u2192 \uacb0\uacfc \u2192 \uc608\ubc29.","H\u1ecdc c\xe1ch tr\xecnh b\xe0y nhi\u1ec1u nguy\xean nh\xe2n v\xe0 l\u1ef1a ch\u1ecdn gi\u1ea3i ph\xe1p ph\xf9 h\u1ee3p.","Luy\u1ec7n h\u1ed9i tho\u1ea1i th\u1ef1c t\u1ebf khi b\xe1o l\u1ed7i s\u1ea3n ph\u1ea9m, m\xe1y m\xf3c v\xe0 ti\u1ebfn \u0111\u1ed9 c\xf4ng vi\u1ec7c."],t.s)
