A.bZ0=new B.dh("\uc628\ub77c\uc778\uc73c\ub85c \ubc1b\uc740 \uc0c1\ud488\uc774 \ud30c\uc190\ub410\uc744 \ub54c \uace0\uac1d\uc13c\ud130\uc5d0 \ubb38\uc758\ud574 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \uc624\ub298 \uc8fc\ubb38\ud55c \uc0c1\ud488\uc744 \ubc1b\uc558\ub294\ub370 \ubb38\uc81c\uac00 \uc788\uc5b4\uc11c \ubb38\uc758\ub4dc\ub9bd\ub2c8\ub2e4. \ud0dd\ubc30 \uc0c1\uc790\ub97c \uc5f4\uc790\ub9c8\uc790 \ud655\uc778\ud588\ub294\ub370 \uc81c\ud488 \ud55c\ucabd\uc774 \ud30c\uc190\ub418\uc5b4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc774\uace0 \ud30c\uc190\ub41c \ubd80\ubd84\uc758 \uc0ac\uc9c4\ub3c4 \ucc0d\uc5b4 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \uc8fc\ubb38 \ubc88\ud638\ub294 12345\uc785\ub2c8\ub2e4. \uad50\ud658\uc774\ub098 \ud658\ubd88\uc774 \uac00\ub2a5\ud55c\uc9c0 \ud655\uc778\ud574 \uc8fc\uc2dc\uaca0\uc5b4\uc694?")
A.nr2=s(["\uba87 \uac1c \uc8fc\ubb38","\uba87 \uac1c \ub3c4\ucc29","\uc8fc\ubb38 \ub0b4\uc5ed","\ub204\ub77d","\ucd94\uac00 \ubc30\uc1a1"],t.s)
A.bYX=new B.dh("\uc8fc\ubb38\ud55c \uc0c1\ud488\uc774 \ub204\ub77d\ub410\uc744 \ub54c \uc0c1\ud669\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\uc800\ub294 \uac19\uc740 \uc0c1\ud488\uc744 \uc138 \uac1c \uc8fc\ubb38\ud588\ub294\ub370 \uc624\ub298 \ud0dd\ubc30\ub97c \ud655\uc778\ud574 \ubcf4\ub2c8 \ub450 \uac1c\ub9cc \ub4e4\uc5b4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc571\uc758 \uc8fc\ubb38 \ub0b4\uc5ed\uc5d0\ub294 \uc138 \uac1c\ub85c \ud45c\uc2dc\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ud3ec\uc7a5 \uacfc\uc815\uc5d0\uc11c \ud55c \uac1c\uac00 \ub204\ub77d\ub41c \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc8fc\ubb38 \ub0b4\uc5ed\uc744 \ud655\uc778\ud574 \uc8fc\uc2dc\uace0 \ub204\ub77d\ub41c \uc0c1\ud488\uc744 \ucd94\uac00\ub85c \ubcf4\ub0b4 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?")
