A.bYQ=new B.dh("\ud300\uc7a5\ub2d8\uc5d0\uac8c \uc624\ub298 \uc791\uc5c5 \uc9c4\ud589 \uc0c1\ud669\uc744 \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.","\uc624\ub298 \uc791\uc5c5 \uc218\ub7c9\uc740 \ucd1d 300\uac1c\uc785\ub2c8\ub2e4. \ud604\uc7ac 220\uac1c\uae4c\uc9c0 \uc644\ub8cc\ud588\uace0 \ub098\uba38\uc9c0 80\uac1c\ub294 \uc9c4\ud589 \uc911\uc785\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \ubb38\uc81c\uac00 \uc5c6\uc73c\uba74 \uc624\ud6c4 4\uc2dc 30\ubd84\uae4c\uc9c0 \ubaa8\ub450 \uc644\ub8cc\ud560 \uc608\uc815\uc785\ub2c8\ub2e4. \uc791\uc5c5\uc774 \ub05d\ub098\ub294 \ub300\ub85c \ub2e4\uc2dc \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.nqd=s(["\ubd88\ub7c9","\uc218\ub7c9","\uc791\uc5c5 \uc911\uc9c0","\uc6d0\uc778","\uc870\uce58"],t.s)
A.bYS=new B.dh("\uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \ubc1c\uacac\ub410\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\uae4c?","A\uc81c\ud488\uc744 \uac80\uc0ac\ud558\ub294 \uc911\uc5d0 \ubd88\ub7c9\uc774 3\uac1c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4. \uce58\uc218\uac00 \uae30\uc900\ubcf4\ub2e4 \ud06c\uac8c \ub098\uc640\uc11c \ud604\uc7ac \uc791\uc5c5\uc744 \uc911\uc9c0\ud588\uc2b5\ub2c8\ub2e4. \ubd88\ub7c9\ud488\uc740 \ub530\ub85c \ubd84\ub9ac\ud574 \ub193\uc558\uace0 \uc9c0\uae08 \uc6d0\uc778\uc744 \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc6d0\uc778\uc774 \ud655\uc778\ub418\ub294 \ub300\ub85c \ub2e4\uc2dc \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.nsf=s(["\uc608\uc0c1\ubcf4\ub2e4","\uc9c0\uc5f0","\uc6d0\uc778","\uc2dc\uac04","\uc644\ub8cc"],t.s)
A.bZa=new B.dh("\uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c8 \ub54c \uc0c1\uc0ac\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub9d0\ud558\uaca0\uc2b5\ub2c8\uae4c?","\uc8c4\uc1a1\ud558\uc9c0\ub9cc \uc608\uc0c1\ubcf4\ub2e4 \uc791\uc5c5\uc774 \uc870\uae08 \uc9c0\uc5f0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uacc4 \uc810\uac80\uc5d0 \uc2dc\uac04\uc774 \uac78\ub824\uc11c \ud604\uc7ac \uc57d 30\ubd84 \uc815\ub3c4 \ub2a6\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uc624\ud6c4 5\uc2dc\uae4c\uc9c0\ub294 \uc644\ub8cc\ud560 \uc218 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
A.kcg=s([A.bYQ,A.bYS,A.bZa],t.Pe)
A.nqj=s(["\uc804\uccb4 \uc791\uc5c5\ub7c9\uc744 \uc4f0\uc138\uc694.","\ud604\uc7ac \uc644\ub8cc\ub41c \uc218\ub7c9\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \uc788\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc644\ub8cc \uc608\uc815 \uc2dc\uac04\uc744 \uc4f0\uc138\uc694.","-(\uc73c)\u3139 \uc608\uc815\uc785\ub2c8\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.c7F=new B.ei("\uc624\ub298 \uc5c5\ubb34 \uc9c4\ud589 \uc0c1\ud669 \ubcf4\uace0\uc11c\ub97c \uac04\ub2e8\ud788 \uc368 \ubcf4\uc138\uc694.","\uc624\ub298 A\uc81c\ud488 \uc791\uc5c5 \ubaa9\ud45c\ub294 \ucd1d 500\uac1c\uc785\ub2c8\ub2e4. \ud604\uc7ac 350\uac1c\uae4c\uc9c0 \uc644\ub8cc\ud588\uace0 150\uac1c\ub294 \uc791\uc5c5 \uc911\uc785\ub2c8\ub2e4. \uc624\uc804\uc5d0 \uae30\uacc4 \uc810\uac80 \ub54c\ubb38\uc5d0 \uc57d 20\ubd84 \uc815\ub3c4 \uc791\uc5c5\uc774 \uc9c0\uc5f0\ub410\uc9c0\ub9cc \ud604\uc7ac\ub294 \uc815\uc0c1\uc801\uc73c\ub85c \uc9c4\ud589\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \ubb38\uc81c\uac00 \uc5c6\uc73c\uba74 \uc624\ud6c4 5\uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \uc791\uc5c5\uc744 \uc644\ub8cc\ud560 \uc608\uc815\uc785\ub2c8\ub2e4.","M\u1ee5c ti\xeau c\xf4ng vi\u1ec7c s\u1ea3n ph\u1ea9m A h\xf4m nay l\xe0 t\u1ed5ng c\u1ed9ng 500 c\xe1i. Hi\u1ec7n \u0111\xe3 ho\xe0n th\xe0nh 350 c\xe1i v\xe0 150 c\xe1i \u0111ang \u0111\u01b0\u1ee3c s\u1ea3n xu\u1ea5t. Bu\u1ed5i s\xe1ng c\xf4ng vi\u1ec7c b\u1ecb ch\u1eadm kho\u1ea3ng 20 ph\xfat do ki\u1ec3m tra m\xe1y nh\u01b0ng hi\u1ec7n \u0111ang ti\u1ebfn h\xe0nh b\xecnh th\u01b0\u1eddng. N\u1ebfu kh\xf4ng c\xf3 v\u1ea5n \u0111\u1ec1 \u0111\u1eb7c bi\u1ec7t, d\u1ef1 ki\u1ebfn to\xe0n b\u1ed9 c\xf4ng vi\u1ec7c s\u1ebd ho\xe0n th\xe0nh tr\u01b0\u1edbc 5 gi\u1edd chi\u1ec1u.")
A.nqB=s(["\uc5b8\uc81c \ubc1c\uacac\ud588\ub294\uc9c0 \uc4f0\uc138\uc694.","\ubd88\ub7c9 \uc218\ub7c9\uc744 \uc4f0\uc138\uc694.","\ubd88\ub7c9 \ub0b4\uc6a9\uc744 \uc124\uba85\ud558\uc138\uc694.","\ud604\uc7ac \uc870\uce58 \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","-\ub294 \ub300\ub85c \ub610\ub294 -\uc544/\uc5b4 \ub193\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.c7u=new B.ei("\ubd88\ub7c9 \ubc1c\uc0dd \ubcf4\uace0\ub97c \uc791\uc131\ud574 \ubcf4\uc138\uc694.","\uc624\ub298 \uc624\uc804 10\uc2dc\uacbd A\uc81c\ud488\uc744 \uac80\uc0ac\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ubd88\ub7c9 5\uac1c\ub97c \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4. \ubd88\ub7c9 \uc81c\ud488\uc740 \ubaa8\ub450 \uce58\uc218\uac00 \uae30\uc900\ubcf4\ub2e4 \ud06c\uac8c \uce21\uc815\ub410\uc2b5\ub2c8\ub2e4. \ubc1c\uacac \uc989\uc2dc \uc791\uc5c5\uc744 \uc911\uc9c0\ud588\uace0 \ubd88\ub7c9\ud488\uc740 \uc815\uc0c1 \uc81c\ud488\uacfc \uc11e\uc774\uc9c0 \uc54a\ub3c4\ub85d \ub530\ub85c \ubd84\ub9ac\ud574 \ub193\uc558\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc124\ube44\uc640 \uacf5\uc815 \uc870\uac74\uc744 \ud655\uc778\ud558\uace0 \uc788\uc73c\uba70 \uc6d0\uc778\uc774 \ud655\uc778\ub418\ub294 \ub300\ub85c \ud300\uc7a5\ub2d8\uaed8 \ub2e4\uc2dc \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\ub2e4.","Kho\u1ea3ng 10 gi\u1edd s\xe1ng h\xf4m nay, trong qu\xe1 tr\xecnh ki\u1ec3m tra s\u1ea3n ph\u1ea9m A \u0111\xe3 ph\xe1t hi\u1ec7n 5 s\u1ea3n ph\u1ea9m l\u1ed7i. T\u1ea5t c\u1ea3 c\xe1c s\u1ea3n ph\u1ea9m l\u1ed7i \u0111\u1ec1u c\xf3 k\xedch th\u01b0\u1edbc \u0111o \u0111\u01b0\u1ee3c l\u1edbn h\u01a1n ti\xeau chu\u1ea9n. Ngay khi ph\xe1t hi\u1ec7n t\xf4i \u0111\xe3 d\u1eebng c\xf4ng vi\u1ec7c v\xe0 t\xe1ch ri\xeang h\xe0ng l\u1ed7i \u0111\u1ec3 kh\xf4ng b\u1ecb l\u1eabn v\u1edbi s\u1ea3n ph\u1ea9m b\xecnh th\u01b0\u1eddng. Hi\u1ec7n \u0111ang ki\u1ec3m tra thi\u1ebft b\u1ecb v\xe0 \u0111i\u1ec1u ki\u1ec7n c\xf4ng \u0111o\u1ea1n, v\xe0 ngay khi x\xe1c \u0111\u1ecbnh \u0111\u01b0\u1ee3c nguy\xean nh\xe2n t\xf4i s\u1ebd b\xe1o c\xe1o l\u1ea1i v\u1edbi tr\u01b0\u1edfng nh\xf3m.")
A.lqD=s([A.c7F,A.c7u],t.vH)
A.jTm=s(["\uc5c5\ubb34","\uc5c5\ubb34 \uc9c0\uc2dc","\uc9c0\uc2dc\uc5d0 \ub530\ub974\ub2e4","\ub2f4\ub2f9\ud558\ub2e4","\ub2f4\ub2f9\uc790","\uc791\uc5c5 \uc21c\uc11c","\uc6b0\uc120\uc21c\uc704","\uc644\ub8cc\ud558\ub2e4","\ubbf8\uc644\ub8cc","\uc9c4\ud589\ud558\ub2e4","\uc9c4\ud589 \uc911","\ubcf4\uace0\ud558\ub2e4","\ubcf4\uace0 \ub0b4\uc6a9","\ud604\ud669","\ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\ub2e4","\uc774\uc0c1\uc774 \uc788\ub2e4","\ubd88\ub7c9","\ubd88\ub7c9\ud488","\ubd88\ub7c9\ub960","\uc870\uce58\ud558\ub2e4","\uc870\uce58 \uacb0\uacfc","\uc6d0\uc778","\uc608\uc0c1\ud558\ub2e4","\uc608\uc815","\uc9c0\uc5f0\ub418\ub2e4","\uae30\ud55c","\uc5f0\uc7a5\ud558\ub2e4","\uc989\uc2dc"],t.s)
