A.cUR=new B.al("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc624\ub298 \uc624\uc804\uc5d0 \uac80\uc0ac \ubb3c\ub7c9\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc774 \ub298\uc5c8\uc2b5\ub2c8\ub2e4. \uac80\uc0ac\ud300\uc740 \uc6d0\ub798 \uc138 \uba85\uc774 \uadfc\ubb34\ud560 \uc608\uc815\uc774\uc5c8\uc9c0\ub9cc \ud55c \uba85\uc774 \uacb0\uadfc\ud588\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc18d\ub3c4\ub85c \uc791\uc5c5\ud560 \uacbd\uc6b0 \uc624\ud6c4 \ucd9c\ud558 \uc77c\uc815\uc774 \ub2a6\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub2f4\ub2f9\uc790\ub294 \uc624\uc804 10\uc2dc\uc5d0 \ud300\uc7a5\uc5d0\uac8c \uc0c1\ud669\uc744 \ubcf4\uace0\ud588\uace0 \uc0dd\uc0b0\ud300\uc5d0\uc11c \ud55c \uba85\uc744 \uc9c0\uc6d0\ubc1b\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.kfj,2,"Ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch \u0111\xe3 b\xe1o s\u1edbm t\xecnh h\xecnh v\xe0 nh\u1eadn h\u1ed7 tr\u1ee3 t\u1eeb \u0111\u1ed9i s\u1ea3n xu\u1ea5t.","\uc77d\uae30")
A.kHH=s(["\uadf8\ub0e5 \ud558\uace0 \uc788\uc5b4\uc694.","\ud604\uc7ac \uc57d 70\ud37c\uc13c\ud2b8 \uc644\ub8cc\ud588\uace0 \uc624\ud6c4 \uc138 \uc2dc\ucbe4 \ub9c8\uce60 \uc608\uc815\uc785\ub2c8\ub2e4.","\ubab0\ub77c\uc694.","\ub2e4\ub978 \uc0ac\ub78c\uc774 \ud560 \uac70\uc608\uc694."],t.s)
A.cUi=new B.al("\ud300\uc7a5\uc774 \u201c\uc9c4\ud589 \uc0c1\ud669\uc774 \uc5b4\ub5bb\uac8c \ub410\uc5b4\uc694?\u201d\ub77c\uace0 \ubb3c\uc5c8\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc88b\uc740 \ub300\ub2f5\uc740?",A.kHH,1,"B\xe1o ti\u1ebfn \u0111\u1ed9 t\u1ed1t n\xean c\xf3 m\u1ee9c ho\xe0n th\xe0nh v\xe0 th\u1eddi gian d\u1ef1 ki\u1ebfn.","\uc2e4\uc81c \uc0c1\ud669")
A.jTP=s(["\ub2f4\ub2f9\uc790\ub97c \uba85\ud655\ud558\uac8c \uc815\ud55c\ub2e4.","\uc9c4\ud589 \uc0c1\ud669\uc744 \uacf5\uc720\ud55c\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uad00\ub828\uc790\uc640 \ud611\uc758\ud55c\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uaca8\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc601\ud5a5\uc744 \uc904 \ub54c\uae4c\uc9c0 \uc54c\ub9ac\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.cW2=new B.al("\ud6a8\uc728\uc801\uc778 \ud611\uc5c5 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.jTP,3,"Che gi\u1ea5u th\xf4ng tin \u0111\u1ebfn khi \u1ea3nh h\u01b0\u1edfng ng\u01b0\u1eddi kh\xe1c s\u1ebd l\xe0m ph\u1ed1i h\u1ee3p k\xe9m h\u01a1n.","\uc885\ud569")
