A.l4u=s(["\uae08\uc561\uc744 \ub354 \ud06c\uac8c \ubcf4\ub0b8\ub2e4.","\uc774\ub984\uc740 \uc911\uc694\ud558\uc9c0 \uc54a\uc73c\ub2c8 \ubcf4\ub0b8\ub2e4.","\ud55c \ubc88 \ubcf4\ub0b4 \ubcf4\uace0 \ub098\uc911\uc5d0 \ud655\uc778\ud55c\ub2e4.","\uc1a1\uae08\uc744 \uc911\ub2e8\ud558\uace0 \uacc4\uc88c \uc815\ubcf4\ub97c \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4."],t.s)
A.cVh=new B.al("\uc1a1\uae08\ud558\ub824\uace0 \ubcf4\ub2c8 \uc608\uae08\uc8fc \uc774\ub984\uc774 \uc608\uc0c1\uacfc \ub2e4\ub985\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740?",A.l4u,3,"Th\xf4ng tin ng\u01b0\u1eddi nh\u1eadn kh\xe1c d\u1ef1 ki\u1ebfn th\xec n\xean d\u1eebng giao d\u1ecbch v\xe0 x\xe1c minh.","\uac70\ub798")
A.kVC=s(["\ubb34\uc870\uac74 \uc0ad\uc81c\ud55c\ub2e4.","\uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4.","\uac70\ub798 \uc2dc\uac04, \uae08\uc561\uacfc \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uacf5\uc2dd \uacbd\ub85c\ub85c \ubb38\uc758\ud55c\ub2e4.","\ubc14\ub85c \ub2e4\ub978 \uacc4\uc88c\ub85c \uc804\uc561 \uc1a1\uae08\ud55c\ub2e4."],t.s)
A.cVN=new B.al("\uac70\ub798 \ub0b4\uc5ed\uc5d0\uc11c \uae30\uc5b5\ud558\uc9c0 \ubabb\ud558\ub294 \ucd9c\uae08\uc744 \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.kVC,2,"Tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c \u0111\u1ecbnh ch\xednh x\xe1c n\u1ed9i dung giao d\u1ecbch v\xe0 d\xf9ng k\xeanh ch\xednh th\u1ee9c \u0111\u1ec3 h\u1ecfi khi c\u1ea7n.","\uc774\uc0c1 \uac70\ub798")
A.lB1=s(["\ube44\ubc00\ubc88\ud638\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uacfc \uacf5\uc720\ud55c\ub2e4.","\uc911\uc694\ud55c \uc815\ubcf4\ub97c \uc785\ub825\ud558\uae30 \uc804\uc5d0 \uc0ac\uc774\ud2b8\uc640 \uc694\uccad \ucd9c\ucc98\ub97c \ud655\uc778\ud55c\ub2e4.","\ubaa8\ub4e0 \uc778\uc99d \ubc88\ud638\ub97c \uba54\ubaa8\ud574\uc11c \uacf5\uac1c\ub41c \uacf3\uc5d0 \ub454\ub2e4.","\ubaa8\ub974\ub294 \uc0ac\ub78c\uc774 \uc694\uccad\ud574\ub3c4 \ubc14\ub85c \uc54c\ub824 \uc900\ub2e4."],t.s)
A.cX4=new B.al("\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.lB1,1,"C\u1ea7n ki\u1ec3m tra ngu\u1ed3n y\xeau c\u1ea7u tr\u01b0\u1edbc khi nh\u1eadp th\xf4ng tin nh\u1ea1y c\u1ea3m.","\uac1c\uc778\uc815\ubcf4")
A.lRL=s(["\uac70\ub798 \uc804 \ubc1b\ub294 \uc0ac\ub78c \uc815\ubcf4\ub97c \ud655\uc778\ud55c\ub2e4.","\uac70\ub798 \ub0b4\uc5ed\uc744 \uc815\uae30\uc801\uc73c\ub85c \ud655\uc778\ud55c\ub2e4.","\uc758\uc2ec\uc2a4\ub7ec\uc6b4 \uc694\uccad\uc740 \uacf5\uc2dd \uacbd\ub85c\ub85c \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc774 \uae09\ud558\ub2e4\uace0 \ud558\uba74 \ud655\uc778 \uc808\ucc28\ub97c \uc0dd\ub7b5\ud55c\ub2e4."],t.s)
A.cTQ=new B.al("\uae08\uc735 \uc704\ud5d8\uc744 \uc904\uc774\ub294 \ud589\ub3d9\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.lRL,3,"Kh\xf4ng n\xean b\u1ecf b\u01b0\u1edbc x\xe1c minh ch\u1ec9 v\xec ng\u01b0\u1eddi kh\xe1c n\xf3i t\xecnh hu\u1ed1ng g\u1ea5p.","\uc704\ud5d8 \uad00\ub9ac")
A.k4u=s(["\ubcf4\uc774\uc2a4\ud53c\uc2f1","\uc790\ub3d9\uc774\uccb4","\uae09\uc5ec \uba85\uc138","\uc815\uae30 \uc608\uae08"],t.s)
A.cTJ=new B.al("\uc804\ud654\ub85c \uae30\uad00\uc774\ub098 \uac00\uc871 \ub4f1\uc744 \uc0ac\uce6d\ud574\uc11c \ub3c8\uc774\ub098 \uc815\ubcf4\ub97c \uc694\uad6c\ud558\ub294 \uc0ac\uae30 \uc720\ud615\uc744 \uc77c\ubc18\uc801\uc73c\ub85c \ubb34\uc5c7\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\uae4c?",A.k4u,0,"\ubcf4\uc774\uc2a4\ud53c\uc2f1 = h\xecnh th\u1ee9c l\u1eeba \u0111\u1ea3o qua \u0111i\u1ec7n tho\u1ea1i b\u1eb1ng c\xe1ch m\u1ea1o danh ho\u1eb7c thao t\xfang ng\u01b0\u1eddi nghe.","\uc5b4\ud718")
A.lWu=s(["\uc218\uc9c4 \uc528\ub294 \ubb38\uc790 \ub9c1\ud06c\uc5d0\uc11c \ubc14\ub85c \uc778\uc99d\ud588\uc2b5\ub2c8\ub2e4.","\uae08\uc735 \uae30\uad00 \uc774\ub984\uc774 \uc788\uc5b4\uc11c \ubb34\uc870\uac74 \ubb38\uc790\ub97c \ubbff\uc5c8\uc2b5\ub2c8\ub2e4.","\uc218\uc9c4 \uc528\ub294 \ubb38\uc790 \ub9c1\ud06c \ub300\uc2e0 \uacf5\uc2dd \uacbd\ub85c\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\uc218\uc9c4 \uc528\ub294 \uc790\uc2e0\uc758 \ube44\ubc00\ubc88\ud638\ub97c \ubb38\uc790\ub85c \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4."],t.s)
A.cSM=new B.al("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc218\uc9c4 \uc528\ub294 \u201c\uacc4\uc88c \uc0ac\uc6a9\uc774 \uace7 \uc81c\ud55c\ub429\ub2c8\ub2e4. \uc9c0\uae08 \ub9c1\ud06c\ub97c \ub20c\ub7ec \ubcf8\uc778 \uc778\uc99d\uc744 \ud558\uc138\uc694.\u201d\ub77c\ub294 \ubb38\uc790\ub97c \ubc1b\uc558\uc2b5\ub2c8\ub2e4. \ubb38\uc790\uc5d0\ub294 \ud3c9\uc18c \uc774\uc6a9\ud558\ub294 \uae08\uc735 \uae30\uad00\uc758 \uc774\ub984\uc774 \uc801\ud600 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc218\uc9c4 \uc528\ub294 \ub9c1\ud06c\ub97c \ub204\ub974\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ub300\uc2e0 \ud3c9\uc18c \uc0ac\uc6a9\ud558\ub358 \uacf5\uc2dd \uc571\uc744 \uc9c1\uc811 \uc5f4\uc5b4 \uacf5\uc9c0 \uc0ac\ud56d\uc744 \ud655\uc778\ud588\uace0 \uc774\uc0c1\uc774 \uc5c6\ub2e4\ub294 \uac83\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.lWu,2,"Sujin kh\xf4ng d\xf9ng link \u0111\u01b0\u1ee3c g\u1eedi m\xe0 t\u1ef1 truy c\u1eadp k\xeanh ch\xednh th\u1ee9c \u0111\u1ec3 ki\u1ec3m tra.","\uc77d\uae30")
A.jvJ=s(["\uba54\uc2dc\uc9c0\uc5d0 \uc801\ud78c \uacc4\uc88c\ub85c \uc989\uc2dc \uc1a1\uae08\ud55c\ub2e4.","\uae30\uc874\uc5d0 \uc54c\uace0 \uc788\ub358 \uc5f0\ub77d\ucc98\ub97c \ud1b5\ud574 \ubcc0\uacbd \uc0ac\uc2e4\uacfc \uacc4\uc88c \uc815\ubcf4\ub97c \ubcc4\ub3c4\ub85c \ud655\uc778\ud55c\ub2e4.","\uc608\uae08\uc8fc\uac00 \ub2ec\ub77c\ub3c4 \uadf8\ub0e5 \ubcf4\ub0b8\ub2e4.","\uacc4\uc88c \ubc88\ud638\ub97c \ub2e4\ub978 \uc5c5\uccb4\uc5d0\ub3c4 \uacf5\uc720\ud55c\ub2e4."],t.s)
A.cW5=new B.al("\ud68c\uc0ac \uac70\ub798\ucc98\uc5d0\uc11c \uac11\uc790\uae30 \u201c\uacc4\uc88c\uac00 \ubc14\ub00c\uc5c8\uc73c\ub2c8 \uc0c8 \uacc4\uc88c\ub85c \ubcf4\ub0b4 \ub2ec\ub77c\u201d\ub294 \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740?",A.jvJ,1,"Th\xf4ng tin thanh to\xe1n thay \u0111\u1ed5i n\xean \u0111\u01b0\u1ee3c x\xe1c minh qua k\xeanh \u0111\u1ed9c l\u1eadp \u0111\xe3 bi\u1ebft tr\u01b0\u1edbc.","\uc2e4\uc81c \uc0c1\ud669")
A.kAu=s(["\uc911\uc694\ud55c \uac70\ub798 \uc804 \uae08\uc561\uacfc \uc0c1\ub300\ubc29 \uc815\ubcf4\ub97c \ud655\uc778\ud55c\ub2e4.","\uac70\ub798 \ub0b4\uc5ed\uc744 \uc8fc\uae30\uc801\uc73c\ub85c \ud655\uc778\ud55c\ub2e4.","\ucd9c\ucc98\uac00 \ubd88\ubd84\uba85\ud55c \uc694\uccad\uc740 \ucd94\uac00\ub85c \ud655\uc778\ud55c\ub2e4.","\ud55c \ubc88 \ubbff\uc740 \uc0c1\ub300\ubc29\uc774\uba74 \uacc4\uc88c \uc815\ubcf4\uac00 \ubc14\ub00c\uc5b4\ub3c4 \ud655\uc778 \uc5c6\uc774 \uacc4\uc18d \uc1a1\uae08\ud55c\ub2e4."],t.s)
A.cSA=new B.al("\uae08\uc735 \uac70\ub798\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud558\ub294 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.kAu,3,"Th\xf4ng tin thay \u0111\u1ed5i v\u1eabn c\u1ea7n \u0111\u01b0\u1ee3c x\xe1c minh d\xf9 \u0111\xe3 t\u1eebng giao d\u1ecbch tr\u01b0\u1edbc \u0111\xf3.","\uc885\ud569")
