A.kP8=s(["\ubaa8\ub4e0 \uc9c0\uc6d0\uc790\uac00 \ubc18\ub4dc\uc2dc \uac16\ucdb0\uc57c \ud558\ub294 \uc870\uac74\uc774\ub2e4.","\uac16\ucd94\uba74 \ucc44\uc6a9 \uacfc\uc815\uc5d0\uc11c \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc9c0\ub9cc \ud544\uc218 \uc870\uac74\uacfc\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4.","\ud68c\uc0ac\uc640 \uc804\ud600 \uad00\uacc4\uc5c6\ub294 \uc815\ubcf4\uc774\ub2e4.","\uc785\uc0ac \ud6c4\uc5d0\ub9cc \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9\uc774\ub2e4."],t.s)
A.cUk=new B.al("\ucc44\uc6a9 \uacf5\uace0\uc758 \u201c\uc6b0\ub300 \uc870\uac74\u201d\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.kP8,1,"\uc6b0\ub300 \uc870\uac74 th\u01b0\u1eddng l\xe0 \u0111i\u1ec1u ki\u1ec7n t\u1ea1o l\u1ee3i th\u1ebf, kh\xf4ng nh\u1ea5t thi\u1ebft l\xe0 \u0111i\u1ec1u ki\u1ec7n b\u1eaft bu\u1ed9c.","\ucc44\uc6a9 \uacf5\uace0")
A.jtd=s(["\uc9c0\uae08\uae4c\uc9c0\uc758 \uc5c5\ubb34 \uacbd\ud5d8\uc744 \uae30\ub85d\ud55c\ub2e4.","\uc7a5\uae30 \ubaa9\ud45c\uc5d0 \ud544\uc694\ud55c \uc5ed\ub7c9\uc744 \ud655\uc778\ud55c\ub2e4.","\ubd80\uc871\ud55c \uc5ed\ub7c9\uc744 \uad50\uc721\uacfc \uacbd\ud5d8\uc73c\ub85c \ubcf4\uc644\ud55c\ub2e4.","\ubaa9\ud45c\ub098 \uc9c1\ubb34\uc640 \uad00\uacc4\uc5c6\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc900\ube44\ud558\ub294 \uc790\uaca9\uc99d\uc744 \ubaa8\ub450 \ub530\ub77c \uc900\ube44\ud55c\ub2e4."],t.s)
A.cWJ=new B.al("\ud6a8\uacfc\uc801\uc778 \uacbd\ub825 \uad00\ub9ac \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.jtd,3,"Qu\u1ea3n l\xfd s\u1ef1 nghi\u1ec7p n\xean d\u1ef1a tr\xean m\u1ee5c ti\xeau v\xe0 n\u0103ng l\u1ef1c c\u1ea7n thi\u1ebft c\u1ee7a ch\xednh m\xecnh.","\uc885\ud569")
A.k7L=s([A.cVW,A.cUl,A.cWc,A.cXa,A.cWU,A.cX6,A.cX0,A.cWp,A.cUv,A.cVq,A.cTd,A.cTC,A.cUq,A.cUk,A.cWJ],t.VX)
A.nqK=s(["\uacbd\ub825","\ub2f4\ub2f9 \uc5c5\ubb34","\uacbd\ud5d8","\uac15\uc810","\ubc30\uc6b4 \uc810"],t.s)
A.cYF=new B.cD("\uba74\uc811\uc5d0\uc11c \uc790\uc2e0\uc758 \uacbd\ub825\uc744 \uc18c\uac1c\ud574 \ubcf4\uc138\uc694.","\uc800\ub294 \uc81c\uc870 \ud604\uc7a5\uc5d0\uc11c \uc0dd\uc0b0\uacfc \ud488\uc9c8 \uad00\ub828 \uc5c5\ubb34 \uacbd\ud5d8\uc744 \uc313\uc544 \uc654\uc2b5\ub2c8\ub2e4. \uc8fc\uc694 \ub2f4\ub2f9 \uc5c5\ubb34\ub294 \uc0dd\uc0b0 \uc124\ube44\ub97c \uc774\uc6a9\ud55c \uc791\uc5c5, \uc81c\ud488 \uc0c1\ud0dc \ud655\uc778, \uc791\uc5c5 \uae30\ub85d\uacfc \uc774\uc0c1 \ubc1c\uc0dd \uc2dc \ubcf4\uace0\uc600\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uac19\uc740 \uc720\ud615\uc758 \ubd88\ub7c9\uc774 \ubc18\ubcf5\ub410\uc744 \ub54c \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud655\uc778\ud558\uace0 \uad00\ub828 \ub2f4\ub2f9\uc790\uc640 \ud568\uaed8 \uc6d0\uc778\uc744 \ubd84\uc11d\ud55c \uacbd\ud5d8\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ud604\uc7a5\uc5d0\uc11c \ubb38\uc81c\ub97c \ube68\ub9ac \ubc1c\uacac\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\ud655\ud558\uac8c \uae30\ub85d\ud558\uace0 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4. \uc81c \uac15\uc810\uc740 \uc0c8\ub85c\uc6b4 \uc791\uc5c5\uc744 \ubc30\uc6b0\uba74 \uba54\ubaa8\ud558\uace0 \ubc18\ubcf5\ud558\uba74\uc11c \ube60\ub974\uac8c \uc775\ud788\ub824\uace0 \ud55c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.")
A.nsA=s(["\ud604\uc7ac \uacbd\ud5d8","\uc9c0\uc6d0 \uc9c1\ubb34","\uad00\uc2ec","\uc5ed\ub7c9","\uc131\uc7a5","\uae30\uc5ec"],t.s)
A.cYs=new B.cD("\uc9c0\uc6d0 \ub3d9\uae30\ub97c \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\uc800\ub294 \uc9c0\uae08\uae4c\uc9c0 \uc81c\uc870 \ud604\uc7a5\uc5d0\uc11c \uc0dd\uc0b0 \uc5c5\ubb34\uc640 \uae30\ubcf8\uc801\uc778 \ud488\uc9c8 \ud655\uc778 \uacbd\ud5d8\uc744 \uc313\uc544 \uc654\uc2b5\ub2c8\ub2e4. \uc77c\uc744 \ud558\uba74\uc11c \ub2e8\uc21c\ud788 \uc81c\ud488\uc744 \uc0dd\uc0b0\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubb38\uc81c\uac00 \uc65c \ubc1c\uc0dd\ud558\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uac1c\uc120\ud558\ub294 \uc5c5\ubb34\uc5d0 \uad00\uc2ec\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc55e\uc73c\ub85c \ud488\uc9c8 \uad00\ub9ac\uc640 \uacf5\uc815 \uac1c\uc120 \uc5ed\ub7c9\uc744 \ub354 \ud0a4\uc6b0\uace0\uc790 \ud569\ub2c8\ub2e4. \uc774\ubc88 \uc9c1\ubb34\ub294 \uc81c\uac00 \uc9c0\uae08\uae4c\uc9c0 \uc313\uc544 \uc628 \ud604\uc7a5 \uacbd\ud5d8\uc744 \ud65c\uc6a9\ud560 \uc218 \uc788\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \ud488\uc9c8 \ubd84\uc57c\uc758 \uc804\ubb38\uc131\uc744 \ubc1c\uc804\uc2dc\ud0ac \uc218 \uc788\ub294 \uae30\ud68c\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uc9c0\uc6d0\ud588\uc2b5\ub2c8\ub2e4.")
A.nrE=s(["\uc7a5\uae30 \ubaa9\ud45c","\ub2e8\uae30 \ubaa9\ud45c","\ud544\uc694\ud55c \uc5ed\ub7c9","\uacbd\ud5d8","\uad50\uc721","\ud655\uc778"],t.s)
A.cYH=new B.cD("\uc790\uc2e0\uc758 \uc7a5\uae30 \ubaa9\ud45c\uc640 \ub2e8\uae30 \ubaa9\ud45c\ub97c \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc81c \uc7a5\uae30 \ubaa9\ud45c\ub294 \ud55c \ubd84\uc57c\uc5d0\uc11c \ucda9\ubd84\ud55c \ud604\uc7a5 \uacbd\ud5d8\uacfc \uc804\ubb38\uc131\uc744 \uac16\ucdb0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \uc6d0\uc778\uc744 \ubd84\uc11d\ud558\uace0 \uac1c\uc120 \ubc29\uc548\uc744 \uc81c\uc548\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774 \ub418\ub294 \uac83\uc785\ub2c8\ub2e4. \uc774\ub97c \uc704\ud574 \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ud604\uc7ac \uc5c5\ubb34\ub97c \uc815\ud655\ud558\uac8c \uc775\ud788\uace0 \uad00\ub828 \uae30\ub85d\uacfc \ud488\uc9c8 \uac80\uc0ac \uacbd\ud5d8\uc744 \ub354 \ub9ce\uc774 \uc313\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubd80\uc871\ud55c \uae30\uc220\uc774 \ubb34\uc5c7\uc778\uc9c0 \ud655\uc778\ud574\uc11c \ud544\uc694\ud55c \uad50\uc721\ub3c4 \ubc1b\uc744 \uacc4\ud68d\uc785\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \uc790\uaca9\uc99d \uc218\ub97c \ub298\ub9ac\ub294 \uac83\ubcf4\ub2e4 \uc2e4\uc81c \uc5c5\ubb34\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc744 \ud558\ub098\uc529 \ub298\ub9ac\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.")
A.nqD=s(["\ud604\uc7ac \uc9c1\ubb34","\uad00\uc2ec \ubd84\uc57c","\uad00\ub828 \uacbd\ud5d8","\ubd80\uc871\ud55c \uc5ed\ub7c9","\uc900\ube44","\ubaa9\ud45c"],t.s)
A.cZv=new B.cD("\uc9c1\ubb34\ub97c \ubc14\uafb8\uace0 \uc2f6\uc740 \uc774\uc720\uc640 \uc900\ube44 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\ud604\uc7ac\ub294 \uc0dd\uc0b0 \uc5c5\ubb34\ub97c \uc8fc\ub85c \ud558\uace0 \uc788\uc9c0\ub9cc \uc77c\uc744 \ud558\uba74\uc11c \ud488\uc9c8 \ubb38\uc81c\uc640 \uc6d0\uc778 \ubd84\uc11d \uc5c5\ubb34\uc5d0 \uad00\uc2ec\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \ud488\uc9c8 \uad00\ub9ac \ucabd\uc73c\ub85c \uc9c1\ubb34\ub97c \ub113\ud788\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ubc14\ub85c \uc9c1\ubb34\ub97c \ubc14\uafb8\uae30\ubcf4\ub2e4\ub294 \ud604\uc7ac \ud68c\uc0ac\uc5d0\uc11c \uac80\uc0ac\uc640 \uc791\uc5c5 \uae30\ub85d \uacbd\ud5d8\uc744 \ub354 \uc313\uace0 \uad00\ub828 \uad50\uc721\ub3c4 \ubc1b\uc73c\ub824\uace0 \ud569\ub2c8\ub2e4. \ub610\ud55c \uc9c0\uae08\uae4c\uc9c0 \ud574\uacb0\ud588\ub358 \ubb38\uc81c\uc640 \uac1c\uc120 \uc0ac\ub840\ub97c \uc815\ub9ac\ud574\uc11c \uc81c\uac00 \uc5b4\ub5a4 \uc5ed\ub7c9\uc744 \uc774\ubbf8 \uac00\uc9c0\uace0 \uc788\uace0 \ubb34\uc5c7\uc774 \ubd80\uc871\ud55c\uc9c0 \ud655\uc778\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4. \uc900\ube44\uac00 \ucda9\ubd84\ud574\uc9c0\uba74 \uad00\ub828 \uc9c1\ubb34\uc5d0 \uc9c0\uc6d0\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.jy_=s([A.cYF,A.cYs,A.cYH,A.cZv],t.uf)
A.nss=s(["\uadfc\ubb34 \ubd84\uc57c\ub97c \uc4f0\uc138\uc694.","\ub2f4\ub2f9 \uc5c5\ubb34\ub97c \uc4f0\uc138\uc694.","\uad6c\uccb4\uc801\uc778 \uacbd\ud5d8\uc744 \ud558\ub098 \uc4f0\uc138\uc694.","\uadf8 \uacbd\ud5d8\uc5d0\uc11c \ubc30\uc6b4 \uc810\uc744 \uc4f0\uc138\uc694.","\uc790\uc2e0\uc758 \uac15\uc810\uc744 \uc4f0\uc138\uc694.","V-\uc544/\uc5b4 \uc624\ub2e4\uc640 V-(\uc73c)\u3134 \uacbd\ud5d8\uc774 \uc788\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbu=new B.di("\uc790\uc2e0\uc758 \uacbd\ub825\uacfc \uc5c5\ubb34 \uacbd\ud5d8\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc744 \uc368 \ubcf4\uc138\uc694.","\uc800\ub294 \uc81c\uc870 \ud604\uc7a5\uc5d0\uc11c \uc0dd\uc0b0\uacfc \ud488\uc9c8 \uad00\ub828 \uc5c5\ubb34\ub97c \uacbd\ud5d8\ud574 \uc654\uc2b5\ub2c8\ub2e4. \uc8fc\ub85c \uc0dd\uc0b0 \uc124\ube44\ub97c \uc774\uc6a9\ud55c \uc791\uc5c5, \uc81c\ud488 \uc0c1\ud0dc \ud655\uc778, \uc791\uc5c5 \uae30\ub85d\uacfc \uc774\uc0c1 \ubc1c\uc0dd \uc2dc \ubcf4\uace0 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud588\uc2b5\ub2c8\ub2e4. \uc5c5\ubb34\ub97c \ud558\uba74\uc11c \uac19\uc740 \uc720\ud615\uc758 \ud488\uc9c8 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub410\uc744 \ub54c \uc0dd\uc0b0 \uae30\ub85d\uacfc \uc791\uc5c5 \uc870\uac74\uc744 \ud655\uc778\ud558\uace0 \uad00\ub828 \ub2f4\ub2f9\uc790\uc640 \ud568\uaed8 \uc6d0\uc778\uc744 \ubd84\uc11d\ud55c \uacbd\ud5d8\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uadf8 \uacfc\uc815\uc5d0\uc11c \ubb38\uc81c\ub97c \ube68\ub9ac \ubc1c\uacac\ud558\ub294 \uac83\ub9cc\ud07c \uc815\ud655\ud558\uac8c \uae30\ub85d\ud558\uace0 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4. \uc800\ub294 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\ub97c \ub9e1\uc73c\uba74 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uba54\ubaa8\ud558\uace0 \ubc18\ubcf5\ud574\uc11c \ud655\uc778\ud558\ub294 \ud3b8\uc774\uba70 \ub9e1\uc740 \uc5c5\ubb34\ub294 \uac00\ub2a5\ud55c \ud55c \ub05d\uae4c\uc9c0 \ucc45\uc784\uc9c0\uace0 \ud655\uc778\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.","T\xf4i \u0111\xe3 t\xedch l\u0169y kinh nghi\u1ec7m li\xean quan \u0111\u1ebfn s\u1ea3n xu\u1ea5t v\xe0 ch\u1ea5t l\u01b0\u1ee3ng t\u1ea1i hi\u1ec7n tr\u01b0\u1eddng s\u1ea3n xu\u1ea5t. T\xf4i ch\u1ee7 y\u1ebfu ph\u1ee5 tr\xe1ch thao t\xe1c b\u1eb1ng thi\u1ebft b\u1ecb s\u1ea3n xu\u1ea5t, ki\u1ec3m tra t\xecnh tr\u1ea1ng s\u1ea3n ph\u1ea9m, ghi ch\xe9p c\xf4ng vi\u1ec7c v\xe0 b\xe1o c\xe1o khi ph\xe1t sinh b\u1ea5t th\u01b0\u1eddng. Trong qu\xe1 tr\xecnh l\xe0m vi\u1ec7c, khi c\xf9ng lo\u1ea1i v\u1ea5n \u0111\u1ec1 ch\u1ea5t l\u01b0\u1ee3ng l\u1eb7p l\u1ea1i, t\xf4i c\xf3 kinh nghi\u1ec7m ki\u1ec3m tra ghi ch\xe9p s\u1ea3n xu\u1ea5t v\xe0 \u0111i\u1ec1u ki\u1ec7n thao t\xe1c r\u1ed3i c\xf9ng ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch li\xean quan ph\xe2n t\xedch nguy\xean nh\xe2n. Qua qu\xe1 tr\xecnh \u0111\xf3 t\xf4i h\u1ecdc \u0111\u01b0\u1ee3c r\u1eb1ng ghi ch\xe9p ch\xednh x\xe1c v\xe0 chia s\u1ebb th\xf4ng tin quan tr\u1ecdng kh\xf4ng k\xe9m vi\u1ec7c ph\xe1t hi\u1ec7n v\u1ea5n \u0111\u1ec1 nhanh. Khi nh\u1eadn c\xf4ng vi\u1ec7c m\u1edbi t\xf4i th\u01b0\u1eddng ghi l\u1ea1i n\u1ed9i dung quan tr\u1ecdng v\xe0 ki\u1ec3m tra l\u1eb7p l\u1ea1i, \u0111\u1ed3ng th\u1eddi c\u1ed1 g\u1eafng ch\u1ecbu tr\xe1ch nhi\u1ec7m ki\u1ec3m tra c\xf4ng vi\u1ec7c \u0111\u01b0\u1ee3c giao \u0111\u1ebfn c\xf9ng.")
A.nsn=s(["\ud604\uc7ac \uc5ed\ub7c9\uc744 \ud3c9\uac00\ud558\uc138\uc694.","\uc7a5\uae30 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694.","\ub2e8\uae30 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694.","\ud544\uc694\ud55c \uacbd\ud5d8\uc744 \uc4f0\uc138\uc694.","\uad50\uc721 \ub610\ub294 \uc790\uaca9\uc99d \uacc4\ud68d\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139 \uc218 \uc788\ub3c4\ub85d\uacfc V/A-(\uc73c)\u3139\uc218\ub85d\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.daT=new B.di("\uc55e\uc73c\ub85c\uc758 \uacbd\ub825 \uac1c\ubc1c \uacc4\ud68d\uc744 \uc368 \ubcf4\uc138\uc694.","\ud604\uc7ac \uc800\ub294 \uae30\ubcf8\uc801\uc778 \uc0dd\uc0b0 \uc5c5\ubb34\uc640 \ud604\uc7a5 \ubb38\uc81c \ub300\uc751 \uacbd\ud5d8\uc740 \uc788\uc9c0\ub9cc \ud488\uc9c8 \ub370\uc774\ud130 \ubd84\uc11d\uacfc \uacf5\uc815 \uac1c\uc120 \uacbd\ud5d8\uc740 \uc544\uc9c1 \ubd80\uc871\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \uc0dd\uc0b0 \uacfc\uc815\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \ubb38\uc81c\ub97c \uc2a4\uc2a4\ub85c \ubd84\uc11d\ud558\uace0 \uac1c\uc120 \ubc29\uc548\uc744 \uc81c\uc548\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774 \ub418\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc704\ud574 \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ud488\uc9c8 \uac80\uc0ac, \uce21\uc815\uacfc \uc791\uc5c5 \uae30\ub85d \uacbd\ud5d8\uc744 \ub354 \uc313\uc744 \uacc4\ud68d\uc785\ub2c8\ub2e4. \ub610\ud55c \uad00\ub828 \uc5c5\ubb34\ub97c \ub3c5\ub9bd\uc801\uc73c\ub85c \uc218\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \ud544\uc694\ud55c \uad50\uc721\uc744 \ubc1b\uace0 \ubd80\uc871\ud55c \uae30\uc220\uc744 \uacf5\ubd80\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uacbd\ub825\uc774 \uc313\uc77c\uc218\ub85d \ub2e8\uc21c\ud788 \uc624\ub798 \uc77c\ud558\ub294 \uac83\ubcf4\ub2e4 \uc5b4\ub5a4 \ub2a5\ub825\uc774 \uc2e4\uc81c\ub85c \uc88b\uc544\uc84c\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub9e4\ub144 \ub2f4\ub2f9 \uc5c5\ubb34, \uc0c8\ub86d\uac8c \ubc30\uc6b4 \uae30\uc220\uacfc \uc8fc\uc694 \uc131\uacfc\ub97c \uc815\ub9ac\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","Hi\u1ec7n t\xf4i c\xf3 kinh nghi\u1ec7m c\u01a1 b\u1ea3n v\u1ec1 s\u1ea3n xu\u1ea5t v\xe0 \u1ee9ng ph\xf3 v\u1ea5n \u0111\u1ec1 t\u1ea1i hi\u1ec7n tr\u01b0\u1eddng, nh\u01b0ng cho r\u1eb1ng kinh nghi\u1ec7m ph\xe2n t\xedch d\u1eef li\u1ec7u ch\u1ea5t l\u01b0\u1ee3ng v\xe0 c\u1ea3i ti\u1ebfn c\xf4ng \u0111o\u1ea1n v\u1eabn c\xf2n thi\u1ebfu. V\u1ec1 l\xe2u d\xe0i t\xf4i mu\u1ed1n tr\u1edf th\xe0nh ng\u01b0\u1eddi c\xf3 th\u1ec3 t\u1ef1 ph\xe2n t\xedch v\u1ea5n \u0111\u1ec1 ph\xe1t sinh trong qu\xe1 tr\xecnh s\u1ea3n xu\u1ea5t v\xe0 \u0111\u1ec1 xu\u1ea5t ph\u01b0\u01a1ng \xe1n c\u1ea3i ti\u1ebfn. \u0110\u1ec3 l\xe0m \u0111\u01b0\u1ee3c \u0111i\u1ec1u \u0111\xf3, trong ng\u1eafn h\u1ea1n t\xf4i d\u1ef1 \u0111\u1ecbnh t\xedch l\u0169y th\xeam kinh nghi\u1ec7m ki\u1ec3m tra ch\u1ea5t l\u01b0\u1ee3ng, \u0111o l\u01b0\u1eddng v\xe0 ghi ch\xe9p c\xf4ng vi\u1ec7c. Ngo\xe0i ra t\xf4i s\u1ebd tham gia \u0111\xe0o t\u1ea1o c\u1ea7n thi\u1ebft v\xe0 h\u1ecdc nh\u1eefng k\u1ef9 n\u0103ng c\xf2n thi\u1ebfu \u0111\u1ec3 c\xf3 th\u1ec3 \u0111\u1ed9c l\u1eadp th\u1ef1c hi\u1ec7n c\xf4ng vi\u1ec7c li\xean quan. T\xf4i ngh\u0129 kinh nghi\u1ec7m c\xe0ng t\xedch l\u0169y th\xec vi\u1ec7c x\xe1c nh\u1eadn n\u0103ng l\u1ef1c th\u1ef1c s\u1ef1 n\xe0o \u0111\xe3 c\u1ea3i thi\u1ec7n c\xf2n quan tr\u1ecdng h\u01a1n ch\u1ec9 l\xe0m l\xe2u. V\xec v\u1eady m\u1ed7i n\u0103m t\xf4i d\u1ef1 \u0111\u1ecbnh t\u1ed5ng h\u1ee3p c\xf4ng vi\u1ec7c \u0111\xe3 ph\u1ee5 tr\xe1ch, k\u1ef9 thu\u1eadt m\u1edbi h\u1ecdc v\xe0 th\xe0nh t\xedch ch\xednh.")
A.npH=s(["\uc774\uc9c1 \uc774\uc720\ub97c \ud655\uc778\ud558\uc138\uc694.","\ud604\uc7ac \uacbd\ub825\uc744 \uc815\ub9ac\ud558\uc138\uc694.","\uc9c0\uc6d0 \uc9c1\ubb34\ub97c \ubd84\uc11d\ud558\uc138\uc694.","\ubd80\uc871\ud55c \uc5ed\ub7c9\uc744 \ud655\uc778\ud558\uc138\uc694.","\uc774\ub825\uc11c\uc640 \uba74\uc811 \uc900\ube44\ub97c \uc4f0\uc138\uc694.","V-\uace0\uc790 \ud558\ub2e4\uc640 V-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbD=new B.di("\uc88b\uc740 \uc774\uc9c1\uc744 \uc704\ud574 \uc900\ube44\ud574\uc57c \ud560 \uac83\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc774\uc9c1\uc744 \uc900\ube44\ud560 \ub54c\ub294 \uba3c\uc800 \uc65c \uc9c1\uc7a5\uc744 \ubc14\uafb8\uace0 \uc2f6\uc740\uc9c0 \uc2a4\uc2a4\ub85c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \ud604\uc7ac \uc77c\uc774 \ud798\ub4e4\ub2e4\ub294 \uc774\uc720\ubfd0\uc774\ub77c\uba74 \ub2e4\uc74c \uc9c1\uc7a5\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uae30\uc801\uc73c\ub85c \uc5b4\ub5a4 \uc9c1\ubb34\uc5d0\uc11c \uc804\ubb38\uc131\uc744 \ub192\uc774\uace0\uc790 \ud558\ub294\uc9c0 \uc815\ud55c \ud6c4 \uc9c0\uae08\uae4c\uc9c0\uc758 \uacbd\ub825\uacfc \uc9c0\uc6d0\ud558\ub824\ub294 \uc9c1\ubb34\ub97c \ube44\uad50\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc790\uc2e0\uc758 \uac15\uc810\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubd80\uc871\ud55c \uc5ed\ub7c9\ub3c4 \ud655\uc778\ud574\uc11c \uad50\uc721\uc774\ub098 \uc2e4\ubb34 \uacbd\ud5d8\uc73c\ub85c \ubcf4\uc644\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uae4c\uc9c0 \ub2f4\ub2f9\ud55c \uc5c5\ubb34\uc640 \uc131\uacfc\ub97c \uc815\ub9ac\ud558\uba74 \uc774\ub825\uc11c\ub97c \uc791\uc131\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uba74\uc811\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uacbd\ud5d8\uc744 \uc124\uba85\ud558\ub294 \ub370\ub3c4 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \ucda9\ubd84\ud788 \uc900\ube44\ud55c \ud6c4 \uc790\uc2e0\uc758 \uacbd\ub825 \ubc29\ud5a5\uacfc \uc5f0\uacb0\ub418\ub294 \ud68c\uc0ac\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi chu\u1ea9n b\u1ecb chuy\u1ec3n vi\u1ec7c, tr\u01b0\u1edbc ti\xean \u0111i\u1ec1u quan tr\u1ecdng l\xe0 t\u1ef1 x\xe1c nh\u1eadn t\u1ea1i sao m\xecnh mu\u1ed1n \u0111\u1ed5i c\xf4ng ty. N\u1ebfu ch\u1ec9 v\xec c\xf4ng vi\u1ec7c hi\u1ec7n t\u1ea1i kh\xf3 kh\u0103n th\xec \u1edf c\xf4ng ty ti\u1ebfp theo c\u0169ng c\xf3 th\u1ec3 x\u1ea3y ra v\u1ea5n \u0111\u1ec1 t\u01b0\u01a1ng t\u1ef1. Sau khi x\xe1c \u0111\u1ecbnh l\xe2u d\xe0i m\xecnh mu\u1ed1n n\xe2ng chuy\xean m\xf4n \u1edf v\u1ecb tr\xed n\xe0o, c\u1ea7n so s\xe1nh kinh nghi\u1ec7m hi\u1ec7n t\u1ea1i v\u1edbi v\u1ecb tr\xed mu\u1ed1n \u1ee9ng tuy\u1ec3n. Ngo\xe0i \u0111i\u1ec3m m\u1ea1nh, c\u0169ng c\u1ea7n x\xe1c nh\u1eadn n\u0103ng l\u1ef1c c\xf2n thi\u1ebfu v\xe0 b\u1ed5 sung b\u1eb1ng \u0111\xe0o t\u1ea1o ho\u1eb7c kinh nghi\u1ec7m th\u1ef1c t\u1ebf. T\u1ed5ng h\u1ee3p c\xf4ng vi\u1ec7c v\xe0 th\xe0nh t\xedch \u0111\xe3 \u0111\u1ea1t kh\xf4ng ch\u1ec9 gi\xfap vi\u1ebft CV m\xe0 c\xf2n gi\xfap gi\u1ea3i th\xedch kinh nghi\u1ec7m c\u1ee5 th\u1ec3 trong ph\u1ecfng v\u1ea5n. Sau khi chu\u1ea9n b\u1ecb \u0111\u1ea7y \u0111\u1ee7, n\xean ch\u1ecdn c\xf4ng ty c\xf3 li\xean h\u1ec7 v\u1edbi h\u01b0\u1edbng ph\xe1t tri\u1ec3n ngh\u1ec1 nghi\u1ec7p c\u1ee7a m\xecnh.")
A.m2l=s([A.dbu,A.daT,A.dbD],t.l5)
