A.cZs=new B.cD("\ud55c \uac00\uc9c0 \uc0ac\ud68c \ubb38\uc81c\ub97c \uc120\ud0dd\ud574\uc11c \uc6d0\uc778\uc744 \ubd84\uc11d\ud574 \ubcf4\uc138\uc694.","\uc800\ub294 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc758 \uad50\ud1b5 \ud63c\uc7a1 \ubb38\uc81c\ub97c \uc608\ub85c \ub4e4\uc5b4 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uad50\ud1b5\ub7c9 \uc99d\uac00\uac00 \uc911\uc694\ud55c \uc6d0\uc778\uc77c \uc218 \uc788\uc9c0\ub9cc \ucc28\ub7c9 \uc218\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud2b9\uc815 \uc2dc\uac04\ub300\uc5d0 \ucd9c\uadfc\uacfc \ud1f4\uadfc\uc774 \uc9d1\uc911\ub418\ub294 \uc810, \uc77c\ubd80 \uc9c0\uc5ed\uc758 \ub300\uc911\uad50\ud1b5 \uc811\uadfc\uc131, \ub3c4\ub85c \uacf5\uc0ac\uc640 \uc9c0\uc5ed \uac1c\ubc1c\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dc\uac04\ub300\ubcc4 \uad50\ud1b5\ub7c9, \ub300\uc911\uad50\ud1b5 \uc774\uc6a9\ub960\uacfc \uc9c0\uc5ed\ubcc4 \uc774\ub3d9 \ub370\uc774\ud130\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \uc5b4\ub5a4 \uc694\uc778\uc774 \ud070 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0 \ub354 \uc815\ud655\ud558\uac8c \ubd84\uc11d\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.nsP=s(["\uae30\uac04","\ubc94\uc704","\ucd9c\ucc98","\ube44\uad50","\ucd94\uc138","\uc6d0\uc778\uacfc \uad00\ub828\uc131"],t.s)
A.cZg=new B.cD("\ud1b5\uacc4 \uc790\ub8cc\ub97c \ubcf4\uace0 \ubc14\ub85c \uacb0\ub860\uc744 \ub0b4\ub9ac\uba74 \uc548 \ub418\ub294 \uc774\uc720\ub97c \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\ud1b5\uacc4\ub294 \uc0ac\ud68c \ud604\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc911\uc694\ud55c \uc790\ub8cc\uc774\uc9c0\ub9cc \uc22b\uc790 \ud558\ub098\ub9cc \ubcf4\uace0 \ubc14\ub85c \uc6d0\uc778\uc744 \ud310\ub2e8\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uba3c\uc800 \uc790\ub8cc\uac00 \uc5b4\ub290 \uae30\uac04\uacfc \uc5b4\ub5a4 \uc9d1\ub2e8\uc744 \ub300\uc0c1\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ud55c \ud574\uc758 \uc218\uce58\uac00 \ud06c\uac8c \ubcc0\ud588\ub354\ub77c\ub3c4 \uc7a5\uae30\uc801\uc778 \ucd94\uc138\uc640\ub294 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ub450 \uc218\uce58\uac00 \uac19\uc774 \ubcc0\ud55c\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ud55c\ucabd\uc774 \ub2e4\ub978 \ucabd\uc758 \uc6d0\uc778\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub2e4\ub978 \uc790\ub8cc\uc640 \ube44\uad50\ud558\uace0 \uc870\uc0ac \ubc29\ubc95\uacfc \ucd9c\ucc98\ub3c4 \ud655\uc778\ud55c \ud6c4 \uacb0\ub860\uc744 \ub0b4\ub9ac\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.npC=s(["\uc77c\uc790\ub9ac","\uad50\uc721","\uad50\ud1b5","\uc758\ub8cc","\uc778\uad6c \uc774\ub3d9","\uc7a5\uae30 \ub300\ucc45"],t.s)
A.cYL=new B.cD("\uc9c0\uc5ed \uaca9\ucc28 \ubb38\uc81c\uc758 \uc6d0\uc778\uacfc \ud574\uacb0 \ubc29\uc548\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc9c0\uc5ed \uaca9\ucc28\ub294 \uc77c\uc790\ub9ac \ud558\ub098\ub9cc\uc758 \ubb38\uc81c\ub77c\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \uc870\uac74\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \uc9c0\uc5ed\uc740 \uc77c\uc790\ub9ac\uac00 \uc801\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uad50\uc721, \uad50\ud1b5\uacfc \uc758\ub8cc \uc11c\ube44\uc2a4 \uc811\uadfc\uc131\ub3c4 \ub0ae\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \ucc28\uc774\uac00 \uc624\ub7ab\ub3d9\uc548 \uc774\uc5b4\uc9c0\ub2e4 \ubcf4\uba74 \uc80a\uc740 \uc778\uad6c\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\uace0 \ub2e4\uc2dc \uc9c0\uc5ed \uc11c\ube44\uc2a4 \uc218\uc694\uac00 \uc904\uc5b4\ub4dc\ub294 \ud604\uc0c1\uc774 \ub098\ud0c0\ub0a0 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ud574\uacb0\uc744 \uc704\ud574\uc11c\ub294 \ub2e8\uae30\uc801\uc73c\ub85c \ud544\uc694\ud55c \uc11c\ube44\uc2a4\ub97c \ubcf4\uc644\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc7a5\uae30\uc801\uc73c\ub85c \uc77c\uc790\ub9ac\uc640 \uc0dd\ud65c \uae30\ubc18\uc744 \ud568\uaed8 \uac1c\uc120\ud558\ub294 \ubc29\uc548\uc744 \uac80\ud1a0\ud560 \ud544\uc694\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.ns1=s(["\ud6a8\uacfc","\ube44\uc6a9","\ub300\uc0c1","\uc2e4\ud589 \uac00\ub2a5\uc131","\ubd80\uc791\uc6a9","\uc7a5\uae30 \ud6a8\uacfc"],t.s)
A.cYS=new B.cD("\ud55c \uac00\uc9c0 \ud574\uacb0\ucc45\uc744 \ud3c9\uac00\ud558\ub294 \uae30\uc900\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\ud574\uacb0\ucc45\uc744 \ud3c9\uac00\ud560 \ub54c\ub294 \ud6a8\uacfc\uac00 \uc788\ub294\uc9c0\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uc5ec\ub7ec \uc870\uac74\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc6b0\uc120 \uc2e4\uc81c\ub85c \ubb38\uc81c\uc758 \uc6d0\uc778\uacfc \uc5f0\uacb0\ub41c \ubc29\ubc95\uc778\uc9c0 \ubd10\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ud544\uc694\ud55c \ube44\uc6a9\uacfc \uc2dc\uac04\uc774 \uc5b4\ub290 \uc815\ub3c4\uc778\uc9c0, \ud604\uc2e4\uc801\uc73c\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \uc9d1\ub2e8\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \ub2e4\ub978 \uc9d1\ub2e8\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubd80\ub2f4\uc744 \uc904 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ub300\uc0c1\ubcc4 \uc601\ud5a5\ub3c4 \ubd84\uc11d\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub2e8\uae30 \ud6a8\uacfc\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2dc\uac04\uc774 \uc9c0\ub09c \ud6c4\uc5d0\ub3c4 \ud6a8\uacfc\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ud3c9\uac00\ud574\uc57c \uc88b\uc740 \ud574\uacb0\ucc45\uc778\uc9c0 \ud310\ub2e8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.k9B=s([A.cZs,A.cZg,A.cYL,A.cYS],t.uf)
A.nsy=s(["\ud604\uc0c1\uc744 \uc4f0\uc138\uc694.","\uc790\ub8cc \uc218\uc9d1\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778\uc744 \ubd84\ub958\ud558\uc138\uc694.","\uc601\ud5a5\uc744 \ubd84\uc11d\ud558\uc138\uc694.","\ud574\uacb0\ucc45\uc744 \ube44\uad50\ud558\uc138\uc694.","N(\uc73c)\ub85c \uc778\ud574\uc640 N\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbd=new B.di("\uc0ac\ud68c \ubb38\uc81c\ub97c \ubd84\uc11d\ud560 \ub54c \ud544\uc694\ud55c \uacfc\uc815\uc744 \uc368 \ubcf4\uc138\uc694.","\uc0ac\ud68c \ubb38\uc81c\ub97c \ubd84\uc11d\ud560 \ub54c\ub294 \uba3c\uc800 \uc5b4\ub5a4 \ud604\uc0c1\uc774 \uc2e4\uc81c\ub85c \ub098\ud0c0\ub098\uace0 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uac1c\uc778\uc801\uc778 \uacbd\ud5d8\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \ud1b5\uacc4, \uc870\uc0ac\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \uc218\uc9d1\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc9c1\uc811\uc801\uc778 \uc6d0\uc778\uacfc \uc7a5\uae30\uc801\uc778 \ubc30\uacbd \uc694\uc778\uc744 \uad6c\ubd84\ud574\uc11c \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uad50\ud1b5 \ud63c\uc7a1\uc73c\ub85c \uc778\ud574 \uc774\ub3d9 \uc2dc\uac04\uc774 \uae38\uc5b4\uc84c\ub2e4\uace0 \ud558\ub354\ub77c\ub3c4 \ucc28\ub7c9 \uc218 \uc99d\uac00\ubfd0\ub9cc \uc544\ub2c8\ub77c \ucd9c\ud1f4\uadfc \uc2dc\uac04 \uc9d1\uc911, \ub3c4\ub85c \uad6c\uc870\uc640 \ub300\uc911\uad50\ud1b5 \uc774\uc6a9 \ud658\uacbd\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc6d0\uc778\uc744 \ubd84\uc11d\ud55c \ud6c4\uc5d0\ub294 \uc5b4\ub5a4 \uc9d1\ub2e8\uc774 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubc1b\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc5ec\ub7ec \ud574\uacb0 \ubc29\uc548\uc758 \ud6a8\uacfc, \ube44\uc6a9\uacfc \uc2e4\ud589 \uac00\ub2a5\uc131\uc744 \ube44\uad50\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi ph\xe2n t\xedch v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i, tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c nh\u1eadn hi\u1ec7n t\u01b0\u1ee3ng n\xe0o th\u1ef1c s\u1ef1 \u0111ang x\u1ea3y ra. Thay v\xec \u0111\xe1nh gi\xe1 ch\u1ec9 d\u1ef1a tr\xean kinh nghi\u1ec7m c\xe1 nh\xe2n, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 thu th\u1eadp th\u1ed1ng k\xea, kh\u1ea3o s\xe1t v\xe0 d\u1eef li\u1ec7u li\xean quan. Sau \u0111\xf3 c\u1ea7n ph\xe2n bi\u1ec7t nguy\xean nh\xe2n tr\u1ef1c ti\u1ebfp v\xe0 c\xe1c y\u1ebfu t\u1ed1 n\u1ec1n t\u1ea3ng d\xe0i h\u1ea1n. V\xed d\u1ee5 d\xf9 th\u1eddi gian di chuy\u1ec3n d\xe0i h\u01a1n do \xf9n t\u1eafc giao th\xf4ng, kh\xf4ng ch\u1ec9 s\u1ed1 l\u01b0\u1ee3ng xe t\u0103ng m\xe0 vi\u1ec7c gi\u1edd \u0111i l\xe0m t\u1eadp trung, c\u1ea5u tr\xfac \u0111\u01b0\u1eddng v\xe0 m\xf4i tr\u01b0\u1eddng s\u1eed d\u1ee5ng giao th\xf4ng c\xf4ng c\u1ed9ng c\u0169ng c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng. Sau khi ph\xe2n t\xedch nguy\xean nh\xe2n, c\u1ea7n x\xe1c \u0111\u1ecbnh nh\xf3m n\xe0o ch\u1ecbu \u1ea3nh h\u01b0\u1edfng nh\u01b0 th\u1ebf n\xe0o v\xe0 so s\xe1nh hi\u1ec7u qu\u1ea3, chi ph\xed c\xf9ng kh\u1ea3 n\u0103ng th\u1ef1c hi\u1ec7n c\u1ee7a nhi\u1ec1u gi\u1ea3i ph\xe1p.")
A.nso=s(["\ud604\uc0c1\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc77c\uc790\ub9ac\ub97c \uc4f0\uc138\uc694.","\uad50\uc721\uacfc \uad50\ud1b5\uc744 \uc4f0\uc138\uc694.","\uc5ec\ub7ec \uc6d0\uc778\uc744 \ube44\uad50\ud558\uc138\uc694.","\uc790\ub8cc\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c\uc640 V-\ub2e4 \ubcf4\ub2c8\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbl=new B.di("\uc9c0\uc5ed \uc778\uad6c \uac10\uc18c\uc758 \uc6d0\uc778\uc744 \ubd84\uc11d\ud558\ub294 \uae00\uc744 \uc368 \ubcf4\uc138\uc694.","\uc77c\ubd80 \uc9c0\uc5ed\uc5d0\uc11c\ub294 \uc80a\uc740 \uc778\uad6c\uac00 \uc9c0\uc18d\uc801\uc73c\ub85c \uac10\uc18c\ud558\ub294 \ud604\uc0c1\uc774 \ub098\ud0c0\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ubb38\uc81c\ub97c \ub2e8\uc21c\ud788 \uc77c\uc790\ub9ac \ubd80\uc871 \ub54c\ubb38\uc774\ub77c\uace0 \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc9c0\uc5ed \ub0b4 \uc77c\uc790\ub9ac\uac00 \uc801\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uad50\uc721 \uae30\ud68c, \uad50\ud1b5 \uc811\uadfc\uc131\uacfc \uc0dd\ud65c \ud3b8\uc758 \uc2dc\uc124\ub3c4 \uc778\uad6c \uc774\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc80a\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub300\ud559\uc774\ub098 \ucde8\uc5c5\uc744 \uc704\ud574 \ub2e4\ub978 \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\ub2e4 \ubcf4\ub2c8 \uadf8 \uc9c0\uc5ed\uc5d0\uc11c \uc7a5\uae30\uac04 \uc815\ucc29\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc778\uad6c\uac00 \uc904\uc5b4\ub4e4\uba74 \uc9c0\uc5ed \uc11c\ube44\uc2a4 \uc774\uc6a9\uc790\uac00 \uac10\uc18c\ud558\uace0 \ub2e4\uc2dc \uc0dd\ud65c \ud658\uacbd\uc774 \uc57d\ud654\ub418\ub294 \uacfc\uc815\uc774 \ub098\ud0c0\ub0a0 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5f0\ub839\ubcc4 \uc774\ub3d9 \uc790\ub8cc\uc640 \uc9c0\uc5ed\ubcc4 \uc77c\uc790\ub9ac, \uad50\uc721\uacfc \uc0dd\ud65c \ud658\uacbd \uc790\ub8cc\ub97c \ud568\uaed8 \ube44\uad50\ud574\uc57c \ubcf4\ub2e4 \uc815\ud655\ud55c \uc6d0\uc778\uc744 \ubd84\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u1ede m\u1ed9t s\u1ed1 khu v\u1ef1c \u0111ang xu\u1ea5t hi\u1ec7n hi\u1ec7n t\u01b0\u1ee3ng d\xe2n s\u1ed1 tr\u1ebb li\xean t\u1ee5c gi\u1ea3m. Kh\xf3 gi\u1ea3i th\xedch v\u1ea5n \u0111\u1ec1 n\xe0y \u0111\u01a1n gi\u1ea3n ch\u1ec9 do thi\u1ebfu vi\u1ec7c l\xe0m. Kh\xf4ng ch\u1ec9 s\u1ed1 vi\u1ec7c l\xe0m trong khu v\u1ef1c \xedt m\xe0 c\u01a1 h\u1ed9i gi\xe1o d\u1ee5c, kh\u1ea3 n\u0103ng ti\u1ebfp c\u1eadn giao th\xf4ng v\xe0 c\u01a1 s\u1edf ti\u1ec7n \xedch c\u0169ng c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn di chuy\u1ec3n d\xe2n s\u1ed1. Khi ng\u01b0\u1eddi tr\u1ebb chuy\u1ec3n sang khu v\u1ef1c kh\xe1c \u0111\u1ec3 h\u1ecdc \u0111\u1ea1i h\u1ecdc ho\u1eb7c t\xecm vi\u1ec7c, c\u0169ng c\xf3 th\u1ec3 ph\xe1t sinh tr\u01b0\u1eddng h\u1ee3p h\u1ecd \u0111\u1ecbnh c\u01b0 l\xe2u d\xe0i t\u1ea1i \u0111\xf3. Ng\u01b0\u1ee3c l\u1ea1i, khi d\xe2n s\u1ed1 gi\u1ea3m, ng\u01b0\u1eddi s\u1eed d\u1ee5ng d\u1ecbch v\u1ee5 khu v\u1ef1c gi\u1ea3m v\xe0 m\xf4i tr\u01b0\u1eddng s\u1ed1ng c\xf3 th\u1ec3 ti\u1ebfp t\u1ee5c suy y\u1ebfu. V\xec v\u1eady c\u1ea7n so s\xe1nh c\xf9ng d\u1eef li\u1ec7u di chuy\u1ec3n theo \u0111\u1ed9 tu\u1ed5i, vi\u1ec7c l\xe0m theo khu v\u1ef1c, gi\xe1o d\u1ee5c v\xe0 m\xf4i tr\u01b0\u1eddng s\u1ed1ng \u0111\u1ec3 ph\xe2n t\xedch nguy\xean nh\xe2n ch\xednh x\xe1c h\u01a1n.")
A.np5=s(["\uc6d0\uc778\uacfc\uc758 \uad00\ub828\uc131\uc744 \uc4f0\uc138\uc694.","\ud6a8\uacfc\ub97c \uc4f0\uc138\uc694.","\ube44\uc6a9\uc744 \uc4f0\uc138\uc694.","\uc2e4\ud589 \uac00\ub2a5\uc131\uc744 \uc4f0\uc138\uc694.","\ub300\uc0c1\ubcc4 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\ub2e8\uae30\xb7\uc7a5\uae30 \ud3c9\uac00\ub97c \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c\uacfc V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbF=new B.di("\uc0ac\ud68c \ubb38\uc81c\uc758 \ud574\uacb0\ucc45\uc744 \ud3c9\uac00\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc0ac\ud68c \ubb38\uc81c\uc758 \ud574\uacb0\ucc45\uc744 \ud3c9\uac00\ud560 \ub54c\ub294 \uc88b\uc740 \uc758\ub3c4\uac00 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ud6a8\uacfc\uc801\uc778 \ubc29\ubc95\uc774\ub77c\uace0 \ud310\ub2e8\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud55c \ub9cc\ud07c \ud574\uacb0\ucc45\ub3c4 \uc5ec\ub7ec \uae30\uc900\uc5d0\uc11c \ud3c9\uac00\ud574\uc57c \ud569\ub2c8\ub2e4. \uba3c\uc800 \ud574\ub2f9 \ubc29\uc548\uc774 \uc2e4\uc81c \uc6d0\uc778\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ubc29\ubc95\uc740 \ub2e8\uae30\uac04\uc5d0 \ud6a8\uacfc\uac00 \ube60\ub978 \ubc18\uba74\uc5d0 \ube44\uc6a9\uc774 \ub9ce\uc774 \ub4e4\uac70\ub098 \uc7a5\uae30\uc801\uc73c\ub85c \uc720\uc9c0\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud2b9\uc815 \uc9d1\ub2e8\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \ub2e4\ub978 \uc9d1\ub2e8\uc5d0\ub294 \ubd80\ub2f4\uc744 \uc904 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud6a8\uacfc, \ube44\uc6a9, \uc2e4\ud589 \uac00\ub2a5\uc131\uacfc \ub300\uc0c1\ubcc4 \uc601\ud5a5\uc744 \ud568\uaed8 \ube44\uad50\ud558\uace0 \uc2dc\ud589 \ud6c4 \uacb0\uacfc\ub97c \ub2e4\uc2dc \ud3c9\uac00\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","Khi \u0111\xe1nh gi\xe1 gi\u1ea3i ph\xe1p cho v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i, kh\xf4ng n\xean ch\u1ec9 v\xec m\u1ee5c \u0111\xedch t\u1ed1t m\xe0 k\u1ebft lu\u1eadn \u0111\xf3 l\xe0 ph\u01b0\u01a1ng ph\xe1p hi\u1ec7u qu\u1ea3. V\u1ea5n \u0111\u1ec1 c\xe0ng ph\u1ee9c t\u1ea1p th\xec gi\u1ea3i ph\xe1p c\xe0ng c\u1ea7n \u0111\u01b0\u1ee3c \u0111\xe1nh gi\xe1 theo nhi\u1ec1u ti\xeau ch\xed. Tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c nh\u1eadn ph\u01b0\u01a1ng \xe1n c\xf3 th\u1ef1c s\u1ef1 li\xean h\u1ec7 v\u1edbi nguy\xean nh\xe2n hay kh\xf4ng. C\xf3 ph\u01b0\u01a1ng ph\xe1p hi\u1ec7u qu\u1ea3 nhanh trong ng\u1eafn h\u1ea1n nh\u01b0ng ng\u01b0\u1ee3c l\u1ea1i chi ph\xed cao ho\u1eb7c kh\xf3 duy tr\xec d\xe0i h\u1ea1n. Ngo\xe0i ra c\xf3 th\u1ec3 gi\xfap m\u1ed9t nh\xf3m nh\u01b0ng t\u1ea1o g\xe1nh n\u1eb7ng cho nh\xf3m kh\xe1c. V\xec v\u1eady c\u1ea7n so s\xe1nh hi\u1ec7u qu\u1ea3, chi ph\xed, kh\u1ea3 n\u0103ng th\u1ef1c hi\u1ec7n v\xe0 \u1ea3nh h\u01b0\u1edfng theo t\u1eebng nh\xf3m, \u0111\u1ed3ng th\u1eddi \u0111\xe1nh gi\xe1 l\u1ea1i k\u1ebft qu\u1ea3 sau khi th\u1ef1c hi\u1ec7n.")
A.kEb=s([A.dbd,A.dbl,A.dbF],t.l5)
A.kZV=s(["\uc0ac\ud68c \ubb38\uc81c","\uc0ac\ud68c \ud604\uc0c1","\uc6d0\uc778","\uc9c1\uc811\uc801\uc778 \uc6d0\uc778","\uad6c\uc870\uc801\uc778 \uc6d0\uc778","\ubc30\uacbd","\uc694\uc778","\uc8fc\uc694 \uc694\uc778","\uc601\ud5a5","\uc601\ud5a5\uc744 \uc8fc\ub2e4","\uc601\ud5a5\uc744 \ubc1b\ub2e4","\uacb0\uacfc","\ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\ub2e4","\ubb38\uc81c\uac00 \uc2ec\ud654\ub418\ub2e4","\ud574\uacb0\ud558\ub2e4","\ud574\uacb0\ucc45","\ud574\uacb0 \ubc29\uc548","\ub300\ucc45","\ub300\ucc45\uc744 \ub9c8\ub828\ud558\ub2e4","\uc608\ubc29\ud558\ub2e4","\ubd84\uc11d\ud558\ub2e4","\uc6d0\uc778 \ubd84\uc11d","\uc790\ub8cc \ubd84\uc11d","\ud30c\uc545\ud558\ub2e4","\uc790\ub8cc","\uc790\ub8cc\ub97c \uc218\uc9d1\ud558\ub2e4","\ud1b5\uacc4","\ud1b5\uacc4 \uc790\ub8cc","\uc870\uc0ac","\uc124\ubb38 \uc870\uc0ac","\ucd94\uc138","\uc99d\uac00\ud558\ub2e4","\uac10\uc18c\ud558\ub2e4","\ube44\uc728","\uaca9\ucc28","\uc9c0\uc5ed \uaca9\ucc28","\uc8fc\uac70\ube44","\uad50\ud1b5 \ud63c\uc7a1","\ud658\uacbd \ubb38\uc81c","\ud658\uacbd \uc624\uc5fc","\uace0\ub839\ud654","\uc800\ucd9c\uc0dd","\uc778\uad6c \uac10\uc18c","\uc77c\uc790\ub9ac \ubd80\uc871","\ub514\uc9c0\ud138 \uaca9\ucc28","\ucde8\uc57d \uacc4\uce35","\ubd80\ub2f4","\uacbd\uc81c\uc801 \ubd80\ub2f4","\uad00\ub828\uc131","\uadfc\uac70","\uadfc\uac70\ub97c \uc81c\uc2dc\ud558\ub2e4"],t.s)
A.kXW=s(["N(\uc73c)\ub85c \uc778\ud574","N\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub2e4","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c","V-\ub2e4 \ubcf4\ub2c8","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c","V/A-(\uc73c)\u3134/\ub294 \uac83\uc73c\ub85c \ub098\ud0c0\ub098\ub2e4","V-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4","V/A-\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc V/A-(\uc73c)\u3134/\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4","N\uc5d0 \ube44\ud574","V-\ub294 \uc6d0\uc778\uc73c\ub85c \uaf3d\ud788\ub2e4","V-\uae30 \uc704\ud574\uc11c\ub294"],t.s)
A.jIn=s(["\uc0ac\ud68c \ubb38\uc81c = v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i","\uc0ac\ud68c \ud604\uc0c1 = hi\u1ec7n t\u01b0\u1ee3ng x\xe3 h\u1ed9i","\uc6d0\uc778 = nguy\xean nh\xe2n","\uc9c1\uc811\uc801\uc778 \uc6d0\uc778 = nguy\xean nh\xe2n tr\u1ef1c ti\u1ebfp","\uad6c\uc870\uc801\uc778 \uc6d0\uc778 = nguy\xean nh\xe2n mang t\xednh c\u1ea5u tr\xfac","\ubc30\uacbd = b\u1ed1i c\u1ea3nh","\uc694\uc778 = y\u1ebfu t\u1ed1","\uc601\ud5a5 = \u1ea3nh h\u01b0\u1edfng","\uacb0\uacfc = k\u1ebft qu\u1ea3","\ud574\uacb0\ucc45 = gi\u1ea3i ph\xe1p","\ud574\uacb0 \ubc29\uc548 = ph\u01b0\u01a1ng \xe1n gi\u1ea3i quy\u1ebft","\ub300\ucc45 = bi\u1ec7n ph\xe1p","\uc608\ubc29\ud558\ub2e4 = ph\xf2ng ng\u1eeba","\ubd84\uc11d\ud558\ub2e4 = ph\xe2n t\xedch","\ud30c\uc545\ud558\ub2e4 = n\u1eafm b\u1eaft","\uc790\ub8cc = d\u1eef li\u1ec7u/t\xe0i li\u1ec7u","\ud1b5\uacc4 = th\u1ed1ng k\xea","\uc870\uc0ac = kh\u1ea3o s\xe1t/\u0111i\u1ec1u tra","\ucd94\uc138 = xu h\u01b0\u1edbng","\uc99d\uac00\ud558\ub2e4 = t\u0103ng","\uac10\uc18c\ud558\ub2e4 = gi\u1ea3m","\ube44\uc728 = t\u1ef7 l\u1ec7","\uaca9\ucc28 = kho\u1ea3ng c\xe1ch/ch\xeanh l\u1ec7ch","\uc9c0\uc5ed \uaca9\ucc28 = kho\u1ea3ng c\xe1ch khu v\u1ef1c","\uc8fc\uac70\ube44 = chi ph\xed nh\xe0 \u1edf","\uad50\ud1b5 \ud63c\uc7a1 = \xf9n t\u1eafc giao th\xf4ng","\ud658\uacbd \ubb38\uc81c = v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng","\ud658\uacbd \uc624\uc5fc = \xf4 nhi\u1ec5m m\xf4i tr\u01b0\u1eddng","\uace0\ub839\ud654 = gi\xe0 h\xf3a d\xe2n s\u1ed1","\uc800\ucd9c\uc0dd = m\u1ee9c sinh th\u1ea5p","\uc778\uad6c \uac10\uc18c = suy gi\u1ea3m d\xe2n s\u1ed1","\uc77c\uc790\ub9ac \ubd80\uc871 = thi\u1ebfu vi\u1ec7c l\xe0m","\ub514\uc9c0\ud138 \uaca9\ucc28 = kho\u1ea3ng c\xe1ch s\u1ed1","\ucde8\uc57d \uacc4\uce35 = nh\xf3m d\u1ec5 b\u1ecb t\u1ed5n th\u01b0\u01a1ng","\ubd80\ub2f4 = g\xe1nh n\u1eb7ng","\uad00\ub828\uc131 = m\u1ed1i li\xean h\u1ec7","\uadfc\uac70 = c\u0103n c\u1ee9","N(\uc73c)\ub85c \uc778\ud574 = do/b\u1edfi v\xec...","N\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub2e4 = \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn...","V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9... m\xe0 c\xf2n...","V-\ub2e4 \ubcf4\ub2c8 = c\u1ee9... r\u1ed3i d\u1eabn \u0111\u1ebfn/nh\u1eadn ra...","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/tr\xe1i l\u1ea1i...","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c = v\xec \u1edf m\u1ee9c... n\xean...","V/A-(\uc73c)\u3134/\ub294 \uac83\uc73c\ub85c \ub098\ud0c0\ub098\ub2e4 = k\u1ebft qu\u1ea3 cho th\u1ea5y...","\uad50\ud1b5 \ud63c\uc7a1\uc73c\ub85c \uc778\ud574 \uc774\ub3d9 \uc2dc\uac04\uc774 \uae38\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","\uc8fc\uac70 \ud658\uacbd\uc740 \uc9c0\uc5ed \uc778\uad6c \uc774\ub3d9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc778\uad6c \uac10\uc18c\ub294 \uc18c\ube44\ub97c \uc904\uc77c \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc9c0\uc5ed \uc11c\ube44\uc2a4 \uc720\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.DY,"\ub3c4\uc2dc\ub294 \uc77c\uc790\ub9ac\uac00 \ub9ce\uc740 \ubc18\uba74\uc5d0 \uc8fc\uac70\ube44 \ubd80\ub2f4\uc774 \ud070 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ubb38\uc81c\uac00 \ubcf5\uc7a1\ud55c \ub9cc\ud07c \uc5ec\ub7ec \uad00\uc810\uc5d0\uc11c \ubd84\uc11d\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc870\uc0ac \uacb0\uacfc \uc9c0\uc5ed\ubcc4 \ucc28\uc774\uac00 \ud070 \uac83\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.","\uad00\ub828\uc131\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uc778\uacfc\uad00\uacc4\uac00 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uac1c\uc778\uc758 \uacbd\ud5d8\uc740 \uc911\uc694\ud55c \uc0ac\ub840\uac00 \ub420 \uc218 \uc788\uc9c0\ub9cc \uc0ac\ud68c \uc804\uccb4\uc758 \ud604\uc0c1\uc744 \ud310\ub2e8\ud558\ub824\uba74 \ub354 \ub113\uc740 \uc790\ub8cc\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","\uc0ac\ud68c \ubb38\uc81c\ub97c \ubd84\uc11d\ud560 \ub54c\ub294 \uba3c\uc800 \uacb0\ub860\uc744 \uc815\ud55c \ub4a4 \uc790\ub8cc\ub97c \ucc3e\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc790\ub8cc\ub97c \ud655\uc778\ud558\uba74\uc11c \uae30\uc874 \uc0dd\uac01\uc744 \uc218\uc815\ud560 \uc218 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4.","\ud575\uc2ec \ud750\ub984: \ud604\uc0c1 \ud655\uc778 \u2192 \uc790\ub8cc \uc218\uc9d1 \u2192 \uc0ac\uc2e4\uacfc \uc758\uacac \uad6c\ubd84 \u2192 \uc9c1\uc811\xb7\uad6c\uc870\uc801 \uc6d0\uc778 \ubd84\uc11d \u2192 \uc601\ud5a5\ubc1b\ub294 \uc9d1\ub2e8 \ud655\uc778 \u2192 \ud574\uacb0\ucc45 \ube44\uad50 \u2192 \uc2e4\ud589 \uac00\ub2a5\uc131 \uac80\ud1a0 \u2192 \uacb0\uacfc \uc7ac\ud3c9\uac00."],t.s)
