A.loz=s(["\uc815\ubcf4 = th\xf4ng tin","\ubbf8\ub514\uc5b4 = truy\u1ec1n th\xf4ng","\ub9e4\uccb4 = ph\u01b0\u01a1ng ti\u1ec7n truy\u1ec1n th\xf4ng","\ucd9c\ucc98 = ngu\u1ed3n","\uacf5\uc2dd \ucd9c\ucc98 = ngu\u1ed3n ch\xednh th\u1ee9c","\uc791\uc131\uc790 = t\xe1c gi\u1ea3","\uac8c\uc2dc\ubb3c = b\xe0i \u0111\u0103ng","\uac8c\uc2dc \ub0a0\uc9dc = ng\xe0y \u0111\u0103ng","\uc0ac\uc2e4 = s\u1ef1 th\u1eadt/d\u1eef ki\u1ec7n","\uc758\uacac = \xfd ki\u1ebfn","\uc8fc\uc7a5 = l\u1eadp lu\u1eadn","\ucd94\uce21 = suy \u0111o\xe1n","\uadfc\uac70 = c\u0103n c\u1ee9","\uc790\ub8cc = t\xe0i li\u1ec7u/d\u1eef li\u1ec7u","\uc6d0\ubb38 = b\u1ea3n g\u1ed1c","\uc778\uc6a9\ud558\ub2e4 = tr\xedch d\u1eabn","\ub9e5\ub77d = ng\u1eef c\u1ea3nh","\uc65c\uace1\ud558\ub2e4 = b\xf3p m\xe9o","\uacfc\uc7a5\ud558\ub2e4 = ph\xf3ng \u0111\u1ea1i","\uac00\uc9dc \ub274\uc2a4 = tin gi\u1ea3","\ud5c8\uc704 \uc815\ubcf4 = th\xf4ng tin sai s\u1ef1 th\u1eadt","\uc798\ubabb\ub41c \uc815\ubcf4 = th\xf4ng tin sai","\uc624\ub798\ub41c \uc815\ubcf4 = th\xf4ng tin c\u0169","\ucd5c\uc2e0 \uc815\ubcf4 = th\xf4ng tin m\u1edbi nh\u1ea5t","\uc790\uadf9\uc801\uc774\ub2e4 = gi\u1eadt g\xe2n","\ub313\uae00 = b\xecnh lu\u1eadn","\uc870\ud68c \uc218 = l\u01b0\u1ee3t xem","\uacf5\uc720\ud558\ub2e4 = chia s\u1ebb","\ud655\uc0b0\ub418\ub2e4 = lan truy\u1ec1n","\uad11\uace0\uc131 \uc815\ubcf4 = th\xf4ng tin qu\u1ea3ng c\xe1o","\uc2e0\ub8b0\uc131 = \u0111\u1ed9 tin c\u1eady","\uac80\uc99d\ud558\ub2e4 = ki\u1ec3m ch\u1ee9ng","\uc870\ud68c \uc218\uac00 \ub9ce\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uc815\ud655\ud55c \uc815\ubcf4\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc815\ubcf4\uac00 \uc5b4\ub514\uc5d0\uc11c \ub098\uc628 \uac83\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc81c\ubaa9\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \ubcf8\ubb38\uc744 \uc9c1\uc811 \uc77d\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc601\uc0c1\uc774 \uc6d0\ub798 \ub9e5\ub77d\uacfc \ub2e4\ub974\uac8c \ud3b8\uc9d1\ub410\uc744 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ud655\uc778 \uacb0\uacfc \uc624\ub798\ub41c \uc0ac\uc9c4\uc778 \uac83\uc73c\ub85c \ud655\uc778\ub410\uc2b5\ub2c8\ub2e4.","SNS\ub294 \uc815\ubcf4\uac00 \ube60\ub978 \ubc18\uba74\uc5d0 \uc798\ubabb\ub41c \uc815\ubcf4\ub3c4 \ube60\ub974\uac8c \ud37c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\ubcf4\ub97c \uc27d\uac8c \uacf5\uc720\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c \ud655\uc778\ud560 \ucc45\uc784\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\uc2e4\uacfc \uc758\uacac\uc740 \uc11c\ub85c \ub2e4\ub985\ub2c8\ub2e4. \uc758\uacac\uc774 \ub9ce\uc544\ub3c4 \uc0ac\uc2e4\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\ucd9c\ucc98\uac00 \uc788\ub2e4\uace0 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucd9c\ucc98 \uc790\uccb4\uac00 \ubb34\uc5c7\uc778\uc9c0, \uc5bc\ub9c8\ub098 \ucd5c\uc2e0\uc778\uc9c0\uc640 \uc6d0\uc790\ub8cc\uac00 \uc2e4\uc81c \uc8fc\uc7a5\uc744 \ub4b7\ubc1b\uce68\ud558\ub294\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc0ac\uc9c4\uacfc \uc601\uc0c1\uc740 \uac15\ud55c \uc778\uc0c1\uc744 \uc904 \uc218 \uc788\uc9c0\ub9cc \ucd2c\uc601 \uc2dc\uc810, \uc7a5\uc18c\uc640 \uc55e\ub4a4 \ub9e5\ub77d\uc774 \ube60\uc9c0\uba74 \uc6d0\ub798 \uc758\ubbf8\uc640 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc624\ub798\ub41c \uc815\ubcf4\ub294 \ub2f9\uc2dc\uc5d0\ub294 \ub9de\uc558\uc744 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud5c8\uc704 \uc815\ubcf4\uc640 \uad6c\ubd84\ud574\uc11c \uc774\ud574\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud575\uc2ec \ud750\ub984: \uc815\ubcf4 \ubc1c\uacac \u2192 \ucd9c\ucc98 \ud655\uc778 \u2192 \uac8c\uc2dc \ub0a0\uc9dc \ud655\uc778 \u2192 \uc791\uc131\uc790 \ud655\uc778 \u2192 \uc6d0\ubb38\xb7\uadfc\uac70 \ud655\uc778 \u2192 \ub2e4\ub978 \uc790\ub8cc \ube44\uad50 \u2192 \uc0ac\uc2e4\xb7\uc758\uacac\xb7\ucd94\uce21 \uad6c\ubd84 \u2192 \ud604\uc7ac \uc801\uc6a9 \uc5ec\ubd80 \ud310\ub2e8 \u2192 \uacf5\uc720 \uc5ec\ubd80 \uacb0\uc815."],t.s)
