A.kLk=s(["V/A-(\uc73c)\u3134/\ub294 \ud3b8\uc774\ub2e4","V/A-(\uc73c)\u3134/\ub294 \uc810\uc774 \uc788\ub2e4","V-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4","V-\ub3c4\ub85d \ub178\ub825\ud558\ub2e4","V-\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\ub2e4","A-\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\ub2e4","V-(\uc73c)\u3134 \ud6c4\ubd80\ud130","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c","V-\uae30\ubcf4\ub2e4\ub294","V/A-\uae30\ub294 \ud558\uc9c0\ub9cc","V-\ub2e4 \ubcf4\ub2c8","V-\ub3c4\ub85d \ud558\ub2e4","V-(\uc73c)\u3139\uc218\ub85d"],t.s)
A.lfv=s(["\ud3c9\uac00 = \u0111\xe1nh gi\xe1","\uc5c5\ubb34 \ud3c9\uac00 = \u0111\xe1nh gi\xe1 c\xf4ng vi\u1ec7c","\uc131\uacfc \ud3c9\uac00 = \u0111\xe1nh gi\xe1 th\xe0nh t\xedch","\ud3c9\uac00 \uae30\uc900 = ti\xeau chu\u1ea9n \u0111\xe1nh gi\xe1","\ud53c\ub4dc\ubc31 = ph\u1ea3n h\u1ed3i","\uc9c0\uc801 = ch\u1ec9 ra \u0111i\u1ec3m sai/v\u1ea5n \u0111\u1ec1","\uc870\uc5b8 = l\u1eddi khuy\xean","\uac1c\uc120 \uc694\uccad = y\xeau c\u1ea7u c\u1ea3i thi\u1ec7n","\uac1d\uad00\uc801\uc774\ub2e4 = kh\xe1ch quan","\uc8fc\uad00\uc801\uc774\ub2e4 = ch\u1ee7 quan","\uacf5\uc815\ud558\ub2e4 = c\xf4ng b\u1eb1ng","\uc131\uacfc = th\xe0nh qu\u1ea3","\uc2e4\uc801 = k\u1ebft qu\u1ea3 th\u1ef1c t\u1ebf","\ubaa9\ud45c \ub2ec\uc131\ub960 = t\u1ef7 l\u1ec7 ho\xe0n th\xe0nh m\u1ee5c ti\xeau","\uc5c5\ubb34 \ud0dc\ub3c4 = th\xe1i \u0111\u1ed9 l\xe0m vi\u1ec7c","\uc801\uadf9\uc131 = t\xednh ch\u1ee7 \u0111\u1ed9ng","\uc815\ud655\uc131 = \u0111\u1ed9 ch\xednh x\xe1c","\ud6a8\uc728\uc131 = t\xednh hi\u1ec7u qu\u1ea3","\ud611\uc5c5 \ub2a5\ub825 = kh\u1ea3 n\u0103ng h\u1ee3p t\xe1c","\uc758\uc0ac\uc18c\ud1b5 \ub2a5\ub825 = kh\u1ea3 n\u0103ng giao ti\u1ebfp","\uac15\uc810 = \u0111i\u1ec3m m\u1ea1nh","\uc57d\uc810 = \u0111i\u1ec3m y\u1ebfu","\uac1c\uc120\uc810 = \u0111i\u1ec3m c\u1ea7n c\u1ea3i thi\u1ec7n","\ubcf4\uc644\ud558\ub2e4 = b\u1ed5 sung/kh\u1eafc ph\u1ee5c","\ubc18\uc601\ud558\ub2e4 = ph\u1ea3n \xe1nh/\xe1p d\u1ee5ng","\uc218\uc6a9\ud558\ub2e4 = ti\u1ebfp nh\u1eadn","\ubc18\ubc15\ud558\ub2e4 = ph\u1ea3n b\xe1c","\ub0a9\ub4dd\ud558\ub2e4 = hi\u1ec3u v\xe0 ch\u1ea5p nh\u1eadn","\uad6c\uccb4\uc801\uc774\ub2e4 = c\u1ee5 th\u1ec3","\ub9c9\uc5f0\ud558\ub2e4 = m\u01a1 h\u1ed3","\ud6c4\uc18d \uc870\uce58 = h\xe0nh \u0111\u1ed9ng ti\u1ebfp theo","V/A-(\uc73c)\u3134/\ub294 \ud3b8\uc774\ub2e4 = thu\u1ed9c d\u1ea1ng/c\xf3 xu h\u01b0\u1edbng...","V/A-(\uc73c)\u3134/\ub294 \uc810\uc774 \uc788\ub2e4 = c\xf3 \u0111i\u1ec3m l\xe0...","V-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4 = c\u1ea7n ph\u1ea3i...","V-\ub3c4\ub85d \ub178\ub825\ud558\ub2e4 = c\u1ed1 g\u1eafng \u0111\u1ec3...","V-\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\ub2e4 = nh\u1eadn ph\u1ea3n h\u1ed3i r\u1eb1ng...","V-(\uc73c)\u3134 \ud6c4\ubd80\ud130 = k\u1ec3 t\u1eeb sau khi...","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c = t\u01b0\u01a1ng x\u1ee9ng v\u1edbi/v\xec \u1edf m\u1ee9c... n\xean...","\uc800\ub294 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\uc5d0 \ube44\uad50\uc801 \ube68\ub9ac \uc801\uc751\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.","\ubcf4\uace0\uac00 \uc870\uae08 \uae38\uc5b4\uc9c0\ub294 \uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ud575\uc2ec \ub0b4\uc6a9\uc744 \uba3c\uc800 \ub9d0\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\uc55e\uc73c\ub85c\ub294 \ubb38\uc81c\ub97c \ubbf8\ub9ac \uacf5\uc720\ud558\ub3c4\ub85d \ub178\ub825\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf4\uace0\uac00 \uae38\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.","\uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \uc0ac\uc6a9\ud55c \ud6c4\ubd80\ud130 \uae30\ub85d \ub204\ub77d\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.","\uacbd\ud5d8\uc774 \ub9ce\uc740 \ub9cc\ud07c \ud6c4\ubc30\uc5d0\uac8c \uc88b\uc740 \uc608\ub97c \ubcf4\uc5ec \uc904 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\uc88b\uc740 \ud53c\ub4dc\ubc31\uc740 \uc0ac\ub78c\uc744 \uacf5\uaca9\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uacfc \uadf8 \uc601\ud5a5\uc5d0 \ub300\ud574 \uc774\uc57c\uae30\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.","\ud53c\ub4dc\ubc31\uc758 \ud575\uc2ec\uc740 \ub4e3\ub294 \uac83\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uc2e4\uc81c \ud589\ub3d9\uc744 \ubc14\uafb8\uace0 \uacb0\uacfc\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.","\ud575\uc2ec \ud750\ub984: \ud3c9\uac00 \uae30\uc900 \ud655\uc778 \u2192 \ud53c\ub4dc\ubc31 \uc774\ud574 \u2192 \uad6c\uccb4\uc801\uc778 \uc0ac\ub840 \ud655\uc778 \u2192 \uac1c\uc120 \ud589\ub3d9 \uacb0\uc815 \u2192 \uc77c\uc815 \uae30\uac04 \uc801\uc6a9 \u2192 \uacb0\uacfc \uce21\uc815 \u2192 \ub2e4\uc2dc \ud53c\ub4dc\ubc31 \ubc1b\uae30."],t.s)
A.Lr=new B.hU(8,"\ud3c9\uac00\uc640 \ud53c\ub4dc\ubc31","\u0110\xe1nh gi\xe1 v\xe0 ph\u1ea3n h\u1ed3i",A.lLI,A.jjs,A.m_e,A.l4y,A.kvI,A.lvx,A.jA2,A.kV3,A.lF3,A.lsR,A.kLk,A.lfv)
A.kDU=s(["\uac1c\uc778 \uc758\uacac\uc744 \uad6c\uc870\ud654\ub41c \ub17c\ub9ac\ub85c \ud45c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc8fc\uc7a5, \uc758\uacac, \uadfc\uac70, \uc608\uc2dc, \ubc18\ub860\uacfc \uacb0\ub860\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc8fc\uc7a5 \u2192 \uc774\uc720 \u2192 \uadfc\uac70 \u2192 \uc608\uc2dc \u2192 \uc608\uc0c1 \ubc18\ub860 \u2192 \uacb0\ub860\uc758 \uae30\ubcf8 \uad6c\uc870\ub97c \uc775\ud799\ub2c8\ub2e4.","\ud1a0\ub860\uc774 \uac1c\uc778\uc801\uc778 \ub9d0\ub2e4\ud23c\uc774 \ub418\uc9c0 \uc54a\ub3c4\ub85d \uc758\uacac\uc744 \uc81c\uc2dc\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc801\uc808\ud55c \uc218\uce58, \uc0ac\ub840\uc640 \uacbd\ud5d8\uc744 \uadfc\uac70\ub85c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uadfc\uac70 \uc788\ub294 \uc8fc\uc7a5\uacfc \ub2e8\uc21c\ud55c \uac10\uc815 \ud45c\ud604\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uadfc\uac70\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc810\uc744 \uc9c0\uc801\ud558\uba70 \uc758\uacac\uc5d0 \ubc18\ubc15\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubc18\ubc15\ud558\uae30 \uc804\uc5d0 \uc0c1\ub300 \uc758\uacac\uc758 \uc77c\ubd80\ub97c \uc778\uc815\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \ub17c\ub9ac\ub97c \uc815\ud655\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc744 \ub54c \ub2e4\uc2dc \ubb3b\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub9d0\ud55c \uc0ac\ub78c\uc744 \uacf5\uaca9\ud558\uc9c0 \uc54a\uace0 \ub0b4\uc6a9 \uc790\uccb4\ub97c \ube44\ud310\uc801\uc73c\ub85c \uac80\ud1a0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub450 \ubc29\uc548\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \ube44\uad50\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc0c8\ub85c\uc6b4 \uadfc\uac70\uac00 \ub098\uc654\uc744 \ub54c \uc790\uc2e0\uc758 \uad00\uc810\uc744 \uc870\uc815\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc790\ub8cc\uac00 \ub4b7\ubc1b\uce68\ud558\ub294 \ubc94\uc704\ub97c \ub118\uc5b4 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0 \uacb0\ub860\uc744 \ub0b4\ub9ac\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc8fc\uc81c \ud655\uc778 \u2192 \uc785\uc7a5 \uc815\ub9ac \u2192 \uadfc\uac70 \uc81c\uc2dc \u2192 \uc0c1\ub300 \uc758\uacac \uacbd\uccad \u2192 \ubc18\ub860 \uac80\ud1a0 \u2192 \uc7ac\ubc18\ub860 \u2192 \uacf5\ud1b5\uc810 \ud655\uc778 \u2192 \uacb0\ub860\uc758 \ud1a0\ub860 \uacfc\uc815\uc744 \uc775\ud799\ub2c8\ub2e4."],t.s)
A.cAt=new B.d("\uc8fc\uc7a5\uc744 \ud560 \ub54c\ub294 \uc774\uc720\uc640 \uadfc\uac70\ub97c \ud568\uaed8 \uc81c\uc2dc\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi \u0111\u01b0a ra l\u1eadp lu\u1eadn c\u1ea7n tr\xecnh b\xe0y c\u1ea3 l\xfd do v\xe0 c\u0103n c\u1ee9.")
