A.cTl=new B.al("\ud1a0\ub860\uc5d0\uc11c \uc591\ucabd \uc758\uacac\uc774 \ubd80\ub52a\uce58\ub294 \ud575\uc2ec \ubb38\uc81c\ub97c \uc758\ubbf8\ud558\ub294 \ub9d0\uc740?",A.kvZ,0,"\uc7c1\uc810 = v\u1ea5n \u0111\u1ec1 tr\u1ecdng t\xe2m \u0111ang \u0111\u01b0\u1ee3c tranh lu\u1eadn.","\uc5b4\ud718")
A.k0m=s(["\ubbfc\uc218 \uc528\ub294 \ubaa8\ub4e0 \ud68c\uc758\ub97c \uc5c6\uc560\uc790\uace0 \uc8fc\uc7a5\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ud68c\uc758 \uc2dc\uac04\uc774 \uc9e7\uc73c\uba74 \ubb34\uc870\uac74 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uc7a5\uc810\uc744 \uc778\uc815\ud558\uba74\uc11c \ubb38\uc81c\uc810\uc744 \uc9c0\uc801\ud558\uace0 \ub300\uc548\uc744 \uc81c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uc5b4\ub5a4 \uc758\uacac\ub3c4 \ub9d0\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4."],t.s)
A.cVE=new B.al("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ud55c \ud68c\uc0ac\uc5d0\uc11c\ub294 \ud68c\uc758 \uc2dc\uac04\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubaa8\ub4e0 \ud68c\uc758\ub97c 20\ubd84\uc73c\ub85c \uc81c\ud55c\ud558\uc790\ub294 \uc758\uacac\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. \ubbfc\uc218 \uc528\ub294 \uc9e7\uc740 \ud68c\uc758\uac00 \uc5c5\ubb34 \uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\ub294 \ucc2c\uc131\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \ub2e4\ub8e8\ub294 \ud68c\uc758\uae4c\uc9c0 \ubaa8\ub450 20\ubd84\uc73c\ub85c \uc81c\ud55c\ud558\uba74 \ucda9\ubd84\ud55c \ub17c\uc758\uac00 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4\uace0 \uc9c0\uc801\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub2e8\uc21c \ubcf4\uace0 \ud68c\uc758\ub294 20\ubd84\uc73c\ub85c \uc81c\ud55c\ud558\uace0 \uc911\uc694\ud55c \uc758\uc0ac \uacb0\uc815 \ud68c\uc758\ub294 \ubcc4\ub3c4\uc758 \uc2dc\uac04\uc744 \uc815\ud558\uc790\ub294 \ub300\uc548\uc744 \uc81c\uc548\ud588\uc2b5\ub2c8\ub2e4.",A.k0m,2,"Minsu c\xf4ng nh\u1eadn \u01b0u \u0111i\u1ec3m, ph\u1ea3n bi\u1ec7n nh\u01b0\u1ee3c \u0111i\u1ec3m v\xe0 \u0111\u01b0a ra ph\u01b0\u01a1ng \xe1n thay th\u1ebf.","\uc77d\uae30")
A.kqL=s(["\uc774\uac83\uc774 100% \uc720\uc77c\ud55c \uc6d0\uc778\uc785\ub2c8\ub2e4.","\ud604\uc7ac \uc790\ub8cc\ub9cc\uc73c\ub85c\ub294 \ud55c \uac00\uc9c0 \uc6d0\uc778\uc73c\ub85c \ub2e8\uc815\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.","\uc81c\uac00 \uadf8\ub807\uac8c \uc0dd\uac01\ud558\ub2c8 \ub9de\uc2b5\ub2c8\ub2e4.","\ucd94\uac00 \uc790\ub8cc\ub294 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4."],t.s)
A.cUn=new B.al("\uc790\ub8cc\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc744 \ub54c \uac00\uc7a5 \uc801\uc808\ud55c \uacb0\ub860 \ud45c\ud604\uc740?",A.kqL,1,"Khi d\u1eef li\u1ec7u ch\u01b0a \u0111\u1ee7 n\xean gi\u1eef m\u1ee9c k\u1ebft lu\u1eadn ph\xf9 h\u1ee3p.","\uacb0\ub860")
A.kfR=s(["\uc8fc\uc7a5\uc5d0\ub294 \uadfc\uac70\uac00 \ud544\uc694\ud558\ub2e4.","\uc0c1\ub300\ubc29\uc758 \ubc18\ub860\uc744 \uac80\ud1a0\ud560 \uc218 \uc788\ub2e4.","\uc0c8\ub85c\uc6b4 \uc790\ub8cc\uac00 \ub098\uc624\uba74 \uae30\uc874 \ud310\ub2e8\uc744 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub2e4.","\ud1a0\ub860\uc758 \ubaa9\uc801\uc740 \uc5b4\ub5a4 \ubc29\ubc95\uc744 \uc368\uc11c\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc744 \uc774\uae30\ub294 \uac83\uc774\ub2e4."],t.s)
A.cWT=new B.al("\uc88b\uc740 \uc8fc\uc7a5\uacfc \ud1a0\ub860\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.kfR,3,"M\u1ee5c ti\xeau c\u1ee7a th\u1ea3o lu\u1eadn t\u1ed1t l\xe0 ki\u1ec3m tra \xfd t\u01b0\u1edfng v\xe0 t\xecm k\u1ebft lu\u1eadn t\u1ed1t h\u01a1n, kh\xf4ng ph\u1ea3i th\u1eafng b\u1eb1ng m\u1ecdi c\xe1ch.","\uc885\ud569")
