A.jLD=s(["\uc8fc\uc7a5 = l\u1eadp lu\u1eadn","\uc758\uacac = \xfd ki\u1ebfn","\uc785\uc7a5 = l\u1eadp tr\u01b0\u1eddng","\ucc2c\uc131 = t\xe1n th\xe0nh","\ubc18\ub300 = ph\u1ea3n \u0111\u1ed1i","\uadfc\uac70 = c\u0103n c\u1ee9","\uc774\uc720 = l\xfd do","\uc608\uc2dc = v\xed d\u1ee5","\uc0ac\ub840 = tr\u01b0\u1eddng h\u1ee3p th\u1ef1c t\u1ebf","\uc790\ub8cc = d\u1eef li\u1ec7u","\ud1b5\uacc4 = th\u1ed1ng k\xea","\uac1d\uad00\uc801\uc774\ub2e4 = kh\xe1ch quan","\uc8fc\uad00\uc801\uc774\ub2e4 = ch\u1ee7 quan","\ub17c\ub9ac = logic","\ub17c\ub9ac\uc801\uc774\ub2e4 = c\xf3 t\xednh logic","\uc124\ub4dd\ub825 = s\u1ee9c thuy\u1ebft ph\u1ee5c","\ud1a0\ub860 = th\u1ea3o lu\u1eadn","\ub17c\uc7c1 = tranh lu\u1eadn/tranh c\xe3i","\uc7c1\uc810 = v\u1ea5n \u0111\u1ec1 tr\u1ecdng t\xe2m","\ubc18\ub860 = ph\u1ea3n bi\u1ec7n","\ubc18\ubc15\ud558\ub2e4 = ph\u1ea3n b\xe1c","\uc7ac\ubc18\ub860 = ph\u1ea3n bi\u1ec7n l\u1ea1i","\ub3d9\uc758\ud558\ub2e4 = \u0111\u1ed3ng \xfd","\uc778\uc815\ud558\ub2e4 = c\xf4ng nh\u1eadn","\ud0c0\ub2f9\ud558\ub2e4 = h\u1ee3p l\xfd","\ud569\ub9ac\uc801\uc774\ub2e4 = h\u1ee3p l\xfd","\ubaa8\uc21c = m\xe2u thu\u1eabn logic","\uc804\uc81c = ti\u1ec1n \u0111\u1ec1","\uacb0\ub860 = k\u1ebft lu\u1eadn","\ub300\uc548 = ph\u01b0\u01a1ng \xe1n thay th\u1ebf","\uacf5\ud1b5\uc810 = \u0111i\u1ec3m chung","\ucc28\uc774\uc810 = \u0111i\u1ec3m kh\xe1c","\ud569\uc758 = s\u1ef1 th\u1ed1ng nh\u1ea5t","N\uc5d0 \ub530\ub974\uba74 = theo N...","V/A-\ub2e4\ub294 \uc810\uc5d0\uc11c = x\xe9t \u1edf \u0111i\u1ec3m r\u1eb1ng...","V/A-\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4 = c\xf3 th\u1ec3 xem l\xe0...","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/tr\xe1i l\u1ea1i...",u.jQ,"V/A-\ub354\ub77c\ub3c4 = d\xf9... th\xec v\u1eabn...","V-\uae30 \uc704\ud574\uc11c\ub294 = \u0111\u1ec3... th\xec c\u1ea7n...","\ucd5c\uadfc \uc870\uc0ac\uc5d0 \ub530\ub974\uba74 \uc774\uc6a9\uc790 \ub9cc\uc871\ub3c4\uac00 \ub192\uc544\uc84c\uc2b5\ub2c8\ub2e4.","\uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774 \ubc29\ubc95\uc740 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc5ec\ub7ec \uc790\ub8cc\ub97c \uc885\ud569\ud558\uba74 \uc77c\uc815\ud55c \ud6a8\uacfc\uac00 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.Ir,"\ub9ce\uc740 \uc0ac\ub78c\uc774 \ucc2c\uc131\ud55c\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uac00\uc7a5 \uc88b\uc740 \ubc29\ubc95\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc758\uacac\uc774 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4.","\uc88b\uc740 \uacb0\ub860\uc744 \ub0b4\ub9ac\uae30 \uc704\ud574\uc11c\ub294 \ucc2c\uc131\uacfc \ubc18\ub300 \uadfc\uac70\ub97c \ubaa8\ub450 \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc8fc\uc7a5\uacfc \uc758\uacac\uc740 \ube44\uc2b7\ud574 \ubcf4\uc774\uc9c0\ub9cc \uc88b\uc740 \uc8fc\uc7a5\uc740 \uc774\uc720\uc640 \uadfc\uac70\ub97c \ud1b5\ud574 \uc790\uc2e0\uc758 \uacb0\ub860\uc744 \uc124\uba85\ud55c\ub2e4\ub294 \ucc28\uc774\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ud1a0\ub860\uc5d0\uc11c \uc0c1\ub300\ubc29\uc758 \uc8fc\uc7a5\uc744 \ubc18\ubc15\ud560 \ub54c\ub294 \uc0ac\ub78c\uc744 \uacf5\uaca9\ud558\uc9c0 \ub9d0\uace0 \uc8fc\uc7a5, \uc804\uc81c, \uc790\ub8cc\uc640 \ub17c\ub9ac \uc0ac\uc774\uc5d0 \ubb38\uc81c\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc790\uc2e0\uc758 \uae30\uc874 \uc8fc\uc7a5\uacfc \ub2e4\ub978 \uc790\ub8cc\uac00 \ub098\uc654\uc744 \ub54c \uc758\uacac\uc744 \uc218\uc815\ud558\ub294 \uac83\uc740 \ud328\ubc30\uac00 \uc544\ub2c8\ub77c \ub354 \uc815\ud655\ud55c \ud310\ub2e8\uc744 \uc704\ud55c \uacfc\uc815\uc785\ub2c8\ub2e4.","\ubc18\ub300 \uc758\uacac\uc744 \ub0bc \ub54c \ubb38\uc81c\uc810\ub9cc \uc9c0\uc801\ud558\uae30\ubcf4\ub2e4 \uac00\ub2a5\ud55c \ub300\uc548\uae4c\uc9c0 \uc81c\uc2dc\ud558\uba74 \ud1a0\ub860\uc758 \uac00\uce58\uac00 \ub192\uc544\uc9d1\ub2c8\ub2e4.","\ud575\uc2ec \uad6c\uc870: \uc8fc\uc81c \ud655\uc778 \u2192 \uc790\uc2e0\uc758 \uc785\uc7a5 \u2192 \uc774\uc720 \u2192 \uadfc\uac70 \u2192 \uad6c\uccb4\uc801 \uc0ac\ub840 \u2192 \uc0c1\ub300\ubc29 \ubc18\ub860 \u2192 \ubc18\ub860 \uac80\ud1a0 \u2192 \uc7ac\ubc18\ub860 \u2192 \uacf5\ud1b5\uc810 \u2192 \ub300\uc548 \u2192 \uacb0\ub860."],t.s)
A.Ls=new B.hU(19,"\uc8fc\uc7a5\uacfc \ud1a0\ub860","L\u1eadp lu\u1eadn v\xe0 th\u1ea3o lu\u1eadn",A.kDU,A.kZ4,A.kUi,A.l4l,A.kpZ,A.lis,A.lET,A.k4p,A.jX5,A.kcs,A.l93,A.jLD)
A.jDP=s(["\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \ud544\uc694\ud55c \uc81c\ub3c4, \ud589\uc815 \uc808\ucc28\uc640 \uacf5\uacf5\uc11c\ube44\uc2a4\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc81c\ub3c4, \uc815\ucc45, \ud589\uc815, \uacf5\uacf5\uc11c\ube44\uc2a4\uc640 \ubbfc\uc6d0\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud55c \uc808\ucc28\ub97c \ub2f4\ub2f9\ud558\ub294 \uae30\uad00\uc774\ub098 \ubd80\uc11c\ub97c \uc815\ud655\ud788 \ucc3e\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad \uc804\uc5d0 \uc870\uac74, \ub300\uc0c1, \ud544\uc694 \uc11c\ub958\uc640 \uc808\ucc28\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad, \uc811\uc218, \uc2ec\uc0ac, \uc2b9\uc778, \ubc1c\uae09\uacfc \ucc98\ub9ac\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ucc98\ub9ac \uae30\uac04\uc744 \uc784\uc758\ub85c \ucd94\uce21\ud558\uc9c0 \uc54a\uace0 \uc815\ud655\ud788 \ubb38\uc758\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc11c\ub958 \ub204\ub77d, \ucd94\uac00 \uc790\ub8cc \uc81c\ucd9c\uacfc \uc815\ubcf4 \uc218\uc815\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad\uc11c, \uc811\uc218 \ucc3d\uad6c\uc640 \uc628\ub77c\uc778 \ud589\uc815 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc18c\ubb38\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \uacf5\uc2dd \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud589\uc815 \uc548\ub0b4\ubb38\uc5d0\uc11c \ub300\uc0c1, \uae30\uac04, \uc870\uac74\uacfc \uc2e0\uccad \ubc29\ubc95\uc744 \ucc3e\uc544 \uc77d\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubb38\uc81c\ub97c \uc81c\uae30\ud558\uac70\ub098 \ucc98\ub9ac \uc0c1\ud669\uc744 \uc815\uc911\ud558\uac8c \ubb38\uc758\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubaa8\ub450\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc11c\ube44\uc2a4\uc640 \ud2b9\uc815 \uc870\uac74\uc744 \ucda9\uc871\ud574\uc57c \uc774\uc6a9\ud560 \uc218 \uc788\ub294 \uc11c\ube44\uc2a4\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub098\uc911\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc811\uc218\ubc88\ud638, \ud655\uc778\uc11c\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud544\uc694\ud55c \uc11c\ube44\uc2a4 \ud655\uc778 \u2192 \ub2f4\ub2f9 \uae30\uad00 \ucc3e\uae30 \u2192 \uacf5\uc2dd \uc815\ubcf4 \ud655\uc778 \u2192 \ud544\uc694 \uc11c\ub958 \uc900\ube44 \u2192 \uc2e0\uccad\xb7\uc811\uc218 \u2192 \uc9c4\ud589 \uc0c1\ud669 \ud655\uc778 \u2192 \uacb0\uacfc \ud655\uc778 \u2192 \uc790\ub8cc \ubcf4\uad00\uc758 \uc774\uc6a9 \uc808\ucc28\ub97c \uc775\ud799\ub2c8\ub2e4."],t.s)
A.cwQ=new B.d("\ud544\uc694\ud55c \uc9c0\uc6d0 \uc81c\ub3c4\uac00 \uc788\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud574 \ubd24\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 ki\u1ec3m tra tr\u01b0\u1edbc xem c\xf3 ch\u1ebf \u0111\u1ed9 h\u1ed7 tr\u1ee3 ph\xf9 h\u1ee3p hay kh\xf4ng.")
