A.ljA=s(["\uc65c \uc800\ub9cc \uadc0\ucc2e\uac8c \ud574\uc694?","\uc5b4\ub5a4 \uc11c\ub958\ub97c \uc5b4\ub5a4 \ubc29\ubc95\uc73c\ub85c \ucd94\uac00 \uc81c\ucd9c\ud574\uc57c \ud558\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\uc544\ubb34\uac70\ub098 \uc81c\ucd9c\ud558\uba74 \ub418\uc8e0?","\uadf8\ub0e5 \ucc98\ub9ac\ud574 \uc8fc\uc138\uc694."],t.s)
A.cTx=new B.al("\ubcf4\uc644 \uc11c\ub958\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc548\ub0b4\ub97c \ubc1b\uc558\uc744 \ub54c \uac00\uc7a5 \uc801\uc808\ud55c \ud45c\ud604\uc740?",A.ljA,1,"C\u1ea7n h\u1ecfi r\xf5 lo\u1ea1i gi\u1ea5y t\u1edd v\xe0 ph\u01b0\u01a1ng th\u1ee9c n\u1ed9p b\u1ed5 sung.","\ubcf4\uc644")
A.kLm=s(["\uc2e0\uccad \uc804\uc5d0 \ub300\uc0c1\uacfc \uc870\uac74\uc744 \ud655\uc778\ud55c\ub2e4.","\ud544\uc694 \uc11c\ub958\ub97c \ubaa9\ub85d\uc73c\ub85c \uc815\ub9ac\ud55c\ub2e4.","\uc811\uc218 \ud6c4 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ubcf4\uad00\ud55c\ub2e4.","\uce5c\uad6c\uac00 \uba87 \ub144 \uc804\uc5d0 \uc774\uc6a9\ud55c \ubc29\ubc95\uc774\uba74 \ud604\uc7ac\ub3c4 \ubb34\uc870\uac74 \uac19\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.cUP=new B.al("\uacf5\uacf5\uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud558\ub294 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.kLm,3,"\u0110i\u1ec1u ki\u1ec7n v\xe0 th\u1ee7 t\u1ee5c c\xf3 th\u1ec3 thay \u0111\u1ed5i n\xean kh\xf4ng n\xean m\u1eb7c \u0111\u1ecbnh th\xf4ng tin c\u0169 v\u1eabn \u0111\xfang.","\uc885\ud569")
A.jC_=s([A.cT1,A.cV6,A.cVo,A.cUx,A.cXf,A.cTn,A.cWI,A.cUo,A.cSG,A.cWS,A.cVy,A.cUF,A.cWo,A.cTx,A.cUP],t.VX)
A.nsz=s(["\uc11c\ube44\uc2a4 \uc774\ub984","\ub2f4\ub2f9 \uae30\uad00","\uc2e0\uccad \ub300\uc0c1","\ud544\uc694 \uc11c\ub958","\uc628\ub77c\uc778 \uc2e0\uccad","\ubc29\ubb38 \uc2e0\uccad"],t.s)
A.cYV=new B.cD("\ucc98\uc74c \uc774\uc6a9\ud558\ub294 \uacf5\uacf5\uc11c\ube44\uc2a4\uc5d0 \ub300\ud574 \ub2f4\ub2f9 \uae30\uad00\uc5d0 \ubb38\uc758\ud574 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \uc774 \uc11c\ube44\uc2a4\ub97c \ucc98\uc74c \uc2e0\uccad\ud558\ub824\uace0 \ud574\uc11c \uba87 \uac00\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc774 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\ub294 \uae30\uad00\uc774 \uc5ec\uae30\uc778\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc81c\uac00 \uc2e0\uccad \ub300\uc0c1\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uc640 \uc5b4\ub5a4 \uc11c\ub958\ub97c \uc900\ube44\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uac00\ub2a5\ud558\uba74 \uc628\ub77c\uc778\uc73c\ub85c \uc2e0\uccad\ud558\uace0 \uc2f6\uc740\ub370 \uc628\ub77c\uc778 \uc2e0\uccad\uc774 \uac00\ub2a5\ud55c\uc9c0 \uc5ec\ubd80\ub3c4 \ud655\uc778\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694? \ubc29\ubb38\uc774 \ud544\uc694\ud558\ub2e4\uba74 \ubc29\ubb38 \uc804\uc5d0 \uc608\uc57d\uc774\ub098 \ucd94\uac00 \uc900\ube44 \uc0ac\ud56d\uc774 \uc788\ub294\uc9c0\ub3c4 \uc54c\ub824 \uc8fc\uc2dc\uba74 \uac10\uc0ac\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.npS=s(["\uc811\uc218 \ubc88\ud638","\ubcf4\uc644 \uc11c\ub958","\ub204\ub77d","\uc81c\ucd9c \ubc29\ubc95","\uae30\ud55c","\ud655\uc778"],t.s)
A.cYw=new B.cD("\ubcf4\uc644 \uc11c\ub958 \uc694\uccad\uc744 \ubc1b\uc740 \uc0c1\ud669\uc5d0\uc11c \ub2f4\ub2f9\uc790\uc5d0\uac8c \uc9c8\ubb38\ud574 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \uc81c\uac00 \uc2e0\uccad\ud55c \uac74\uc5d0 \ubcf4\uc644 \uc11c\ub958\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc5f0\ub77d\uc744 \ubc1b\uc544\uc11c \ubb38\uc758\ub4dc\ub9bd\ub2c8\ub2e4. \uc811\uc218 \ubc88\ud638\ub294 A12345\uc785\ub2c8\ub2e4. \uc815\ud655\ud788 \uc5b4\ub5a4 \uc11c\ub958\uac00 \ub204\ub77d\ub410\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uc11c\ub958\ub97c \uc900\ube44\ud55c \ud6c4 \uc628\ub77c\uc778\uc73c\ub85c \ucd94\uac00 \uc81c\ucd9c\ud560 \uc218 \uc788\ub294\uc9c0, \uc544\ub2c8\uba74 \uc9c1\uc811 \ubc29\ubb38\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \uc54c\ub824 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694? \uadf8\ub9ac\uace0 \ubcf4\uc644 \uc11c\ub958 \uc81c\ucd9c \uae30\ud55c\uc774 \ub530\ub85c \uc788\ub2e4\uba74 \uac19\uc774 \ud655\uc778 \ubd80\ud0c1\ub4dc\ub9bd\ub2c8\ub2e4.")
A.nsw=s(["\uc2e0\uccad \ub0a0\uc9dc","\uc811\uc218 \ubc88\ud638","\uc9c4\ud589 \uc0c1\ud669","\uc2ec\uc0ac","\ucd94\uac00 \uc694\uccad","\uacb0\uacfc \ud655\uc778"],t.s)
A.cZ6=new B.cD("\uc2e0\uccad\ud55c \uc5c5\ubb34\uc758 \uc9c4\ud589 \uc0c1\ud669\uc744 \ud655\uc778\ud574 \ubcf4\uc138\uc694.","\uc548\ub155\ud558\uc138\uc694. \uc9c0\ub09c\uc8fc\uc5d0 \uc2e0\uccad\ud55c \uc5c5\ubb34\uc758 \uc9c4\ud589 \uc0c1\ud669\uc744 \ud655\uc778\ud558\uace0 \uc2f6\uc5b4\uc11c \uc5f0\ub77d\ub4dc\ub838\uc2b5\ub2c8\ub2e4. \uc2e0\uccad \ub0a0\uc9dc\ub294 \uc9c0\ub09c\uc8fc \uc6d4\uc694\uc77c\uc774\uace0 \uc811\uc218 \ubc88\ud638\ub294 A12345\uc785\ub2c8\ub2e4. \ud604\uc7ac \uc5b4\ub290 \ub2e8\uacc4\uae4c\uc9c0 \ucc98\ub9ac\ub410\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\uc744\uae4c\uc694? \ub9cc\uc57d \uc2ec\uc0ac \uc911\uc774\ub77c\uba74 \uc81c\uac00 \ucd94\uac00\ub85c \uc900\ube44\ud558\uac70\ub098 \uc81c\ucd9c\ud574\uc57c \ud560 \ub0b4\uc6a9\uc774 \uc788\ub294\uc9c0\ub3c4 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uacb0\uacfc\ub294 \uc5b4\ub5a4 \ubc29\ubc95\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\ub294\uc9c0\ub3c4 \uc548\ub0b4 \ubd80\ud0c1\ub4dc\ub9bd\ub2c8\ub2e4.")
A.nra=s(["\uc778\ud130\ub137 \uae00","\uc791\uc131 \ub0a0\uc9dc","\uacf5\uc2dd \uc548\ub0b4","\ud604\uc7ac \uae30\uc900","\ub2f4\ub2f9 \uae30\uad00","\ucd5c\uc2e0 \uc815\ubcf4"],t.s)
A.cZt=new B.cD("\uc778\ud130\ub137 \uc815\ubcf4\uc640 \uacf5\uc2dd \uc548\ub0b4\uac00 \ub2e4\ub97c \ub54c \uc5b4\ub5bb\uac8c \ud655\uc778\ud560\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc778\ud130\ub137\uc5d0\uc11c \ud589\uc815 \uc808\ucc28\ub97c \uac80\uc0c9\ud588\ub294\ub370 \uc624\ub798\ub41c \uae00\uacfc \ud604\uc7ac \uacf5\uc2dd \uc548\ub0b4\uc758 \ub0b4\uc6a9\uc774 \ub2ec\ub790\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \uacbd\uc6b0\uc5d0\ub294 \uc778\ud130\ub137 \uae00\uc744 \ubc14\ub85c \ubbff\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc791\uc131 \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ud574\ub2f9 \uae30\uad00\uc758 \uacf5\uc2dd \ud648\ud398\uc774\uc9c0\uc5d0\uc11c \ucd5c\uc2e0 \uc548\ub0b4\ubb38\uc744 \ucc3e\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc774 \uc788\ub2e4\uba74 \ub2f4\ub2f9 \uae30\uad00\uc5d0 \uc9c1\uc811 \ubb38\uc758\ud574\uc11c \ud604\uc7ac \uc81c \uc0c1\ud669\uc5d0\ub294 \uc5b4\ub5a4 \uae30\uc900\uc774 \uc801\uc6a9\ub418\ub294\uc9c0 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc911\uc694\ud55c \ud589\uc815 \uc808\ucc28\uc77c\uc218\ub85d \ucd5c\uc2e0 \uacf5\uc2dd \uc815\ubcf4\ub97c \uae30\uc900\uc73c\ub85c \uc900\ube44\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.l2P=s([A.cYV,A.cYw,A.cZ6,A.cZt],t.uf)
A.nsp=s(["\ub2f4\ub2f9 \uae30\uad00\uc744 \uc4f0\uc138\uc694.","\uc2e0\uccad \ub300\uc0c1\uacfc \uc870\uac74\uc744 \uc4f0\uc138\uc694.","\ud544\uc694 \uc11c\ub958\ub97c \uc4f0\uc138\uc694.","\uc628\ub77c\uc778\xb7\ubc29\ubb38 \uc2e0\uccad\uc744 \uc4f0\uc138\uc694.","\uc811\uc218 \ud655\uc778\uc744 \uc4f0\uc138\uc694.","V-\uae30 \uc704\ud574\uc11c\ub294\uacfc V-\ub294\uc9c0 \uc5ec\ubd80\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbJ=new B.di("\uacf5\uacf5\uc11c\ube44\uc2a4\ub97c \ucc98\uc74c \uc2e0\uccad\ud560 \ub54c \ud544\uc694\ud55c \uacfc\uc815\uc744 \uc368 \ubcf4\uc138\uc694.","\uacf5\uacf5\uc11c\ube44\uc2a4\ub97c \ucc98\uc74c \uc2e0\uccad\ud558\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc5b4\ub5a4 \uae30\uad00\uc774 \ud574\ub2f9 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc790\uc2e0\uc774 \uc2e0\uccad \ub300\uc0c1\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\uc640 \ud544\uc694\ud55c \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc2e0\uccad\uc774 \uac00\ub2a5\ud558\ub2e4\uba74 \uad6c\ube44 \uc11c\ub958 \ubaa9\ub85d\uc744 \ud655\uc778\ud558\uace0 \uc11c\ub958\ub97c \uc900\ube44\ud574\uc57c \ud569\ub2c8\ub2e4. \ubc29\ubb38 \uc804\uc5d0 \uc628\ub77c\uc778\uc73c\ub85c \uc2e0\uccad\ud560 \uc218 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud558\uba74 \uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc2e0\uccad\uc11c\ub97c \uc81c\ucd9c\ud55c \ud6c4\uc5d0\ub294 \uc815\uc0c1\uc801\uc73c\ub85c \uc811\uc218\ub410\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc811\uc218 \ubc88\ud638\ub098 \uad00\ub828 \uc548\ub0b4\ub97c \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \ud544\uc694\ud558\uba74 \uc811\uc218 \ubc88\ud638\ub97c \uc774\uc6a9\ud574 \uc9c4\ud589 \uc0c1\ud669\uacfc \ucc98\ub9ac \uacb0\uacfc\ub97c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 l\u1ea7n \u0111\u1ea7u \u0111\u0103ng k\xfd d\u1ecbch v\u1ee5 c\xf4ng, tr\u01b0\u1edbc ti\xean c\u1ea7n ki\u1ec3m tra c\u01a1 quan n\xe0o ph\u1ee5 tr\xe1ch th\u1ee7 t\u1ee5c \u0111\xf3. Sau \u0111\xf3 \u0111i\u1ec1u quan tr\u1ecdng l\xe0 x\xe1c nh\u1eadn m\xecnh c\xf3 thu\u1ed9c \u0111\u1ed1i t\u01b0\u1ee3ng \u0111\u0103ng k\xfd v\xe0 c\xe1c \u0111i\u1ec1u ki\u1ec7n c\u1ea7n thi\u1ebft hay kh\xf4ng. N\u1ebfu c\xf3 th\u1ec3 \u0111\u0103ng k\xfd th\xec c\u1ea7n ki\u1ec3m tra danh s\xe1ch gi\u1ea5y t\u1edd v\xe0 chu\u1ea9n b\u1ecb. Tr\u01b0\u1edbc khi \u0111\u1ebfn tr\u1ef1c ti\u1ebfp, n\u1ebfu ki\u1ec3m tra \u0111\u01b0\u1ee3c c\xf3 th\u1ec3 \u0111\u0103ng k\xfd online hay kh\xf4ng th\xec c\xf3 th\u1ec3 ti\u1ebft ki\u1ec7m th\u1eddi gian. Sau khi n\u1ed9p \u0111\u01a1n n\xean x\xe1c nh\u1eadn h\u1ed3 s\u01a1 \u0111\xe3 \u0111\u01b0\u1ee3c ti\u1ebfp nh\u1eadn b\xecnh th\u01b0\u1eddng v\xe0 l\u01b0u s\u1ed1 ti\u1ebfp nh\u1eadn ho\u1eb7c h\u01b0\u1edbng d\u1eabn li\xean quan. Sau \u0111\xf3 n\u1ebfu c\u1ea7n c\xf3 th\u1ec3 d\xf9ng s\u1ed1 ti\u1ebfp nh\u1eadn \u0111\u1ec3 ki\u1ec3m tra ti\u1ebfn \u0111\u1ed9 v\xe0 k\u1ebft qu\u1ea3 x\u1eed l\xfd.")
A.nr5=s(["\ucd5c\uc2e0 \uc548\ub0b4\ub97c \uc4f0\uc138\uc694.","\uc11c\ub958 \ubaa9\ub85d\uc744 \uc4f0\uc138\uc694.","\uc2e0\uccad\uc11c \ud655\uc778\uc744 \uc4f0\uc138\uc694.","\ub204\ub77d\uc744 \uc4f0\uc138\uc694.","\ubcf4\uc644\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139 \uacbd\uc6b0\uc5d0\ub294\uacfc V-\uace0 \ub098\uc11c\uc57c\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbo=new B.di("\ud589\uc815 \uc11c\ub958\ub97c \uc900\ube44\ud560 \ub54c \uc2e4\uc218\ub97c \uc904\uc774\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\ud589\uc815 \uc11c\ub958\ub97c \uc900\ube44\ud560 \ub54c\ub294 \uc778\ud130\ub137\uc5d0\uc11c \ubcf8 \uc624\ub798\ub41c \uc815\ubcf4\ub9cc \uc774\uc6a9\ud558\uae30\ubcf4\ub2e4 \ub2f4\ub2f9 \uae30\uad00\uc758 \ucd5c\uc2e0 \uc548\ub0b4\ub97c \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uc11c\ub958\ub97c \ubaa9\ub85d\uc73c\ub85c \uc815\ub9ac\ud55c \ud6c4 \ud558\ub098\uc529 \uc900\ube44\ud558\uba74 \ub204\ub77d\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc2e0\uccad\uc11c\ub97c \uc791\uc131\ud55c \ub4a4\uc5d0\ub294 \uc774\ub984, \uc8fc\uc18c\uc640 \uc5f0\ub77d\ucc98\ucc98\ub7fc \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uae30\uad00\uc5d0 \ub3c4\ucc29\ud558\uace0 \ub098\uc11c\uc57c \uc11c\ub958\uac00 \ube60\uc9c4 \uac83\uc744 \uc54c\uac8c \ub418\uba74 \ub2e4\uc2dc \uc900\ube44\ud574\uc57c \ud574\uc11c \uc2dc\uac04\uc774 \ub354 \uac78\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \uc811\uc218 \ud6c4 \ubcf4\uc644\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc5f0\ub77d\uc744 \ubc1b\uc744 \uacbd\uc6b0\uc5d0\ub294 \uc5b4\ub5a4 \uc11c\ub958\uac00 \ubd80\uc871\ud55c\uc9c0\uc640 \uc81c\ucd9c \ubc29\ubc95, \ud544\uc694\ud55c \uacbd\uc6b0 \uc81c\ucd9c \uae30\ud55c\uae4c\uc9c0 \uc815\ud655\ud558\uac8c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi chu\u1ea9n b\u1ecb h\u1ed3 s\u01a1 h\xe0nh ch\xednh, thay v\xec ch\u1ec9 d\xf9ng th\xf4ng tin c\u0169 xem tr\xean m\u1ea1ng, n\xean ki\u1ec3m tra h\u01b0\u1edbng d\u1eabn m\u1edbi nh\u1ea5t c\u1ee7a c\u01a1 quan ph\u1ee5 tr\xe1ch tr\u01b0\u1edbc. N\u1ebfu li\u1ec7t k\xea gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft r\u1ed3i chu\u1ea9n b\u1ecb t\u1eebng m\u1ee5c th\xec c\xf3 th\u1ec3 gi\u1ea3m thi\u1ebfu s\xf3t. Sau khi \u0111i\u1ec1n \u0111\u01a1n c\u1ea7n ki\u1ec3m tra l\u1ea1i nh\u1eefng n\u1ed9i dung quan tr\u1ecdng nh\u01b0 t\xean, \u0111\u1ecba ch\u1ec9 v\xe0 th\xf4ng tin li\xean h\u1ec7. N\u1ebfu m\xe3i \u0111\u1ebfn khi \u0111\u1ebfn c\u01a1 quan m\u1edbi bi\u1ebft thi\u1ebfu gi\u1ea5y t\u1edd th\xec s\u1ebd m\u1ea5t th\xeam th\u1eddi gian \u0111\u1ec3 chu\u1ea9n b\u1ecb l\u1ea1i. N\u1ebfu sau ti\u1ebfp nh\u1eadn nh\u1eadn th\xf4ng b\xe1o c\u1ea7n b\u1ed5 sung th\xec n\xean x\xe1c nh\u1eadn ch\xednh x\xe1c gi\u1ea5y t\u1edd n\xe0o thi\u1ebfu, c\xe1ch n\u1ed9p v\xe0 n\u1ebfu c\u1ea7n c\u1ea3 th\u1eddi h\u1ea1n n\u1ed9p.")
A.nr0=s(["\uc81c\ub3c4 \ubcc0\uacbd\uc744 \uc4f0\uc138\uc694.","\uac1c\uc778 \uacbd\ud5d8\uc758 \ud55c\uacc4\ub97c \uc4f0\uc138\uc694.","\uacf5\uc2dd \ud648\ud398\uc774\uc9c0\ub97c \uc4f0\uc138\uc694.","\ub2f4\ub2f9 \uae30\uad00 \ubb38\uc758\ub97c \uc4f0\uc138\uc694.","\ud604\uc7ac \uae30\uc900\uc744 \uc4f0\uc138\uc694.","V-\ub294 \uac83\uc73c\ub85c \uc548\ub0b4\ub418\ub2e4\uc640 V-\ub3c4\ub85d \ub418\uc5b4 \uc788\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.dbB=new B.di("\uacf5\uacf5\uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud560 \ub54c \uacf5\uc2dd \uc815\ubcf4\ub97c \ud655\uc778\ud574\uc57c \ud558\ub294 \uc774\uc720\ub97c \uc368 \ubcf4\uc138\uc694.","\uacf5\uacf5\uc11c\ube44\uc2a4\uc640 \ud589\uc815 \uc81c\ub3c4\ub294 \ub0b4\uc6a9\uc774\ub098 \uc2e0\uccad \ubc29\ubc95\uc774 \ubc14\ub014 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc624\ub798\ub41c \uc778\ud130\ub137 \uae00\uc774\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub9cc\uc73c\ub85c \uc900\ube44\ud558\uba74 \uc2e4\uc218\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc774 \uac19\uc740 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud588\ub354\ub77c\ub3c4 \uc2e0\uccad \uc2dc\uae30\ub098 \uac1c\uc778 \uc0c1\ud669\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \uc870\uac74\uc774 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uba3c\uc800 \uacf5\uc2dd \ud648\ud398\uc774\uc9c0\uc758 \ucd5c\uc2e0 \uc548\ub0b4\ubb38\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc628\ub77c\uc778\uc73c\ub85c \uc2e0\uccad\ud560 \uc218 \uc788\ub294 \uac83\uc73c\ub85c \uc548\ub0b4\ub418\uc5b4 \uc788\ub2e4\uba74 \uc2e4\uc81c \uc2e0\uccad \ud654\uba74\uacfc \ud604\uc7ac \uc870\uac74\uc744 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc2dc\uc2a4\ud15c\uc5d0\uc11c \ud544\uc218 \ud56d\ubaa9\uc744 \uc785\ub825\ud558\ub3c4\ub85d \ub418\uc5b4 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uc790\uc2e0\uc5d0\uac8c \ud544\uc694\ud55c \ucd94\uac00 \uc11c\ub958\uac00 \uc788\ub294\uc9c0\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \ub2f4\ub2f9 \uae30\uad00\uc5d0 \ubb38\uc758\ud574 \ud604\uc7ac \uae30\uc900\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc548\uc804\ud569\ub2c8\ub2e4.","V\xec n\u1ed9i dung ho\u1eb7c c\xe1ch \u0111\u0103ng k\xfd c\u1ee7a d\u1ecbch v\u1ee5 c\xf4ng v\xe0 ch\u1ebf \u0111\u1ed9 h\xe0nh ch\xednh c\xf3 th\u1ec3 thay \u0111\u1ed5i n\xean n\u1ebfu ch\u1ec9 chu\u1ea9n b\u1ecb d\u1ef1a tr\xean b\xe0i vi\u1ebft c\u0169 tr\xean m\u1ea1ng ho\u1eb7c kinh nghi\u1ec7m c\u1ee7a ng\u01b0\u1eddi kh\xe1c c\xf3 th\u1ec3 x\u1ea3y ra sai s\xf3t. D\xf9 ng\u01b0\u1eddi kh\xe1c \u0111\xe3 s\u1eed d\u1ee5ng c\xf9ng d\u1ecbch v\u1ee5, \u0111i\u1ec1u ki\u1ec7n c\u1ea7n thi\u1ebft c\xf3 th\u1ec3 kh\xe1c t\xf9y th\u1eddi \u0111i\u1ec3m \u0111\u0103ng k\xfd ho\u1eb7c ho\xe0n c\u1ea3nh c\xe1 nh\xe2n. V\xec v\u1eady tr\u01b0\u1edbc ti\xean n\xean ki\u1ec3m tra th\xf4ng b\xe1o m\u1edbi nh\u1ea5t tr\xean trang ch\xednh th\u1ee9c. V\xed d\u1ee5 n\u1ebfu \u0111\u01b0\u1ee3c h\u01b0\u1edbng d\u1eabn l\xe0 c\xf3 th\u1ec3 \u0111\u0103ng k\xfd online th\xec v\u1eabn c\u1ea7n ki\u1ec3m tra m\xe0n h\xecnh \u0111\u0103ng k\xfd th\u1ef1c t\u1ebf v\xe0 \u0111i\u1ec1u ki\u1ec7n hi\u1ec7n t\u1ea1i. Ngay c\u1ea3 khi h\u1ec7 th\u1ed1ng \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf b\u1eaft bu\u1ed9c nh\u1eadp c\xe1c m\u1ee5c c\u1ea7n thi\u1ebft, v\u1eabn c\u1ea7n x\xe1c nh\u1eadn ri\xeang xem tr\u01b0\u1eddng h\u1ee3p c\u1ee7a m\xecnh c\xf3 gi\u1ea5y t\u1edd b\u1ed5 sung n\xe0o kh\xf4ng. N\u1ebfu c\xf3 ph\u1ea7n ch\u01b0a hi\u1ec3u, c\xe1ch an to\xe0n nh\u1ea5t l\xe0 h\u1ecfi c\u01a1 quan ph\u1ee5 tr\xe1ch \u0111\u1ec3 x\xe1c nh\u1eadn ti\xeau chu\u1ea9n hi\u1ec7n t\u1ea1i.")
A.jOi=s([A.dbJ,A.dbo,A.dbB],t.l5)
A.lRb=s(["\uc81c\ub3c4","\uc9c0\uc6d0 \uc81c\ub3c4","\uc815\ucc45","\ud589\uc815","\ud589\uc815 \uc808\ucc28","\ud589\uc815 \uc11c\ube44\uc2a4","\uacf5\uacf5\uc11c\ube44\uc2a4","\uacf5\uacf5\uae30\uad00","\uad00\uacf5\uc11c","\uc8fc\ubbfc\uc13c\ud130","\ub2f4\ub2f9 \uae30\uad00","\ub2f4\ub2f9 \ubd80\uc11c","\ucc3d\uad6c","\uc548\ub0b4 \ub370\uc2a4\ud06c","\ubbfc\uc6d0","\ubbfc\uc6d0 \uc5c5\ubb34","\uc2e0\uccad","\uc2e0\uccad\ud558\ub2e4","\uc2e0\uccad\uc11c","\uc791\uc131\ud558\ub2e4","\uc81c\ucd9c\ud558\ub2e4","\uc811\uc218","\uc811\uc218\ud558\ub2e4","\uc811\uc218 \ubc88\ud638","\ucc98\ub9ac","\ucc98\ub9ac \uc0c1\ud0dc","\ucc98\ub9ac \uae30\uac04","\uc9c4\ud589 \uc0c1\ud669","\uc2ec\uc0ac","\uc2ec\uc0ac \uc911","\uc2b9\uc778","\uc2b9\uc778\ub418\ub2e4","\ubc18\ub824","\ubc18\ub824\ub418\ub2e4","\ubc1c\uae09","\ubc1c\uae09\ubc1b\ub2e4","\uc99d\uba85\uc11c","\uad6c\ube44 \uc11c\ub958","\ud544\uc694 \uc11c\ub958","\ubcf4\uc644 \uc11c\ub958","\ub204\ub77d\ub418\ub2e4","\ubcf4\uc644\ud558\ub2e4","\uc218\uc815\ud558\ub2e4","\uc790\uaca9","\uc2e0\uccad \uc790\uaca9","\ub300\uc0c1","\uc9c0\uc6d0 \ub300\uc0c1","\uc870\uac74","\uc2e0\uccad \uae30\uac04","\uae30\ud55c","\uc628\ub77c\uc778 \uc2e0\uccad","\ubc29\ubb38 \uc2e0\uccad","\uacf5\uc2dd \uc548\ub0b4","\uc548\ub0b4\ubb38","\ubb38\uc758\ud558\ub2e4","\ud655\uc778\ud558\ub2e4"],t.s)
A.jpl=s(["V-\uae30 \uc704\ud574\uc11c\ub294","V-(\uc73c)\u3139 \uacbd\uc6b0\uc5d0\ub294","V-\ub294\uc9c0 \uc5ec\ubd80","V-\ub294 \uac83\uc73c\ub85c \uc548\ub0b4\ub418\ub2e4","V-\ub3c4\ub85d \ub418\uc5b4 \uc788\ub2e4","V-\ub294 \ub370 \uc2dc\uac04\uc774 \uac78\ub9ac\ub2e4","V-\uace0 \ub098\uc11c\uc57c","V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4","V-(\uc73c)\u3139 \uc218 \uc788\ub294\uc9c0","V-\uae30 \uc804\uc5d0","N\uc5d0 \ub530\ub77c","V-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4"],t.s)
A.lql=s(["\uc81c\ub3c4 = ch\u1ebf \u0111\u1ed9/h\u1ec7 th\u1ed1ng","\uc815\ucc45 = ch\xednh s\xe1ch","\ud589\uc815 = h\xe0nh ch\xednh","\uacf5\uacf5\uc11c\ube44\uc2a4 = d\u1ecbch v\u1ee5 c\xf4ng","\uacf5\uacf5\uae30\uad00 = c\u01a1 quan c\xf4ng","\uad00\uacf5\uc11c = c\u01a1 quan h\xe0nh ch\xednh nh\xe0 n\u01b0\u1edbc","\uc8fc\ubbfc\uc13c\ud130 = trung t\xe2m h\xe0nh ch\xednh \u0111\u1ecba ph\u01b0\u01a1ng","\ub2f4\ub2f9 \uae30\uad00 = c\u01a1 quan ph\u1ee5 tr\xe1ch","\ub2f4\ub2f9 \ubd80\uc11c = b\u1ed9 ph\u1eadn ph\u1ee5 tr\xe1ch","\ucc3d\uad6c = qu\u1ea7y ti\u1ebfp nh\u1eadn","\uc548\ub0b4 \ub370\uc2a4\ud06c = b\xe0n h\u01b0\u1edbng d\u1eabn","\ubbfc\uc6d0 = y\xeau c\u1ea7u h\xe0nh ch\xednh/ph\u1ea3n \xe1nh","\uc2e0\uccad = \u0111\u0103ng k\xfd","\uc2e0\uccad\uc11c = \u0111\u01a1n \u0111\u0103ng k\xfd","\uc791\uc131\ud558\ub2e4 = \u0111i\u1ec1n/so\u1ea1n","\uc81c\ucd9c\ud558\ub2e4 = n\u1ed9p","\uc811\uc218 = ti\u1ebfp nh\u1eadn","\uc811\uc218 \ubc88\ud638 = s\u1ed1 ti\u1ebfp nh\u1eadn","\ucc98\ub9ac = x\u1eed l\xfd","\ucc98\ub9ac \uae30\uac04 = th\u1eddi gian x\u1eed l\xfd","\uc9c4\ud589 \uc0c1\ud669 = ti\u1ebfn \u0111\u1ed9","\uc2ec\uc0ac = x\xe9t duy\u1ec7t","\uc2b9\uc778 = ph\xea duy\u1ec7t","\ubc18\ub824 = tr\u1ea3 l\u1ea1i/kh\xf4ng ti\u1ebfp t\u1ee5c x\u1eed l\xfd h\u1ed3 s\u01a1","\ubc1c\uae09 = c\u1ea5p gi\u1ea5y t\u1edd","\uc99d\uba85\uc11c = gi\u1ea5y ch\u1ee9ng nh\u1eadn","\uad6c\ube44 \uc11c\ub958 = b\u1ed9 gi\u1ea5y t\u1edd c\u1ea7n chu\u1ea9n b\u1ecb","\ud544\uc694 \uc11c\ub958 = gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft","\ubcf4\uc644 \uc11c\ub958 = gi\u1ea5y t\u1edd b\u1ed5 sung","\ub204\ub77d\ub418\ub2e4 = b\u1ecb thi\u1ebfu","\ubcf4\uc644\ud558\ub2e4 = b\u1ed5 sung","\uc218\uc815\ud558\ub2e4 = ch\u1ec9nh s\u1eeda","\uc790\uaca9 = t\u01b0 c\xe1ch/\u0111i\u1ec1u ki\u1ec7n \u0111\u1ee7","\ub300\uc0c1 = \u0111\u1ed1i t\u01b0\u1ee3ng","\uc870\uac74 = \u0111i\u1ec1u ki\u1ec7n","\uc2e0\uccad \uae30\uac04 = th\u1eddi gian \u0111\u0103ng k\xfd","\uae30\ud55c = th\u1eddi h\u1ea1n","\uc628\ub77c\uc778 \uc2e0\uccad = \u0111\u0103ng k\xfd online","\ubc29\ubb38 \uc2e0\uccad = \u0111\u0103ng k\xfd tr\u1ef1c ti\u1ebfp","\uacf5\uc2dd \uc548\ub0b4 = h\u01b0\u1edbng d\u1eabn ch\xednh th\u1ee9c","\uc548\ub0b4\ubb38 = th\xf4ng b\xe1o h\u01b0\u1edbng d\u1eabn","V-\uae30 \uc704\ud574\uc11c\ub294 = \u0111\u1ec3... th\xec c\u1ea7n...","V-(\uc73c)\u3139 \uacbd\uc6b0\uc5d0\ub294 = trong tr\u01b0\u1eddng h\u1ee3p...","V-\ub294\uc9c0 \uc5ec\ubd80 = vi\u1ec7c c\xf3... hay kh\xf4ng","V-\ub294 \uac83\uc73c\ub85c \uc548\ub0b4\ub418\ub2e4 = \u0111\u01b0\u1ee3c h\u01b0\u1edbng d\u1eabn r\u1eb1ng...","V-\ub3c4\ub85d \ub418\uc5b4 \uc788\ub2e4 = \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf/quy \u0111\u1ecbnh \u0111\u1ec3...","V-\ub294 \ub370 \uc2dc\uac04\uc774 \uac78\ub9ac\ub2e4 = m\u1ea5t th\u1eddi gian \u0111\u1ec3...","V-\uace0 \ub098\uc11c\uc57c = m\xe3i sau khi... m\u1edbi...","\uc11c\ube44\uc2a4\ub97c \uc2e0\uccad\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc2e0\uccad \uc790\uaca9\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc11c\ub958\uac00 \ub204\ub77d\ub410\uc744 \uacbd\uc6b0\uc5d0\ub294 \ubcf4\uc644 \ubc29\ubc95\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc81c\uac00 \uc2e0\uccad \ub300\uc0c1\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\ub97c \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\uc628\ub77c\uc778\uc73c\ub85c \uc2e0\uccad\ud560 \uc218 \uc788\ub294 \uac83\uc73c\ub85c \uc548\ub0b4\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.","\uc811\uc218 \ud6c4 \uc9c4\ud589 \uc0c1\ud669\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.","\uc11c\ub958\ub97c \uc900\ube44\ud558\ub294 \ub370 \uc2dc\uac04\uc774 \uc870\uae08 \uac78\ub838\uc2b5\ub2c8\ub2e4.","\uae30\uad00\uc5d0 \ub3c4\ucc29\ud558\uace0 \ub098\uc11c\uc57c \uc11c\ub958 \ud558\ub098\uac00 \ube60\uc9c4 \uac83\uc744 \uc54c\uc558\uc2b5\ub2c8\ub2e4.","\uc2e0\uccad \u2192 \uc811\uc218 \u2192 \uc2ec\uc0ac \u2192 \uacb0\uacfc \ud655\uc778\uc740 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uacc4\uc77c \uc218 \uc788\uc73c\ubbc0\ub85c \uac01 \ub2e8\uacc4\uc758 \uc0c1\ud0dc\ub97c \uad6c\ubd84\ud574\uc11c \uc774\ud574\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\ud589\uc815 \uc808\ucc28\ub294 \uc81c\ub3c4, \uc2dc\uae30\uc640 \uac1c\uc778 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc2e4\uc81c \uc2e0\uccad \uc804\uc5d0\ub294 \ucd5c\uc2e0 \uacf5\uc2dd \uc548\ub0b4\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc778\ud130\ub137 \uacbd\ud5d8\ub2f4\uc740 \ucc38\uace0\ud560 \uc218 \uc788\uc9c0\ub9cc \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4\uace0 \ub2e8\uc815\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4.","\ud575\uc2ec \ud750\ub984: \ud544\uc694\ud55c \uc11c\ube44\uc2a4 \ud655\uc778 \u2192 \ub2f4\ub2f9 \uae30\uad00 \ud655\uc778 \u2192 \ub300\uc0c1\xb7\uc870\uac74 \ud655\uc778 \u2192 \ucd5c\uc2e0 \uacf5\uc2dd \uc548\ub0b4 \ud655\uc778 \u2192 \uc11c\ub958 \uc900\ube44 \u2192 \uc2e0\uccad\xb7\uc811\uc218 \u2192 \ubcf4\uc644 \uc5ec\ubd80 \ud655\uc778 \u2192 \uc9c4\ud589 \uc0c1\ud669 \ud655\uc778 \u2192 \uacb0\uacfc \ud655\uc778 \u2192 \uad00\ub828 \uc790\ub8cc \ubcf4\uad00."],t.s)
