A.jn5=s(["\ubd88\ub7c9\uc740 \uc624\uc804\uc5d0\ub9cc \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4.","\ubd88\ub7c9\ud488\uc744 \uc815\uc0c1 \uc81c\ud488\uacfc \ud568\uaed8 \ubcf4\uad00\ud588\uc2b5\ub2c8\ub2e4.","\uc124\ube44 \uc870\uac74 \ubcc0\uacbd \uc774\ud6c4 \ubd88\ub7c9\uc774 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.","\ucd94\uac00 \uac80\uc0ac\ub97c \ud558\uc9c0 \uc54a\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.cSZ=new B.al("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uac80\uc0ac\ud300\uc740 \uc624\ud6c4 \uc0dd\uc0b0\ud488\uc5d0\uc11c \ub3d9\uc77c\ud55c \uade0\uc5f4 \ubd88\ub7c9\uc744 \uc5ec\ub7ec \uac1c \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4. \ud574\ub2f9 \uc81c\ud488\uc744 \ubcc4\ub3c4 \uad6c\uc5ed\uc5d0 \uaca9\ub9ac\ud55c \ud6c4 \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \ud655\uc778 \uacb0\uacfc \uc624\ud6c4 \ub450 \uc2dc\uc5d0 \uc124\ube44 \uc870\uac74\uc774 \ubcc0\uacbd\ub41c \uc774\ud6c4 \uc0dd\uc0b0\ub41c \uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \uc9d1\uc911\ub41c \uac83\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\ub294 \uc870\uac74\uc744 \uc6d0\ub798 \uae30\uc900\uc73c\ub85c \uc870\uc815\ud558\uace0 \ubcc0\uacbd \uc804\ud6c4 \uc81c\ud488\uc744 \ucd94\uac00 \uac80\uc0ac\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.jn5,2,"\u0110o\u1ea1n v\u0103n n\xf3i l\u1ed7i t\u1eadp trung \u1edf s\u1ea3n ph\u1ea9m s\u1ea3n xu\u1ea5t sau khi \u0111i\u1ec1u ki\u1ec7n thi\u1ebft b\u1ecb thay \u0111\u1ed5i.","\uc77d\uae30")
A.l0S=s(["\ubb54\uac00 \uc774\uc0c1\ud574\uc694.","\uc624\ud6c4 \ub450 \uc2dc \uc774\ud6c4 \uc0dd\uc0b0\ud488 30\uac1c \uc911 \uc6a9\uc811 \uade0\uc5f4 \ubd88\ub7c9\uc774 4\uac1c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4.","\uc81c\ud488\uc774 \ubcc4\ub85c\uc608\uc694.","\uae30\uacc4\uac00 \ubb38\uc81c\uc778 \uac83 \uac19\uc544\uc694. \ud655\uc2e4\ud574\uc694."],t.s)
A.cTt=new B.al("\ub2e4\uc74c \uc911 \uac00\uc7a5 \uc88b\uc740 \ud488\uc9c8 \ubb38\uc81c \ubcf4\uace0\ub294?",A.l0S,1,"B\xe1o c\xe1o t\u1ed1t ph\u1ea3i c\xf3 th\u1eddi gian, ph\u1ea1m vi, s\u1ed1 l\u01b0\u1ee3ng v\xe0 lo\u1ea1i l\u1ed7i c\u1ee5 th\u1ec3.","\ubcf4\uace0")
A.l1F=s(["\ubd88\ub7c9\uc744 \ubc1c\uacac\ud558\uba74 \uc81c\ud488\uc744 \uad6c\ubd84\ud55c\ub2e4.","\uad00\ub828\uc790\uc5d0\uac8c \uc0c1\ud669\uc744 \uacf5\uc720\ud55c\ub2e4.","\uc6d0\uc778\uc744 \ud655\uc778\ud558\uace0 \uac1c\uc120 \ub300\ucc45\uc744 \uc801\uc6a9\ud55c\ub2e4.","\uc6d0\uc778\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uac80\uc0ac\ub9cc \uacc4\uc18d\ud558\uba74 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.cXj=new B.al("\ud488\uc9c8 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uc21c\uc11c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.l1F,3,"Ki\u1ec3m tra ch\u1ec9 ph\xe1t hi\u1ec7n s\u1ea3n ph\u1ea9m l\u1ed7i; mu\u1ed1n ng\u0103n t\xe1i di\u1ec5n ph\u1ea3i x\u1eed l\xfd nguy\xean nh\xe2n.","\uc885\ud569")
