A.lrn=s(["\uc798 \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \ub4e3\ub294\ub2e4.","\uc758\uacac\uacfc \uac10\uc815\uc744 \uad6c\ubd84\ud574\uc11c \ud45c\ud604\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc758 \uc758\ub3c4\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc790\uc2e0\uc758 \ucd94\uce21\uc744 \uc0ac\uc2e4\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.cT7=new B.al("\uc758\uc0ac\uc18c\ud1b5 \ubb38\uc81c\ub97c \uc904\uc774\uae30 \uc704\ud55c \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.lrn,3,"Suy \u0111o\xe1n \xfd \u0111\u1ecbnh nh\u01b0 s\u1ef1 th\u1eadt l\xe0 nguy\xean nh\xe2n ph\u1ed5 bi\u1ebfn g\xe2y hi\u1ec3u l\u1ea7m.","\uc885\ud569")
