A.cYX=new B.cD("\uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \uc815\ud655\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc744 \ub54c \ub2e4\uc2dc \ud655\uc778\ud574 \ubcf4\uc138\uc694.","\uc81c\uac00 \uc815\ud655\ud788 \uc774\ud574\ud588\ub294\uc9c0 \ud55c\ubc88 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ud300\uc7a5\ub2d8 \ub9d0\uc500\uc740 \uc624\ub298 \uc548\uc5d0 \ubaa8\ub4e0 \uc791\uc5c5\uc744 \ub05d\ub0b4\uc57c \ud55c\ub2e4\ub294 \ub73b\uc778\uac00\uc694, \uc544\ub2c8\uba74 \uc6b0\uc120 \uc911\uc694\ud55c \ub450 \ud56d\ubaa9\ub9cc \uc624\ub298 \uc644\ub8cc\ud558\uba74 \ub41c\ub2e4\ub294 \ub73b\uc778\uac00\uc694? \uc81c\uac00 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc798\ubabb \uc774\ud574\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc6b0\uc120\uc21c\uc704\ub97c \ub2e4\uc2dc \ud55c\ubc88 \ub9d0\uc500\ud574 \uc8fc\uc2dc\uba74 \uac10\uc0ac\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.noS=s(["\uac1c\uc778\uc801\uc778 \ub0b4\uc6a9","\ubd80\ub2f4\uc2a4\ub7fd\ub2e4","\uac70\uc808","\uad00\uacc4 \uc720\uc9c0","\ub2e4\ub978 \uc774\uc57c\uae30"],t.s)
A.cZi=new B.cD("\uce5c\ud55c \uc0ac\ub78c\uc774 \ubd88\ud3b8\ud55c \uac1c\uc778\uc801\uc778 \uc9c8\ubb38\uc744 \ud588\uc744 \ub54c \uc815\uc911\ud558\uac8c \ub300\ub2f5\ud574 \ubcf4\uc138\uc694.","\uad81\uae08\ud574\uc11c \ubb3c\uc5b4\ubcf4\uc2e0 \uac74 \uc774\ud574\ud569\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ubd80\ubd84\uc740 \uc800\uc5d0\uac8c \uc870\uae08 \uac1c\uc778\uc801\uc778 \ub0b4\uc6a9\uc774\ub77c \uc790\uc138\ud788 \ub9d0\uc500\ub4dc\ub9ac\uae30\ub294 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uae30\ubd84 \ub098\uc058\uac8c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uc168\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \uc774\uc57c\uae30\ub294 \ud3b8\ud558\uac8c \ud574\ub3c4 \uad1c\ucc2e\uc544\uc694.")
A.nq4=s(["\ucd5c\uadfc \ubd84\uc704\uae30","\uc624\ud574","\uc758\ub3c4","\uc0ac\uacfc","\ub2e4\uc2dc \ud655\uc778","\uac1c\uc120"],t.s)
A.cZ9=new B.cD("\uc624\ud574 \ub54c\ubb38\uc5d0 \uad00\uacc4\uac00 \uc5b4\uc0c9\ud574\uc9c4 \ub3d9\ub8cc\uc640 \ub300\ud654\ub97c \uc2dc\uc791\ud574 \ubcf4\uc138\uc694.","\ucd5c\uadfc\uc5d0 \uc800\ud76c\uac00 \uc774\uc57c\uae30\ud560 \ub54c \uc870\uae08 \uc5b4\uc0c9\ud574\uc9c4 \uac83 \uac19\uc544\uc11c \ud55c\ubc88 \ub9d0\uc500\ub4dc\ub9ac\uace0 \uc2f6\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c0\ub09c\ubc88\uc5d0 \uc81c\uac00 \ubcf4\ub0b8 \uba54\uc2dc\uc9c0\uac00 \ub108\ubb34 \uc9e7\uc544\uc11c \uc81c \uc758\ub3c4\uc640 \ub2e4\ub974\uac8c \uc804\ub2ec\ub41c \ubd80\ubd84\uc774 \uc788\uc5c8\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud639\uc2dc \uadf8 \ub9d0 \ub54c\ubb38\uc5d0 \ubd88\ud3b8\ud558\uc168\ub2e4\uba74 \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \uc800\ub294 \ud654\uac00 \ub098\uc11c \uadf8\ub807\uac8c \uc4f4 \uac83\uc774 \uc544\ub2c8\ub77c \ub2f9\uc2dc \uc5c5\ubb34 \uc911\uc774\ub77c \uae09\ud558\uac8c \ubcf4\ub0b8 \uac83\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uc774\uc720\uae4c\uc9c0 \uac19\uc774 \uc124\uba85\ud558\ub3c4\ub85d \ud558\uaca0\uc2b5\ub2c8\ub2e4.")
