A.loB=s(["\ud68c\uc0ac\ub294 \ucc98\uc74c \ucd94\uce21\ud55c \uc6d0\uc778\uc744 \ubc14\ub85c \uc0ac\uc2e4\ub85c \uacb0\uc815\ud588\uc2b5\ub2c8\ub2e4.","\ud68c\uc0ac\ub294 \uc5ec\ub7ec \uc790\ub8cc\ub97c \ube44\uad50\ud55c \ud6c4 \uc6d0\uc778\uc744 \ub2e4\uc2dc \ud310\ub2e8\ud588\uc2b5\ub2c8\ub2e4.","\ud68c\uc0ac\uc5d0\uc11c\ub294 \uc544\ubb34 \uc870\uce58\ub3c4 \ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\uc81c\ud488 \ubd88\ub7c9\uacfc \uc124\ube44 \uc870\uac74\uc740 \uc804\ud600 \uad00\ub828\uc774 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4."],t.s)
A.cW4=new B.al("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ud55c \uacf5\uc7a5\uc5d0\uc11c \ucd5c\uadfc \uc81c\ud488 \ud45c\uba74 \ubd88\ub7c9\uc774 \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4. \uc791\uc5c5\uc790\ub4e4\uc740 \ucc98\uc74c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \uc6d0\uc790\uc7ac\uac00 \uc6d0\uc778\uc774\ub77c\uace0 \uc0dd\uac01\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub2f4\ub2f9 \ud300\uc740 \ubc14\ub85c \uacb0\ub860\uc744 \ub0b4\ub9ac\uc9c0 \uc54a\uace0 \uc0dd\uc0b0 \uae30\ub85d, \uc124\ube44 \uc870\uac74\uacfc \uac80\uc0ac \uc790\ub8cc\ub97c \ube44\uad50\ud588\uc2b5\ub2c8\ub2e4. \ubd84\uc11d \uacb0\uacfc \uc6d0\uc790\uc7ac \uc790\uccb4\ubcf4\ub2e4 \ud2b9\uc815 \uc2dc\uac04\ub300\uc758 \uc124\ube44 \uc870\uac74 \ubcc0\ud654\uc640 \uad00\ub828\uc131\uc774 \ud070 \uac83\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\ub294 \ud574\ub2f9 \uc870\uac74\uc744 \uc870\uc815\ud55c \ud6c4 \ubd88\ub7c9\ub960\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.",A.loB,1,"Nh\xf3m \u0111\xe3 so s\xe1nh d\u1eef li\u1ec7u thay v\xec coi suy \u0111o\xe1n ban \u0111\u1ea7u l\xe0 s\u1ef1 th\u1eadt.","\uc77d\uae30")
A.kWm=s(["\uc790\ub8cc\uc758 \uc2e0\ub8b0\uc131\uc744 \ud655\uc778\ud55c\ub2e4.","\ud544\uc694\ud558\uba74 \uae30\uc874 \ud310\ub2e8\uc744 \uc218\uc815\ud55c\ub2e4.","\ucd94\uac00 \uc790\ub8cc\ub3c4 \ud655\uc778\ud55c\ub2e4.","\uc790\uc2e0\uc758 \uc758\uacac\uacfc \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc790\ub8cc\ub97c \ubb34\uc870\uac74 \ubb34\uc2dc\ud55c\ub2e4."],t.s)
A.cTa=new B.al("\uc0c8\ub85c\uc6b4 \uc790\ub8cc\uac00 \uc790\uc2e0\uc758 \uae30\uc874 \uc758\uacac\uacfc \ub2e4\ub974\uac8c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \ud0dc\ub3c4\ub294?",A.kWm,3,"Kh\xf4ng n\xean lo\u1ea1i b\u1ecf d\u1eef li\u1ec7u ch\u1ec9 v\xec n\xf3 tr\xe1i v\u1edbi suy ngh\u0129 ban \u0111\u1ea7u.","\uc885\ud569")
