A.dZH=new B.dr("\ud55c\uad6d \uc0dd\ud65c\uc5d0 \uc801\uc751\ud558\uba74\uc11c \uac00\uc7a5 \uc5b4\ub824\uc6b4 \uc810\uc740 \ubb34\uc5c7\uc77c \uc218 \uc788\uc2b5\ub2c8\uae4c?",A.lFT,"\uc678\uad6d\uc778\uc774 \ud55c\uad6d \uc0dd\ud65c\uc5d0 \uc801\uc751\ud560 \ub54c\ub294 \uc5b8\uc5b4\uac00 \uac00\uc7a5 \ud070 \uc5b4\ub824\uc6c0 \uc911 \ud558\ub098\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae30\ubcf8\uc801\uc778 \ub300\ud654\uac00 \uac00\ub2a5\ud558\ub354\ub77c\ub3c4 \ubcd1\uc6d0\uc774\ub098 \ud589\uc815\uae30\uad00, \uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc5b4\ub824\uc6b4 \ud45c\ud604\uc744 \uc790\uc8fc \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub610\ud55c \ud68c\uc0ac \ubb38\ud654\ub098 \uc778\uac04\uad00\uacc4 \ubc29\uc2dd\uc774 \uc775\uc219\ud558\uc9c0 \uc54a\uc544 \uc624\ud574\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5b8\uc5b4 \uad50\uc721\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2e4\uc81c \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\uc640 \uc0c1\ub2f4 \uc9c0\uc6d0\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.lKa=s(["\ub2e4\uc591\uc131","\ubb38\ud654 \uad50\ub958","\uc778\uc7ac","\uc5b8\uc5b4","\uc0c8\ub85c\uc6b4 \uad00\uc810","\uacbd\uc81c"],t.s)
A.dZP=new B.dr("\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc758 \uc7a5\uc810\uc740 \ubb34\uc5c7\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.lKa,"\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uacfc \uad00\uc810\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uae30 \ub54c\ubb38\uc5d0 \uc0ac\ud68c\uac00 \ub354 \ub2e4\uc591\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc5c5\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uc5b8\uc5b4\uc640 \ubb38\ud654\uc5d0 \uc775\uc219\ud55c \uc778\uc7ac\uac00 \ud574\uc678 \uc2dc\uc7a5\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc77c\uc0c1\uc801\uc778 \ubb38\ud654 \uad50\ub958\uac00 \ub298\uc5b4\ub098\uba74 \ub2e4\ub978 \ub098\ub77c\uc640 \ubb38\ud654\uc5d0 \ub300\ud55c \uc774\ud574\ub3c4 \ub192\uc544\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \uc7a5\uc810\uc744 \uc0b4\ub9ac\uae30 \uc704\ud574\uc11c\ub294 \ucc28\ubcc4\uc744 \uc904\uc774\uace0 \uacf5\uc815\ud55c \ucc38\uc5ec \uae30\ud68c\ub97c \uc81c\uacf5\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.luc=s(["\uc678\uad6d\uc778","\uc815\ubd80","\uae30\uc5c5","\uc9c0\uc5ed \uc0ac\ud68c","\uc5b8\uc5b4","\uc0c1\ud638 \uc874\uc911"],t.s)
A.dZj=new B.dr("\uc678\uad6d\uc778\uc774 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc798 \uc815\ucc29\ud558\uae30 \uc704\ud574 \ub204\uad6c\uc758 \ub178\ub825\uc774 \ud544\uc694\ud569\ub2c8\uae4c?",A.luc,"\uc0ac\ud68c \ud1b5\ud569\uc740 \uc678\uad6d\uc778 \uac1c\uc778\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uae30 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc678\uad6d\uc778\ub3c4 \ud55c\uad6d\uc5b4\uc640 \uae30\ubcf8\uc801\uc778 \uc0ac\ud68c \uaddc\ubc94\uc744 \ubc30\uc6b0\ub824\uace0 \ub178\ub825\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub3d9\uc2dc\uc5d0 \uc815\ubd80\uc640 \uc9c0\uc5ed \uc0ac\ud68c\ub294 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc27d\uac8c \uc81c\uacf5\ud558\uace0 \uae30\uc5c5\ub3c4 \uc678\uad6d\uc778 \uadfc\ub85c\uc790\uac00 \uc9c1\uc7a5\uc5d0\uc11c \uc815\ud655\ud788 \uc758\uc0ac\uc18c\ud1b5\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc6d0\ud574\uc57c \ud569\ub2c8\ub2e4. \uc11c\ub85c\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \ubcc0\ud654\ub97c \uc694\uad6c\ud558\uae30\ubcf4\ub2e4 \ud568\uaed8 \uc801\uc751\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.lEh=s([A.dZH,A.dZP,A.dZj],t.Gu)
A.jNM=s(["\ub2e4\ubb38\ud654 \uc0ac\ud68c\uac00 \ud655\ub300\ub418\ub294 \ubc30\uacbd\uc744 \uc124\uba85\ud558\uc138\uc694.","\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc758 \uc7a5\uc810\uc744 \uc4f0\uc138\uc694.","\ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uac08\ub4f1\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc678\uad6d\uc778\uacfc \uc9c0\uc5ed \uc0ac\ud68c\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\uc0ac\ud68c \ud1b5\ud569\uc744 \uc704\ud55c \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.el2=new B.eB("\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc758 \uc7a5\uc810\uacfc \uacfc\uc81c",A.jNM,"\uad6d\uc81c\uc801\uc778 \uc778\uad6c \uc774\ub3d9\uc774 \ud65c\ubc1c\ud574\uc9c0\uace0 \uc678\uad6d\uc778 \uadfc\ub85c\uc790\uc640 \uc720\ud559\uc0dd, \uacb0\ud63c\uc774\ubbfc\uc790 \ub4f1\uc774 \uc99d\uac00\ud558\uba74\uc11c \uc5ec\ub7ec \uc0ac\ud68c\uac00 \ub2e4\ubb38\ud654 \uc0ac\ud68c\ub85c \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\uc591\ud55c \ubb38\ud654\uc801 \ubc30\uacbd\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uba74 \uc0c8\ub85c\uc6b4 \uad00\uc810\uacfc \uacbd\ud5d8\uc774 \uc0ac\ud68c\uc5d0 \ub4e4\uc5b4\uc640 \ubb38\ud654\uc640 \uacbd\uc81c\uc758 \ubc1c\uc804\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc5b8\uc5b4 \uc7a5\ubcbd\uc774\ub098 \uc0dd\ud65c \ubc29\uc2dd\uc758 \ucc28\uc774\ub85c \uc624\ud574\uc640 \uac08\ub4f1\uc774 \ubc1c\uc0dd\ud560 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc904\uc774\uae30 \uc704\ud574\uc11c\ub294 \uc678\uad6d\uc778\ub3c4 \uac70\uc8fc \uc0ac\ud68c\uc758 \uc5b8\uc5b4\uc640 \uae30\ubcf8 \uaddc\ubc94\uc744 \uc774\ud574\ud558\ub824\uace0 \ub178\ub825\ud574\uc57c \ud558\uba70 \uc9c0\uc5ed \uc0ac\ud68c\ub3c4 \ub2e4\uc591\ud55c \ubb38\ud654\ub97c \uc874\uc911\ud558\uace0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc81c\uacf5\ud574\uc57c \ud569\ub2c8\ub2e4. \uacb0\uad6d \uc0ac\ud68c \ud1b5\ud569\uc740 \uc5b4\ub290 \ud55c\ucabd\uc758 \uc77c\ubc29\uc801\uc778 \uc801\uc751\uc774 \uc544\ub2c8\ub77c \uc0c1\ud638 \uc774\ud574\uc640 \ucc38\uc5ec\ub97c \ud1b5\ud574 \uc774\ub8e8\uc5b4\uc838\uc57c \ud569\ub2c8\ub2e4.")
A.jB8=s(["\uc678\uad6d\uc778\uc774 \uacaa\uc744 \uc218 \uc788\ub294 \uc5b4\ub824\uc6c0\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc5b8\uc5b4 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\ud589\uc815\uacfc \uc0dd\ud65c \uc815\ubcf4 \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc9c1\uc7a5\uacfc \uc9c0\uc5ed \uc0ac\ud68c\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\ud6a8\uacfc\uc801\uc778 \uc9c0\uc6d0 \ubc29\uc548\uc744 \uc81c\uc2dc\ud558\uc138\uc694."],t.s)
A.ekJ=new B.eB("\uc678\uad6d\uc778 \uc8fc\ubbfc\uc758 \uc548\uc815\uc801\uc778 \uc815\ucc29\uc744 \uc704\ud55c \uc9c0\uc6d0",A.jB8,"\uc678\uad6d\uc778\uc774 \uc0c8\ub85c\uc6b4 \uad6d\uac00\uc5d0\uc11c \uc0dd\ud65c\uc744 \uc2dc\uc791\ud558\uba74 \uc5b8\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud589\uc815, \uc758\ub8cc, \uc8fc\uac70, \ucde8\uc5c5 \ub4f1 \ub2e4\uc591\ud55c \ubd84\uc57c\uc5d0\uc11c \uc5b4\ub824\uc6c0\uc744 \uacaa\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ud55c\uad6d\uc5b4\uac00 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \ucd08\uae30\uc5d0\ub294 \ud544\uc694\ud55c \uc81c\ub3c4\uac00 \uc788\uc5b4\ub3c4 \uc815\ubcf4\ub97c \ucc3e\uc9c0 \ubabb\ud558\uac70\ub098 \uc11c\ub958\ub97c \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uc9c0 \ubabb\ud558\ub294 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5ec\ub7ec \uc5b8\uc5b4\ub85c \uae30\ubcf8 \uc0dd\ud65c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \ud1b5\uc5ed \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc9c1\uc7a5\uc5d0\uc11c\ub3c4 \uc5c5\ubb34 \uc9c0\uc2dc\uc640 \uc548\uc804 \uad50\uc721\uc744 \uc678\uad6d\uc778 \uadfc\ub85c\uc790\uac00 \uc815\ud655\ud558\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc6d0\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc9c0\uc6d0\uc740 \uc678\uad6d\uc778\ub9cc\uc744 \uc704\ud55c \ud61c\ud0dd\uc774\ub77c\uae30\ubcf4\ub2e4 \uc0ac\ud68c \uad6c\uc131\uc6d0\uc774 \uc548\uc804\ud558\uace0 \uc548\uc815\uc801\uc73c\ub85c \uc0dd\ud65c\ud558\ub3c4\ub85d \ub3d5\ub294 \uc0ac\ud68c \ud1b5\ud569\uc758 \uacfc\uc815\uc774\ub77c\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.jS4=s([A.el2,A.ekJ],t.Qd)
A.kAk=s(["\ub2e4\ubb38\ud654 \uc0ac\ud68c","\ubb38\ud654 \ub2e4\uc591\uc131","\uc774\uc8fc\ubbfc","\uc678\uad6d\uc778 \uc8fc\ubbfc","\uc0ac\ud68c \ud1b5\ud569","\uc815\ucc29","\uc801\uc751","\ubb38\ud654 \ucc28\uc774","\ud3b8\uacac","\ucc28\ubcc4","\uc0c1\ud638 \uc774\ud574","\ubb38\ud654 \uad50\ub958","\uc815\uccb4\uc131","\ud3ec\uc6a9\uc131"],t.s)
A.kDV=s(["-\uc744/\ub97c \ub9c9\ub860\ud558\uace0","-\ub294\uac00 \ud558\uba74","-\uc5d0 \ub530\ub77c","-\ub294 \ub370 \uc788\uc5b4\uc11c","-\ub2e4\uace0 \ud574\uc11c","-\uae30\ubcf4\ub2e4\ub294","-\ub294 \ubc18\uba74\uc5d0","-(\uc73c)\u3139\uc218\ub85d","-\uc744/\ub97c \uacc4\uae30\ub85c","-\ub294 \uacfc\uc815\uc5d0\uc11c","-\uc9c0 \uc54a\ub3c4\ub85d","-\uc5d0 \ub300\ud55c \uc774\ud574","-\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4","-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4","-\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4"],t.s)
A.jWU=s(["\ub2e4\ubb38\ud654 \uc0ac\ud68c\ub294 \uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\uc801 \ubc30\uacbd\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uc0ac\ud68c\ub97c \uc758\ubbf8\ud55c\ub2e4.","\ubb38\ud654 \ub2e4\uc591\uc131\uc740 \uc5b8\uc5b4, \uc0dd\ud65c \ubc29\uc2dd, \uac00\uce58\uad00, \uc885\uad50, \uc74c\uc2dd \ub4f1 \uc5ec\ub7ec \ucc28\uc774\uc5d0\uc11c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4.","\uc678\uad6d\uc778\uc774 \uc0c8\ub85c\uc6b4 \uc0ac\ud68c\uc5d0 \uc815\ucc29\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc5b8\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c \uc81c\ub3c4\uc640 \ubb38\ud654\uc5d0 \ub300\ud55c \uc774\ud574\ub3c4 \ud544\uc694\ud558\ub2e4.","\uc0ac\ud68c \ud1b5\ud569\uc740 \ud55c\ucabd\uc774 \uc790\uc2e0\uc758 \ubb38\ud654\ub97c \uc644\uc804\ud788 \ubc84\ub9ac\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubb38\ud654 \ucc28\uc774\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc5b4\ub290 \ud55c \ubb38\ud654\uac00 \ub354 \uc6b0\uc6d4\ud558\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4.","\ud3b8\uacac\uc740 \ucda9\ubd84\ud55c \uc815\ubcf4\ub098 \uacbd\ud5d8 \uc5c6\uc774 \ud2b9\uc815 \uc9d1\ub2e8\uc744 \ubbf8\ub9ac \ud310\ub2e8\ud558\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\ub2e4.","\ucc28\ubcc4\uc740 \ucd9c\uc2e0 \uad6d\uac00\ub098 \uc5b8\uc5b4 \ub4f1\uacfc \uac19\uc740 \uc774\uc720\ub85c \ubd88\ub9ac\ud558\uac8c \ub300\uc6b0\ud558\ub294 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4.","\ub2e4\ubb38\ud654 \uac00\uc815\uc758 \uc790\ub140\ub294 \uc5ec\ub7ec \ubb38\ud654\uc801 \ubc30\uacbd\uc744 \ub3d9\uc2dc\uc5d0 \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4.","\ubb38\ud654 \uad50\ub958\uc640 \uc0c1\ud638 \uc774\ud574\ub294 \ubd88\ud544\uc694\ud55c \uc624\ud574\uc640 \uac08\ub4f1\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\ub2e4\uc591\uc131\uc744 \uc874\uc911\ud558\uba74\uc11c \uc0ac\ud68c \uad6c\uc131\uc6d0\uc5d0\uac8c \uacf5\uc815\ud55c \uae30\ud68c\ub97c \uc81c\uacf5\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
