A.dVg=new B.a9("\ube48\uace4 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.kBF,1,"\ube48\uace4\uc740 \uc5ec\ub7ec \uc0ac\ud68c\xb7\uacbd\uc81c\uc801 \uc694\uc778\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ubcf5\ud569\uc801\uc778 \uc811\uadfc\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","\uc0ac\ud68c \uc774\ud574","\uace0\uae09")
A.jI5=s(["Ch\u1ec9 t\u0103ng quy\u1ec1n l\u1ee3i","Hi\u1ec7u qu\u1ea3 h\u1ed7 tr\u1ee3 + ngu\u1ed3n t\xe0i ch\xednh + t\xednh c\xf4ng b\u1eb1ng","Kh\xf4ng c\u1ea7n \u0111\xe1nh gi\xe1","Ch\u1ec9 gi\u1ea3m thu\u1ebf"],t.s)
A.dUh=new B.a9("\uc9c0\uc18d \uac00\ub2a5\ud55c \ubcf5\uc9c0 \uc81c\ub3c4\ub97c \uc704\ud574 \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740?",A.jI5,1,"\ubcf5\uc9c0\uc758 \uc9c0\uc18d \uac00\ub2a5\uc131\uc744 \uc704\ud574\uc11c\ub294 \ud6a8\uacfc, \ud615\ud3c9\uc131, \uc7ac\uc6d0\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc815\ucc45 \uc774\ud574","\uace0\uae09")
