A.lZk=s(["\uc9c8\ubcd1","\uc2e4\uc5c5","\ube48\uace4","\uc0ac\ud68c\uc548\uc804\ub9dd","\uae30\ud68c","\uc0ac\ud68c \ud1b5\ud569"],t.s)
A.dZw=new B.dr("\uc0ac\ud68c\uc5d0\uc11c \ubcf5\uc9c0\uac00 \ud544\uc694\ud55c \uc774\uc720\ub294 \ubb34\uc5c7\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.lZk,"\ub204\uad6c\ub098 \uc9c8\ubcd1\uc774\ub098 \uc2e4\uc5c5\ucc98\ub7fc \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc5b4\ub824\uc6c0\uc744 \uacaa\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uae30\ubcf8\uc801\uc778 \uc0ac\ud68c\uc548\uc804\ub9dd\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubcf5\uc9c0\ub294 \ub2e8\uc21c\ud788 \uc5b4\ub824\uc6b4 \uc0ac\ub78c\uc5d0\uac8c \ub3c8\uc744 \uc8fc\ub294 \uc81c\ub3c4\uac00 \uc544\ub2c8\ub77c \ucd5c\uc18c\ud55c\uc758 \uc0dd\ud65c\uacfc \ub2e4\uc2dc \uc790\ub9bd\ud560 \uc218 \uc788\ub294 \uae30\ud68c\ub97c \uc81c\uacf5\ud558\ub294 \uc5ed\ud560\ub3c4 \ud569\ub2c8\ub2e4. \uc801\uc808\ud55c \ubcf5\uc9c0 \uc81c\ub3c4\ub294 \ube48\uace4\uc744 \uc644\ud654\ud558\uace0 \uc7a5\uae30\uc801\uc73c\ub85c \uc0ac\ud68c \ud1b5\ud569\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.jVO=s(["\uad50\uc721","\uace0\uc6a9","\uc784\uae08","\uc138\uae08","\ubcf5\uc9c0","\uae30\ud68c"],t.s)
A.e_2=new B.dr("\uc18c\ub4dd \uaca9\ucc28\ub97c \uc904\uc774\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc815\ucc45\uc774 \ud544\uc694\ud569\ub2c8\uae4c?",A.jVO,"\uc18c\ub4dd \uaca9\ucc28\ub97c \uc904\uc774\uae30 \uc704\ud574\uc11c\ub294 \ubcf5\uc9c0 \uc815\ucc45\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc88b\uc740 \uad50\uc721\uc744 \ubc1b\uc744 \uae30\ud68c\uc640 \uc548\uc815\uc801\uc778 \uc77c\uc790\ub9ac\ub97c \uc5bb\uc744 \uae30\ud68c\ub97c \ud568\uaed8 \ud655\ub300\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc800\uc18c\ub4dd\uce35\uc758 \uae30\ubcf8 \uc0dd\ud65c\uc744 \uc9c0\uc6d0\ud558\ub294 \ud55c\ud3b8 \uc138\uae08\uacfc \uc0ac\ud68c\ubcf4\uc7a5 \uc81c\ub3c4\ub97c \ud1b5\ud574 \uc9c0\ub098\uce5c \uaca9\ucc28\ub97c \uc644\ud654\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.kag=s(["\uc811\uadfc\uc131","\uc7ac\uc6d0","\ucde8\uc57d \uacc4\uce35","\uacf5\uc815\uc131","\ud589\uc815 \ube44\uc6a9","\uc815\ucc45 \ubaa9\uc801"],t.s)
A.dZg=new B.dr("\ubcf4\ud3b8\uc801 \ubcf5\uc9c0\uc640 \uc120\ubcc4\uc801 \ubcf5\uc9c0 \uc911 \uc5b4\ub290 \ubc29\uc2dd\uc774 \ub354 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.kag,"\ud55c \uac00\uc9c0 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \ubd84\uc57c\uc5d0\uc11c \ub354 \uc88b\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uae30\ubcf8\uc801\uc778 \uc758\ub8cc\ub098 \uad50\uc721\ucc98\ub7fc \uc0ac\ud68c \uc804\uccb4\uc5d0 \ud544\uc694\ud55c \uc11c\ube44\uc2a4\ub294 \ubcf4\ud3b8\uc801\uc73c\ub85c \uc81c\uacf5\ud560 \ud544\uc694\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc81c\ud55c\ub41c \uc7ac\uc6d0\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \ubd84\uc57c\uc5d0\uc11c\ub294 \ub3c4\uc6c0\uc774 \ub354 \ud544\uc694\ud55c \uacc4\uce35\uc744 \uc9d1\uc911\uc801\uc73c\ub85c \uc9c0\uc6d0\ud558\ub294 \ubc29\uc2dd\ub3c4 \ud544\uc694\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc815\ucc45 \ubaa9\uc801\uc5d0 \ub530\ub77c \ub450 \ubc29\uc2dd\uc744 \uc801\uc808\ud788 \uacb0\ud569\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.lEB=s([A.dZw,A.e_2,A.dZg],t.Gu)
A.ldh=s(["\uc18c\ub4dd \uaca9\ucc28\uc758 \uc758\ubbf8\ub97c \uc124\uba85\ud558\uc138\uc694.","\uaca9\ucc28\uac00 \ubc1c\uc0dd\ud558\ub294 \uc6d0\uc778\uc744 \uc4f0\uc138\uc694.","\uad50\uc721\uacfc \uc8fc\uac70\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc0ac\ud68c\uc801 \uac08\ub4f1\uacfc\uc758 \uad00\uacc4\ub97c \uc4f0\uc138\uc694.","\uac00\ub2a5\ud55c \ub300\ucc45\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.el8=new B.eB("\uc18c\ub4dd \uaca9\ucc28\uac00 \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5",A.ldh,"\uc18c\ub4dd \uaca9\ucc28\ub294 \uac1c\uc778\uc774\ub098 \uac00\uad6c\uac00 \ubc8c\uc5b4\ub4e4\uc774\ub294 \uc18c\ub4dd \uc218\uc900\uc758 \ucc28\uc774\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uaca9\ucc28\ub294 \uc9c1\uc5c5\uacfc \uace0\uc6a9 \ud615\ud0dc, \uad50\uc721 \uc218\uc900, \uc0b0\uc5c5 \uad6c\uc870 \ub4f1 \ub2e4\uc591\ud55c \uc694\uc778\uc5d0 \uc758\ud574 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc81c\ub294 \uc18c\ub4dd \uaca9\ucc28\uac00 \ub2e8\uc21c\ud55c \uc18c\ube44 \uc218\uc900\uc758 \ucc28\uc774\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc8fc\uac70\uc640 \uad50\uc721 \uae30\ud68c\uc758 \ucc28\uc774\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \ud2b9\ud788 \uc774\ub7ec\ud55c \ucc28\uc774\uac00 \uc138\ub300\ub97c \ub118\uc5b4 \ubc18\ubcf5\ub418\uba74 \uc0ac\ud68c \uc774\ub3d9\uc131\uc774 \ub0ae\uc544\uc9c0\uace0 \uc0ac\ud68c\uc801 \uac08\ub4f1\ub3c4 \uc2ec\ud654\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc800\uc18c\ub4dd\uce35\uc758 \uae30\ubcf8 \uc0dd\ud65c\uc744 \uc9c0\uc6d0\ud558\ub294 \uac83\uacfc \ud568\uaed8 \uad50\uc721\uacfc \uace0\uc6a9 \uae30\ud68c\ub97c \ud655\ub300\ud558\uace0 \uacf5\uc815\ud55c \uacbd\uc7c1 \ud658\uacbd\uc744 \ub9cc\ub4dc\ub294 \uc815\ucc45\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.kcC=s(["\ubcf5\uc9c0\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc7ac\uc815 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc9c0\uc6d0 \ub300\uc0c1\uacfc \uacf5\uc815\uc131 \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\ubcf5\uc9c0 \uc0ac\uac01\uc9c0\ub300 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc9c0\uc18d \uac00\ub2a5\ud55c \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.ekW=new B.eB("\uc9c0\uc18d \uac00\ub2a5\ud55c \ubcf5\uc9c0 \uc81c\ub3c4\ub97c \uc704\ud55c \uc870\uac74",A.kcC,"\ubcf5\uc9c0 \uc81c\ub3c4\ub294 \uc9c8\ubcd1\uc774\ub098 \uc2e4\uc5c5, \ub178\ub839 \ub4f1\uc73c\ub85c \uc5b4\ub824\uc6c0\uc744 \uacaa\ub294 \uc0ac\ub78c\uc774 \uae30\ubcf8\uc801\uc778 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc6d0\ud558\ub294 \uc911\uc694\ud55c \uc0ac\ud68c\uc548\uc804\ub9dd\uc785\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ubcf5\uc9c0\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \ud655\ub300\ud558\uae30 \uc704\ud574\uc11c\ub294 \ud544\uc694\ud55c \uc7ac\uc6d0\uc744 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ud560 \uac83\uc778\uc9c0\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc9c0\uc6d0 \uae30\uc900\uc774 \uc9c0\ub098\uce58\uac8c \ubcf5\uc7a1\ud558\uba74 \uc2e4\uc81c\ub85c \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc774 \ubcf5\uc9c0 \uc0ac\uac01\uc9c0\ub300\uc5d0 \ub193\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc9c0\uc6d0 \ubc94\uc704\ub97c \uc9c0\ub098\uce58\uac8c \ub113\ud788\uba74 \uc7ac\uc815 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc815\ucc45\uc758 \ubaa9\uc801\uc5d0 \ub530\ub77c \ubcf4\ud3b8\uc801 \ubcf5\uc9c0\uc640 \uc120\ubcc4\uc801 \ubcf5\uc9c0\ub97c \uc801\uc808\ud788 \ud65c\uc6a9\ud558\uace0 \uc815\ucc45 \ud6a8\uacfc\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \ud3c9\uac00\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.ktt=s([A.el8,A.ekW],t.Qd)
A.jRu=s(["\uc0ac\ud68c\ubcf5\uc9c0","\uc0ac\ud68c\ubcf4\uc7a5","\uc0ac\ud68c\uc548\uc804\ub9dd","\uc18c\ub4dd \uaca9\ucc28","\uc790\uc0b0 \uaca9\ucc28","\ube48\uace4","\ucde8\uc57d \uacc4\uce35","\ubcf5\uc9c0 \uc815\ucc45","\uc18c\ub4dd \uc7ac\ubd84\ubc30","\uc0ac\ud68c\uc801 \uc57d\uc790","\uae30\ucd08\uc0dd\ud65c\ubcf4\uc7a5","\uc0ac\ud68c \uc591\uadf9\ud654","\uc911\uc0b0\uce35","\uacf5\uc815\uc131"],t.s)
A.m0Z=s(["-\uc5d0 \ube44\ud574","-\ub294 \ubc18\uba74\uc5d0","-\uc744/\ub97c \ube44\ub86f\ud574","-\uc5d0 \ub530\ub77c","-(\uc73c)\u3139\uc218\ub85d","-\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0","-\uc9c0 \uc54a\ub294 \ud55c","-\ub2e4\uace0 \ud574\uc11c","-(\uc73c)\u3139 \uc218\ubc16\uc5d0 \uc5c6\ub2e4","-\ub294 \uac00\uc6b4\ub370","-\uc744/\ub97c \uac10\uc548\ud558\uba74","-\uae30 \ub9c8\ub828\uc774\ub2e4","-\uc744/\ub97c \ub300\uc0c1\uc73c\ub85c","-\ub294 \ucc28\uc6d0\uc5d0\uc11c","-\uace0\uc790 \ud558\ub2e4"],t.s)
A.kVT=s(["\uc0ac\ud68c\ubcf5\uc9c0\ub294 \uc0ac\ud68c \uad6c\uc131\uc6d0\uc774 \uae30\ubcf8\uc801\uc778 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc6d0\ud558\ub294 \uc81c\ub3c4\uc640 \uc11c\ube44\uc2a4\ub97c \ud3ec\ud568\ud55c\ub2e4.","\uc0ac\ud68c\ubcf4\uc7a5\uc740 \uc9c8\ubcd1, \uc2e4\uc5c5, \ub178\ub839 \ub4f1 \uc0ac\ud68c\uc801 \uc704\ud5d8\uc73c\ub85c\ubd80\ud130 \uad6d\ubbfc\uc758 \uc0dd\ud65c\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4.","\uc0ac\ud68c\uc548\uc804\ub9dd\uc740 \uacbd\uc81c\uc801\xb7\uc0ac\ud68c\uc801 \uc704\uae30\uc5d0 \ucc98\ud55c \uc0ac\ub78c\uc774 \ucd5c\uc18c\ud55c\uc758 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub3c4\ub85d \ub3d5\ub294 \uccb4\uacc4\ub97c \uc758\ubbf8\ud55c\ub2e4.","\uc18c\ub4dd \uaca9\ucc28\uc640 \uc790\uc0b0 \uaca9\ucc28\ub294 \uc11c\ub85c \uad00\ub828\ub418\uc5b4 \uc788\uc9c0\ub9cc \ub3d9\uc77c\ud55c \uac1c\ub150\uc740 \uc544\ub2c8\ub2e4.","\ube48\uace4 \ubb38\uc81c\ub294 \ub2e8\uc21c\ud788 \ud604\uc7ac \uc18c\ub4dd\uc774 \ub0ae\ub2e4\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uad50\uc721, \uac74\uac15, \uc8fc\uac70\uc640\ub3c4 \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4.","\uc18c\ub4dd \uc7ac\ubd84\ubc30\ub294 \uc138\uae08\uacfc \ubcf5\uc9c0 \uc81c\ub3c4 \ub4f1\uc744 \ud1b5\ud574 \uacbd\uc81c\uc801 \uaca9\ucc28\ub97c \uc644\ud654\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4.","\ubcf5\uc9c0 \uc815\ucc45\uc740 \ud61c\ud0dd\uc758 \uaddc\ubaa8\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc2e4\uc81c\ub85c \uc804\ub2ec\ub418\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4.","\uc0ac\ud68c\uc801 \uc57d\uc790\ub97c \uc9c0\uc6d0\ud558\ub294 \uac83\uc740 \uac1c\uc778\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc0ac\ud68c \uc804\uccb4\uc758 \uc548\uc815\uacfc\ub3c4 \uad00\ub828\uc774 \uc788\ub2e4.","\uacf5\uc815\uc131\uacfc \ud3c9\ub4f1\uc740 \ube44\uc2b7\ud574 \ubcf4\uc774\uc9c0\ub9cc \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \ub611\uac19\uc774 \uc81c\uacf5\ud558\ub294 \uac83\uacfc \ud544\uc694\ud55c \uc218\uc900\uc5d0 \ub530\ub77c \uc9c0\uc6d0\ud558\ub294 \uac83\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4.","\uc9c0\uc18d \uac00\ub2a5\ud55c \ubcf5\uc9c0 \uc81c\ub3c4\ub97c \uc704\ud574\uc11c\ub294 \ud544\uc694\ud55c \uc7ac\uc6d0\uacfc \uc0ac\ud68c\uc801 \ud569\uc758\ub97c \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4."],t.s)
