A.lBI=s(["Ch\u1ec9 t\u0103ng l\u01b0\u1ee3ng c\xf4ng vi\u1ec7c","\u0110\xe3i ng\u1ed9 + m\xf4i tr\u01b0\u1eddng + c\u01a1 h\u1ed9i ph\xe1t tri\u1ec3n","Kh\xf4ng c\u1ea7n \u0111\xe0o t\u1ea1o","Ch\u1ec9 tuy\u1ec3n ng\u01b0\u1eddi m\u1edbi"],t.s)
A.dV_=new B.a9("C\xf4ng ty mu\u1ed1n gi\u1eef nh\xe2n vi\xean gi\u1ecfi th\xec \u0111i\u1ec1u n\xe0o ph\xf9 h\u1ee3p nh\u1ea5t?",A.lBI,1,"\u0110\xe3i ng\u1ed9, m\xf4i tr\u01b0\u1eddng l\xe0m vi\u1ec7c v\xe0 c\u01a1 h\u1ed9i ph\xe1t tri\u1ec3n \u0111\u1ec1u \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn kh\u1ea3 n\u0103ng gi\u1eef nh\xe2n t\xe0i.","\uc2e4\uc804","\uace0\uae09")
