A.dZG=new B.dr("\uae30\uc220 \uad6d\uc0b0\ud654\ub294 \uc65c \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\uae4c?",A.lQG,"\ubaa8\ub4e0 \uae30\uc220\uacfc \ubd80\ud488\uc744 \uad6d\ub0b4\uc5d0\uc11c \uc0dd\uc0b0\ud560 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc \ud575\uc2ec \ubd80\ud488\uc758 \ud574\uc678 \uc758\uc874\ub3c4\uac00 \uc9c0\ub098\uce58\uac8c \ub192\uc73c\uba74 \uc704\ud5d8\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uad6d\uc81c\uc801\uc778 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud574 \uacf5\uae09\uc774 \uc911\ub2e8\ub418\uba74 \uc804\uccb4 \uc0dd\uc0b0\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc911\uc694\ud55c \ubd84\uc57c\uc5d0\uc11c\ub294 \uc77c\uc815 \uc218\uc900\uc758 \uc790\uccb4 \uae30\uc220\uc744 \ud655\ubcf4\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uacf5\uae09\ub9dd\uc744 \ub2e4\uc591\ud654\ud558\ub294 \uc804\ub7b5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.liz=s(["\uc2e0\ub8b0\uc131","\ub370\uc774\ud130","\ud45c\uc808","\uc7ac\ud604\uc131","\uc0ac\ud68c\uc801 \ucc45\uc784"],t.s)
A.dZm=new B.dr("\uacfc\ud559 \uc5f0\uad6c\uc5d0\uc11c \uc5f0\uad6c \uc724\ub9ac\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.liz,"\uacfc\ud559 \uc5f0\uad6c\ub294 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc640 \uc0ac\ud68c\uac00 \uadf8 \uacb0\uacfc\ub97c \ubbff\uace0 \ud65c\uc6a9\ud560 \uc218 \uc788\uc5b4\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \uc2e0\ub8b0\uc131\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uc5f0\uad6c\uc790\uac00 \uc6d0\ud558\ub294 \uacb0\uacfc\ub97c \uc5bb\uae30 \uc704\ud574 \ub370\uc774\ud130\ub97c \uc870\uc791\ud558\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc5f0\uad6c\ub97c \ucd9c\ucc98 \uc5c6\uc774 \uc0ac\uc6a9\ud55c\ub2e4\uba74 \uc5f0\uad6c \uc804\uccb4\uc5d0 \ub300\ud55c \uc2e0\ub8b0\uac00 \ubb34\ub108\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc88b\uc740 \uc5f0\uad6c \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294 \uac83\uc5d0 \ubabb\uc9c0\uc54a\uac8c \ud22c\uba85\ud558\uace0 \uc815\uc9c1\ud55c \uc5f0\uad6c \uacfc\uc815\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.jOP=s([A.dZI,A.dZG,A.dZm],t.Gu)
A.kly=s(["\uacfc\ud559 \uae30\uc220 \ubc1c\uc804\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uacbd\uc81c\uc640 \uc0b0\uc5c5\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uac1c\uc778\uc758 \uc0dd\ud65c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc55e\uc73c\ub85c \ud544\uc694\ud55c \ud0dc\ub3c4\ub97c \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.ekO=new B.eB("\uacfc\ud559 \uae30\uc220 \ubc1c\uc804\uc774 \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5",A.kly,"\uacfc\ud559 \uae30\uc220\uc758 \ubc1c\uc804\uc740 \uc0c8\ub85c\uc6b4 \uc0b0\uc5c5\uc744 \ub9cc\ub4e4\uace0 \uc0dd\uc0b0\uc131\uc744 \ub192\uc774\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \ubc18\ub3c4\uccb4\uc640 \ubc14\uc774\uc624, \ub85c\ubd07, \uc6b0\uc8fc \uc0b0\uc5c5\uacfc \uac19\uc740 \ucca8\ub2e8 \uae30\uc220\uc740 \uad6d\uac00\uc640 \uae30\uc5c5\uc758 \uacbd\uc7c1\ub825\uc744 \uacb0\uc815\ud558\ub294 \uc911\uc694\ud55c \uc694\uc18c\uac00 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc0c8\ub85c\uc6b4 \uc758\ub8cc\uae30\uae30\uc640 \ud1b5\uc2e0 \uae30\uc220\uc740 \uac1c\uc778\uc758 \uc0dd\ud65c\uc744 \ub354\uc6b1 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uae30\uc220 \ubc1c\uc804\uc774 \ube60\ub97c\uc218\ub85d \uad6d\uac00\uc640 \uacc4\uce35 \uac04 \uae30\uc220 \uaca9\ucc28\uac00 \ucee4\uc9c0\uac70\ub098 \uae30\uc874 \uc77c\uc790\ub9ac \uad6c\uc870\uac00 \ubcc0\ud558\ub294 \ubb38\uc81c\ub3c4 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5f0\uad6c\uac1c\ubc1c\uc744 \ud655\ub300\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uad50\uc721\uacfc \uc7ac\uad50\uc721\uc744 \uac15\ud654\ud558\uace0 \uae30\uc220\uc774 \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc9c0\uc18d\uc801\uc73c\ub85c \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.kJ9=s(["\uae30\uc220 \uacbd\uc7c1\uc758 \ud604\ud669\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc5f0\uad6c\uac1c\ubc1c\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\uae30\ucd08 \uc5f0\uad6c\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\uae30\uc5c5\uacfc \ub300\ud559\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\uc7a5\uae30\uc801\uc778 \uc815\ucc45 \ubc29\ud5a5\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.el7=new B.eB("\uad6d\uac00 \uacbd\uc7c1\ub825\uacfc \uc5f0\uad6c\uac1c\ubc1c \ud22c\uc790\uc758 \uc911\uc694\uc131",A.kJ9,"\ucca8\ub2e8 \uae30\uc220\uc744 \ub458\ub7ec\uc2fc \uad6d\uac00 \uac04 \uacbd\uc7c1\uc774 \uc2ec\ud654\ub418\uba74\uc11c \uc5f0\uad6c\uac1c\ubc1c \ub2a5\ub825\uc740 \uad6d\uac00 \uacbd\uc7c1\ub825\uc758 \uc911\uc694\ud55c \uc694\uc18c\uac00 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc5c5\uc740 \uc2dc\uc7a5\uc5d0\uc11c \ud544\uc694\ud55c \uae30\uc220\uc744 \ube60\ub974\uac8c \uac1c\ubc1c\ud558\ub294 \uc5ed\ud560\uc744 \ud558\uc9c0\ub9cc \ub2e8\uae30\uac04\uc5d0 \uc131\uacfc\ub97c \ub0b4\uae30 \uc5b4\ub824\uc6b4 \uae30\ucd08 \uc5f0\uad6c\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4. \uae30\ucd08 \uc5f0\uad6c\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc774 \uc2dc\uac04\uc774 \uc9c0\ub098 \uc751\uc6a9 \uc5f0\uad6c\uc640 \uc0b0\uc5c5 \uae30\uc220\ub85c \ubc1c\uc804\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc815\ubd80\uc640 \ub300\ud559, \uc5f0\uad6c\uae30\uad00, \uae30\uc5c5\uc774 \uc7a5\uae30\uc801\uc778 \uad00\uc810\uc5d0\uc11c \ud611\ub825\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc5f0\uad6c \uc131\uacfc\uac00 \uc2e4\uc81c \uc0b0\uc5c5\uc73c\ub85c \uc5f0\uacb0\ub420 \uc218 \uc788\ub3c4\ub85d \uc0b0\ud559 \ud611\ub825\uacfc \uae30\uc220 \uc774\uc804, \uae30\uc220 \ucc3d\uc5c5\uc744 \uc9c0\uc6d0\ud558\ub294 \uc0b0\uc5c5 \uc0dd\ud0dc\uacc4\ub97c \uad6c\ucd95\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.ljP=s([A.ekO,A.el7],t.Qd)
A.lHn=s(["\uc5f0\uad6c\uac1c\ubc1c","\uae30\uc220 \ud601\uc2e0","\ubc18\ub3c4\uccb4","\ubc14\uc774\uc624 \uc0b0\uc5c5","\uc591\uc790 \uae30\uc220","\uc6b0\uc8fc \uc0b0\uc5c5","\ud2b9\ud5c8","\uc9c0\uc2dd\uc7ac\uc0b0\uad8c","\uc0b0\ud559 \ud611\ub825","\uae30\uc220 \uc774\uc804","\uae30\uc220 \uaca9\ucc28","\uc5f0\uad6c \uc724\ub9ac","\uc0b0\uc5c5 \uc0dd\ud0dc\uacc4","\uc0c1\uc6a9\ud654"],t.s)
A.jV2=s(["-\uc5d0 \ud798\uc785\uc5b4","-\uc744/\ub97c \uacc4\uae30\ub85c","-\uae30\uc5d0 \uc774\ub974\ub2e4","-\uae30\uc5d0\ub294","-\uc744/\ub97c \ubc14\ud0d5\uc73c\ub85c","-\ub294 \ub9cc\ud07c","-\uace0\uc790 \ud558\ub2e4","-\uc744/\ub97c \ub458\ub7ec\uc2f8\uace0","-\uae30 \ub9c8\ub828\uc774\ub2e4","-\uc5d0 \ubabb\uc9c0\uc54a\uac8c","-\ub294 \ub370 \uc788\uc5b4\uc11c","-\uc744/\ub97c \uc55e\ub450\uace0","-\uc744/\ub97c \ud1b5\ud574","-\ub294 \ub3d9\uc2dc\uc5d0","-(\uc73c)\u3139 \uac83\uc73c\ub85c \uae30\ub300\ub418\ub2e4"],t.s)
A.kEF=s(["\uc5f0\uad6c\uac1c\ubc1c\uc740 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc774\ub098 \uae30\uc220\uc744 \ub9cc\ub4e4\uace0 \uc2e4\uc81c \uc0b0\uc5c5\uc5d0 \ud65c\uc6a9\ud558\uae30 \uc704\ud55c \ud65c\ub3d9\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uae30\ucd08 \uc5f0\uad6c\ub294 \uae30\ubcf8\uc801\uc778 \uc6d0\ub9ac\uc640 \uc9c0\uc2dd\uc744 \ud0d0\uad6c\ud558\uace0 \uc751\uc6a9 \uc5f0\uad6c\ub294 \uc2e4\uc81c \ubb38\uc81c \ud574\uacb0\uacfc \ud65c\uc6a9 \uac00\ub2a5\uc131\uc5d0 \ub354 \ucd08\uc810\uc744 \ub454\ub2e4.","\uc5f0\uad6c \uacb0\uacfc\uac00 \uc2e4\uc81c \uc81c\ud488\uc774\ub098 \uc11c\ube44\uc2a4\ub85c \uc5f0\uacb0\ub418\ub294 \uacfc\uc815\uc744 \uc0c1\uc6a9\ud654\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4.","\ud2b9\ud5c8\uc640 \uc9c0\uc2dd\uc7ac\uc0b0\uad8c\uc740 \uae30\uc220\uacfc \uc544\uc774\ub514\uc5b4\ub97c \ubcf4\ud638\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4.","\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc5d0\uc11c\ub294 \uc124\uacc4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc18c\uc7ac, \ubd80\ud488, \uc7a5\ube44, \uacf5\uc815 \uae30\uc220\uacfc \uc218\uc728\ub3c4 \uc911\uc694\ud558\ub2e4.","\ubc14\uc774\uc624 \uc0b0\uc5c5\uc5d0\uc11c\ub294 \uc5f0\uad6c \uc131\uacfc\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc548\uc804\uc131\uacfc \uc784\uc0c1\uc2dc\ud5d8 \uacfc\uc815\ub3c4 \uc911\uc694\ud558\ub2e4.","\uc591\uc790 \uae30\uc220\uacfc \uc6b0\uc8fc \uc0b0\uc5c5\uc740 \ubbf8\ub798 \uc131\uc7a5 \uc0b0\uc5c5\uc73c\ub85c \uc8fc\ubaa9\ubc1b\uace0 \uc788\ub2e4.","\uae30\uc220 \uacbd\uc7c1\uc774 \uc2ec\ud654\ub420\uc218\ub85d \ud575\uc2ec \uae30\uc220\uacfc \uacf5\uae09\ub9dd \ud655\ubcf4\uc758 \uc911\uc694\uc131\ub3c4 \ucee4\uc9c8 \uc218 \uc788\ub2e4.","\uc5f0\uad6c \uacb0\uacfc\uc758 \uc2e0\ub8b0\uc131\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud574 \uc5f0\uad6c \uc724\ub9ac\uc640 \ub370\uc774\ud130 \uad00\ub9ac\uac00 \uc911\uc694\ud558\ub2e4.","\uae30\uc220 \ubc1c\uc804\uc740 \uacbd\uc81c \uc131\uc7a5\uc5d0 \uae30\uc5ec\ud560 \uc218 \uc788\uc9c0\ub9cc \uae30\uc220 \uaca9\ucc28\uc640 \uc0ac\ud68c\uc801 \uc601\ud5a5\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4."],t.s)
A.zM=new B.hV(16,"\uacfc\ud559 \uae30\uc220\uacfc \ubbf8\ub798 \uc0ac\ud68c",A.kic,A.m0E,A.jHR,A.kod,A.kk_,A.jUB,A.jvq,A.jOP,A.ljP,A.lHn,A.jV2,A.kEF)
A.kUk=s(["\uad50\uc721\uacfc \ud6c8\ub828\uc5d0 \uad00\ud55c \uc911\xb7\uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uad50\uc721 \uc81c\ub3c4\uc640 \ud559\uc2b5 \uae30\ud68c\uc5d0 \ub300\ud574 \uc124\uba85\ud55c\ub2e4.","\ud559\ub825, \ud559\ubc8c, \ud559\uc704, \uc790\uaca9\uc758 \ucc28\uc774\ub97c \uad6c\ubcc4\ud55c\ub2e4.","\ud559\ub825\ub9cc\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc5c5\ubb34 \ub2a5\ub825\uc758 \uc911\uc694\uc131\uc744 \uc81c\uc2dc\ud55c\ub2e4.","\uc9c1\uc5c5 \uad50\uc721\uacfc \uae30\uc5c5 \ub0b4 \uad50\uc721\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\ud3c9\uc0dd \ud559\uc2b5\uacfc \uc5ed\ub7c9 \ud5a5\uc0c1\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud55c\ub2e4.","\uad50\uc721 \uaca9\ucc28\uc758 \uc6d0\uc778\uacfc \uc0ac\ud68c\uc801 \uc601\ud5a5\uc744 \ubd84\uc11d\ud55c\ub2e4.","\uc0ac\uad50\uc721\uacfc \uad50\uc721\ube44 \ubd80\ub2f4 \ubb38\uc81c\ub97c \uc124\uba85\ud55c\ub2e4.","\uc628\ub77c\uc778 \uad50\uc721\uacfc \ud63c\ud569\ud615 \ud559\uc2b5\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc790\uae30 \uc8fc\ub3c4 \ud559\uc2b5 \ub2a5\ub825\uacfc \ube44\ud310\uc801 \uc0ac\uace0\ub97c \uc124\uba85\ud55c\ub2e4.","\uc778\uacf5\uc9c0\ub2a5\uc774 \uad50\uc721\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ubd84\uc11d\ud55c\ub2e4.","\uc7ac\uad50\uc721\uacfc \uc9c1\ubb34 \ub2a5\ub825 \ud5a5\uc0c1\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud55c\ub2e4.","\ud3c9\uac00, \uc131\ucde8\ub3c4, \ud559\uc2b5 \uc5ed\ub7c9\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\ud559\uc2b5\uc790 \uc911\uc2ec \uad50\uc721\uc758 \uc7a5\uc810\uacfc \uacfc\uc81c\ub97c \ud1a0\ub860\ud55c\ub2e4.","\uad50\uc721 \uae30\ud68c\uc758 \uacf5\uc815\uc131\uc5d0 \ub300\ud574 \uadfc\uac70\ub97c \ub4e4\uc5b4 \ub9d0\ud55c\ub2e4.","\uad50\uc721\uacfc \uc9c1\uc5c5\uc758 \ubbf8\ub798\ub97c \uc8fc\uc81c\ub85c \uace0\uae09 TOPIK \uc4f0\uae30\ub97c \uc5f0\uc2b5\ud55c\ub2e4."],t.s)
A.dFu=new B.h("\uad50\uc721\uc740 \uac1c\uc778\uc758 \uc131\uc7a5\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c \ubc1c\uc804\uc5d0\ub3c4 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.","Gi\xe1o d\u1ee5c \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng kh\xf4ng ch\u1ec9 \u0111\u1ed1i v\u1edbi s\u1ef1 ph\xe1t tri\u1ec3n c\xe1 nh\xe2n m\xe0 c\u1ea3 x\xe3 h\u1ed9i.")
