A.e__=new B.dr("\uc9c1\uc7a5\uc778\uc774 \uacc4\uc18d \uacf5\ubd80\ud574\uc57c \ud558\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.kgJ,"\uacfc\uac70\uc5d0\ub294 \ud55c \uac00\uc9c0 \uae30\uc220\uc744 \ubc30\uc6b0\uba74 \uc624\ub7ab\ub3d9\uc548 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc5c8\uc9c0\ub9cc \uc9c0\uae08\uc740 \uae30\uc220 \ubcc0\ud654 \uc18d\ub3c4\uac00 \ub9e4\uc6b0 \ube60\ub985\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc124\ube44\uc640 AI \uc2dc\uc2a4\ud15c\uc774 \ub3c4\uc785\ub418\uba74 \uae30\uc874 \uc5c5\ubb34 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc9c1\uc7a5\uc778\ub3c4 \uacc4\uc18d \ubc30\uc6cc\uc57c \ud569\ub2c8\ub2e4. \ud3c9\uc0dd\ud559\uc2b5\uc740 \ub2e8\uc21c\ud788 \uc790\uaca9\uc99d\uc744 \ub530\uae30 \uc704\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc790\uc2e0\uc758 \uc9c1\ubb34 \uacbd\uc7c1\ub825\uc744 \uc720\uc9c0\ud558\uace0 \uc0c8\ub85c\uc6b4 \uae30\ud68c\uc5d0 \ub300\ube44\ud558\uae30 \uc704\ud574 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.kWD=s([A.dZU,A.dZV,A.e__],t.Gu)
A.kBg=s(["\uae30\uc874 \uad50\uc721 \ubc29\uc2dd\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","AI\uac00 \uad50\uc721\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","AI \uad50\uc721\uc758 \uc7a5\uc810\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubb38\uc81c\uc810\uc774\ub098 \uc704\ud5d8 \uc694\uc18c\ub97c \uc4f0\uc138\uc694.","\uc55e\uc73c\ub85c \ud544\uc694\ud55c \uad50\uc721 \ubc29\ud5a5\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.eli=new B.eB("AI \uc2dc\ub300\uc758 \uad50\uc721 \ubcc0\ud654",A.kBg,"\uc778\uacf5\uc9c0\ub2a5 \uae30\uc220\uc758 \ubc1c\uc804\uc73c\ub85c \uad50\uc721 \ubc29\uc2dd\ub3c4 \ube60\ub974\uac8c \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uacfc\uac70\uc5d0\ub294 \uad50\uc0ac\uac00 \uc9c0\uc2dd\uc744 \uc804\ub2ec\ud558\uace0 \ud559\uc0dd\uc774 \uc774\ub97c \uc554\uae30\ud558\ub294 \ubc29\uc2dd\uc774 \uc911\uc2ec\uc774\uc5c8\ub2e4\uba74 \uc55e\uc73c\ub85c\ub294 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\uace0 \ubd84\uc11d\ud558\uba70 \ud65c\uc6a9\ud558\ub294 \ub2a5\ub825\uc774 \ub354\uc6b1 \uc911\uc694\ud574\uc9c8 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4. AI\ub97c \ud65c\uc6a9\ud558\uba74 \ud559\uc2b5\uc790\uc758 \uc218\uc900\uacfc \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ubd84\uc11d\ud558\uc5ec \ub9de\ucda4\ud615 \ud559\uc2b5\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 AI\uac00 \uc81c\uacf5\ud55c \uc815\ubcf4\uac00 \ud56d\uc0c1 \uc815\ud655\ud55c \uac83\uc740 \uc544\ub2c8\ubbc0\ub85c \ud559\uc0dd\uc774 \uc815\ubcf4\ub97c \uac80\uc99d\ud558\ub294 \ube44\ud310\uc801 \uc0ac\uace0\ub3c4 \ud568\uaed8 \uae38\ub7ec\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \ubbf8\ub798 \uad50\uc721\uc740 AI\ub97c \ub2e8\uc21c\ud788 \uc0ac\uc6a9\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 AI\ub97c \uc62c\ubc14\ub974\uac8c \ud65c\uc6a9\ud558\uace0 \ud310\ub2e8\ud558\ub294 \ub2a5\ub825\uc744 \ud0a4\uc6b0\ub294 \ubc29\ud5a5\uc73c\ub85c \ubc1c\uc804\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.k_f=s(["\uc0ac\ud68c\uc640 \uae30\uc220\uc758 \ubcc0\ud654\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc9c1\uc5c5\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uc7ac\uad50\uc721\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\uac1c\uc778\uc774 \uc900\ube44\ud574\uc57c \ud560 \uac83\uc744 \uc4f0\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.ekH=new B.eB("\ud3c9\uc0dd\ud559\uc2b5\uc774 \ud544\uc694\ud55c \uc774\uc720",A.k_f,"\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uae30\uc220\uacfc \uc0b0\uc5c5 \uad6c\uc870\uac00 \ube60\ub974\uac8c \ubcc0\ud654\ud558\uace0 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud559\uad50\uc5d0\uc11c \ubc30\uc6b4 \uc9c0\uc2dd\ub9cc\uc73c\ub85c \ud3c9\uc0dd \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc77c\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc790\ub3d9\ud654\uc640 \uc778\uacf5\uc9c0\ub2a5\uc758 \ubc1c\uc804\uc73c\ub85c \uc77c\ubd80 \uc5c5\ubb34\ub294 \uc904\uc5b4\ub4dc\ub294 \ubc18\uba74\uc5d0 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ub2e4\ub8e8\ub294 \uc9c1\ubb34\ub294 \uacc4\uc18d \uc0dd\uaca8\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\uc5d0 \ub300\uc751\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc9c1\uc7a5\uc778\ub3c4 \uc7ac\uad50\uc721\uc744 \ud1b5\ud574 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubc30\uc6b0\uace0 \uc790\uc2e0\uc758 \uc9c1\ubb34 \uc5ed\ub7c9\uc744 \uafb8\uc900\ud788 \ub192\uc5ec\uc57c \ud569\ub2c8\ub2e4. \uae30\uc5c5 \uc5ed\uc2dc \uc9c1\uc6d0\uc758 \uad50\uc721\uc744 \ube44\uc6a9\uc73c\ub85c\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \uc7a5\uae30\uc801\uc778 \uacbd\uc7c1\ub825\uc744 \uc704\ud55c \ud22c\uc790\ub85c \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uad6d \ud3c9\uc0dd\ud559\uc2b5\uc740 \uac1c\uc778\uc758 \ucde8\uc5c5\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubcc0\ud654\ud558\ub294 \uc0ac\ud68c\uc5d0 \uc801\uc751\ud558\uae30 \uc704\ud55c \uae30\ubcf8\uc801\uc778 \ub2a5\ub825\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.lEF=s([A.eli,A.ekH],t.Qd)
A.lJt=s(["\uad50\uc721","\ud559\uc2b5","\ud3c9\uc0dd\ud559\uc2b5","\ud559\ub825","\ud559\uc704","\uc9c1\uc5c5 \uad50\uc721","\uc7ac\uad50\uc721","\uc5ed\ub7c9 \uac1c\ubc1c","\uc628\ub77c\uc778 \uad50\uc721","\uad50\uc721 \uaca9\ucc28","\uc0ac\uad50\uc721","\uc790\uae30\uc8fc\ub3c4\ud559\uc2b5","\ube44\ud310\uc801 \uc0ac\uace0","AI \uad50\uc721"],t.s)
A.jVw=s(["-\ub294 \ub370 \uc788\uc5b4\uc11c","-\uc744/\ub97c \ubc14\ud0d5\uc73c\ub85c","-\uae30\ubcf4\ub2e4\ub294","-(\uc73c)\u3139\uc218\ub85d","-\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0","-(\uc73c)\u3141\uc5d0 \ub530\ub77c","-\ub294 \ubc18\uba74\uc5d0","-\ub2e4\uace0 \ud574\uc11c","-\uc9c0 \uc54a\ub294 \ud55c","-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4","-\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub2e4","-\uc744/\ub97c \ud1b5\ud574","-\uace0\uc790 \ud558\ub2e4","-\ub294 \uac00\uc6b4\ub370","-(\uc73c)\u3139 \uac83\uc73c\ub85c \uc804\ub9dd\ub418\ub2e4"],t.s)
A.jl2=s(["\ud559\ub825\uc740 \uc5b4\ub290 \uc218\uc900\uc758 \uad50\uc721\uc744 \ubc1b\uc558\ub294\uc9c0\ub97c \uc758\ubbf8\ud558\uace0 \ud559\uc704\ub294 \ub300\ud559 \ub4f1\uc5d0\uc11c \uc218\uc5ec\ud558\ub294 \ud559\ubb38\uc801 \uc790\uaca9\uc744 \ub9d0\ud55c\ub2e4.","\ud559\ubc8c\uc740 \uac1c\uc778\uc774 \ub098\uc628 \ud559\uad50\uc758 \uc0ac\ud68c\uc801 \ubc30\uacbd\uc774\ub098 \ud3c9\uac00\uc640 \uad00\ub828\ub41c \ud45c\ud604\uc774\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \ud559\ub825\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2e4\uc81c \uc9c1\ubb34 \uc5ed\ub7c9\ub3c4 \uc911\uc694\ud574\uc9c0\uace0 \uc788\ub2e4.","\ud3c9\uc0dd\ud559\uc2b5\uc740 \ud559\uad50\ub97c \uc878\uc5c5\ud55c \ub4a4\uc5d0\ub3c4 \uc9c0\uc18d\uc801\uc73c\ub85c \ubc30\uc6b0\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uae30\uc220 \ubcc0\ud654\uac00 \ube60\ub97c\uc218\ub85d \uc7ac\uad50\uc721\uacfc \uc9c1\ubb34 \uc5ed\ub7c9 \uac1c\ubc1c\uc758 \uc911\uc694\uc131\uc774 \ucee4\uc9c4\ub2e4.","\uc628\ub77c\uc778 \uad50\uc721\uc740 \uc2dc\uac04\uacfc \uc7a5\uc18c\uc758 \uc81c\uc57d\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\ub2e4.","\uad50\uc721 \uaca9\ucc28\ub294 \uc18c\ub4dd, \uc9c0\uc5ed, \uac00\uc815 \ud658\uacbd, \ub514\uc9c0\ud138 \uc811\uadfc\uc131 \ub4f1 \uc5ec\ub7ec \uc694\uc778\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.","\uc790\uae30\uc8fc\ub3c4\ud559\uc2b5 \ub2a5\ub825\uc740 \uc2a4\uc2a4\ub85c \ubaa9\ud45c\ub97c \uc138\uc6b0\uace0 \ud559\uc2b5 \uacfc\uc815\uc744 \uad00\ub9ac\ud558\ub294 \ub2a5\ub825\uc774\ub2e4.","\ube44\ud310\uc801 \uc0ac\uace0\ub294 \uc815\ubcf4\ub97c \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uace0 \uadfc\uac70\uc640 \ub17c\ub9ac\ub97c \uac80\ud1a0\ud558\ub294 \ub2a5\ub825\uc774\ub2e4.","AI \uc2dc\ub300\uc5d0\ub294 \uc9c0\uc2dd\uc744 \uc554\uae30\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\ubcf4\ub97c \ud65c\uc6a9\ud558\uace0 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
A.zN=new B.hV(11,"\uad50\uc721\uacfc \ud3c9\uc0dd\ud559\uc2b5",A.kUk,A.jsY,A.lDt,A.jRG,A.kmW,A.lJ8,A.lfK,A.kWD,A.lEF,A.lJt,A.jVw,A.jl2)
A.kxK=s(["\uc740\ud589, \uc2e0\uc6a9, \uac1c\uc778 \uae08\uc735\uc5d0 \uad00\ud55c \uc911\xb7\uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc608\uae08, \uc801\uae08, \ub300\ucd9c, \ud22c\uc790, \ubcf4\ud5d8\uc758 \ucc28\uc774\ub97c \uad6c\ubcc4\ud55c\ub2e4.","\uae08\ub9ac, \ubd80\ucc44, \uc0c1\ud658 \ub2a5\ub825\uc5d0 \ub300\ud574 \uc815\ud655\ud788 \uc124\uba85\ud55c\ub2e4.","\ub300\ucd9c\uc744 \ubc1b\uae30 \uc804\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uc870\uac74\uc744 \uc810\uac80\ud55c\ub2e4.","\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uae08\uc735 \uc704\ud5d8\uc744 \ud30c\uc545\ud55c\ub2e4.","\uc774\uc0c1 \uac70\ub798\ub97c \ubc1c\uacac\ud588\uc744 \ub54c\uc758 \ub300\uc751 \uc808\ucc28\ub97c \uc775\ud78c\ub2e4.","\ubcf4\uc774\uc2a4\ud53c\uc2f1\uacfc \uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\ub294 \ubc29\ubc95\uc744 \uc775\ud78c\ub2e4.","\uae08\uc735 \ubb38\uc81c\uc758 \uc6d0\uc778\uacfc \uacb0\uacfc\ub97c \ub17c\ub9ac\uc801\uc73c\ub85c \uc124\uba85\ud55c\ub2e4.","\ud22c\uc790 \uc218\uc775\uacfc \uc704\ud5d8\uc744 \uae30\uc900\uc5d0 \ub530\ub77c \ube44\uad50\ud55c\ub2e4.","\uae34\uae09 \uc0c1\ud669\uc5d0 \ub300\ube44\ud55c \ube44\uc0c1 \uc790\uae08 \uacc4\ud68d\uc744 \uc138\uc6b4\ub2e4.","\uc9c0\ucd9c\uc744 \uad00\ub9ac\ud558\uace0 \uacfc\ub3c4\ud55c \ubd80\ucc44\ub97c \ud53c\ud558\ub294 \ubc29\ubc95\uc744 \uc775\ud78c\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uc740\ud589\uacfc \uc815\ud655\ud558\uac8c \uc0c1\ub2f4\ud55c\ub2e4.","\uae08\uc735 \uacc4\uc57d\uc11c\uc5d0 \uc790\uc8fc \ub098\uc624\ub294 \uc8fc\uc694 \ud45c\ud604\uc744 \uc774\ud574\ud55c\ub2e4.","\uc548\uc804\ud55c \uae08\uc735 \uc120\ud0dd\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4.","\uae08\uc735 \uc704\ud5d8 \uad00\ub9ac\ub97c \uc8fc\uc81c\ub85c \uae00\uc744 \uc4f0\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."],t.s)
A.dH0=new B.h("\uae08\uc735 \uc9c0\uc2dd\uc744 \uac16\ucd94\uba74 \ud569\ub9ac\uc801\uc778 \uacbd\uc81c \uacb0\uc815\uc744 \ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","C\xf3 ki\u1ebfn th\u1ee9c t\xe0i ch\xednh gi\xfap \u0111\u01b0a ra quy\u1ebft \u0111\u1ecbnh kinh t\u1ebf h\u1ee3p l\xfd.")
A.km0=s([A.dH0],t.T)
A.ejO=new B.i("\uae08\uc735","T\xe0i ch\xednh","\uba85\uc0ac",A.km0,A.a,A.a)
A.dz5=new B.h("\ub300\ucd9c\uc744 \uc2e0\uccad\ud558\uae30 \uc804\uc5d0 \uc5ec\ub7ec \uae08\uc735\uae30\uad00\uc758 \uc870\uac74\uc744 \ube44\uad50\ud588\uc2b5\ub2c8\ub2e4.","Tr\u01b0\u1edbc khi \u0111\u0103ng k\xfd vay, t\xf4i \u0111\xe3 so s\xe1nh \u0111i\u1ec1u ki\u1ec7n c\u1ee7a nhi\u1ec1u t\u1ed5 ch\u1ee9c t\xe0i ch\xednh.")
