A.jET=s(["\ud575\uc2ec \uacfc\uc81c","\uc790\ub8cc","\uc6d0\uc778","\uc601\ud5a5","\uc704\ud5d8 \uc694\uc18c","\ub300\uc751 \uc804\ub7b5"],t.s)
A.dZX=new B.dr("\ud68c\uc0ac\uc5d0\uc11c \ubcf5\uc7a1\ud55c \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcf4\uace0\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\uae4c?",A.jET,"\ubcf5\uc7a1\ud55c \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c\ub294 \ub2e8\uc21c\ud788 \ubb38\uc81c\uac00 \uc788\ub2e4\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \ud575\uc2ec \uacfc\uc81c\uac00 \ubb34\uc5c7\uc778\uc9c0 \uba3c\uc800 \uc815\ub9ac\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uad00\ub828 \uc790\ub8cc\uc640 \ud604\uc7a5 \uc758\uacac\uc744 \ubc14\ud0d5\uc73c\ub85c \uc6d0\uc778\uc744 \ubd84\uc11d\ud558\uace0, \uc0dd\uc0b0\uc774\ub098 \ube44\uc6a9\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub294\uc9c0 \uc124\uba85\ud574\uc57c \ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub2e8\uae30 \ub300\ucc45\uacfc \uc7a5\uae30 \ub300\ucc45\uc744 \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\uba74 \ub354 \uc124\ub4dd\ub825 \uc788\ub294 \ubcf4\uace0\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.jCk=s(["\ucd08\uae30 \ube44\uc6a9","\uc6b4\uc601 \ube44\uc6a9","\uac1c\uc120 \ud6a8\uacfc","\ud68c\uc218 \uae30\uac04","\uc704\ud5d8 \uc694\uc18c","\uc2dc\uc2a4\ud15c \uc548\uc815\uc131"],t.s)
A.dZW=new B.dr("\uc0c8\ub85c\uc6b4 \uae30\uc220\uc774\ub098 \uc124\ube44\uc5d0 \ud22c\uc790\ud560 \ub54c \uc5b4\ub5a4 \uc810\uc744 \uace0\ub824\ud574\uc57c \ud569\ub2c8\uae4c?",A.jCk,"\uc0c8\ub85c\uc6b4 \uae30\uc220\uc774\ub098 \uc124\ube44\uc5d0 \ud22c\uc790\ud560 \ub54c\ub294 \uc608\uc0c1\ub418\ub294 \uac1c\uc120 \ud6a8\uacfc\ub9cc \ubcf4\uba74 \uc548 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ucd08\uae30 \ube44\uc6a9\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc778 \uc6b4\uc601 \ube44\uc6a9\uacfc \uc720\uc9c0 \ube44\uc6a9\ub3c4 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \ud22c\uc790\uae08\uc744 \ud68c\uc218\ud558\ub294 \ub370 \uc5bc\ub9c8\ub098 \uac78\ub9ac\ub294\uc9c0, \uc2dc\uc2a4\ud15c \uc548\uc815\uc131\uc5d0\ub294 \ubb38\uc81c\uac00 \uc5c6\ub294\uc9c0, \uae30\uc874 \uc9c1\uc6d0\uc758 \uc5c5\ubb34 \ubd80\ub2f4\uc740 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0\ub3c4 \ud568\uaed8 \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.kO1=s(["\ub370\uc774\ud130 \uae30\ubc18","\ud604\uc7a5 \uacbd\ud5d8","\uc885\ud569 \ud310\ub2e8","\uc758\uc0ac\uacb0\uc815 \uccb4\uacc4","\ud55c\uacc4","\uc2e4\ud589\ub825"],t.s)
A.dZx=new B.dr("\uc88b\uc740 \uc758\uc0ac\uacb0\uc815\uc744 \uc704\ud574 \ub370\uc774\ud130\uc640 \ud604\uc7a5 \uacbd\ud5d8 \uc911 \ubb34\uc5c7\uc774 \ub354 \uc911\uc694\ud569\ub2c8\uae4c?",A.kO1,"\uc800\ub294 \ub370\uc774\ud130\uc640 \ud604\uc7a5 \uacbd\ud5d8 \uc911 \ud558\ub098\ub9cc \uc120\ud0dd\ud558\uae30\ubcf4\ub2e4 \ub450 \uac00\uc9c0\ub97c \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\ub294 \ubb38\uc81c\ub97c \uac1d\uad00\uc801\uc73c\ub85c \ud30c\uc545\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \ud604\uc7a5\uc758 \uad6c\uccb4\uc801\uc778 \uc0c1\ud669\uc744 \ubaa8\ub450 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \ubabb\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \ud604\uc7a5 \uacbd\ud5d8\uc740 \ud604\uc2e4\uc801\uc778 \ud310\ub2e8\uc5d0 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uac1c\uc778\uc758 \ub290\ub08c\uc5d0 \uce58\uc6b0\uce60 \uc704\ud5d8\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub370\uc774\ud130\uc640 \ud604\uc7a5 \uc758\uacac\uc744 \uc885\ud569\ud574 \ud310\ub2e8\ud560 \uc218 \uc788\ub294 \uc758\uc0ac\uacb0\uc815 \uccb4\uacc4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.ksy=s([A.dZX,A.dZW,A.dZx],t.Gu)
A.k62=s(["\ubcf5\uc7a1\ud55c \uacbd\uc601 \ubb38\uc81c\uac00 \uc0dd\uae30\ub294 \uc774\uc720\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc790\ub8cc\uc640 \ud604\uc7a5 \uc758\uacac\uc758 \uc911\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\ub2e8\uae30 \ub300\ucc45\uacfc \uc7a5\uae30 \ub300\ucc45\uc744 \uad6c\ubd84\ud558\uc138\uc694.","\ube44\uc6a9\uacfc \uc704\ud5d8 \uc694\uc18c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc885\ud569\uc801 \ud310\ub2e8\uc758 \ud544\uc694\uc131\uc744 \uc81c\uc2dc\ud558\uc138\uc694."],t.s)
A.eld=new B.eB("\uae30\uc5c5\uc774 \ubcf5\uc7a1\ud55c \uacbd\uc601 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\ubc95",A.k62,"\uae30\uc5c5\uc774 \uc9c1\uba74\ud558\ub294 \uacbd\uc601 \ubb38\uc81c\ub294 \ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc6d0\uac00 \uc0c1\uc2b9, \uc778\ub825 \ubd80\uc871, \uae30\uc220 \ubcc0\ud654, \uc18c\ube44 \uc2dc\uc7a5 \ubcc0\ud654\uac00 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub098\uba74 \ub2e8\uc21c\ud55c \ub300\ucc45\ub9cc\uc73c\ub85c\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uae30\uc5c5\uc740 \uba3c\uc800 \uac1d\uad00\uc801\uc778 \uc790\ub8cc\ub97c \ubc14\ud0d5\uc73c\ub85c \ud575\uc2ec \uacfc\uc81c\ub97c \ud30c\uc545\ud558\uace0 \ud604\uc7a5 \uc758\uacac\uc744 \ud1b5\ud574 \uc2e4\uc81c \uc0c1\ud669\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uc0dd\uc0b0 \ucc28\uc9c8\uacfc \ube44\uc6a9 \ubd80\ub2f4\uc744 \uc904\uc774\ub294 \ub300\ucc45\uc774 \ud544\uc694\ud558\uace0 \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \uae30\uc220 \ub3c4\uc785, \uc9c1\uc6d0 \uc7ac\uad50\uc721, \uc218\uc775 \uad6c\uc870 \uac1c\uc120\uacfc \uac19\uc740 \uc804\ub7b5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \ub610\ud55c \uc0c8\ub85c\uc6b4 \ud22c\uc790\ub97c \uacb0\uc815\ud560 \ub54c\ub294 \uc608\uc0c1 \ud6a8\uacfc\ubfd0\ub9cc \uc544\ub2c8\ub77c \ucd08\uae30 \ube44\uc6a9, \uc6b4\uc601 \ube44\uc6a9, \uc704\ud5d8 \uc694\uc18c\ub3c4 \ud568\uaed8 \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4. \uacb0\uad6d \ubcf5\uc7a1\ud55c \ubb38\uc81c\uc77c\uc218\ub85d \uc5ec\ub7ec \uc694\uc18c\ub97c \uc885\ud569\uc801\uc73c\ub85c \ud310\ub2e8\ud558\uace0 \uc2e4\ud589 \uac00\ub2a5\ud55c \ub300\uc548\uc744 \ub9c8\ub828\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.ka9=s(["\ub370\uc774\ud130 \uae30\ubc18 \uc758\uc0ac\uacb0\uc815\uc758 \uc758\ubbf8\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc7a5\uc810\uc744 \uc4f0\uc138\uc694.","\ud55c\uacc4\uc810\uc744 \uc124\uba85\ud558\uc138\uc694.","\ud604\uc7a5 \uacbd\ud5d8\uacfc\uc758 \uad00\uacc4\ub97c \uc4f0\uc138\uc694.","\ubc14\ub78c\uc9c1\ud55c \ud65c\uc6a9 \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.elh=new B.eB("\ub370\uc774\ud130 \uae30\ubc18 \uc758\uc0ac\uacb0\uc815\uc758 \uc7a5\uc810\uacfc \ud55c\uacc4",A.ka9,"\ub370\uc774\ud130 \uae30\ubc18 \uc758\uc0ac\uacb0\uc815\uc740 \uac1c\uc778\uc758 \ub290\ub08c\uc774\ub098 \uacbd\ud5d8\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \uac1d\uad00\uc801\uc778 \uc790\ub8cc\uc640 \uc218\uce58\ub97c \ud65c\uc6a9\ud574 \ud310\ub2e8\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubc29\uc2dd\uc740 \ubb38\uc81c\uc758 \uc6d0\uc778\uc744 \ub354 \uc815\ud655\ud558\uac8c \ud30c\uc545\ud558\uace0 \uc815\ucc45\uc774\ub098 \uc804\ub7b5\uc758 \ud6a8\uacfc\ub97c \ube44\uad50\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc0dd\uc0b0 \ud604\uc7a5\uc5d0\uc11c\ub294 \ubd88\ub7c9\ub960, \uc0dd\uc0b0\uc131, \ube44\uc6a9 \uc790\ub8cc\ub97c \ubd84\uc11d\ud574 \uac1c\uc120 \ubc29\ud5a5\uc744 \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub370\uc774\ud130\uac00 \ud56d\uc0c1 \ubaa8\ub4e0 \ud604\uc2e4\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc870\uc0ac \uae30\uc900\uc774 \ubd80\uc815\ud655\ud558\uac70\ub098 \ud604\uc7a5\uc758 \ud2b9\uc218\ud55c \uc0c1\ud669\uc774 \ubc18\uc601\ub418\uc9c0 \uc54a\uc73c\uba74 \uc798\ubabb\ub41c \uacb0\ub860\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub370\uc774\ud130\ub294 \uc911\uc694\ud55c \ud310\ub2e8 \uadfc\uac70\ub85c \ud65c\uc6a9\ud558\ub418 \ud604\uc7a5 \uacbd\ud5d8\uacfc \uc774\ud574\uad00\uacc4\uc790\uc758 \uc758\uacac\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uc2e4\uc81c \uacbd\ud5d8\uc744 \uc885\ud569\ud560 \ub54c \ub354 \ud604\uc2e4\uc801\uc774\uace0 \uc2e4\ud589 \uac00\ub2a5\ud55c \uacb0\uc815\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.jxM=s([A.eld,A.elh],t.Qd)
