A.dZR=new B.dr("\uc9c1\uc7a5\uc5d0\uc11c \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574 \ubb34\uc5c7\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.ltc,"\uc9c1\uc7a5\uc5d0\uc11c \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uadfc\ub85c\uacc4\uc57d\uc11c\uc640 \ud68c\uc0ac \uaddc\uc815\uc744 \uc815\ud655\ud788 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae09\uc5ec\uc640 \uadfc\ub85c\uc2dc\uac04 \uac19\uc740 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uac00\ub2a5\ud55c \ud55c \ubb38\uc11c\ub85c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\ub294 \uac10\uc815\uc801\uc73c\ub85c \ub300\uc751\ud558\uae30\ubcf4\ub2e4 \uad00\ub828 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uc0c1\ub2f4 \uae30\uad00\uc744 \ud1b5\ud574 \ud574\uacb0 \ubc29\ubc95\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.kaa=s(["\uc0ac\uc0dd\ud65c","\uae08\uc735 \uc0ac\uae30","\ub3d9\uc758","\uc628\ub77c\uc778","\uc815\ubcf4 \uc720\ucd9c","\ud53c\ud574"],t.s)
A.dZE=new B.dr("\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.kaa,"\uac1c\uc778\uc815\ubcf4\uc5d0\ub294 \uc774\ub984\uacfc \uc5f0\ub77d\ucc98\ubfd0\ub9cc \uc544\ub2c8\ub77c \uae08\uc735 \uc815\ubcf4\ub098 \uc704\uce58 \uc815\ubcf4\ucc98\ub7fc \ubbfc\uac10\ud55c \uc815\ubcf4\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc815\ubcf4\uac00 \ubcf8\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uc720\ucd9c\ub418\uba74 \uae08\uc735 \uc0ac\uae30\ub098 \uc0ac\uc0dd\ud65c \uce68\ud574\uc640 \uac19\uc740 \ud53c\ud574\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud560 \ub54c \uc5b4\ub5a4 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294\uc9c0 \ud655\uc778\ud558\uace0 \ube44\ubc00\ubc88\ud638\ub098 \uc778\uc99d \uc815\ubcf4\ub3c4 \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.kLG=s(["\ud611\uc758","\ud569\uc758","\uc870\uc815","\uc0c1\ub2f4","\uc790\ub8cc","\uacc4\uc57d"],t.s)
A.dZO=new B.dr("\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud588\uc744 \ub54c \uc18c\uc1a1 \uc804\uc5d0 \uc5b4\ub5a4 \ubc29\ubc95\uc744 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\uc2b5\ub2c8\uae4c?",A.kLG,"\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud588\ub2e4\uace0 \ud574\uc11c \ubc14\ub85c \uc18c\uc1a1\uc744 \ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uba3c\uc800 \uacc4\uc57d\uc11c\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ud655\uc778\ud558\uace0 \uc0c1\ub300\ubc29\uacfc \uc0ac\uc2e4 \uad00\uacc4\ub97c \uc815\ub9ac\ud574 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2f9\uc0ac\uc790\ub07c\ub9ac \ud574\uacb0\ud558\uae30 \uc5b4\ub835\ub2e4\uba74 \uc0c1\ub2f4\uc774\ub098 \uc870\uc815 \uc808\ucc28\ub97c \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\ub3c4 \uac80\ud1a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc0c1\ud669\uc5d0 \ub530\ub77c \uc801\uc808\ud55c \uc808\ucc28\uac00 \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c \ud544\uc694\ud55c \uacbd\uc6b0 \uc804\ubb38\uc801\uc778 \ub3c4\uc6c0\uc744 \ubc1b\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.jk0=s([A.dZR,A.dZE,A.dZO],t.Gu)
A.jrW=s(["\uadfc\ub85c\uc790\uc758 \uae30\ubcf8\uc801\uc778 \uad8c\ub9ac\ub97c \uc124\uba85\ud558\uc138\uc694.","\uadfc\ub85c\uacc4\uc57d\uc758 \uc911\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\ub294 \uc6d0\uc778\uc744 \uc124\uba85\ud558\uc138\uc694.","\uadfc\ub85c\uc790\uac00 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc4f0\uc138\uc694.","\uae30\uc5c5\uacfc \uc0ac\ud68c\uc758 \uc5ed\ud560\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.ekY=new B.eB("\uc9c1\uc7a5\uc778\uc758 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \uac83",A.jrW,"\uadfc\ub85c\uc790\ub294 \uc815\ub2f9\ud55c \uc784\uae08\uc744 \ubc1b\uace0 \uc548\uc804\ud55c \ud658\uacbd\uc5d0\uc11c \uc77c\ud560 \uc218 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uc704\ud574\uc11c\ub294 \uadfc\ubb34\ub97c \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uc784\uae08, \uadfc\ub85c\uc2dc\uac04, \ub2f4\ub2f9 \uc5c5\ubb34 \ub4f1 \uc911\uc694\ud55c \uadfc\ub85c\uc870\uac74\uc744 \ud655\uc778\ud558\uace0 \uacc4\uc57d \ub0b4\uc6a9\uc744 \ubb38\uc11c\ub85c \ub0a8\uae30\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \uc0ac\uc2e4\uc744 \ud655\uc778\ud560 \uc790\ub8cc\uac00 \uc5c6\ub2e4\uba74 \uc790\uc2e0\uc758 \uc0c1\ud669\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadfc\ub85c\uc790\ub3c4 \uacc4\uc57d\uc11c\uc640 \uae09\uc5ec \uc790\ub8cc, \uadfc\ubb34 \uae30\ub85d \ub4f1\uc744 \uc798 \ubcf4\uad00\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc5c5 \uc5ed\uc2dc \uad00\ub828 \uaddc\uc815\uc744 \uc900\uc218\ud558\uace0 \uc9c1\uc6d0\uc774 \ubb38\uc81c\ub97c \uc81c\uae30\ud560 \uc218 \uc788\ub294 \ud22c\uba85\ud55c \uc808\ucc28\ub97c \ub9c8\ub828\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.l6c=s(["\uac1c\uc778\uc815\ubcf4\uc758 \uc758\ubbf8\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc815\ubcf4 \uc720\ucd9c\ub85c \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uac1c\uc778\uc774 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \uc124\uba85\ud558\uc138\uc694.","\uae30\uc5c5\uc758 \ucc45\uc784\uc744 \uc4f0\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.ekQ=new B.eB("\ub514\uc9c0\ud138 \uc0ac\ud68c\uc5d0\uc11c \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uc758 \uc911\uc694\uc131",A.l6c,"\ub514\uc9c0\ud138 \uc11c\ube44\uc2a4\uac00 \ud655\ub300\ub418\uba74\uc11c \uac1c\uc778\uc774 \uc628\ub77c\uc778\uc5d0 \uc81c\uacf5\ud558\ub294 \uc815\ubcf4\ub3c4 \ud06c\uac8c \ub298\uc5b4\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc815\ubcf4\uac00 \ubd80\uc801\uc808\ud558\uac8c \uc720\ucd9c\ub418\uba74 \uae08\uc735 \uc0ac\uae30\ub098 \uc0ac\uc0dd\ud65c \uce68\ud574 \ub4f1 \ub2e4\uc591\ud55c \ud53c\ud574\uac00 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac1c\uc778\uc740 \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \uc815\ubcf4\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud558\uace0 \ucd9c\ucc98\uac00 \ubd88\ubd84\uba85\ud55c \ub9c1\ud06c\ub098 \uc5f0\ub77d\uc5d0 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \uae30\uc5c5\ub3c4 \ud544\uc694\ud55c \ubc94\uc704\uc5d0\uc11c\ub9cc \uc815\ubcf4\ub97c \uc218\uc9d1\ud558\uace0 \uc774\uc6a9 \ubaa9\uc801\uacfc \ubcf4\uad00 \ubc29\ubc95\uc744 \uba85\ud655\ud558\uac8c \uc548\ub0b4\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ub294 \uac1c\uc778\ub9cc\uc758 \ucc45\uc784\uc774 \uc544\ub2c8\ub77c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub294 \uae30\uc5c5\uacfc \uc0ac\ud68c\uac00 \ud568\uaed8 \uad00\ub9ac\ud574\uc57c \ud560 \ubb38\uc81c\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
