A.dZJ=new B.dr("\uc6d4\uae09\uc744 \ubc1b\uc73c\uba74 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.lDf,"\uc6d4\uae09\uc744 \ubc1b\uc73c\uba74 \uba3c\uc800 \uc6d4\uc138\ub098 \ubcf4\ud5d8\ub8cc \uac19\uc740 \uace0\uc815 \uc9c0\ucd9c\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc815\ud558\uace0 \uc77c\uc815 \uae08\uc561\uc740 \uc800\ucd95\uacfc \ube44\uc0c1\uae08\uc73c\ub85c \ub530\ub85c \uad00\ub9ac\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \ub0a8\uc740 \ub3c8\uc744 \ubaa8\ub450 \uc18c\ube44\ud558\uae30\ubcf4\ub2e4\ub294 \uc7a5\uae30\uc801\uc778 \ubaa9\ud45c\ub97c \uc704\ud574 \uacc4\ud68d\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.l9F=s(["\uae08\ub9ac","\uc0c1\ud658 \uae30\uac04","\uc6d0\uae08","\uc774\uc790","\uc18c\ub4dd","\uc0c1\ud658 \ub2a5\ub825"],t.s)
A.dZy=new B.dr("\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c \ubb34\uc5c7\uc744 \uac00\uc7a5 \uc911\uc694\ud558\uac8c \ud655\uc778\ud574\uc57c \ud569\ub2c8\uae4c?",A.l9F,"\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c\ub294 \ub2e8\uc21c\ud788 \ub300\ucd9c \ud55c\ub3c4\ub9cc \ubcf4\uba74 \uc548 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud604\uc7ac \uc18c\ub4dd\uc73c\ub85c \ub9e4\ub2ec \uc6d0\uae08\uacfc \uc774\uc790\ub97c \uc548\uc815\uc801\uc73c\ub85c \uac1a\uc744 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae08\ub9ac\uac00 \uc624\ub97c \uacbd\uc6b0 \uc0c1\ud658 \ubd80\ub2f4\uc774 \uc5bc\ub9c8\ub098 \ucee4\uc9c8 \uc218 \uc788\ub294\uc9c0\ub3c4 \ubbf8\ub9ac \uacc4\uc0b0\ud574 \ubcf4\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.lqY=s(["\uc548\uc815\uc131","\uc218\uc775\ub960","\uc704\ud5d8","\ube44\uc0c1\uae08","\uc7a5\uae30 \ubaa9\ud45c"],t.s)
A.dZN=new B.dr("\uc800\ucd95\uacfc \ud22c\uc790 \uc911 \uc5b4\ub290 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.lqY,"\uc800\ucd95\uacfc \ud22c\uc790\ub294 \ubaa9\uc801\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub290 \ud558\ub098\ub9cc \uc911\uc694\ud558\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud560 \ube44\uc0c1\uae08\uc740 \ube44\uad50\uc801 \uc548\uc804\ud55c \ubc29\uc2dd\uc73c\ub85c \ubcf4\uad00\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc7a5\uae30\uc801\uc778 \uc790\uc0b0 \ud615\uc131\uc744 \uc704\ud574\uc11c\ub294 \uc790\uc2e0\uc758 \uc704\ud5d8 \uac10\uc218 \uc218\uc900\uc5d0 \ub9de\ub294 \ud22c\uc790\ub3c4 \uace0\ub824\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.jJQ=s([A.dZJ,A.dZy,A.dZN],t.Gu)
A.lzT=s(["\uc18c\ub4dd\uacfc \uc9c0\ucd9c \uad00\ub9ac \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uc800\ucd95\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubd80\ucc44 \uad00\ub9ac \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ube44\uc0c1\uae08\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.ekM=new B.eB("\ud569\ub9ac\uc801\uc778 \uac00\uacc4 \uc7ac\uc815 \uad00\ub9ac \ubc29\ubc95",A.lzT,"\uc548\uc815\uc801\uc778 \uac00\uacc4 \uc7ac\uc815\uc744 \uc720\uc9c0\ud558\ub824\uba74 \uba3c\uc800 \ub9e4\ub2ec \ubc1c\uc0dd\ud558\ub294 \uc18c\ub4dd\uacfc \uc9c0\ucd9c\uc744 \uc815\ud655\ud788 \ud30c\uc545\ud574\uc57c \ud569\ub2c8\ub2e4. \uc6d4\uc138\uc640 \ubcf4\ud5d8\ub8cc \uac19\uc740 \uace0\uc815 \uc9c0\ucd9c\uc744 \ud655\uc778\ud55c \ud6c4 \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc815\ud558\uace0 \ubd88\ud544\uc694\ud55c \uc18c\ube44\ub97c \uc904\uc77c \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c8\ubcd1\uc774\ub098 \uc2e4\uc9c1\uc5d0 \ub300\ube44\ud560 \uc218 \uc788\ub3c4\ub85d \uc77c\uc815\ud55c \ube44\uc0c1\uae08\uc744 \ub9c8\ub828\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \ub300\ucd9c\uc774 \uc788\ub2e4\uba74 \ub192\uc740 \uc218\uc775\uc744 \uae30\ub300\ud558\uba70 \ubb34\ub9ac\ud558\uac8c \ud22c\uc790\ud558\uae30\ubcf4\ub2e4 \uc548\uc815\uc801\uc73c\ub85c \ubd80\ucc44\ub97c \uc0c1\ud658\ud560 \uc218 \uc788\ub294 \uacc4\ud68d\uc744 \uc6b0\uc120 \uc138\uc6cc\uc57c \ud569\ub2c8\ub2e4.")
A.kf4=s(["\uac00\uacc4 \ubd80\ucc44 \uc99d\uac00 \ud604\uc0c1\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc8fc\ud0dd \uac00\uaca9\uacfc \ub300\ucd9c\uc758 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uae08\ub9ac \uc0c1\uc2b9 \uc2dc \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uac00\uacc4\uc640 \uacbd\uc81c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\ub300\ucc45\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.el0=new B.eB("\uac00\uacc4 \ubd80\ucc44 \uc99d\uac00\uc758 \uc6d0\uc778\uacfc \uc601\ud5a5",A.kf4,"\uac00\uacc4 \ubd80\ucc44\ub294 \uc8fc\ud0dd \uad6c\uc785\uacfc \uc0dd\ud65c\ube44, \uac01\uc885 \uc18c\ube44\ub97c \uc704\ud574 \ub300\ucd9c\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc99d\uac00\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc8fc\ud0dd \uac00\uaca9\uc774 \uc18c\ub4dd\ubcf4\ub2e4 \ube60\ub974\uac8c \uc0c1\uc2b9\ud558\uba74 \ub9ce\uc740 \uac00\uad6c\uac00 \ud070 \uaddc\ubaa8\uc758 \ub300\ucd9c\uc744 \uc774\uc6a9\ud558\uac8c \ub429\ub2c8\ub2e4. \uae08\ub9ac\uac00 \ub0ae\uc744 \ub54c\ub294 \uc0c1\ud658 \ubd80\ub2f4\uc774 \ube44\uad50\uc801 \uc791\uc744 \uc218 \uc788\uc9c0\ub9cc \uae08\ub9ac\uac00 \uc0c1\uc2b9\ud558\uba74 \ub9e4\ub2ec \ub0b4\uc57c \ud558\ub294 \uc774\uc790\uac00 \ud06c\uac8c \ub298\uc5b4\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uacc4\uac00 \uc18c\ub4dd\uc758 \ub9ce\uc740 \ubd80\ubd84\uc744 \ub300\ucd9c \uc0c1\ud658\uc5d0 \uc0ac\uc6a9\ud558\uba74 \uc18c\ube44 \uc5ec\ub825\uc774 \uc904\uc5b4 \uacbd\uc81c \uc804\uccb4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac1c\uc778\uc740 \uc790\uc2e0\uc758 \uc0c1\ud658 \ub2a5\ub825\uc744 \uace0\ub824\ud574 \ub300\ucd9c \uaddc\ubaa8\ub97c \uacb0\uc815\ud558\uace0 \uc7a5\uae30\uc801\uc778 \uc7ac\uc815 \uacc4\ud68d\uc744 \uc138\uc6b8 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.juR=s([A.ekM,A.el0],t.Qd)
