A.jGM=s(["-\ub294 \ub370 \ube44\ud574","-(\uc73c)\u3139\uc218\ub85d","-\uc5d0 \ub530\ub77c","-\uc744/\ub97c \uac10\uc548\ud558\uba74","-\uc9c0 \uc54a\ub294 \ud55c","-(\uc73c)\u3139 \uc6b0\ub824\uac00 \uc788\ub2e4","-\ub294 \uc148\uc774\ub2e4","-\uae30\ub294 \ud558\uc9c0\ub9cc","-\ub294 \ubc18\uba74\uc5d0","-\uae30 \ub9c8\ub828\uc774\ub2e4","-\uc5d0 \ube44\ucd94\uc5b4 \ubcfc \ub54c","-\uc744/\ub97c \ud1a0\ub300\ub85c","-\ub294 \uac00\uc6b4\ub370","-(\uc73c)\u3141\uc73c\ub85c\uc368","-\uace0\uc790 \ud558\ub2e4"],t.s)
A.lGu=s(["\uc18c\ub4dd\uc740 \uc77c\uc815 \uae30\uac04 \ubc8c\uc5b4\ub4e4\uc778 \uacbd\uc81c\uc801 \uc218\uc785\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uc9c0\ucd9c\uc740 \uc0ac\uc6a9\ud55c \ub3c8 \uc804\uccb4\ub97c \ub9d0\ud558\uba70 \uc18c\ube44\ub294 \uc0c1\ud488\uc774\ub098 \uc11c\ube44\uc2a4\ub97c \uad6c\ub9e4\ud558\uc5ec \uc0ac\uc6a9\ud558\ub294 \ud589\uc704\ub97c \uac15\uc870\ud55c\ub2e4.","\uc608\uae08\uc740 \ubaa9\ub3c8\uc744 \ub9e1\uae30\ub294 \ubc29\uc2dd\uc774 \ub9ce\uace0 \uc801\uae08\uc740 \uc77c\uc815 \uae08\uc561\uc744 \uc815\uae30\uc801\uc73c\ub85c \ub123\ub294 \ubc29\uc2dd\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.","\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c\ub294 \uae08\ub9ac\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0c1\ud658 \uae30\uac04\uacfc \ucd1d\uc774\uc790\ub3c4 \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\uc2e0\uc6a9\uc810\uc218\ub294 \uae08\uc735 \uac70\ub798 \uc774\ub825\uacfc \uc0c1\ud658 \uc0c1\ud0dc \ub4f1\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.","\uc790\uc0b0\uc5d0\uc11c \ubd80\ucc44\ub97c \ube7c\uba74 \uc21c\uc790\uc0b0\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub2e4.","\uc218\uc775\ub960\uc774 \ub192\uc744\uc218\ub85d \uc77c\ubc18\uc801\uc73c\ub85c \ub354 \ud070 \uc704\ud5d8\uc744 \ub3d9\ubc18\ud560 \uac00\ub2a5\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4.","\ubb3c\uac00\uac00 \uc624\ub974\uba74 \uac19\uc740 \ub3c8\uc73c\ub85c \uc0b4 \uc218 \uc788\ub294 \uc0c1\ud488\uc758 \uc591\uc774 \uc904\uc5b4 \uad6c\ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\ub2e4.","\ube44\uc0c1\uae08\uc740 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud558\uae30 \uc704\ud55c \uc790\uae08\uc774\ub2e4.","\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\uae30 \uc704\ud574 \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \ubc88\ud638\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc54c\ub824 \uc8fc\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4."],t.s)
A.zU=new B.hV(9,"\uae08\uc735 \uc0dd\ud65c\uacfc \uac00\uacc4 \uacbd\uc81c",A.joy,A.lTW,A.jyI,A.kBO,A.jB6,A.kyE,A.lcN,A.jJQ,A.juR,A.lsW,A.jGM,A.lGu)
A.lIz=s(["HANNEST 5 \uc218\uc900\uc5d0\uc11c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud1a0\ub860\ud558\ub294 \ubc29\ubc95\uc744 \uc885\ud569\uc801\uc73c\ub85c \ubcf5\uc2b5\ud55c\ub2e4.","\uc6d0\uc778, \uc601\ud5a5, \ud574\uacb0\ucc45\uc744 \ubd84\uc11d\ud558\ub294 \ub370 \ud544\uc694\ud55c \uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\ud604\uc0c1, \uc6d0\uc778, \uacb0\uacfc, \ud574\uacb0\ucc45\uc758 \ub17c\ub9ac\uc801 \uad6c\uc870\ub85c \ubb38\uc81c\ub97c \uc124\uba85\ud55c\ub2e4.","\uac1c\uc778\uc758 \uad00\uc810\uacfc \uc0ac\ud68c\uc801 \uad00\uc810\uc744 \ube44\uad50\ud558\uc5ec \uc81c\uc2dc\ud55c\ub2e4.","\uac10\uc815\uc801\uc778 \uc8fc\uc7a5\ubcf4\ub2e4 \uadfc\uac70\uc5d0 \uae30\ubc18\ud55c \ub17c\ub9ac\ub97c \uc804\uac1c\ud55c\ub2e4.","\uc815\ucc45\uc758 \ud6a8\uacfc, \ud55c\uacc4, \uc9c0\uc18d \uac00\ub2a5\uc131\uc744 \uc124\uba85\ud55c\ub2e4.","\uc778\uad6c, \ub178\ub3d9, \ubcf5\uc9c0, \uae30\uc220, \ud658\uacbd, \uc18c\ube44 \uc8fc\uc81c\ub97c \uc11c\ub85c \uc5f0\uacb0\ud55c\ub2e4.","\uc815\ucc45\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uade0\ud615 \uc788\uac8c \uc81c\uc2dc\ud55c\ub2e4.","\ud1a0\ub860\uc5d0\uc11c \uc0c1\ub300\ub97c \uc874\uc911\ud558\uba74\uc11c \ubc18\ub860\uc744 \uc81c\uae30\ud55c\ub2e4.","\uad6c\uccb4\uc801\uc778 \ud604\uc2e4 \uc0ac\ub840\ub97c \ud65c\uc6a9\ud558\uc5ec \uc8fc\uc7a5\uc758 \uc124\ub4dd\ub825\uc744 \ub192\uc778\ub2e4.","\uc0ac\ud68c\uc801 \ud569\uc758\uc640 \uc774\ud574\uad00\uacc4 \ucda9\ub3cc\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uac1c\uc778, \uae30\uc5c5, \uc815\ubd80\uc758 \ucc45\uc784\uc744 \uad6c\ubd84\ud558\uc5ec \uc124\uba85\ud55c\ub2e4.","\ub2e8\uae30 \ud574\uacb0\ucc45\uacfc \uc7a5\uae30 \ud574\uacb0\ucc45\uc744 \ub098\ub204\uc5b4 \uc81c\uc2dc\ud55c\ub2e4.","\uc11c\ub860, \ubcf8\ub860, \uacb0\ub860\uc744 \uac16\ucd98 \uace0\uae09 TOPIK \ubb38\ub2e8\uc744 \uc791\uc131\ud55c\ub2e4.","\uc0ac\ud68c \ubb38\uc81c\uc5d0 \uad00\ud55c \uba74\uc811 \ub2f5\ubcc0, \ud1a0\ub860, \ub17c\uc220\uc744 \uc885\ud569\uc801\uc73c\ub85c \uc5f0\uc2b5\ud55c\ub2e4.","5\ub2e8\uacc4 \uc804\uccb4\ub97c \ubcf5\uc2b5\ud560 \uc218 \uc788\ub294 \uc885\ud569 \ud559\uc2b5\uc73c\ub85c HANNEST 5\ub97c \ub9c8\ubb34\ub9ac\ud55c\ub2e4."],t.s)
A.dDB=new B.h("\ubcf5\uc7a1\ud55c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824\uba74 \uc885\ud569\uc801 \uc0ac\uace0\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","Mu\u1ed1n gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i ph\u1ee9c t\u1ea1p th\xec c\u1ea7n t\u01b0 duy t\u1ed5ng h\u1ee3p.")
A.lBY=s([A.dDB],t.T)
A.e5r=new B.i("\uc885\ud569\uc801 \uc0ac\uace0","T\u01b0 duy t\u1ed5ng h\u1ee3p","\uba85\uc0ac",A.lBY,A.a,A.a)
A.dBF=new B.h("\uc815\ubcf4\ub97c \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4 \ube44\ud310\uc801 \uc0ac\uace0\ub97c \ud1b5\ud574 \ud310\ub2e8\ud574\uc57c \ud569\ub2c8\ub2e4.","Thay v\xec ti\u1ebfp nh\u1eadn nguy\xean th\xf4ng tin, c\u1ea7n ph\xe1n \u0111o\xe1n th\xf4ng qua t\u01b0 duy ph\u1ea3n bi\u1ec7n.")
A.kxu=s([A.dBF],t.T)
A.e3k=new B.i("\ube44\ud310\uc801 \uc0ac\uace0","T\u01b0 duy ph\u1ea3n bi\u1ec7n","\uba85\uc0ac",A.kxu,A.a,A.a)
A.dp8=new B.h("\ubb38\uc81c \uc778\uc2dd\uc774 \ubd80\uc871\ud558\uba74 \uc801\uc808\ud55c \ud574\uacb0 \ubc29\uc548\uc744 \ucc3e\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.","N\u1ebfu thi\u1ebfu nh\u1eadn th\u1ee9c v\u1ea5n \u0111\u1ec1 th\xec kh\xf3 t\xecm \u0111\u01b0\u1ee3c ph\u01b0\u01a1ng \xe1n gi\u1ea3i quy\u1ebft ph\xf9 h\u1ee3p.")
