A.jPn=s(["\uac10\uc815 \ud45c\ud604\ub9cc \ubc18\ubcf5\ud55c\ub2e4","\ud604\uc0c1, \uc6d0\uc778, \uc601\ud5a5, \ud574\uacb0 \ubc29\uc548, \uacb0\ub860 \uc21c\uc11c\ub85c \uc815\ub9ac\ud55c\ub2e4","\uc608\uc2dc \uc5c6\uc774 \uc8fc\uc7a5\ub9cc \uc4f4\ub2e4","\ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc \ub2e8\uc815\ud55c\ub2e4"],t.s)
A.dWx=new B.a9("\uc0ac\ud68c \ubb38\uc81c \uae00\uc4f0\uae30 \uad6c\uc870\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.jPn,1,"TOPIK \uace0\uae09 \uc4f0\uae30\uc5d0\uc11c\ub294 \ub17c\ub9ac\uc801 \uad6c\uc870\uac00 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc4f0\uae30 \uc804\ub7b5","\uace0\uae09")
A.lmU=s([A.dT2,A.dWz,A.dUJ,A.dTL,A.dXP,A.dXw,A.dXM,A.dT1,A.dVt,A.dXh,A.dWe,A.dT_,A.dXd,A.dTV,A.dW6,A.dTb,A.dUA,A.dWx],t.yc)
A.liJ=s(["\uac1c\uc778\uc801 \uc694\uc778","\uad6c\uc870\uc801 \ubb38\uc81c","\uc81c\ub3c4 \uac1c\uc120","\ucc45\uc784 \ubd84\ub2f4","\uc0ac\ud68c\uc801 \uc9c0\uc6d0","\uc885\ud569\uc801 \uc811\uadfc"],t.s)
A.e_5=new B.dr("\uc0ac\ud68c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \ub54c \uac1c\uc778\uc758 \ub178\ub825\uacfc \uc81c\ub3c4 \uac1c\uc120 \uc911 \ubb34\uc5c7\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.liJ,"\uc800\ub294 \uac1c\uc778\uc758 \ub178\ub825\uacfc \uc81c\ub3c4 \uac1c\uc120\uc744 \ub530\ub85c \ubd84\ub9ac\ud574\uc11c \ubcf4\uae30 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uac1c\uc778\uc774 \ucc45\uc784\uac10\uc744 \uac00\uc9c0\uace0 \ub178\ub825\ud558\ub294 \ud0dc\ub3c4\ub294 \uc911\uc694\ud569\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uccad\ub144 \uc2e4\uc5c5\uc774\ub098 \uc800\ucd9c\uc0b0, \ube48\uace4 \uac19\uc740 \ubb38\uc81c\ub294 \uac1c\uc778\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uad6c\uc870\uc801 \uc694\uc778\ub3c4 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac1c\uc778\uc774 \ub2a5\ub825\uc744 \ud0a4\uc6b8 \uc218 \uc788\ub3c4\ub85d \uad50\uc721\uacfc \uc815\ubcf4 \uc811\uadfc\uc131\uc744 \ub192\uc774\uace0, \ub3d9\uc2dc\uc5d0 \uc815\ubd80\uc640 \uc0ac\ud68c\uac00 \uc81c\ub3c4\uc801 \ud658\uacbd\uc744 \uac1c\uc120\ud574\uc57c \ud569\ub2c8\ub2e4. \uacb0\uad6d \uc911\uc694\ud55c \uac83\uc740 \uc5b4\ub290 \ud55c\ucabd\ub9cc \uac15\uc870\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc5ed\ud560\uc744 \ub098\ub204\uc5b4 \uc885\ud569\uc801\uc73c\ub85c \uc811\uadfc\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.")
A.kOr=s(["\uc0dd\uc0b0\uc131","\ud3b8\ub9ac\uc131","\uc77c\uc790\ub9ac \ubcc0\ud654","\uae30\uc220 \uaca9\ucc28","\uac1c\uc778\uc815\ubcf4","\uc0ac\ud68c\uc801 \ucc45\uc784"],t.s)
A.dZS=new B.dr("\uae30\uc220 \ubc1c\uc804\uc774 \uc0ac\ud68c\uc5d0 \uc8fc\ub294 \uae0d\uc815\uc801\uc778 \uc601\ud5a5\uacfc \ubd80\uc815\uc801\uc778 \uc601\ud5a5\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.kOr,"\uae30\uc220 \ubc1c\uc804\uc740 \uc0dd\uc0b0\uc131\uc744 \ub192\uc774\uace0 \uc0dd\ud65c\uc744 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc5d0\uc11c \uae0d\uc815\uc801\uc778 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\uc640 \uc758\ub8cc \uae30\uc220, \uc790\ub3d9\ud654 \uae30\uc220\uc740 \uc2dc\uac04\uacfc \ube44\uc6a9\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc77c\ubd80 \uc77c\uc790\ub9ac\uac00 \uc0ac\ub77c\uc9c0\uac70\ub098 \uae30\uc220\uc744 \uc798 \ud65c\uc6a9\ud558\ub294 \uc0ac\ub78c\uacfc \uadf8\ub807\uc9c0 \ubabb\ud55c \uc0ac\ub78c \uc0ac\uc774\uc758 \uaca9\ucc28\uac00 \ucee4\uc9c8 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uc640 \uc5f0\uad6c \uc724\ub9ac \uac19\uc740 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\ub3c4 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uae30\uc220 \ubc1c\uc804\uc744 \ubb34\uc870\uac74 \ub9c9\uae30\ubcf4\ub2e4 \uad50\uc721\uacfc \uc81c\ub3c4 \uac1c\uc120\uc744 \ud1b5\ud574 \ubd80\uc791\uc6a9\uc744 \uc904\uc774\ub294 \ubc29\ud5a5\uc73c\ub85c \uad00\ub9ac\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.jWl=s(["\ud658\uacbd","\ubcf5\uc9c0","\uacbd\uc81c","\ubbf8\ub798 \uc138\ub300","\uc0ac\ud68c\uc801 \ud569\uc758","\ucc45\uc784 \uc18c\ube44"],t.s)
A.dZZ=new B.dr("\uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\ud68c\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc5b4\ub5a4 \ub178\ub825\uc774 \ud544\uc694\ud569\ub2c8\uae4c?",A.jWl,"\uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\ud68c\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574\uc11c\ub294 \uacbd\uc81c \uc131\uc7a5\ub9cc \ubcf4\ub294 \ud0dc\ub3c4\uc5d0\uc11c \ubc97\uc5b4\ub098 \ud658\uacbd\uacfc \ubcf5\uc9c0, \ubbf8\ub798 \uc138\ub300\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uae30\uc5c5\uc740 \uc0dd\uc0b0 \uacfc\uc815\uc5d0\uc11c \ud658\uacbd\uc801 \ucc45\uc784\uc744 \uac15\ud654\ud558\uace0 \uc18c\ube44\uc790\ub294 \ud544\uc694\ud55c \ub9cc\ud07c \uad6c\ub9e4\ud558\ub294 \ucc45\uc784 \uc18c\ube44\ub97c \uc2e4\ucc9c\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ubd80\ub294 \ucde8\uc57d \uacc4\uce35\uc744 \ubcf4\ud638\ud558\uba74\uc11c\ub3c4 \uc7a5\uae30\uc801\uc73c\ub85c \uc720\uc9c0 \uac00\ub2a5\ud55c \ubcf5\uc9c0 \uc81c\ub3c4\ub97c \uc124\uacc4\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\ub294 \ud55c \uc0ac\ub78c\uc774\ub098 \ud55c \uae30\uad00\ub9cc\uc758 \ub178\ub825\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uae30 \uc5b4\ub835\uae30 \ub54c\ubb38\uc5d0 \uc0ac\ud68c\uc801 \ud569\uc758\uc640 \uacf5\ub3d9 \ub300\uc751\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.jug=s([A.e_5,A.dZS,A.dZZ],t.Gu)
A.kcx=s(["\uc0ac\ud68c \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud55c \uc774\uc720\ub97c \uc124\uba85\ud558\uc138\uc694.","\uac1c\uc778\uc801 \uc694\uc778\uacfc \uad6c\uc870\uc801 \uc694\uc778\uc744 \uad6c\ubd84\ud574\uc11c \uc4f0\uc138\uc694.","\uc815\ucc45\uc758 \ud544\uc694\uc131\uacfc \ud55c\uacc4\uc810\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc815\ubd80, \uae30\uc5c5, \uac1c\uc778\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\uc885\ud569\uc801 \ud574\uacb0 \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.elg=new B.eB("\ubcf5\uc7a1\ud55c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \uc885\ud569\uc801 \uc811\uadfc",A.kcx,"\ud604\ub300 \uc0ac\ud68c\uc758 \ubb38\uc81c\ub294 \ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc800\ucd9c\uc0b0\uc740 \uac1c\uc778\uc758 \uac00\uce58\uad00 \ubcc0\ud654\uc640 \uad00\ub828\uc774 \uc788\uc9c0\ub9cc \ub3d9\uc2dc\uc5d0 \uc8fc\uac70\ube44 \ubd80\ub2f4, \uace0\uc6a9 \ubd88\uc548, \uc591\uc721 \ud658\uacbd\uacfc \uac19\uc740 \uad6c\uc870\uc801 \ubb38\uc81c\uc640\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac1c\uc778\uc5d0\uac8c \ub354 \ub178\ub825\ud558\ub77c\uace0 \uc694\uad6c\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc815\ubd80\ub294 \uc7a5\uae30\uc801\uc778 \uc81c\ub3c4 \uac1c\uc120\uacfc \uc548\uc815\uc801\uc778 \uc9c0\uc6d0 \uccb4\uacc4\ub97c \ub9c8\ub828\ud574\uc57c \ud558\uba70 \uae30\uc5c5\uc740 \uadfc\ub85c\uc790\uac00 \uc77c\uacfc \uac00\uc815\uc744 \uc591\ub9bd\ud560 \uc218 \uc788\ub294 \ud658\uacbd\uc744 \uc870\uc131\ud574\uc57c \ud569\ub2c8\ub2e4. \uac1c\uc778 \uc5ed\uc2dc \uc815\ubcf4\ub97c \uc801\uadf9\uc801\uc73c\ub85c \ud65c\uc6a9\ud558\uace0 \uc0ac\ud68c\uc801 \ucc45\uc784\uc744 \uc778\uc2dd\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uad6d \ubcf5\uc7a1\ud55c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub2e8\ud3b8\uc801\uc778 \ub300\ucc45\ubcf4\ub2e4 \uc5ec\ub7ec \ubd84\uc57c\ub97c \uc5f0\uacb0\ud55c \uc885\ud569\uc801 \uc811\uadfc\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.jlW=s(["\ubbf8\ub798 \uc0ac\ud68c\uc758 \ubcc0\ud654\ub97c \uc124\uba85\ud558\uc138\uc694.","\uae30\uc220 \ubc1c\uc804\uacfc \uc778\uad6c \ubcc0\ud654\uc758 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uad50\uc721\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc81c\ub3c4 \uac1c\uc120\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\ubbf8\ub798 \uc138\ub300\ub97c \uc704\ud55c \ubc29\ud5a5\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.ekT=new B.eB("\ubbf8\ub798 \uc0ac\ud68c\ub97c \uc900\ube44\ud558\uae30 \uc704\ud55c \uad50\uc721\uacfc \uc81c\ub3c4\uc758 \uc5ed\ud560",A.jlW,"\ubbf8\ub798 \uc0ac\ud68c\ub294 \uae30\uc220 \ubc1c\uc804\uacfc \uc778\uad6c \uad6c\uc870 \ubcc0\ud654\ub85c \uc778\ud574 \uc9c0\uae08\ubcf4\ub2e4 \ub354 \ube60\ub974\uac8c \ubcc0\ud654\ud560 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4. \uc778\uacf5\uc9c0\ub2a5\uacfc \uc790\ub3d9\ud654, \ud50c\ub7ab\ud3fc \uacbd\uc81c\ub294 \uc77c\ud558\ub294 \ubc29\uc2dd\uacfc \uc18c\ube44 \ubc29\uc2dd\uc744 \ubc14\uafb8\uace0 \uc788\uc73c\uba70 \uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\ub294 \ub178\ub3d9\uc2dc\uc7a5\uacfc \ubcf5\uc9c0 \uc81c\ub3c4\uc5d0 \ud070 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\uc5d0 \ub300\uc751\ud558\uae30 \uc704\ud574\uc11c\ub294 \uad50\uc721\uc758 \uc5ed\ud560\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \ud559\uad50 \uad50\uc721\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc131\uc778\uc744 \uc704\ud55c \ud3c9\uc0dd\ud559\uc2b5\uacfc \uc9c1\ubb34 \uc7ac\uad50\uc721\uc744 \uac15\ud654\ud558\uc5ec \uc0ac\ub78c\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0 \uc801\uc751\ud560 \uc218 \uc788\ub3c4\ub85d \ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae30\uc874 \uc81c\ub3c4\uac00 \uc0c8\ub85c\uc6b4 \uc0ac\ud68c \ud604\uc2e4\uc744 \ucda9\ubd84\ud788 \ubc18\uc601\ud558\uc9c0 \ubabb\ud55c\ub2e4\uba74 \uc81c\ub3c4 \uac1c\uc120\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc815\ubd80\uc640 \uae30\uc5c5, \uc2dc\ubbfc\uc740 \ubbf8\ub798 \uc138\ub300\uc758 \ubd80\ub2f4\uc744 \uace0\ub824\ud558\uba74\uc11c \uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\ud68c\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \ud568\uaed8 \ub178\ub825\ud574\uc57c \ud560 \uac83\uc785\ub2c8\ub2e4.")
A.jxf=s([A.elg,A.ekT],t.Qd)
