A.eZU=new B.a2("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\uc758 \ud0dd\ubc30\uac00 \uc606\uc9d1\uc73c\ub85c \uc798\ubabb \ubc30\ub2ec\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc606\uc9d1 \uc0ac\ub78c\uc774 \ud0dd\ubc30\ub97c \ub300\uc2e0 \ubc1b\uc544 \ub450\uc5c8\ub2e4\uac00 \ubbfc \uc528\uc5d0\uac8c \uc804\ub2ec\ud588\uc2b5\ub2c8\ub2e4.",A.lzv,1,"H\xe0ng x\xf3m \u0111\xe3 nh\u1eadn h\u1ed9 b\u01b0u ki\u1ec7n.")
A.kje=s(["\ubbfc \uc528\ub294 \uc774\uc6c3\uc5d0\uac8c \ubbf8\ub9ac \uc54c\ub838\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc544\ubb34 \ub9d0\ub3c4 \ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\uc218\ub9ac\ud560 \ub54c \uc804\ud600 \uc18c\ub9ac\uac00 \ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uad00\ub9ac\ube44\ub97c \ub0b4\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4."],t.s)
A.eXO=new B.a2("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc8fc\ub9d0\uc5d0 \uc9d1 \uc218\ub9ac\ub97c \ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uc18c\uc74c\uc774 \ub0a0 \uc218 \uc788\uc5b4\uc11c \uacf5\uc0ac \uc804\uc5d0 \uc774\uc6c3\uc5d0\uac8c \ubbf8\ub9ac \uc54c\ub824 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.",A.kje,0,"Min \u0111\xe3 b\xe1o tr\u01b0\u1edbc v\xec vi\u1ec7c s\u1eeda c\xf3 th\u1ec3 g\xe2y ti\u1ebfng \u1ed3n.")
