A.jPL=s(["\uae30\ubcf8\uae09, \uc218\ub2f9, \uacf5\uc81c l\xe0 c\xe1c m\u1ee5c kh\xe1c nhau.","B\xe0i n\xe0y luy\u1ec7n \u0111\u1ecdc v\xe0 h\u1ecfi th\xf4ng tin; v\xed d\u1ee5 kh\xf4ng thay th\u1ebf ki\u1ec3m tra h\u1ee3p \u0111\u1ed3ng th\u1ef1c t\u1ebf.","Kh\xf4ng suy r\u1ed9ng ng\xe0y tr\u1ea3 l\u01b0\u01a1ng c\u1ee7a t\xecnh hu\u1ed1ng cho m\u1ecdi c\xf4ng ty."],t.s)
A.fxi=new B.hJ(4,"\uadfc\ub85c\uacc4\uc57d\uacfc \uc784\uae08","H\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng v\xe0 ti\u1ec1n l\u01b0\u01a1ng",A.kO3,"\ub2e4\uc74c\uc740 \uc5b8\uc5b4 \uc5f0\uc2b5\uc744 \uc704\ud55c \uac00\uc0c1 \uc548\ub0b4\ubb38\uc785\ub2c8\ub2e4. \uc774 \ud68c\uc0ac\ub294 \ub9e4\uc6d4 25\uc77c\uc5d0 \uae09\uc5ec\ub97c \uc9c0\uae09\ud569\ub2c8\ub2e4. \uc774\ubc88 \ub2ec \uba85\uc138\uc11c\ub294 23\uc77c\ubd80\ud130 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc561\uc5d0 \ub300\ud574 \uc9c8\ubb38\uc774 \uc788\uc73c\uba74 \uadfc\ubb34 \uae30\ub85d\uacfc \uba85\uc138\uc11c\ub97c \uc900\ube44\ud574\uc11c \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubb38\uc758\ud558\uc138\uc694. \uc774 \uc548\ub0b4\ubb38\uc5d0 \ub098\uc628 \ub0a0\uc9dc\uc640 \ud56d\ubaa9\uc740 \ubaa8\ub4e0 \ud68c\uc0ac\uc5d0 \uc801\uc6a9\ub418\ub294 \uae30\uc900\uc774 \uc544\ub2d9\ub2c8\ub2e4.","\u0110\xe2y l\xe0 th\xf4ng b\xe1o gi\u1ea3 \u0111\u1ecbnh \u0111\u1ec3 luy\u1ec7n ng\xf4n ng\u1eef. C\xf4ng ty n\xe0y tr\u1ea3 l\u01b0\u01a1ng ng\xe0y 25 h\u1eb1ng th\xe1ng. C\xf3 th\u1ec3 xem b\u1ea3ng k\xea th\xe1ng n\xe0y t\u1eeb ng\xe0y 23. N\u1ebfu c\xf3 c\xe2u h\u1ecfi v\u1ec1 s\u1ed1 ti\u1ec1n, h\xe3y chu\u1ea9n b\u1ecb b\u1ea3n ghi gi\u1edd l\xe0m v\xe0 b\u1ea3ng k\xea \u0111\u1ec3 h\u1ecfi ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch. Ng\xe0y v\xe0 c\xe1c m\u1ee5c trong th\xf4ng b\xe1o kh\xf4ng ph\u1ea3i ti\xeau chu\u1ea9n \xe1p d\u1ee5ng cho m\u1ecdi c\xf4ng ty.",A.lJZ,A.kOG,A.kc1,A.kCe,A.kOI,A.jPL)
A.kEL=s(["Tr\xecnh b\xe0y m\u1ee5c ti\xeau v\xe0 th\u1ee9 t\u1ef1 th\u1ef1c hi\u1ec7n.","N\xf3i \u0111i\u1ec1u ki\u1ec7n c\xf3 th\u1ec3 khi\u1ebfn k\u1ebf ho\u1ea1ch thay \u0111\u1ed5i.","\u0110\u1ecdc k\u1ebf ho\u1ea1ch \u0111\u1ec3 t\xecm b\u01b0\u1edbc ch\u01b0a ch\u1eafc ch\u1eafn."],t.s)
A.fxH=new B.eu("N\xf3i m\u1ee5c ti\xeau ba th\xe1ng, m\u1ed7i th\xe1ng m\u1ed9t b\u01b0\u1edbc v\xe0 m\u1ed9t ph\u01b0\u01a1ng \xe1n khi b\u1eadn.","\uccab \ub2ec\uc5d0\ub294 \ub9e4\uc77c \uc138 \ubb38\uc7a5\uc744 \uc4f0\uaca0\uc2b5\ub2c8\ub2e4. \ub458\uc9f8 \ub2ec\uc5d0\ub294 \uadf8 \ubb38\uc7a5\uc744 \uc18c\ub9ac \ub0b4\uc5b4 \uc77d\uaca0\uc2b5\ub2c8\ub2e4. \uc14b\uc9f8 \ub2ec\uc5d0\ub294 \ucc98\uc74c \ub179\uc74c\uacfc \ube44\uad50\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ubc14\ube60\uc9c0\uba74 \ubd84\ub7c9\uc744 \uc904\uc5ec\uc11c \uacc4\uc18d\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","M\u1ee5c ti\xeau r\xf5; c\xe1c b\u01b0\u1edbc li\xean k\u1ebft; c\xf3 ki\u1ec3m tra ti\u1ebfn b\u1ed9; ph\u01b0\u01a1ng \xe1n khi l\u1ecbch thay \u0111\u1ed5i.")
A.fxS=new B.eu("Vi\u1ebft \u0111o\u1ea1n 5 c\xe2u t\u1ed5ng k\u1ebft \u0111i\u1ec1u \u0111\xe3 h\u1ecdc v\xe0 m\u1ee5c ti\xeau ti\u1ebfp theo.","\uc0dd\ud65c \uc548\ub0b4\ubb38\uc5d0\uc11c \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\ub294 \uc5f0\uc2b5\uc744 \ud588\uc2b5\ub2c8\ub2e4. \ub0a0\uc9dc\uc640 \uc2dc\uac04\uc744 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc911\uc694\ud588\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 \uc81c \uc758\uacac\uc744 \ub354 \uae38\uac8c \ub9d0\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ub9e4\uc8fc \ud55c \uac00\uc9c0 \uc8fc\uc81c\ub85c \ub179\uc74c\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4. \uc5b4\ub824\uc6b0\uba74 \uc9e7\uc740 \ubb38\uc7a5\ubd80\ud130 \uc2dc\uc791\ud558\uaca0\uc2b5\ub2c8\ub2e4.","M\u1ed9t k\u1ef9 n\u0103ng \u0111\xe3 h\u1ecdc; \u0111i\u1ec1u r\xfat ra; m\u1ee5c ti\xeau m\u1edbi; h\xe0nh \u0111\u1ed9ng; \u0111i\u1ec1u ch\u1ec9nh khi kh\xf3.")
