A.lG6=s(["\uacbd\uc81c = kinh t\u1ebf.","\uc18c\ub4dd = thu nh\u1eadp.","\uc9c0\ucd9c = chi ti\xeau.","\uc218\uc785 = kho\u1ea3n ti\u1ec1n v\xe0o / thu nh\u1eadp.","\uac00\uacc4 = kinh t\u1ebf gia \u0111\xecnh.","\uac00\uacc4\ubd80 = s\u1ed5 thu chi gia \u0111\xecnh.","\uc0dd\ud65c\ube44 = chi ph\xed sinh ho\u1ea1t.","\uc8fc\uac70\ube44 = chi ph\xed nh\xe0 \u1edf.","\uad50\ud1b5\ube44 = chi ph\xed giao th\xf4ng.","\ud1b5\uc2e0\ube44 = chi ph\xed vi\u1ec5n th\xf4ng.","\uad50\uc721\ube44 = chi ph\xed gi\xe1o d\u1ee5c.","\uc800\ucd95\ud558\ub2e4 = ti\u1ebft ki\u1ec7m ti\u1ec1n.","\uc800\ucd95 = vi\u1ec7c/ti\u1ec1n ti\u1ebft ki\u1ec7m.","\uc608\uae08 = ti\u1ec1n g\u1eedi ng\xe2n h\xe0ng.","\ub300\ucd9c = kho\u1ea3n vay.","\uc774\uc790 = ti\u1ec1n l\xe3i.","\uae08\ub9ac = l\xe3i su\u1ea5t.","\ubb3c\uac00 = m\u1ee9c gi\xe1 c\u1ea3.","\uac00\uaca9 = gi\xe1.","\uc18c\ube44 = ti\xeau d\xf9ng.","\uc18c\ube44\uc790 = ng\u01b0\u1eddi ti\xeau d\xf9ng.","\ud569\ub9ac\uc801\uc778 \uc18c\ube44 = ti\xeau d\xf9ng h\u1ee3p l\xfd.","\ucda9\ub3d9\uad6c\ub9e4 = mua h\xe0ng b\u1ed1c \u0111\u1ed3ng.","\uc808\uc57d\ud558\ub2e4 = ti\u1ebft ki\u1ec7m.","\uc608\uc0b0 = ng\xe2n s\xe1ch.","\uacc4\ud68d\uc744 \uc138\uc6b0\ub2e4 = l\u1eadp k\u1ebf ho\u1ea1ch.","\uc6b0\uc120\uc21c\uc704 = th\u1ee9 t\u1ef1 \u01b0u ti\xean.","\ubd80\ub2f4 = g\xe1nh n\u1eb7ng.","-(\uc73c)\ubbc0\ub85c = v\xec / do..., th\u01b0\u1eddng d\xf9ng trong c\xe1ch gi\u1ea3i th\xedch kh\xe1 trang tr\u1ecdng.","-\ubbc0\ub85c = v\xec / do... \u1edf d\u1ea1ng ph\xf9 h\u1ee3p.",u.mb,"-\uae30\ub294\ucee4\ub155 = ch\u1eb3ng nh\u1eefng kh\xf4ng l\xe0m... m\xe0 c\xf2n...","-\uae30 \ub54c\ubb38\uc5d0 = b\u1edfi v\xec...","-\ub3c4\ub85d \ud558\ub2e4 = c\u1ed1 g\u1eafng / l\xe0m sao \u0111\u1ec3...",u.Bd,"\uac00\uacc4\ubd80\ub97c \uc4f0\uba74 \uc218\uc785\uacfc \uc9c0\ucd9c\uc758 \ud750\ub984\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.oF,u.uI,u.Hg],t.s)
