A.hbD=new B.an("\uadc0\ud654\ub294 \uc678\uad6d\uc778\uc774 \ub300\ud55c\ubbfc\uad6d \uad6d\uc801\uc744 \ucde8\ub4dd\ud558\ub294 \ubc29\ubc95 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","Nh\u1eadp qu\u1ed1c t\u1ecbch l\xe0 m\u1ed9t trong nh\u1eefng c\xe1ch ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 \u0111\u01b0\u1ee3c qu\u1ed1c t\u1ecbch H\xe0n Qu\u1ed1c.","N \uc911 \ud558\ub098 = m\u1ed9t trong nh\u1eefng N.")
A.hck=new B.an("\uadc0\ud654\ub97c \uc2e0\uccad\ud558\uae30 \uc804\uc5d0 \ud544\uc694\ud55c \uc694\uac74\uacfc \uc808\ucc28\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","Tr\u01b0\u1edbc khi xin nh\u1eadp qu\u1ed1c t\u1ecbch c\u1ea7n ki\u1ec3m tra c\xe1c \u0111i\u1ec1u ki\u1ec7n v\xe0 th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft.","-\uae30 \uc804\uc5d0 = tr\u01b0\u1edbc khi. -\uc544/\uc5b4\uc57c \ud558\ub2e4 = ph\u1ea3i.")
A.hf6=new B.an("\uc2e0\uccad \uc870\uac74\uc740 \uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u0110i\u1ec1u ki\u1ec7n \u0111\u0103ng k\xfd c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y ho\xe0n c\u1ea3nh c\u1ee7a m\u1ed7i ng\u01b0\u1eddi.","-\uc5d0 \ub530\ub77c = t\xf9y theo. \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4 = c\xf3 th\u1ec3 kh\xe1c.")
A.hf1=new B.an("\ud55c\uad6d\uc5b4\uc640 \ud55c\uad6d \uc0ac\ud68c\ub97c \uc774\ud574\ud558\ub294 \uac83\uc740 \uc548\uc815\uc801\uc778 \uc0dd\ud65c\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","Hi\u1ec3u ti\u1ebfng H\xe0n v\xe0 x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c gi\xfap \xedch cho cu\u1ed9c s\u1ed1ng \u1ed5n \u0111\u1ecbnh.","-\ub294 \uac83\uc740 = vi\u1ec7c...; \ub3c4\uc6c0\uc774 \ub418\ub2e4 = c\xf3 \xedch.")
A.hcj=new B.an("\uad6d\ubbfc\uc774 \ub418\uba74 \uad8c\ub9ac\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc758\ubb34\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi tr\u1edf th\xe0nh c\xf4ng d\xe2n, kh\xf4ng ch\u1ec9 quy\u1ec1n m\xe0 c\xf2n ph\u1ea3i ngh\u0129 \u0111\u1ebfn ngh\u0129a v\u1ee5.","-\ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9... m\xe0 c\xf2n.")
A.hfc=new B.an("\uc815\ud655\ud55c \uad6d\uc801 \uc815\ubcf4\ub294 \uacf5\uc2dd \uae30\uad00\uc758 \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\u0110\u1ed1i v\u1edbi th\xf4ng tin qu\u1ed1c t\u1ecbch ch\xednh x\xe1c, n\xean ki\u1ec3m tra h\u01b0\u1edbng d\u1eabn c\u1ee7a c\u01a1 quan ch\xednh th\u1ee9c.","-\ub294 \uac83\uc774 \uc88b\ub2e4 = n\xean.")
