A.lYA=s(["\uad6d\uc801 = qu\u1ed1c t\u1ecbch; \uccb4\ub958\uc790\uaca9 = t\u01b0 c\xe1ch l\u01b0u tr\xfa. Hai kh\xe1i ni\u1ec7m n\xe0y kh\xe1c nhau.","\uc601\uc8fc \uc790\uaca9\uacfc \ub300\ud55c\ubbfc\uad6d \uad6d\uc801\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.","\uadc0\ud654 = m\u1ed9t ph\u01b0\u01a1ng th\u1ee9c \u0111\u1ec3 ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 qu\u1ed1c t\u1ecbch H\xe0n Qu\u1ed1c.","\uadc0\ud654 \uc2e0\uccad\uc744 \ud588\ub2e4\uace0 \ud574\uc11c \ubc14\ub85c \ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uadc0\ud654 \uc694\uac74\uacfc \uc808\ucc28\ub294 \uac1c\uc778\uc758 \uc0c1\ud669\uacfc \uc2e0\uccad \uc720\ud615\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0ac\ub840\uac00 \uc790\uc2e0\uc758 \uacbd\uc6b0\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4.","\uad8c\ub9ac = quy\u1ec1n; \uc758\ubb34 = ngh\u0129a v\u1ee5.",u.yR],t.s)
A.kBa=s(["\uad6d\uc801 \u2192 m\u1ed9t ng\u01b0\u1eddi thu\u1ed9c v\u1ec1 qu\u1ed1c gia n\xe0o v\u1ec1 m\u1eb7t ph\xe1p l\xfd.","\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc \u2192 ng\u01b0\u1eddi c\xf3 qu\u1ed1c t\u1ecbch H\xe0n Qu\u1ed1c.","\uadc0\ud654 \u2192 m\u1ed9t ph\u01b0\u01a1ng th\u1ee9c ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 th\u1ec3 c\xf3 qu\u1ed1c t\u1ecbch H\xe0n Qu\u1ed1c.","\uadc0\ud654\ub97c \uc704\ud574\uc11c\ub294 \ubc95\uc5d0\uc11c \uc815\ud55c \uc694\uac74\uacfc \uc808\ucc28\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \uc801\uc6a9\ub418\ub294 \uc870\uac74\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4.","\ud55c\uad6d\uc5b4 \ub2a5\ub825\uacfc \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud55c \uc774\ud574\ub294 \uc0ac\ud68c\uc0dd\ud65c\uc5d0 \uc911\uc694\ud558\ub2e4.","\uad6d\ubbfc\uc740 \ubc95\uc5d0 \ub530\ub978 \uad8c\ub9ac\ub97c \uac00\uc9c4\ub2e4.","\uad6d\ubbfc\uc5d0\uac8c\ub294 \ucc45\uc784\uacfc \uc758\ubb34\ub3c4 \uc788\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud574\uc57c \ud55c\ub2e4.","\uad6d\uc801 \uad00\ub828 \uc815\ubcf4\ub294 \uacf5\uc2dd \uae30\uad00\uc5d0\uc11c \uc815\ud655\ud558\uac8c \ud655\uc778\ud574\uc57c \ud55c\ub2e4."],t.s)
A.a7H=s(["\uac1c\uc778\uc774 \uc5b4\ub290 \uad6d\uac00\uc758 \uad6d\ubbfc\uc778\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \ubc95\uc801 \uad00\uacc4","\ud68c\uc0ac\uc5d0\uc11c \ud558\ub294 \uc5c5\ubb34\uc758 \uc885\ub958","\uc740\ud589 \uacc4\uc88c\uc758 \uc885\ub958","\uc8fc\ud0dd\uc758 \ud06c\uae30"],t.s)
