A.h9j=new B.S("\ub2e8\uad70\uc655\uac80\uacfc \uad00\ub828\ud558\uc5ec \uc774\ud574\ud560 \uc218 \uc788\ub294 \uace0\ub300 \uc0ac\ud68c\uc758 \ud2b9\uc9d5\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\u1eb7c \u0111i\u1ec3m x\xe3 h\u1ed9i c\u1ed5 \u0111\u1ea1i th\u01b0\u1eddng \u0111\u01b0\u1ee3c li\xean h\u1ec7 v\u1edbi t\xean g\u1ecdi Dangun Wanggeom l\xe0 g\xec?",A.a5q,0,"\ub2e8\uad70\uc655\uac80\uc774\ub77c\ub294 \uba85\uce6d\uc740 \uc81c\uc0ac\uc640 \uc815\uce58\uac00 \uacb0\ud569\ub41c \uc81c\uc815\uc77c\uce58 \uc0ac\ud68c\ub97c \uc124\uba85\ud560 \ub54c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.")
