A.lBM=s(["\ud55c\ubc18\ub3c4 = b\xe1n \u0111\u1ea3o Tri\u1ec1u Ti\xean; \ub300\ud55c\ubbfc\uad6d = H\xe0n Qu\u1ed1c. Kh\xf4ng ho\xe0n to\xe0n l\xe0 c\xf9ng m\u1ed9t kh\xe1i ni\u1ec7m \u0111\u1ecba l\xfd.","\ub3d9\ucabd \u2192 \ub3d9\ud574, \uc11c\ucabd \u2192 \uc11c\ud574, \ub0a8\ucabd \u2192 \ub0a8\ud574.","\ud55c\uad6d\uc740 \uc0ac\uacc4\uc808\uc774 \uc788\uc9c0\ub9cc \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \ub0a0\uc528\uac00 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc5ec\ub984 \u2192 \ub365\uace0 \uc2b5\ud568, \uc7a5\ub9c8\uc640 \ud0dc\ud48d\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\uc74c.","\uaca8\uc6b8 \u2192 \ub300\uccb4\ub85c \ucda5\uace0 \uac74\uc870\ud568.","\ub3d9\uace0\uc11c\uc800 \u2192 \ub3d9\ucabd\uc774 \ub192\uace0 \uc11c\ucabd\uc774 \ub0ae\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.","\ub3d9\ucabd\uc5d0\ub294 \uc0b0\uc9c0\uac00 \ub9ce\uace0 \uc11c\ucabd\uacfc \ub0a8\ucabd\uc5d0\ub294 \ud3c9\uc57c\uac00 \ube44\uad50\uc801 \ubc1c\ub2ec\ud588\uc2b5\ub2c8\ub2e4.","\ud55c\uac15\uc740 \uc218\ub3c4\uad8c, \ub099\ub3d9\uac15\uc740 \uc601\ub0a8 \uc9c0\uc5ed\uacfc \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud558\uba74 \uc88b\uc2b5\ub2c8\ub2e4.","\ud55c\ub77c\uc0b0 \u2192 \uc81c\uc8fc\ub3c4.","\ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \uc0b0 \u2192 \ud55c\ub77c\uc0b0."],t.s)
A.lk0=s(["\ud55c\uad6d \u2192 \uc544\uc2dc\uc544 \ub300\ub959 \ub3d9\ucabd, \ud55c\ubc18\ub3c4.","\ud55c\ubc18\ub3c4 \u2192 \uc0bc\uba74\uc774 \ubc14\ub2e4.","\ub3d9\ucabd \u2192 \ub3d9\ud574.","\uc11c\ucabd \u2192 \uc11c\ud574.","\ub0a8\ucabd \u2192 \ub0a8\ud574.","\ud55c\uad6d \uae30\ud6c4 \u2192 \uc0ac\uacc4\uc808\uc774 \ube44\uad50\uc801 \ub69c\ub837\ud568.","\uc5ec\ub984 \u2192 \ub365\uace0 \uc2b5\ud568.","\uc7a5\ub9c8 \u2192 \uc5ec\ub984\ucca0 \ub9ce\uc740 \ube44.","\uaca8\uc6b8 \u2192 \ucda5\uace0 \uac74\uc870\ud55c \ud3b8.","\ud55c\uad6d \uc9c0\ud615 \u2192 \uc0b0\uc9c0\uac00 \ub9ce\uc74c.","\ub3d9\uace0\uc11c\uc800 \u2192 \ub3d9\ucabd\uc774 \ub192\uace0 \uc11c\ucabd\uc774 \ub0ae\uc74c.","\uc11c\ubd80\xb7\ub0a8\ubd80 \u2192 \ud3c9\uc57c \ubc1c\ub2ec.","\ud55c\uac15 \u2192 \uc218\ub3c4\uad8c.","\ub099\ub3d9\uac15 \u2192 \uc601\ub0a8 \uc9c0\uc5ed.","\ud55c\ub77c\uc0b0 \u2192 \uc81c\uc8fc\ub3c4, \ub300\ud55c\ubbfc\uad6d \ucd5c\uace0\ubd09."],t.s)
