A.h5I=new B.S("\uc81c\uc8fc\ub3c4\uc5d0 \uc788\uc73c\uba70 \ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \uc0b0\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ng\u1ecdn n\xfai n\u1eb1m tr\xean \u0111\u1ea3o Jeju v\xe0 cao nh\u1ea5t H\xe0n Qu\u1ed1c l\xe0 n\xfai n\xe0o?",A.a0p,0,"\ud55c\ub77c\uc0b0\uc740 \uc81c\uc8fc\ub3c4\uc5d0 \uc788\uc73c\uba70 \ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \uc0b0\uc785\ub2c8\ub2e4.")
A.VW=s(["\ud55c\uad6d\uc758 \uc704\uce58\uc640 \uae30\ud6c4, \uc9c0\ud615\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4.","\ud55c\uad6d\uc5d0\ub294 \uc0b0\uc774 \uac70\uc758 \uc5c6\ub2e4.","\ud55c\uad6d\uc740 \uc77c \ub144 \ub0b4\ub0b4 \uac19\uc740 \uae30\ud6c4\uc774\ub2e4.","\ud55c\ub77c\uc0b0\uc740 \uc11c\uc6b8\uc5d0 \uc788\ub2e4."],t.s)
A.h8x=new B.S("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.VW,0,"\u0110\u1ecba l\xfd t\u1ef1 nhi\xean \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn \u0111\u1eddi s\u1ed1ng, n\xf4ng nghi\u1ec7p, giao th\xf4ng v\xe0 v\u0103n h\xf3a t\u1eebng khu v\u1ef1c.")
