A.h4V=new B.S("\uc808\ub3c4\ub098 \uc0ac\uae30\uc640 \uac19\uc774 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \uc0ac\uac74\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","V\u1ee5 vi\u1ec7c li\xean quan \u0111\u1ebfn t\u1ed9i ph\u1ea1m nh\u01b0 tr\u1ed9m c\u1eafp ho\u1eb7c l\u1eeba \u0111\u1ea3o l\xe0 g\xec?",A.a6z,0,"C\xe1c v\u1ee5 vi\u1ec7c li\xean quan \u0111\u1ebfn t\u1ed9i ph\u1ea1m c\xf3 th\u1ec3 l\xe0 v\u1ee5 \xe1n h\xecnh s\u1ef1.")
A.a_1=s(["\ub300\ud654\ub97c \ud1b5\ud574 \ud574\uacb0\ud55c\ub2e4.","\uc870\uc815\uc744 \uc774\uc6a9\ud55c\ub2e4.","\uc7ac\ud310\uc744 \uc774\uc6a9\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc5d0\uac8c \ud3ed\ub825\uc744 \uc0ac\uc6a9\ud55c\ub2e4."],t.s)
A.h50=new B.S("\ubd84\uc7c1\uc744 \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u KH\xd4NG ph\u1ea3i c\xe1ch ph\xf9 h\u1ee3p \u0111\u1ec3 gi\u1ea3i quy\u1ebft tranh ch\u1ea5p?",A.a_1,3,"S\u1eed d\u1ee5ng b\u1ea1o l\u1ef1c kh\xf4ng ph\u1ea3i c\xe1ch gi\u1ea3i quy\u1ebft tranh ch\u1ea5p ph\xf9 h\u1ee3p.")
