A.h3R=new B.S("\ubc94\uc8c4 \uc2e0\uace0\uc640 \uac00\uc7a5 \uad00\uacc4\uac00 \uae4a\uc740 \uae30\uad00\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","C\u01a1 quan li\xean quan m\u1eadt thi\u1ebft nh\u1ea5t \u0111\u1ebfn b\xe1o c\xe1o t\u1ed9i ph\u1ea1m l\xe0 \u0111\xe2u?",A.TW,0,"\ubc94\uc8c4 \uc2e0\uace0\uc640 \uce58\uc548\uc740 \uacbd\ucc30\uacfc \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.")
A.a70=s(["\uc18c\ubc29\uc11c","\uad6c\uccad","\ub3c4\uc11c\uad00","\uc740\ud589"],t.s)
A.h7I=new B.S("\ud654\uc7ac\uc640 \uad6c\uc870 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\ub294 \uae30\uad00\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","C\u01a1 quan ph\u1ee5 tr\xe1ch ch\xe1y v\xe0 c\u1ee9u h\u1ed9 l\xe0 \u0111\xe2u?",A.a70,0,"\uc18c\ubc29\uae30\uad00\uc740 \ud654\uc7ac, \uad6c\uc870, \uad6c\uae09 \ub4f1\uc758 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud569\ub2c8\ub2e4.")
A.a5g=s(["\ub3c4\uc11c\uad00","\uacbd\ucc30\uc11c","\uc18c\ubc29\uc11c","\uc2dc\uccad"],t.s)
A.h7H=new B.S("\ucc45\uc744 \ube4c\ub9ac\uace0 \uacf5\ubd80\ud560 \uc218 \uc788\ub294 \uc9c0\uc5ed\uc2dc\uc124\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","C\u01a1 s\u1edf \u0111\u1ecba ph\u01b0\u01a1ng n\u01a1i c\xf3 th\u1ec3 m\u01b0\u1ee3n s\xe1ch v\xe0 h\u1ecdc t\u1eadp l\xe0 \u0111\xe2u?",A.a5g,0,"\ub3c4\uc11c\uad00\uc5d0\uc11c\ub294 \ucc45\uc744 \uc77d\uace0 \ube4c\ub9ac\uac70\ub098 \uacf5\ubd80\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.a1w=s(["\uc0ac\ud68c\ubcf5\uc9c0\uad00","\uace0\uc18d\ub3c4\ub85c","\uacf5\ud56d","\ud56d\uad6c"],t.s)
A.h6R=new B.S("\uc8fc\ubbfc\uc744 \uc704\ud55c \ub2e4\uc591\ud55c \ubcf5\uc9c0 \ud504\ub85c\uadf8\ub7a8\uacfc \uad00\uacc4\uac00 \uae4a\uc740 \uacf3\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","N\u01a1i n\xe0o g\u1eafn v\u1edbi c\xe1c ch\u01b0\u01a1ng tr\xecnh ph\xfac l\u1ee3i d\xe0nh cho c\u01b0 d\xe2n?",A.a1w,0,"\uc0ac\ud68c\ubcf5\uc9c0\uad00\uc5d0\uc11c\ub294 \ub2e4\uc591\ud55c \uc8fc\ubbfc \ubcf5\uc9c0 \ud504\ub85c\uadf8\ub7a8\uc744 \uc6b4\uc601\ud569\ub2c8\ub2e4.")
A.a0V=s(["\uac00\uc871\uc13c\ud130 \ub610\ub294 \uad00\ub828 \uc9c0\uc6d0\uae30\uad00","\uc8fc\uc720\uc18c","\uacf5\uc7a5","\uc6b4\ub3d9\uc7a5\ub9cc"],t.s)
A.h5k=new B.S("\uac00\uc871\uc0dd\ud65c\uc774\ub098 \ud55c\uad6d\uc0dd\ud65c \uc801\uc751 \uc0c1\ub2f4\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uae30\uad00\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","C\u01a1 quan ph\xf9 h\u1ee3p \u0111\u1ec3 nh\u1eadn t\u01b0 v\u1ea5n v\u1ec1 \u0111\u1eddi s\u1ed1ng gia \u0111\xecnh ho\u1eb7c th\xedch nghi cu\u1ed9c s\u1ed1ng H\xe0n Qu\u1ed1c l\xe0 \u0111\xe2u?",A.a0V,0,"\uac00\uc871\uc13c\ud130\uc640 \uad00\ub828 \uc9c0\uc6d0\uae30\uad00\uc5d0\uc11c \uac00\uc871\uc0dd\ud65c\uacfc \uc801\uc751 \uc0c1\ub2f4 \ub4f1\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.a5P=s(["\uad6c \uc9c0\uc5ed\uc758 \ud589\uc815 \uc5c5\ubb34\uc640 \uad00\ub828\ub41c \uae30\uad00\uc774\ub2e4.","\ubd88\uc744 \ub044\ub294 \uae30\uad00\uc774\ub2e4.","\ucc45\ub9cc \ube4c\ub824\uc8fc\ub294 \ubbfc\uac04 \uc0c1\uc810\uc774\ub2e4.","\ube44\ud589\uae30\ub97c \uc6b4\ud56d\ud558\ub294 \uae30\uad00\uc774\ub2e4."],t.s)
A.h6N=new B.S("\u201c\uad6c\uccad\u201d\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ph\xe1t bi\u1ec3u n\xe0o \u0111\xfang v\u1ec1 \uad6c\uccad?",A.a5P,0,"\uad6c\uccad\uc740 \uad6c \ub2e8\uc704\uc758 \ud589\uc815 \uc5c5\ubb34\uc640 \uad00\ub828\ub41c \uae30\uad00\uc785\ub2c8\ub2e4.")
A.a4A=s(["\uc6b4\uc601\uc2dc\uac04\uacfc \ud544\uc694\ud55c \uc11c\ub958","\uce5c\uad6c\uc758 \ucde8\ubbf8\ub9cc","\uad00\uad11\uc9c0\uc758 \uc0ac\uc9c4\ub9cc","\uc544\ubb34\uac83\ub3c4 \ud655\uc778\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4."],t.s)
A.h3Z=new B.S("\uacf5\uacf5\uae30\uad00\uc744 \ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uba74 \uc88b\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Tr\u01b0\u1edbc khi \u0111\u1ebfn c\u01a1 quan c\xf4ng n\xean ki\u1ec3m tra \u0111i\u1ec1u g\xec?",A.a4A,0,"\uc6b4\uc601\uc2dc\uac04\uacfc \uc900\ube44 \uc11c\ub958, \ub2f4\ub2f9 \uc5c5\ubb34\ub97c \ubbf8\ub9ac \ud655\uc778\ud558\uba74 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.")
A.XT=s(["\uc9c0\uc5ed\uc0ac\ud68c \uae30\uad00\uc758 \uc5ed\ud560\uc744 \uc54c\uba74 \ud544\uc694\ud55c \ub3c4\uc6c0\uc744 \ub354 \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub2e4.","\ubaa8\ub4e0 \ud589\uc815 \uc5c5\ubb34\ub294 \uacbd\ucc30\uc11c\uc5d0\uc11c \ucc98\ub9ac\ud55c\ub2e4.","\ub3c4\uc11c\uad00\uc5d0\uc11c\ub294 \ucc45\uc744 \uc77d\uc744 \uc218 \uc5c6\ub2e4.","\ubcf4\uac74\uc18c\ub294 \ud654\uc7ac \uc9c4\uc555\ub9cc \ub2f4\ub2f9\ud55c\ub2e4."],t.s)
A.h9S=new B.S("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.XT,0,"Bi\u1ebft ch\u1ee9c n\u0103ng c\u1ee7a t\u1eebng c\u01a1 quan gi\xfap t\xecm \u0111\xfang s\u1ef1 tr\u1ee3 gi\xfap khi g\u1eb7p v\u1ea5n \u0111\u1ec1.")
A.kx_=s([A.haD,A.h5Y,A.h3R,A.h7I,A.h7H,A.h6R,A.h5k,A.h6N,A.h3Z,A.h9S],t.h)
A.lsV=s(["\uc9c0\uc5ed\uc0ac\ud68c \uae30\uad00 = c\xe1c c\u01a1 quan v\xe0 c\u01a1 s\u1edf ph\u1ee5c v\u1ee5 c\u01b0 d\xe2n \u0111\u1ecba ph\u01b0\u01a1ng.","\uc8fc\ubbfc\uc13c\ud130\xb7\ud589\uc815\ubcf5\uc9c0\uc13c\ud130 = \ud589\uc815 \uc5c5\ubb34 + \ubcf5\uc9c0 \uc0c1\ub2f4.","\uc2dc\uccad = ch\xednh quy\u1ec1n th\xe0nh ph\u1ed1.","\uad6c\uccad = c\u01a1 quan h\xe0nh ch\xednh qu\u1eadn.","\uad70\uccad = c\u01a1 quan h\xe0nh ch\xednh huy\u1ec7n.","\ubcf4\uac74\uc18c = s\u1ee9c kh\u1ecfe v\xe0 d\u1ecbch v\u1ee5 y t\u1ebf c\xf4ng c\u1ed9ng.","\uacbd\ucc30\uc11c = t\u1ed9i ph\u1ea1m + an ninh + b\xe1o c\xe1o.","\uc18c\ubc29\uc11c = h\u1ecfa ho\u1ea1n + c\u1ee9u h\u1ed9 + c\u1ea5p c\u1ee9u.","\ub3c4\uc11c\uad00 = s\xe1ch + h\u1ecdc t\u1eadp + ch\u01b0\u01a1ng tr\xecnh v\u0103n h\xf3a.","\uc0ac\ud68c\ubcf5\uc9c0\uad00 = c\xe1c ch\u01b0\u01a1ng tr\xecnh ph\xfac l\u1ee3i cho c\u01b0 d\xe2n.","\uac00\uc871\uc13c\ud130 = t\u01b0 v\u1ea5n v\xe0 h\u1ed7 tr\u1ee3 \u0111\u1eddi s\u1ed1ng gia \u0111\xecnh.","\uc678\uad6d\uc778\uc8fc\ubbfc \uc9c0\uc6d0\uae30\uad00 = h\u1ed7 tr\u1ee3 th\xedch nghi cu\u1ed9c s\u1ed1ng H\xe0n Qu\u1ed1c.",u.q5,"\ubc29\ubb38 \uc804 \uc6b4\uc601\uc2dc\uac04\uacfc \ud544\uc694\ud55c \uc11c\ub958\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.h2F=new B.dQ(49,"\uc9c0\ub9ac","\uc9c0\uc5ed\uc0ac\ud68c \uae30\uad00","C\xe1c c\u01a1 quan trong c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng",A.kDg,A.l7F,A.k3o,A.lTv,"\uc6b0\ub9ac \ub3d9\ub124\uc758 \uc5ec\ub7ec \uae30\uad00","\uc6b0\ub9ac\uac00 \uc0dd\ud65c\ud558\ub294 \uc9c0\uc5ed\uc0ac\ud68c\uc5d0\ub294 \uc8fc\ubbfc\ub4e4\uc774 \ud3b8\ub9ac\ud558\uace0 \uc548\uc804\ud558\uac8c \uc0dd\ud65c\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \ub2e4\uc591\ud55c \uae30\uad00\uacfc \uc2dc\uc124\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc8fc\ubbfc\uc13c\ud130 \ub610\ub294 \ud589\uc815\ubcf5\uc9c0\uc13c\ud130\ub294 \uc8fc\ubbfc\uacfc \uac00\uae4c\uc6b4 \ud589\uc815\uae30\uad00\uc785\ub2c8\ub2e4. \uc774\uacf3\uc5d0\uc11c\ub294 \uc8fc\ubbfc \uc0dd\ud65c\uacfc \uad00\ub828\ub41c \ud589\uc815 \uc5c5\ubb34\ub97c \ubb38\uc758\ud558\uac70\ub098 \ubcf5\uc9c0 \uc11c\ube44\uc2a4\uc5d0 \ub300\ud55c \uc548\ub0b4\uc640 \uc0c1\ub2f4\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uaddc\ubaa8\uac00 \ub354 \ud070 \ud589\uc815 \uc5c5\ubb34\ub294 \uc2dc\uccad, \uad6c\uccad, \uad70\uccad \ub4f1\uc5d0\uc11c \ub2f4\ub2f9\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \uae30\uad00\uc5d0\uc11c \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud574\uc57c \ud558\ub294\uc9c0 \ubaa8\ub97c \uacbd\uc6b0 \uba3c\uc800 \ub2f4\ub2f9 \uae30\uad00\uc5d0 \ubb38\uc758\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\uac74\uac15\uacfc \uad00\ub828\ud574\uc11c\ub294 \ubcf4\uac74\uc18c\ub97c \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubcf4\uac74\uc18c\uc5d0\uc11c\ub294 \uc9c0\uc5ed \uc8fc\ubbfc\uc758 \uac74\uac15\uc744 \uc704\ud55c \uc5ec\ub7ec \ubcf4\uac74 \uc0ac\uc5c5\uacfc \uc0c1\ub2f4 \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4. \ub2e4\ub9cc \uc81c\uacf5\ub418\ub294 \uc11c\ube44\uc2a4\ub294 \uc9c0\uc5ed\uc774\ub098 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548\uc804\uacfc \uad00\ub828\ub41c \uae30\uad00\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uacbd\ucc30\uc740 \ubc94\uc8c4 \uc2e0\uace0\uc640 \uce58\uc548 \uc720\uc9c0 \ub4f1\uc758 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\uba70, \uc18c\ubc29\uae30\uad00\uc740 \ud654\uc7ac, \uad6c\uc870, \uad6c\uae09 \ub4f1 \uae34\uae09\ud55c \uc548\uc804 \ubb38\uc81c\ub97c \ub2f4\ub2f9\ud569\ub2c8\ub2e4.\n\n\uc9c0\uc5ed\uc0ac\ud68c\uc5d0\ub294 \uc0dd\ud65c\uacfc \ubb38\ud654 \ud65c\ub3d9\uc744 \uc704\ud55c \uc2dc\uc124\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub3c4\uc11c\uad00\uc5d0\uc11c\ub294 \ucc45\uc744 \uc77d\uac70\ub098 \ube4c\ub9b4 \uc218 \uc788\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uacf5\ubd80, \uac15\uc88c, \ubb38\ud654 \ud504\ub85c\uadf8\ub7a8 \ub4f1\uc5d0 \ucc38\uc5ec\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc0ac\ud68c\ubcf5\uc9c0\uad00\uc5d0\uc11c\ub294 \uc5b4\ub9b0\uc774, \uccad\uc18c\ub144, \ub178\uc778, \uc7a5\uc560\uc778 \ub4f1 \ub2e4\uc591\ud55c \uc8fc\ubbfc\uc744 \uc704\ud55c \ubcf5\uc9c0 \ud504\ub85c\uadf8\ub7a8\uc744 \uc6b4\uc601\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uac00\uc871\uc13c\ud130\ub098 \uc678\uad6d\uc778\uc8fc\ubbfc\uc744 \uc9c0\uc6d0\ud558\ub294 \uae30\uad00\uc5d0\uc11c\ub294 \ud55c\uad6d\uc0dd\ud65c \uc801\uc751, \uac00\uc871\uc0dd\ud65c, \uc5b8\uc5b4\uad50\uc721, \uc0c1\ub2f4 \ub4f1\uc5d0 \uad00\ud55c \ub3c4\uc6c0\uc744 \uc81c\uacf5\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uc678\uad6d\uc778\uc774 \ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub2e4 \ubcf4\uba74 \uc5b4\ub5a4 \uae30\uad00\uc744 \uc774\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 \ubab0\ub77c \uc5b4\ub824\uc6c0\uc744 \uacaa\uc744 \ub54c\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7f4 \ub54c\uc5d0\ub294 \ud63c\uc790 \uace0\ubbfc\ud558\uae30\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \ud589\uc815\uae30\uad00\uc774\ub098 \uad00\ub828 \uc9c0\uc6d0\uae30\uad00\uc5d0 \ubb38\uc758\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\ub610\ud55c \uae30\uad00\ub9c8\ub2e4 \uc774\uc6a9\uc2dc\uac04\uacfc \ud544\uc694\ud55c \uc11c\ub958, \uc2e0\uccad \ubc29\ubc95\uc774 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \uc804\ud654\ub098 \uacf5\uc2dd \uc548\ub0b4\ub97c \ud1b5\ud574 \ud655\uc778\ud558\uba74 \ub354 \ud3b8\ub9ac\ud558\uac8c \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc9c0\uc5ed\uc0ac\ud68c \uae30\uad00\uc758 \uc5ed\ud560\uc744 \uc54c\uc544 \ub450\uba74 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \ud544\uc694\ud55c \ub3c4\uc6c0\uc744 \ub354 \ube60\ub974\uac8c \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n","Trong c\u1ed9ng \u0111\u1ed3ng n\u01a1i ch\xfang ta sinh s\u1ed1ng c\xf3 nhi\u1ec1u c\u01a1 quan v\xe0 c\u01a1 s\u1edf gi\xfap c\u01b0 d\xe2n s\u1ed1ng thu\u1eadn ti\u1ec7n v\xe0 an to\xe0n h\u01a1n.\n\nTrung t\xe2m c\u01b0 d\xe2n ho\u1eb7c trung t\xe2m h\xe0nh ch\xednh v\xe0 ph\xfac l\u1ee3i l\xe0 c\u01a1 quan h\xe0nh ch\xednh g\u1ea7n g\u0169i v\u1edbi ng\u01b0\u1eddi d\xe2n. T\u1ea1i \u0111\xe2y c\xf3 th\u1ec3 h\u1ecfi v\u1ec1 c\xe1c th\u1ee7 t\u1ee5c h\xe0nh ch\xednh li\xean quan \u0111\u1ebfn \u0111\u1eddi s\u1ed1ng ho\u1eb7c nh\u1eadn h\u01b0\u1edbng d\u1eabn v\xe0 t\u01b0 v\u1ea5n v\u1ec1 d\u1ecbch v\u1ee5 ph\xfac l\u1ee3i.\n\nM\u1ed9t s\u1ed1 c\xf4ng vi\u1ec7c h\xe0nh ch\xednh c\xf3 quy m\xf4 l\u1edbn h\u01a1n c\xf3 th\u1ec3 do t\xf2a th\u1ecb ch\xednh, v\u0103n ph\xf2ng qu\u1eadn ho\u1eb7c v\u0103n ph\xf2ng huy\u1ec7n ph\u1ee5 tr\xe1ch. N\u1ebfu kh\xf4ng bi\u1ebft ph\u1ea3i l\xe0m th\u1ee7 t\u1ee5c t\u1ea1i c\u01a1 quan n\xe0o th\xec n\xean h\u1ecfi c\u01a1 quan ph\u1ee5 tr\xe1ch tr\u01b0\u1edbc.\n\n\u0110\u1ed1i v\u1edbi v\u1ea5n \u0111\u1ec1 s\u1ee9c kh\u1ecfe c\xf3 th\u1ec3 s\u1eed d\u1ee5ng trung t\xe2m y t\u1ebf c\xf4ng c\u1ed9ng. Trung t\xe2m n\xe0y cung c\u1ea5p nhi\u1ec1u ch\u01b0\u01a1ng tr\xecnh v\xe0 d\u1ecbch v\u1ee5 t\u01b0 v\u1ea5n li\xean quan \u0111\u1ebfn s\u1ee9c kh\u1ecfe c\u1ee7a c\u01b0 d\xe2n. Tuy nhi\xean, d\u1ecbch v\u1ee5 c\u1ee5 th\u1ec3 c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y khu v\u1ef1c v\xe0 t\xecnh hu\u1ed1ng.\n\nNgo\xe0i ra c\xf2n c\xf3 c\xe1c c\u01a1 quan li\xean quan \u0111\u1ebfn an to\xe0n. C\u1ea3nh s\xe1t ph\u1ee5 tr\xe1ch ti\u1ebfp nh\u1eadn b\xe1o c\xe1o t\u1ed9i ph\u1ea1m v\xe0 duy tr\xec tr\u1eadt t\u1ef1, c\xf2n c\u01a1 quan c\u1ee9u h\u1ecfa ph\u1ee5 tr\xe1ch c\xe1c t\xecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p nh\u01b0 ch\xe1y, c\u1ee9u h\u1ed9 v\xe0 c\u1ea5p c\u1ee9u.\n\nC\u1ed9ng \u0111\u1ed3ng c\u0169ng c\xf3 c\xe1c c\u01a1 s\u1edf ph\u1ee5c v\u1ee5 \u0111\u1eddi s\u1ed1ng v\xe0 ho\u1ea1t \u0111\u1ed9ng v\u0103n h\xf3a.\n\nT\u1ea1i th\u01b0 vi\u1ec7n, kh\xf4ng ch\u1ec9 c\xf3 th\u1ec3 \u0111\u1ecdc ho\u1eb7c m\u01b0\u1ee3n s\xe1ch m\xe0 c\xf2n c\xf3 th\u1ec3 h\u1ecdc t\u1eadp, tham gia c\xe1c kh\xf3a h\u1ecdc v\xe0 ch\u01b0\u01a1ng tr\xecnh v\u0103n h\xf3a.\n\nC\xe1c trung t\xe2m ph\xfac l\u1ee3i x\xe3 h\u1ed9i c\u0169ng c\xf3 th\u1ec3 t\u1ed5 ch\u1ee9c nhi\u1ec1u ch\u01b0\u01a1ng tr\xecnh d\xe0nh cho tr\u1ebb em, thanh thi\u1ebfu ni\xean, ng\u01b0\u1eddi cao tu\u1ed5i, ng\u01b0\u1eddi khuy\u1ebft t\u1eadt v\xe0 c\xe1c nh\xf3m c\u01b0 d\xe2n kh\xe1c.\n\nTrung t\xe2m gia \u0111\xecnh ho\u1eb7c c\xe1c c\u01a1 quan h\u1ed7 tr\u1ee3 ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 th\u1ec3 cung c\u1ea5p tr\u1ee3 gi\xfap v\u1ec1 th\xedch nghi cu\u1ed9c s\u1ed1ng H\xe0n Qu\u1ed1c, \u0111\u1eddi s\u1ed1ng gia \u0111\xecnh, gi\xe1o d\u1ee5c ng\xf4n ng\u1eef v\xe0 t\u01b0 v\u1ea5n.\n\nKhi ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i s\u1ed1ng t\u1ea1i H\xe0n Qu\u1ed1c, \u0111\xf4i khi c\xf3 th\u1ec3 g\u1eb7p kh\xf3 kh\u0103n v\xec kh\xf4ng bi\u1ebft n\xean s\u1eed d\u1ee5ng c\u01a1 quan n\xe0o. Trong tr\u01b0\u1eddng h\u1ee3p \u0111\xf3, thay v\xec t\u1ef1 lo l\u1eafng, n\xean h\u1ecfi c\u01a1 quan h\xe0nh ch\xednh g\u1ea7n nh\u1ea5t ho\u1eb7c c\u01a1 quan h\u1ed7 tr\u1ee3 c\xf3 li\xean quan.\n\nNgo\xe0i ra, gi\u1edd ho\u1ea1t \u0111\u1ed9ng, gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft v\xe0 c\xe1ch \u0111\u0103ng k\xfd c\u1ee7a t\u1eebng c\u01a1 quan c\xf3 th\u1ec3 kh\xe1c nhau. V\xec v\u1eady ki\u1ec3m tra tr\u01b0\u1edbc b\u1eb1ng \u0111i\u1ec7n tho\u1ea1i ho\u1eb7c th\xf4ng tin ch\xednh th\u1ee9c s\u1ebd thu\u1eadn ti\u1ec7n h\u01a1n.\n\nN\u1ebfu hi\u1ec3u vai tr\xf2 c\u1ee7a c\xe1c c\u01a1 quan trong c\u1ed9ng \u0111\u1ed3ng, khi g\u1eb7p v\u1ea5n \u0111\u1ec1 ch\xfang ta c\xf3 th\u1ec3 t\xecm \u0111\u01b0\u1ee3c s\u1ef1 h\u1ed7 tr\u1ee3 c\u1ea7n thi\u1ebft nhanh h\u01a1n.\n","\uc5b4\ub290 \uae30\uad00\uc5d0 \uac00\uc57c \ud560\uae4c\uc694?","\uc548: \ubbfc\uc218 \uc528, \ud55c\uad6d\uc5d0\ub294 \uae30\uad00\uc774 \ub108\ubb34 \ub9ce\uc544\uc11c \uc5b4\ub514\ub85c \uac00\uc57c \ud560\uc9c0 \uc798 \ubaa8\ub974\uaca0\uc5b4\uc694.\n\n\ubbfc\uc218: \uc5b4\ub5a4 \uc77c\uc774 \uc788\uc5b4\uc694?\n\n\uc548: \uc0dd\ud65c \uad00\ub828 \ud589\uc815 \uc5c5\ubb34\ub97c \ubb3c\uc5b4\ubcf4\uace0 \uc2f6\uc5b4\uc694.\n\n\ubbfc\uc218: \uadf8\ub7ec\uba74 \uac00\uae4c\uc6b4 \uc8fc\ubbfc\uc13c\ud130\ub098 \ud589\uc815\ubcf5\uc9c0\uc13c\ud130\uc5d0 \uba3c\uc800 \ubb38\uc758\ud574 \ubcf4\uc138\uc694.\n\n\uc548: \uac74\uac15 \uad00\ub828 \uc0c1\ub2f4\uc744 \ubc1b\uace0 \uc2f6\uc73c\uba74\uc694?\n\n\ubbfc\uc218: \uc9c0\uc5ed \ubcf4\uac74\uc18c\uc5d0\uc11c \uac00\ub2a5\ud55c \uc11c\ube44\uc2a4\ub97c \ud655\uc778\ud574 \ubcfc \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \uc9c0\uac11\uc744 \uc783\uc5b4\ubc84\ub838\ub294\ub370 \uacbd\ucc30\uc5d0\ub3c4 \ubb38\uc758\ud560 \uc218 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \ub124. \ubd84\uc2e4\ubb3c\uc774\ub098 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \ubb38\uc81c\ub294 \uacbd\ucc30\uc5d0 \ubb38\uc758\ud560 \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \ud654\uc7ac\ub098 \uad6c\uc870\uac00 \ud544\uc694\ud55c \uae34\uae09 \uc0c1\ud669\uc740\uc694?\n\n\ubbfc\uc218: \uadf8\ub7f0 \uc0c1\ud669\uc740 \uc18c\ubc29\uae30\uad00\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544\uc57c \ud574\uc694.\n\n\uc548: \ud55c\uad6d\uc5b4 \uacf5\ubd80\ub3c4 \ud558\uace0 \ucc45\ub3c4 \ube4c\ub9ac\uace0 \uc2f6\uc740\ub370\uc694.\n\n\ubbfc\uc218: \uac00\uae4c\uc6b4 \ub3c4\uc11c\uad00\uc744 \uc774\uc6a9\ud574 \ubcf4\uc138\uc694. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e4\uc591\ud55c \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc788\uc5b4\uc694.\n\n\uc548: \uc678\uad6d\uc778\uc744 \uc704\ud55c \uc0dd\ud65c\uc0c1\ub2f4\uc744 \ubc1b\uace0 \uc2f6\uc73c\uba74 \uc5b4\ub514\ub85c \uac00\uba74 \ub420\uae4c\uc694?\n\n\ubbfc\uc218: \uc9c0\uc5ed\uc758 \uac00\uc871\uc13c\ud130\ub098 \uc678\uad6d\uc778\uc8fc\ubbfc \uc9c0\uc6d0\uae30\uad00\uc744 \ucc3e\uc544\ubcfc \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \uac00\uae30 \uc804\uc5d0 \uc900\ube44\ud574\uc57c \ud560 \uac83\uc774 \uc788\uc744\uae4c\uc694?\n\n\ubbfc\uc218: \uae30\uad00\ub9c8\ub2e4 \ud544\uc694\ud55c \uc11c\ub958\ub098 \uc6b4\uc601\uc2dc\uac04\uc774 \ub2e4\ub97c \uc218 \uc788\uc73c\ub2c8\uae4c \uba3c\uc800 \uc804\ud654\ub098 \uacf5\uc2dd \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc544\uc694.\n\n\uc548: \uc774\uc81c \uc5b4\ub290 \uae30\uad00\uc744 \uc774\uc6a9\ud574\uc57c \ud560\uc9c0 \uc870\uae08 \uc54c \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ud544\uc694\ud55c \uae30\uad00\uc744 \uc54c\uc544 \ub450\uba74 \ud55c\uad6d\uc0dd\ud65c\uc774 \ud6e8\uc52c \ud3b8\ub9ac\ud574\uc838\uc694.\n","An: Minsu, \u1edf H\xe0n Qu\u1ed1c c\xf3 qu\xe1 nhi\u1ec1u c\u01a1 quan n\xean t\xf4i kh\xf4ng bi\u1ebft ph\u1ea3i \u0111i \u0111\xe2u.\n\nMinsu: Anh \u0111ang c\xf3 vi\u1ec7c g\xec?\n\nAn: T\xf4i mu\u1ed1n h\u1ecfi m\u1ed9t th\u1ee7 t\u1ee5c h\xe0nh ch\xednh li\xean quan \u0111\u1ebfn \u0111\u1eddi s\u1ed1ng.\n\nMinsu: V\u1eady tr\u01b0\u1edbc ti\xean h\xe3y h\u1ecfi trung t\xe2m c\u01b0 d\xe2n ho\u1eb7c trung t\xe2m h\xe0nh ch\xednh v\xe0 ph\xfac l\u1ee3i g\u1ea7n nh\xe0.\n\nAn: N\u1ebfu mu\u1ed1n t\u01b0 v\u1ea5n v\u1ec1 s\u1ee9c kh\u1ecfe th\xec sao?\n\nMinsu: C\xf3 th\u1ec3 ki\u1ec3m tra c\xe1c d\u1ecbch v\u1ee5 \u0111\u01b0\u1ee3c cung c\u1ea5p t\u1ea1i trung t\xe2m y t\u1ebf c\xf4ng c\u1ed9ng c\u1ee7a \u0111\u1ecba ph\u01b0\u01a1ng.\n\nAn: T\xf4i l\xe0m m\u1ea5t v\xed, c\xf3 th\u1ec3 h\u1ecfi c\u1ea3nh s\xe1t kh\xf4ng?\n\nMinsu: C\xf3. Nh\u1eefng v\u1ea5n \u0111\u1ec1 li\xean quan \u0111\u1ebfn \u0111\u1ed3 th\u1ea5t l\u1ea1c ho\u1eb7c t\u1ed9i ph\u1ea1m c\xf3 th\u1ec3 h\u1ecfi c\u1ea3nh s\xe1t.\n\nAn: C\xf2n tr\u01b0\u1eddng h\u1ee3p kh\u1ea9n c\u1ea5p c\u1ea7n ch\u1eefa ch\xe1y hay c\u1ee9u h\u1ed9?\n\nMinsu: Nh\u1eefng t\xecnh hu\u1ed1ng \u0111\xf3 c\u1ea7n s\u1ef1 h\u1ed7 tr\u1ee3 c\u1ee7a c\u01a1 quan c\u1ee9u h\u1ecfa.\n\nAn: T\xf4i mu\u1ed1n h\u1ecdc ti\u1ebfng H\xe0n v\xe0 c\u0169ng mu\u1ed1n m\u01b0\u1ee3n s\xe1ch.\n\nMinsu: H\xe3y th\u1eed s\u1eed d\u1ee5ng th\u01b0 vi\u1ec7n g\u1ea7n nh\xe0. T\xf9y t\u1eebng \u0111\u1ecba ph\u01b0\u01a1ng c\u0169ng c\xf3 nhi\u1ec1u ch\u01b0\u01a1ng tr\xecnh kh\xe1c nhau.\n\nAn: N\u1ebfu mu\u1ed1n t\u01b0 v\u1ea5n \u0111\u1eddi s\u1ed1ng d\xe0nh cho ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i th\xec \u0111i \u0111\xe2u?\n\nMinsu: C\xf3 th\u1ec3 t\xecm trung t\xe2m gia \u0111\xecnh ho\u1eb7c c\u01a1 quan h\u1ed7 tr\u1ee3 c\u01b0 d\xe2n n\u01b0\u1edbc ngo\xe0i trong khu v\u1ef1c.\n\nAn: C\xf3 c\u1ea7n chu\u1ea9n b\u1ecb g\xec tr\u01b0\u1edbc khi \u0111\u1ebfn kh\xf4ng?\n\nMinsu: V\xec gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft v\xe0 gi\u1edd l\xe0m vi\u1ec7c c\u1ee7a t\u1eebng c\u01a1 quan c\xf3 th\u1ec3 kh\xe1c nhau n\xean t\u1ed1t nh\u1ea5t ki\u1ec3m tra tr\u01b0\u1edbc b\u1eb1ng \u0111i\u1ec7n tho\u1ea1i ho\u1eb7c h\u01b0\u1edbng d\u1eabn ch\xednh th\u1ee9c.\n\nAn: B\xe2y gi\u1edd t\xf4i \u0111\xe3 hi\u1ec3u h\u01a1n n\xean s\u1eed d\u1ee5ng c\u01a1 quan n\xe0o.\n\nMinsu: N\u1ebfu bi\u1ebft c\xe1c c\u01a1 quan c\u1ea7n thi\u1ebft th\xec cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c s\u1ebd thu\u1eadn ti\u1ec7n h\u01a1n nhi\u1ec1u.\n",A.k0F,A.m_8,A.kx_,A.lsV)
A.kjh=s(["Hi\u1ec3u \xfd ngh\u0129a c\u01a1 b\u1ea3n c\u1ee7a \ubcf4\uc721 v\xe0 \ubcf4\uc721\uc81c\ub3c4.","Bi\u1ebft c\xe1c c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb em nh\u01b0 \uc5b4\ub9b0\uc774\uc9d1 v\xe0 \uc720\uce58\uc6d0.","Hi\u1ec3u vai tr\xf2 c\u1ee7a gia \u0111\xecnh v\xe0 x\xe3 h\u1ed9i trong vi\u1ec7c ch\u0103m s\xf3c tr\u1ebb em.","H\u1ecdc t\u1eeb v\u1ef1ng li\xean quan \u0111\u1ebfn nu\xf4i d\u1ea1y v\xe0 ch\u0103m s\xf3c tr\u1ebb.","Bi\u1ebft c\xe1ch h\u1ecfi th\xf4ng tin v\u1ec1 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb em.","C\xf3 th\u1ec3 \u0111\u1ecdc hi\u1ec3u \u0111o\u1ea1n v\u0103n ng\u1eafn v\u1ec1 ch\u1ebf \u0111\u1ed9 ch\u0103m s\xf3c tr\u1ebb em.","Luy\u1ec7n c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn b\u1ea3o\u80b2 v\xe0 gia \u0111\xecnh."],t.s)
A.jKr=s([u.D4,"\ud55c\uad6d\uc5d0\ub294 \uc5b4\ub9b0\uc774\uc9d1\uacfc \uc720\uce58\uc6d0 \ub4f1 \uc544\uc774\ub4e4\uc744 \uc704\ud55c \ub2e4\uc591\ud55c \uae30\uad00\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc5b4\ub9b0\uc774\uc9d1\uc740 \uc601\uc720\uc544\uc758 \ubcf4\uc721\uc744 \ub2f4\ub2f9\ud558\ub294 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc785\ub2c8\ub2e4.","\uc720\uce58\uc6d0\uc740 \uc720\uc544\uc758 \uad50\uc721\uacfc \uc0dd\ud65c \uc9c0\ub3c4\ub97c \ub2f4\ub2f9\ud558\ub294 \uad50\uc721\uae30\uad00\uc785\ub2c8\ub2e4.","\ub9de\ubc8c\uc774 \uac00\uc815\uc774 \ub298\uc5b4\ub098\uba74\uc11c \ubcf4\uc721\uc11c\ube44\uc2a4\uc758 \uc911\uc694\uc131\ub3c4 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.",u.JR,"\uac00\uc815\uacfc \ubcf4\uc721\uae30\uad00\uc774 \uc11c\ub85c \ud611\ub825\ud558\uba74 \uc544\uc774\uc758 \uac74\uac15\ud55c \uc131\uc7a5\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4."],t.s)
