A.js7=s(["\uad6d\uc81c\uad00\uacc4 = quan h\u1ec7 qu\u1ed1c t\u1ebf n\xf3i chung; \uc678\uad50 = ho\u1ea1t \u0111\u1ed9ng ngo\u1ea1i giao gi\u1eefa c\xe1c qu\u1ed1c gia.","\uc218\ucd9c = b\xe1n/g\u1eedi h\xe0ng h\xf3a ra n\u01b0\u1edbc ngo\xe0i; \uc218\uc785 = \u0111\u01b0a h\xe0ng h\xf3a t\u1eeb n\u01b0\u1edbc ngo\xe0i v\xe0o.","\uad6d\uc81c\uae30\uad6c = t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf; \uc720\uc5d4 l\xe0 m\u1ed9t v\xed d\u1ee5 ti\xeau bi\u1ec3u.","\uad6d\uc81c\ud611\ub825 kh\xf4ng ch\u1ec9 li\xean quan \u0111\u1ebfn kinh t\u1ebf m\xe0 c\xf2n c\xf3 m\xf4i tr\u01b0\u1eddng, y t\u1ebf, gi\xe1o d\u1ee5c v\xe0 nhi\u1ec1u l\u0129nh v\u1ef1c kh\xe1c.","\uad50\ub958 = trao \u0111\u1ed5i/giao l\u01b0u; \ud611\ub825 = c\xf9ng h\u1ee3p t\xe1c \u0111\u1ec3 th\u1ef1c hi\u1ec7n m\u1ee5c ti\xeau.","\uc138\uacc4\ud654 = qu\xe1 tr\xecnh c\xe1c qu\u1ed1c gia v\xe0 x\xe3 h\u1ed9i ng\xe0y c\xe0ng k\u1ebft n\u1ed1i ch\u1eb7t ch\u1ebd.","\uc0c1\ud638 \uc758\uc874 = c\xe1c qu\u1ed1c gia ph\u1ee5 thu\u1ed9c v\xe0 \u1ea3nh h\u01b0\u1edfng l\u1eabn nhau.","\uac08\ub4f1\uc774 \uc0dd\uacbc\uc744 \ub54c \ud3c9\ud654\uc801\uc778 \ub300\ud654\uc640 \ud611\ub825\uc744 \ud1b5\ud574 \ud574\uacb0\ud558\ub824\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.lpO=s(["\uad6d\uc81c\uad00\uacc4 \u2192 quan h\u1ec7 gi\u1eefa c\xe1c qu\u1ed1c gia.","\uc678\uad50 \u2192 ho\u1ea1t \u0111\u1ed9ng x\xe2y d\u1ef1ng v\xe0 duy tr\xec quan h\u1ec7 v\u1edbi c\xe1c n\u01b0\u1edbc kh\xe1c.","\uad6d\uc81c\uc0ac\ud68c \u2192 c\u1ed9ng \u0111\u1ed3ng qu\u1ed1c t\u1ebf.","\uad6d\uc81c\uae30\uad6c \u2192 t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf.","\uc720\uc5d4 \u2192 m\u1ed9t t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf ti\xeau bi\u1ec3u.","\ubb34\uc5ed \u2192 ho\u1ea1t \u0111\u1ed9ng th\u01b0\u01a1ng m\u1ea1i gi\u1eefa c\xe1c qu\u1ed1c gia.","\uc218\ucd9c \u2192 xu\u1ea5t kh\u1ea9u.","\uc218\uc785 \u2192 nh\u1eadp kh\u1ea9u.","\uad6d\uc81c\ud611\ub825 \u2192 h\u1ee3p t\xe1c qu\u1ed1c t\u1ebf.","\ubb38\ud654\uad50\ub958 \u2192 giao l\u01b0u v\u0103n h\xf3a.","\uc138\uacc4\ud654\ub85c \uad6d\uac00 \uac04\uc758 \uc0c1\ud638 \uc758\uc874\uc774 \ucee4\uc9c0\uace0 \uc788\ub2e4.","\ud658\uacbd\uacfc \uac10\uc5fc\ubcd1 \uac19\uc740 \ubb38\uc81c\ub294 \uad6d\uc81c\ud611\ub825\uc774 \uc911\uc694\ud558\ub2e4.","\uad6d\uac00 \uac04 \uac08\ub4f1\uc740 \ud3c9\ud654\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \ud574\uacb0\ud558\ub824\ub294 \ub178\ub825\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
A.YJ=s(["\uad6d\uac00\uc640 \uad6d\uac00 \uc0ac\uc774\uc758 \ub2e4\uc591\ud55c \uad00\uacc4","\ud55c \uac00\uc871 \uc548\uc758 \uad00\uacc4","\ud55c \ud68c\uc0ac\uc758 \uc9c1\uc6d0 \uad00\uacc4","\ud559\uad50 \uce5c\uad6c \uad00\uacc4\ub9cc\uc744 \uc758\ubbf8\ud558\ub294 \uac83"],t.s)
A.haJ=new B.S("\u201c\uad6d\uc81c\uad00\uacc4\u201d\uc758 \ub73b\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a ph\xf9 h\u1ee3p nh\u1ea5t c\u1ee7a \uad6d\uc81c\uad00\uacc4 l\xe0 g\xec?",A.YJ,0,"\uad6d\uc81c\uad00\uacc4 l\xe0 nh\u1eefng m\u1ed1i quan h\u1ec7 \u0111a d\u1ea1ng gi\u1eefa c\xe1c qu\u1ed1c gia.")
