A.hav=new B.S("\uad6d\uc81c\ud611\ub825\uc774 \ud2b9\ud788 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","V\u1ea5n \u0111\u1ec1 n\xe0o \u0111\u1eb7c bi\u1ec7t c\u1ea7n h\u1ee3p t\xe1c qu\u1ed1c t\u1ebf?",A.a4a,0,"C\xe1c v\u1ea5n \u0111\u1ec1 xuy\xean bi\xean gi\u1edbi nh\u01b0 kh\xed h\u1eadu v\xe0 b\u1ec7nh truy\u1ec1n nhi\u1ec5m c\u1ea7n s\u1ef1 h\u1ee3p t\xe1c qu\u1ed1c t\u1ebf.")
A.a6G=s(["\uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\ubaa8\ub4e0 \ub098\ub77c\uc758 \ubb38\ud654\ub97c \uac19\uac8c \ub9cc\ub4e0\ub2e4.","\ub2e4\ub978 \ub098\ub77c\uc640 \ub300\ud654\ub97c \ud558\uc9c0 \uc54a\uac8c \ud55c\ub2e4.","\uad6d\uc81c\uad00\uacc4\ub97c \uc5c6\uc564\ub2e4."],t.s)
A.h9W=new B.S("\ubb38\ud654\uad50\ub958\uc758 \uae0d\uc815\uc801\uc778 \ud6a8\uacfc\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 t\xe1c d\u1ee5ng t\xedch c\u1ef1c c\u1ee7a giao l\u01b0u v\u0103n h\xf3a?",A.a6G,0,"Giao l\u01b0u v\u0103n h\xf3a gi\xfap m\u1ecdi ng\u01b0\u1eddi hi\u1ec3u v\u0103n h\xf3a c\u1ee7a nhau.")
A.a7P=s(["\uad6d\uac00 \uac04\uc758 \uad50\ub958\uc640 \uc5f0\uacb0\uc774 \uc99d\uac00\ud55c\ub2e4.","\ubaa8\ub4e0 \uad6d\uac00\uac00 \uc11c\ub85c \uad00\uacc4\ub97c \ub04a\ub294\ub2e4.","\ubb34\uc5ed\uc774 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c4\ub2e4.","\ud55c \uc9c0\uc5ed \uc548\uc5d0\uc11c\ub9cc \uc0dd\ud65c\ud574\uc57c \ud55c\ub2e4."],t.s)
A.h6o=new B.S("\u201c\uc138\uacc4\ud654\u201d\uc640 \uac00\uc7a5 \uad00\ub828\uc774 \uc788\ub294 \uc124\uba85\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","M\xf4 t\u1ea3 n\xe0o li\xean quan nh\u1ea5t \u0111\u1ebfn to\xe0n c\u1ea7u h\xf3a?",A.a7P,0,"\uc138\uacc4\ud654 l\xe0m t\u0103ng k\u1ebft n\u1ed1i v\xe0 giao l\u01b0u gi\u1eefa c\xe1c qu\u1ed1c gia.")
A.YD=s(["\ub300\ud654\uc640 \ud611\ub825\uc744 \ud1b5\ud574 \ud3c9\ud654\uc801\uc73c\ub85c \ud574\uacb0\ud55c\ub2e4.","\ud56d\uc0c1 \ud798\uc73c\ub85c \ud574\uacb0\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc758 \uc758\uacac\uc744 \uc804\ud600 \ub4e3\uc9c0 \uc54a\ub294\ub2e4.","\ubaa8\ub4e0 \uad6d\uc81c\uad00\uacc4\ub97c \uc911\ub2e8\ud55c\ub2e4."],t.s)
A.h6D=new B.S("\uad6d\uac00 \uac04 \uac08\ub4f1\uc744 \ud574\uacb0\ud558\ub294 \ubc14\ub78c\uc9c1\ud55c \ubc29\ubc95\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\xe1ch ph\xf9 h\u1ee3p \u0111\u1ec3 gi\u1ea3i quy\u1ebft xung \u0111\u1ed9t gi\u1eefa c\xe1c qu\u1ed1c gia l\xe0 g\xec?",A.YD,0,"\u0110\u1ed1i tho\u1ea1i v\xe0 h\u1ee3p t\xe1c h\xf2a b\xecnh l\xe0 ph\u01b0\u01a1ng th\u1ee9c ph\xf9 h\u1ee3p \u0111\u1ec3 gi\u1ea3i quy\u1ebft xung \u0111\u1ed9t.")
A.a7D=s(["\ud55c\uad6d\uc740 \uc5ec\ub7ec \ub098\ub77c\uc640 \ub2e4\uc591\ud55c \ubd84\uc57c\uc5d0\uc11c \uad50\ub958\ud558\uace0 \uc788\ub2e4.","\uad6d\uc81c\ud611\ub825\uc740 \uacbd\uc81c \ubd84\uc57c\uc5d0\ub9cc \ud544\uc694\ud558\ub2e4.","\ud55c\uad6d\uc740 \ub2e4\ub978 \ub098\ub77c\uc640 \ubb34\uc5ed\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc138\uacc4\ud654\uac00 \uc9c4\ud589\ub420\uc218\ub85d \uad6d\uac00 \uac04 \uad50\ub958\uac00 \uc904\uc5b4\ub4e0\ub2e4."],t.s)
A.h9i=new B.S("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.a7D,0,"H\xe0n Qu\u1ed1c giao l\u01b0u v\xe0 h\u1ee3p t\xe1c v\u1edbi nhi\u1ec1u qu\u1ed1c gia trong nhi\u1ec1u l\u0129nh v\u1ef1c.")
A.lnh=s([A.haJ,A.h40,A.h6y,A.h6p,A.hat,A.hav,A.h9W,A.h6o,A.h6D,A.h9i],t.h)
A.jIm=s(["\uad6d\uc81c\uad00\uacc4 = quan h\u1ec7 qu\u1ed1c t\u1ebf.","\uc678\uad50 = ngo\u1ea1i giao.","\uad6d\uc81c\uc0ac\ud68c = c\u1ed9ng \u0111\u1ed3ng qu\u1ed1c t\u1ebf.","\uad6d\uc81c\uae30\uad6c = t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf.","\uc720\uc5d4 = Li\xean H\u1ee3p Qu\u1ed1c.","\ubb34\uc5ed = th\u01b0\u01a1ng m\u1ea1i.","\uc218\ucd9c = xu\u1ea5t kh\u1ea9u.","\uc218\uc785 = nh\u1eadp kh\u1ea9u.","\uad6d\uc81c\ud611\ub825 = h\u1ee3p t\xe1c qu\u1ed1c t\u1ebf.","\ubb38\ud654\uad50\ub958 = giao l\u01b0u v\u0103n h\xf3a.","\uc138\uacc4\ud654 = to\xe0n c\u1ea7u h\xf3a.","\ud3c9\ud654 = h\xf2a b\xecnh.","\uc138\uacc4\ud654\ub85c \uad6d\uac00 \uac04\uc758 \uad50\ub958\uc640 \uc0c1\ud638 \uc758\uc874\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\uad6d\uc81c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec \ub098\ub77c\uc758 \ud611\ub825\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.h2K=new B.dQ(24,"\uc815\uce58","\ud55c\uad6d\uc758 \uad6d\uc81c\uad00\uacc4","Quan h\u1ec7 qu\u1ed1c t\u1ebf c\u1ee7a H\xe0n Qu\u1ed1c",A.kx4,A.kNi,A.k_T,A.jFH,"\uc138\uacc4\uc640 \ud611\ub825\ud558\ub294 \ud55c\uad6d","\uc624\ub298\ub0a0 \uc138\uacc4\uc758 \uc5ec\ub7ec \ub098\ub77c\ub294 \uc11c\ub85c \ubc00\uc811\ud55c \uad00\uacc4\ub97c \ub9fa\uc73c\uba70 \uc0b4\uc544\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uad6d\uac00\uc640 \uad6d\uac00 \uc0ac\uc774\uc758 \uc815\uce58, \uacbd\uc81c, \ubb38\ud654 \ub4f1 \ub2e4\uc591\ud55c \uad00\uacc4\ub97c \uad6d\uc81c\uad00\uacc4\ub77c\uace0 \ud569\ub2c8\ub2e4. \ub2e4\ub978 \ub098\ub77c\uc640 \uacf5\uc2dd\uc801\uc778 \uad00\uacc4\ub97c \ub9fa\uace0 \uad6d\uac00\uc758 \uc774\uc775\uacfc \ud3c9\ud654\ub97c \uc704\ud574 \ud65c\ub3d9\ud558\ub294 \uac83\uc744 \uc678\uad50\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc740 \uc138\uacc4 \uc5ec\ub7ec \ub098\ub77c\uc640 \uc678\uad50\uad00\uacc4\ub97c \ub9fa\uace0 \uacbd\uc81c, \ubb38\ud654, \uacfc\ud559, \uad50\uc721 \ub4f1 \ub2e4\uc591\ud55c \ubd84\uc57c\uc5d0\uc11c \uad50\ub958\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud2b9\ud788 \ud55c\uad6d \uacbd\uc81c\uc5d0\uc11c\ub294 \ubb34\uc5ed\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \ud55c\uad6d \uae30\uc5c5\uc740 \uc790\ub3d9\ucc28, \uc804\uc790\uc81c\ud488 \ub4f1 \ub2e4\uc591\ud55c \uc0c1\ud488\uc744 \ud574\uc678\uc5d0 \uc218\ucd9c\ud558\uace0, \uad6d\ub0b4\uc5d0\uc11c \ud544\uc694\ud55c \uc6d0\ub8cc\ub098 \uc0c1\ud488\uc744 \uc678\uad6d\uc5d0\uc11c \uc218\uc785\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\ub610\ud55c \ud55c\uad6d\uc740 \uc720\uc5d4\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \uad6d\uc81c\uae30\uad6c\uc758 \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74\uc11c \uad6d\uc81c\uc0ac\ud68c\uc640 \ud611\ub825\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uad6d\uc81c\ud611\ub825\uc740 \uacbd\uc81c \ubd84\uc57c\uc5d0\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uae30\ud6c4\ubcc0\ud654, \ud658\uacbd, \uac10\uc5fc\ubcd1, \uc7ac\ub09c\uacfc \uac19\uc740 \ubb38\uc81c\ub294 \ud55c \uad6d\uac00\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5ec\ub7ec \ub098\ub77c\uac00 \uc815\ubcf4\ub97c \ub098\ub204\uace0 \ud568\uaed8 \ub300\uc751\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\ubb38\ud654\uad50\ub958\ub3c4 \uad6d\uc81c\uad00\uacc4\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc785\ub2c8\ub2e4. \ud55c\uad6d\uc758 \uc74c\uc545, \ub4dc\ub77c\ub9c8, \uc74c\uc2dd \ub4f1\uc774 \ud574\uc678\uc5d0 \uc54c\ub824\uc9c0\uace0 \ub2e4\ub978 \ub098\ub77c\uc758 \ubb38\ud654\ub3c4 \ud55c\uad6d\uc5d0 \uc18c\uac1c\ub418\uba74\uc11c \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc138\uacc4\ud654\uac00 \uc9c4\ud589\ub420\uc218\ub85d \uad6d\uac00\ub4e4\uc740 \uc11c\ub85c \ub354 \ub9ce\uc740 \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\uac8c \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub2e4\ub978 \ub098\ub77c\ub97c \uc774\ud574\ud558\uace0 \ud3c9\ud654\uc640 \ud611\ub825\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\n","Ng\xe0y nay, c\xe1c qu\u1ed1c gia tr\xean th\u1ebf gi\u1edbi s\u1ed1ng trong m\u1ed1i quan h\u1ec7 ng\xe0y c\xe0ng ch\u1eb7t ch\u1ebd v\u1edbi nhau.\n\nC\xe1c m\u1ed1i quan h\u1ec7 \u0111a d\u1ea1ng nh\u01b0 ch\xednh tr\u1ecb, kinh t\u1ebf v\xe0 v\u0103n h\xf3a gi\u1eefa c\xe1c qu\u1ed1c gia \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 quan h\u1ec7 qu\u1ed1c t\u1ebf. Vi\u1ec7c thi\u1ebft l\u1eadp quan h\u1ec7 ch\xednh th\u1ee9c v\u1edbi c\xe1c qu\u1ed1c gia kh\xe1c v\xe0 ho\u1ea1t \u0111\u1ed9ng v\xec l\u1ee3i \xedch qu\u1ed1c gia c\u0169ng nh\u01b0 h\xf2a b\xecnh \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 ngo\u1ea1i giao.\n\nH\xe0n Qu\u1ed1c thi\u1ebft l\u1eadp quan h\u1ec7 ngo\u1ea1i giao v\u1edbi nhi\u1ec1u qu\u1ed1c gia tr\xean th\u1ebf gi\u1edbi v\xe0 giao l\u01b0u trong c\xe1c l\u0129nh v\u1ef1c nh\u01b0 kinh t\u1ebf, v\u0103n h\xf3a, khoa h\u1ecdc v\xe0 gi\xe1o d\u1ee5c.\n\n\u0110\u1eb7c bi\u1ec7t, th\u01b0\u01a1ng m\u1ea1i \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng trong n\u1ec1n kinh t\u1ebf H\xe0n Qu\u1ed1c. C\xe1c doanh nghi\u1ec7p H\xe0n Qu\u1ed1c xu\u1ea5t kh\u1ea9u nhi\u1ec1u lo\u1ea1i h\xe0ng h\xf3a nh\u01b0 \xf4 t\xf4 v\xe0 s\u1ea3n ph\u1ea9m \u0111i\u1ec7n t\u1eed ra n\u01b0\u1edbc ngo\xe0i, \u0111\u1ed3ng th\u1eddi nh\u1eadp kh\u1ea9u nguy\xean li\u1ec7u v\xe0 h\xe0ng h\xf3a c\u1ea7n thi\u1ebft t\u1eeb c\xe1c n\u01b0\u1edbc kh\xe1c.\n\nNgo\xe0i ra, H\xe0n Qu\u1ed1c tham gia ho\u1ea1t \u0111\u1ed9ng c\u1ee7a Li\xean H\u1ee3p Qu\u1ed1c v\xe0 nhi\u1ec1u t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf kh\xe1c \u0111\u1ec3 h\u1ee3p t\xe1c v\u1edbi c\u1ed9ng \u0111\u1ed3ng qu\u1ed1c t\u1ebf.\n\nH\u1ee3p t\xe1c qu\u1ed1c t\u1ebf kh\xf4ng ch\u1ec9 c\u1ea7n thi\u1ebft trong l\u0129nh v\u1ef1c kinh t\u1ebf. Nh\u1eefng v\u1ea5n \u0111\u1ec1 nh\u01b0 bi\u1ebfn \u0111\u1ed5i kh\xed h\u1eadu, m\xf4i tr\u01b0\u1eddng, b\u1ec7nh truy\u1ec1n nhi\u1ec5m v\xe0 thi\xean tai th\u01b0\u1eddng kh\xf3 c\xf3 th\u1ec3 gi\u1ea3i quy\u1ebft ch\u1ec9 b\u1eb1ng n\u1ed7 l\u1ef1c c\u1ee7a m\u1ed9t qu\u1ed1c gia. V\xec v\u1eady, nhi\u1ec1u n\u01b0\u1edbc c\u1ea7n chia s\u1ebb th\xf4ng tin v\xe0 c\xf9ng \u1ee9ng ph\xf3.\n\nGiao l\u01b0u v\u0103n h\xf3a c\u0169ng l\xe0 m\u1ed9t ph\u1ea7n quan tr\u1ecdng c\u1ee7a quan h\u1ec7 qu\u1ed1c t\u1ebf. Khi \xe2m nh\u1ea1c, phim truy\u1ec1n h\xecnh v\xe0 \u1ea9m th\u1ef1c H\xe0n Qu\u1ed1c \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u ra n\u01b0\u1edbc ngo\xe0i, \u0111\u1ed3ng th\u1eddi v\u0103n h\xf3a c\xe1c n\u01b0\u1edbc kh\xe1c \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u t\u1ea1i H\xe0n Qu\u1ed1c, s\u1ef1 giao l\u01b0u gi\u1eefa con ng\u01b0\u1eddi ng\xe0y c\xe0ng s\xf4i \u0111\u1ed9ng.\n\nTo\xe0n c\u1ea7u h\xf3a c\xe0ng ph\xe1t tri\u1ec3n th\xec c\xe1c qu\u1ed1c gia c\xe0ng \u1ea3nh h\u01b0\u1edfng l\u1eabn nhau nhi\u1ec1u h\u01a1n. V\xec v\u1eady, c\u1ea7n c\xf3 th\xe1i \u0111\u1ed9 hi\u1ec3u c\xe1c qu\u1ed1c gia kh\xe1c v\xe0 coi tr\u1ecdng h\xf2a b\xecnh c\u0169ng nh\u01b0 h\u1ee3p t\xe1c.\n","\ud55c\uad6d\uacfc \uc138\uacc4\uc758 \uad00\uacc4 \uc774\uc57c\uae30\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \ud55c\uad6d\uc740 \uc65c \ub2e4\ub978 \ub098\ub77c\uc640 \ud611\ub825\ud574\uc57c \ud574\uc694?\n\n\ubbfc\uc218: \uc694\uc998\uc740 \ud55c \ub098\ub77c\ub9cc\uc758 \ud798\uc73c\ub85c \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\uac00 \ub9ce\uae30 \ub54c\ubb38\uc774\uc5d0\uc694.\n\n\uc548: \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \ud658\uacbd \ubb38\uc81c\ub098 \uac10\uc5fc\ubcd1, \uacbd\uc81c \ubb38\uc81c \uac19\uc740 \uac83\uc774 \uc788\uc5b4\uc694.\n\n\uc548: \ubb34\uc5ed\ub3c4 \uad6d\uc81c\uad00\uacc4\uc5d0 \ud3ec\ud568\ub418\uc9c0\uc694?\n\n\ubbfc\uc218: \ubb3c\ub860\uc774\uc8e0. \ud55c\uad6d\uc740 \uc5ec\ub7ec \ub098\ub77c\uc5d0 \uc0c1\ud488\uc744 \uc218\ucd9c\ud558\uace0 \ud544\uc694\ud55c \uac83\uc744 \uc218\uc785\ud558\uae30\ub3c4 \ud574\uc694.\n\n\uc548: \ubb38\ud654\uad50\ub958\ub3c4 \uc911\uc694\ud55c \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \ud55c\uad6d \ubb38\ud654\uac00 \uc678\uad6d\uc5d0 \uc54c\ub824\uc9c0\uace0 \ub2e4\ub978 \ub098\ub77c\uc758 \ubb38\ud654\ub3c4 \ud55c\uad6d\uc5d0 \ub9ce\uc774 \uc18c\uac1c\ub418\uace0 \uc788\uc5b4\uc694.\n\n\uc548: \uad6d\uc81c\uae30\uad6c\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \uc77c\uc744 \ud574\uc694?\n\n\ubbfc\uc218: \uc5ec\ub7ec \ub098\ub77c\uac00 \ud568\uaed8 \ud574\uacb0\ud574\uc57c \ud558\ub294 \ubb38\uc81c\ub97c \ub17c\uc758\ud558\uace0 \ud611\ub825\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\uc548: \uacb0\uad6d \uc138\uacc4\ud654 \ub54c\ubb38\uc5d0 \ub098\ub77c\ub4e4\uc774 \uc11c\ub85c \ub354 \uac00\uae4c\uc6cc\uc9c4 \uac70\ub124\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\uc11c \ub2e4\ub978 \ub098\ub77c\ub97c \uc774\ud574\ud558\uace0 \ud611\ub825\ud558\ub294 \ud0dc\ub3c4\uac00 \ub354 \uc911\uc694\ud574\uc9c0\uace0 \uc788\uc5b4\uc694.\n","An: Minsu, t\u1ea1i sao H\xe0n Qu\u1ed1c c\u1ea7n h\u1ee3p t\xe1c v\u1edbi c\xe1c n\u01b0\u1edbc kh\xe1c?\n\nMinsu: V\xec ng\xe0y nay c\xf3 nhi\u1ec1u v\u1ea5n \u0111\u1ec1 kh\xf3 gi\u1ea3i quy\u1ebft ch\u1ec9 b\u1eb1ng s\u1ee9c c\u1ee7a m\u1ed9t qu\u1ed1c gia.\n\nAn: V\xed d\u1ee5 nh\u01b0 nh\u1eefng v\u1ea5n \u0111\u1ec1 n\xe0o?\n\nMinsu: Nh\u01b0 m\xf4i tr\u01b0\u1eddng, b\u1ec7nh truy\u1ec1n nhi\u1ec5m ho\u1eb7c c\xe1c v\u1ea5n \u0111\u1ec1 kinh t\u1ebf.\n\nAn: Th\u01b0\u01a1ng m\u1ea1i c\u0169ng thu\u1ed9c quan h\u1ec7 qu\u1ed1c t\u1ebf \u0111\xfang kh\xf4ng?\n\nMinsu: T\u1ea5t nhi\xean. H\xe0n Qu\u1ed1c xu\u1ea5t kh\u1ea9u h\xe0ng h\xf3a sang nhi\u1ec1u n\u01b0\u1edbc v\xe0 c\u0169ng nh\u1eadp kh\u1ea9u nh\u1eefng th\u1ee9 c\u1ea7n thi\u1ebft.\n\nAn: T\xf4i ngh\u0129 giao l\u01b0u v\u0103n h\xf3a c\u0169ng quan tr\u1ecdng.\n\nMinsu: \u0110\xfang v\u1eady. V\u0103n h\xf3a H\xe0n Qu\u1ed1c \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u ra n\u01b0\u1edbc ngo\xe0i v\xe0 v\u0103n h\xf3a c\xe1c n\u01b0\u1edbc kh\xe1c c\u0169ng \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u nhi\u1ec1u t\u1ea1i H\xe0n Qu\u1ed1c.\n\nAn: C\xe1c t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf l\xe0m g\xec?\n\nMinsu: H\u1ecd c\xf3 vai tr\xf2 \u0111\u1ec3 nhi\u1ec1u qu\u1ed1c gia c\xf9ng th\u1ea3o lu\u1eadn v\xe0 h\u1ee3p t\xe1c gi\u1ea3i quy\u1ebft nh\u1eefng v\u1ea5n \u0111\u1ec1 chung.\n\nAn: Cu\u1ed1i c\xf9ng th\xec do to\xe0n c\u1ea7u h\xf3a, c\xe1c qu\u1ed1c gia ng\xe0y c\xe0ng g\u1ea7n nhau h\u01a1n nh\u1ec9.\n\nMinsu: \u0110\xfang v\u1eady. V\xec th\u1ebf th\xe1i \u0111\u1ed9 hi\u1ec3u v\xe0 h\u1ee3p t\xe1c v\u1edbi c\xe1c qu\u1ed1c gia kh\xe1c ng\xe0y c\xe0ng quan tr\u1ecdng.\n",A.js7,A.lpO,A.lnh,A.jIm)
A.jnE=s(["Hi\u1ec3u m\u1ed1i quan h\u1ec7 gi\u1eefa kinh t\u1ebf H\xe0n Qu\u1ed1c v\xe0 kinh t\u1ebf th\u1ebf gi\u1edbi.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \ubb34\uc5ed, \uc218\ucd9c v\xe0 \uc218\uc785.","Bi\u1ebft kh\xe1i ni\u1ec7m \uc138\uacc4\uc2dc\uc7a5 v\xe0 \uc790\uc720\ubb34\uc5ed.","Hi\u1ec3u \xfd ngh\u0129a c\u01a1 b\u1ea3n c\u1ee7a FTA.","Bi\u1ebft v\xec sao t\u1ef7 gi\xe1 v\xe0 gi\xe1 nguy\xean li\u1ec7u c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn n\u1ec1n kinh t\u1ebf.","Hi\u1ec3u vai tr\xf2 c\u1ee7a doanh nghi\u1ec7p H\xe0n Qu\u1ed1c tr\xean th\u1ecb tr\u01b0\u1eddng qu\u1ed1c t\u1ebf.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn kinh t\u1ebf to\xe0n c\u1ea7u."],t.s)
A.m3h=s(["\ud55c\uad6d \uacbd\uc81c\ub294 \uc138\uacc4 \uc5ec\ub7ec \ub098\ub77c\uc758 \uacbd\uc81c\uc640 \ubc00\uc811\ud558\uac8c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.",u.Y9,u.el,"\uc5d0\ub108\uc9c0\uc640 \uc6d0\uc790\uc7ac \ub4f1\uc740 \ud574\uc678\uc5d0\uc11c \uc218\uc785\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.","\uc138\uacc4 \uacbd\uc81c \uc0c1\ud669\uc774 \ubcc0\ud558\uba74 \ud55c\uad6d \uacbd\uc81c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud658\uc728 \ubcc0\ud654\ub294 \uc218\ucd9c\uacfc \uc218\uc785 \uac00\uaca9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc790\uc720\ubb34\uc5ed\ud611\uc815\uc778 FTA\ub294 \uad6d\uac00 \uac04 \ubb34\uc5ed\uc744 \ud655\ub300\ud558\ub294 \ub370 \uc774\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.vX],t.s)
A.hhO=new B.v("\uc138\uacc4\uacbd\uc81c","kinh t\u1ebf th\u1ebf gi\u1edbi","\uc138\uacc4\uacbd\uc81c\uc758 \ubcc0\ud654\ub294 \ud55c\uad6d \uacbd\uc81c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Nh\u1eefng thay \u0111\u1ed5i c\u1ee7a kinh t\u1ebf th\u1ebf gi\u1edbi c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn kinh t\u1ebf H\xe0n Qu\u1ed1c.")
