A.hbV=new B.an("\ud55c\uad6d\uc740 \uc5ec\ub7ec \uc81c\ud488\uc744 \uc218\ucd9c\ud558\ub294 \ub3d9\uc2dc\uc5d0 \ud544\uc694\ud55c \uc790\uc6d0\uc744 \uc218\uc785\ud569\ub2c8\ub2e4.","H\xe0n Qu\u1ed1c v\u1eeba xu\u1ea5t kh\u1ea9u nhi\u1ec1u s\u1ea3n ph\u1ea9m, \u0111\u1ed3ng th\u1eddi nh\u1eadp kh\u1ea9u c\xe1c ngu\u1ed3n t\xe0i nguy\xean c\u1ea7n thi\u1ebft.","-\ub294 \ub3d9\uc2dc\uc5d0 = \u0111\u1ed3ng th\u1eddi.")
A.hdT=new B.an("\ud658\uc728\uc774 \ubcc0\ud558\uba74 \uc218\ucd9c\uacfc \uc218\uc785\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu t\u1ef7 gi\xe1 thay \u0111\u1ed5i th\xec xu\u1ea5t kh\u1ea9u v\xe0 nh\u1eadp kh\u1ea9u c\u0169ng c\xf3 th\u1ec3 b\u1ecb \u1ea3nh h\u01b0\u1edfng.","-(\uc73c)\uba74 = n\u1ebfu. \uc601\ud5a5\uc744 \uc8fc\ub2e4 = g\xe2y \u1ea3nh h\u01b0\u1edfng.")
A.hfD=new B.an("FTA\ub294 \uad6d\uac00 \uac04 \ubb34\uc5ed\uc744 \ud655\ub300\ud558\uae30 \uc704\ud55c \ud611\uc815\uc785\ub2c8\ub2e4.","FTA l\xe0 hi\u1ec7p \u0111\u1ecbnh nh\u1eb1m m\u1edf r\u1ed9ng th\u01b0\u01a1ng m\u1ea1i gi\u1eefa c\xe1c qu\u1ed1c gia.","-\uae30 \uc704\ud55c = nh\u1eb1m \u0111\u1ec3. \ud611\uc815 = hi\u1ec7p \u0111\u1ecbnh.")
A.hbS=new B.an("\uc138\uacc4\uc2dc\uc7a5\uc5d0\uc11c \uacbd\uc7c1\ud558\ub824\uba74 \uae30\uc220\uacfc \ud488\uc9c8\uc744 \ub192\uc5ec\uc57c \ud569\ub2c8\ub2e4.","Mu\u1ed1n c\u1ea1nh tranh tr\xean th\u1ecb tr\u01b0\u1eddng th\u1ebf gi\u1edbi th\xec ph\u1ea3i n\xe2ng cao c\xf4ng ngh\u1ec7 v\xe0 ch\u1ea5t l\u01b0\u1ee3ng.","-(\uc73c)\ub824\uba74 = n\u1ebfu mu\u1ed1n. -\uc544/\uc5b4\uc57c \ud558\ub2e4 = ph\u1ea3i.")
