A.h3U=new B.S("\ub2e4\uc74c \uc911 \ud55c\uad6d\uc758 \uc8fc\uc694 \uc0b0\uc5c5\uacfc \uad00\ub828\uc774 \uae4a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 l\u0129nh v\u1ef1c li\xean quan nhi\u1ec1u \u0111\u1ebfn c\xe1c ng\xe0nh quan tr\u1ecdng c\u1ee7a H\xe0n Qu\u1ed1c?",A.a1S,0,"Ch\u1ea5t b\xe1n d\u1eabn v\xe0 \xf4 t\xf4 l\xe0 nh\u1eefng ng\xe0nh quan tr\u1ecdng c\u1ee7a kinh t\u1ebf H\xe0n Qu\u1ed1c.")
A.UY=s(["\uc11c\ub85c \ub2e4\ub978 \ub098\ub77c \ud654\ud3d0\uc758 \uad50\ud658 \ube44\uc728","\ud559\uad50 \uc2dc\ud5d8 \uc810\uc218","\uc8fc\ud0dd\uc758 \ud06c\uae30","\uadfc\ub85c\uc2dc\uac04"],t.s)
A.h9N=new B.S("\u201c\ud658\uc728\u201d\uacfc \uac00\uc7a5 \uad00\ub828\uc774 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\ud658\uc728 li\xean quan nh\u1ea5t \u0111\u1ebfn \u0111i\u1ec1u g\xec?",A.UY,0,"\ud658\uc728 l\xe0 t\u1ef7 l\u1ec7 trao \u0111\u1ed5i gi\u1eefa c\xe1c \u0111\u1ed3ng ti\u1ec1n kh\xe1c nhau.")
A.V4=s(["\uc790\uc720\ubb34\uc5ed\ud611\uc815","\uadfc\ub85c\uacc4\uc57d\uc11c","\uad6d\ubb34\ud68c\uc758","\ud3c9\uc0dd\uad50\uc721"],t.s)
