A.htS=new B.v("\ub18d\uc5c5","n\xf4ng nghi\u1ec7p","\uacfc\uac70\uc5d0\ub294 \ub18d\uc5c5\uc5d0 \uc885\uc0ac\ud558\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc558\uc2b5\ub2c8\ub2e4.","Tr\u01b0\u1edbc \u0111\xe2y c\xf3 nhi\u1ec1u ng\u01b0\u1eddi l\xe0m vi\u1ec7c trong l\u0129nh v\u1ef1c n\xf4ng nghi\u1ec7p.")
A.hlF=new B.v("\uc81c\uc870\uc5c5","ng\xe0nh s\u1ea3n xu\u1ea5t / ch\u1ebf t\u1ea1o","\uc81c\uc870\uc5c5\uc758 \ubc1c\uc804\uc740 \uacbd\uc81c\uc131\uc7a5\uc5d0 \ud070 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.","S\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a ng\xe0nh s\u1ea3n xu\u1ea5t \u0111\xe3 \u1ea3nh h\u01b0\u1edfng l\u1edbn \u0111\u1ebfn t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf.")
A.hmy=new B.v("\uc11c\ube44\uc2a4\uc5c5","ng\xe0nh d\u1ecbch v\u1ee5","\uacbd\uc81c\uac00 \ubc1c\uc804\ud558\uba74\uc11c \uc11c\ube44\uc2a4\uc5c5\uc758 \ube44\uc911\ub3c4 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.","Khi kinh t\u1ebf ph\xe1t tri\u1ec3n, t\u1ef7 tr\u1ecdng ng\xe0nh d\u1ecbch v\u1ee5 c\u0169ng t\u0103ng l\xean.")
