A.has=new B.S("\uacbd\uc81c\uc131\uc7a5\uc73c\ub85c \ub098\ud0c0\ub09c \uae0d\uc815\uc801\uc778 \ubcc0\ud654\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 thay \u0111\u1ed5i t\xedch c\u1ef1c do t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf?",A.VR,0,"T\u0103ng tr\u01b0\u1edfng kinh t\u1ebf g\xf3p ph\u1ea7n n\xe2ng cao m\u1ee9c s\u1ed1ng.")
