A.h3y=new B.S("\ub2e4\uc74c \uc778\ubb3c\uacfc \uc7a5\uc18c\uc758 \uc5f0\uacb0\uc774 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\u1eb7p nh\xe2n v\u1eadt v\xe0 \u0111\u1ecba \u0111i\u1ec3m n\xe0o d\u01b0\u1edbi \u0111\xe2y l\xe0 \u0111\xfang?",A.Vc,0,"\uc548\uc911\uadfc\uc740 1909\ub144 \uc911\uad6d \ud558\uc5bc\ube48\uacfc \uad00\ub828\ud558\uc5ec \uae30\uc5b5\ud558\uba74 \ub429\ub2c8\ub2e4.")
A.a5V=s(["\uad50\uc721, \uc678\uad50, \ub9cc\uc138\uc6b4\ub3d9, \ubb34\uc7a5\ud22c\uc7c1 \ub4f1 \uc5ec\ub7ec \ud615\ud0dc\uac00 \uc788\uc5c8\ub2e4.","\uc624\uc9c1 \ud55c \uac00\uc9c0 \ubc29\ubc95\uc73c\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc84c\ub2e4.","1910\ub144\uc5d0 \ubaa8\ub450 \ub05d\ub0ac\ub2e4.","\ud55c\uad6d \ubc16\uc5d0\uc11c\ub294 \ub3c5\ub9bd\uc6b4\ub3d9\uc774 \uc804\ud600 \uc5c6\uc5c8\ub2e4."],t.s)
A.h7U=new B.S("\ud55c\uad6d\uc758 \ub3c5\ub9bd\uc6b4\ub3d9\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ph\xe1t bi\u1ec3u n\xe0o \u0111\xfang v\u1ec1 phong tr\xe0o \u0111\u1ed9c l\u1eadp H\xe0n Qu\u1ed1c?",A.a5V,0,"Phong tr\xe0o \u0111\u1ed9c l\u1eadp di\u1ec5n ra d\u01b0\u1edbi nhi\u1ec1u h\xecnh th\u1ee9c kh\xe1c nhau.")
A.VV=s(["\uae40\uad6c - \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80","\uc724\ubd09\uae38 - \ud6c8\ubbfc\uc815\uc74c \ucc3d\uc81c","\uc548\ucc3d\ud638 - \ub3d9\uc758\ubcf4\uac10 \ud3b8\ucc2c","\uc720\uad00\uc21c - \uace0\ub824 \uac74\uad6d"],t.s)
A.h9V=new B.S("\ub2e4\uc74c \uc778\ubb3c\uacfc \ud65c\ub3d9\uc758 \uc5f0\uacb0\uc774 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\u1eb7p nh\xe2n v\u1eadt v\xe0 ho\u1ea1t \u0111\u1ed9ng n\xe0o \u0111\xfang?",A.VV,0,"\uae40\uad6c\ub294 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\uc2b5\ub2c8\ub2e4.")
A.loU=s([A.h9d,A.h8Y,A.h4o,A.h5V,A.h9Z,A.h7X,A.h6w,A.h3y,A.h7U,A.h9V],t.h)
A.kfw=s(["\uc548\uc911\uadfc \u2192 1909\ub144 \xb7 \ud558\uc5bc\ube48 \xb7 \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8.","\uc720\uad00\uc21c \u2192 1919\ub144 \xb7 3\xb71 \uc6b4\ub3d9 \xb7 \uc544\uc6b0\ub0b4 \uc7a5\ud130.","\uae40\uad6c \u2192 \ubc31\ubc94 \xb7 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80.","\uc548\ucc3d\ud638 \u2192 \uad50\uc721 \xb7 \uc778\uc7ac \uc591\uc131 \xb7 \ud765\uc0ac\ub2e8.","\uc724\ubd09\uae38 \u2192 1932\ub144 \xb7 \uc0c1\ud558\uc774 \xb7 \ud6d9\ucee4\uc6b0\uacf5\uc6d0 \uc758\uac70.","\ub3c5\ub9bd\uc6b4\ub3d9\uc740 \uc5ec\ub7ec \uc7a5\uc18c\uc5d0\uc11c \ub2e4\uc591\ud55c \ubc29\ubc95\uc73c\ub85c \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","\ub9cc\uc138\uc6b4\ub3d9\ub3c4 \ub3c5\ub9bd\uc6b4\ub3d9\uc758 \ud55c \ud615\ud0dc\uc785\ub2c8\ub2e4.","\uad50\uc721\uacfc \uc678\uad50\ud65c\ub3d9\ub3c4 \ub3c5\ub9bd\uc6b4\ub3d9\uc758 \uc911\uc694\ud55c \ubc29\ubc95\uc774\uc5c8\uc2b5\ub2c8\ub2e4.","\ubb34\uc7a5\ud22c\uc7c1\ub3c4 \uad6d\ub0b4\uc678\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","\uc778\ubb3c \ubb38\uc81c\ub294 \uc774\ub984\ub9cc \uc678\uc6b0\uc9c0 \ub9d0\uace0 \uc5f0\ub3c4\uc640 \uc7a5\uc18c, \ub300\ud45c \ud65c\ub3d9\uae4c\uc9c0 \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.h31=new B.dQ(43,"\uc5ed\uc0ac","\ud55c\uad6d\uc758 \uc778\ubb3c\uc0ac \u2161","C\xe1c nh\xe2n v\u1eadt l\u1ecbch s\u1eed H\xe0n Qu\u1ed1c II",A.l78,A.jJa,A.jUz,A.lAR,"\ub3c5\ub9bd\uc744 \uc704\ud574 \ud65c\ub3d9\ud55c \uc0ac\ub78c\ub4e4","\ud55c\uad6d\uc774 \uc77c\ubcf8\uc758 \uc9c0\ubc30\ub97c \ubc1b\ub358 \uc2dc\uae30\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub098\ub77c\uc758 \ub3c5\ub9bd\uc744 \ub418\ucc3e\uae30 \uc704\ud574 \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.\n\n\ub3c5\ub9bd\uc6b4\ub3d9\uc758 \ubc29\ubc95\uc740 \ud55c \uac00\uc9c0\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uac70\ub9ac\uc5d0\uc11c \ub3c5\ub9bd\uc744 \uc678\uce58\ub294 \ub9cc\uc138\uc6b4\ub3d9\ub3c4 \uc788\uc5c8\uace0 \uad50\uc721\uc744 \ud1b5\ud574 \ubbfc\uc871\uc758 \ud798\uc744 \ud0a4\uc6b0\ub824\ub294 \ud65c\ub3d9\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc678\uad6d\uc5d0\uc11c \ub3c5\ub9bd\uc758 \ud544\uc694\uc131\uc744 \uc54c\ub9ac\ub294 \uc678\uad50\ud65c\ub3d9\uacfc \ubb34\uc7a5\ud22c\uc7c1\ub3c4 \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.\n\n\uc548\uc911\uadfc\uc740 \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4. \uadf8\ub294 1909\ub144 \uc911\uad6d \ud558\uc5bc\ube48\uc5d0\uc11c \ud55c\uad6d \uce68\ub7b5\uc5d0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub358 \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8\ub97c \uc800\uaca9\ud588\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \uccb4\ud3ec\ub418\uc5b4 \uc7ac\ud310\uc744 \ubc1b\uace0 1910\ub144\uc5d0 \uc21c\uad6d\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc720\uad00\uc21c\uc740 1919\ub144 3\xb71 \uc6b4\ub3d9\uc744 \ub300\ud45c\ud558\ub294 \uc778\ubb3c \uc911 \ud55c \uba85\uc785\ub2c8\ub2e4. \uadf8\ub294 \ud559\uc0dd\uc73c\ub85c\uc11c \ub3c5\ub9bd\uc6b4\ub3d9\uc5d0 \ucc38\uc5ec\ud588\uace0 \uace0\ud5a5\uc73c\ub85c \ub0b4\ub824\uac00 \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9\uc5d0\ub3c4 \ucc38\uc5ec\ud588\uc2b5\ub2c8\ub2e4. \uccb4\ud3ec\ub41c \ud6c4\uc5d0\ub3c4 \ub3c5\ub9bd\uc758 \ub73b\uc744 \uad7d\ud788\uc9c0 \uc54a\uc558\uc73c\uba70 1920\ub144\uc5d0 \uac10\uc625\uc5d0\uc11c \uc138\uc0c1\uc744 \ub5a0\ub0ac\uc2b5\ub2c8\ub2e4.\n\n\uae40\uad6c\ub294 \uc624\ub7ab\ub3d9\uc548 \ub3c5\ub9bd\uc6b4\ub3d9\uc744 \ud55c \ub300\ud45c\uc801\uc778 \uc9c0\ub3c4\uc790\uc785\ub2c8\ub2e4. \uadf8\uc758 \ud638\ub294 \ubc31\ubc94\uc785\ub2c8\ub2e4. \uadf8\ub294 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\uba70 \ud55c\uad6d\uc758 \ub3c5\ub9bd\uc744 \uc704\ud574 \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc548\ucc3d\ud638\ub3c4 \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4. \uadf8\ub294 \ub098\ub77c\uac00 \uac15\ud574\uc9c0\uae30 \uc704\ud574\uc11c\ub294 \uad6d\ubbfc\uc758 \uad50\uc721\uacfc \uc778\uc7ac \uc591\uc131\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud588\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud765\uc0ac\ub2e8\uc744 \uc870\uc9c1\ud558\uc5ec \ub3c5\ub9bd\uc6b4\ub3d9\uacfc \uc0ac\ud68c\uc6b4\ub3d9\uc744 \uc804\uac1c\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc724\ubd09\uae38\uc740 1932\ub144 \uc911\uad6d \uc0c1\ud558\uc774 \ud6d9\ucee4\uc6b0\uacf5\uc6d0\uc5d0\uc11c \uc77c\ubcf8 \uce21 \ud589\uc0ac\uc7a5\uc744 \ub300\uc0c1\uc73c\ub85c \uc758\uac70\ub97c \uc77c\uc73c\ucf30\uc2b5\ub2c8\ub2e4. \uadf8\uc758 \ud65c\ub3d9\uc740 \ud55c\uad6d\uc758 \ub3c5\ub9bd\uc6b4\ub3d9\uc744 \uad6d\uc81c\uc0ac\ud68c\uc5d0 \uc54c\ub9ac\ub294 \ub370\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\uc774\ucc98\ub7fc \ub3c5\ub9bd\uc6b4\ub3d9\uac00\ub4e4\uc740 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc640 \ubc29\ubc95\uc73c\ub85c \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub098\ub77c\uc758 \ub3c5\ub9bd\uacfc \ubbfc\uc871\uc758 \uc790\uc720\ub97c \ub418\ucc3e\uc73c\ub824 \ud588\ub2e4\ub294 \uacf5\ud1b5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc624\ub298\ub0a0 \ud55c\uad6d\uc5d0\uc11c\ub294 \uc774\ub7ec\ud55c \uc778\ubb3c\ub4e4\uc758 \ud65c\ub3d9\uacfc \ud76c\uc0dd\uc744 \uae30\uc5b5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n","Trong th\u1eddi k\u1ef3 H\xe0n Qu\u1ed1c n\u1eb1m d\u01b0\u1edbi s\u1ef1 cai tr\u1ecb c\u1ee7a Nh\u1eadt B\u1ea3n, r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi \u0111\xe3 ho\u1ea1t \u0111\u1ed9ng \u0111\u1ec3 gi\xe0nh l\u1ea1i n\u1ec1n \u0111\u1ed9c l\u1eadp c\u1ee7a \u0111\u1ea5t n\u01b0\u1edbc.\n\nPhong tr\xe0o \u0111\u1ed9c l\u1eadp kh\xf4ng ch\u1ec9 c\xf3 m\u1ed9t h\xecnh th\u1ee9c. C\xf3 c\xe1c cu\u1ed9c bi\u1ec3u t\xecnh h\xf4 vang \u0111\u1ed9c l\u1eadp tr\xean \u0111\u01b0\u1eddng ph\u1ed1, nh\u1eefng ho\u1ea1t \u0111\u1ed9ng gi\xe1o d\u1ee5c nh\u1eb1m n\xe2ng cao s\u1ee9c m\u1ea1nh d\xe2n t\u1ed9c, c\xe1c ho\u1ea1t \u0111\u1ed9ng ngo\u1ea1i giao \u0111\u1ec3 th\xf4ng b\xe1o v\u1edbi th\u1ebf gi\u1edbi v\u1ec1 mong mu\u1ed1n \u0111\u1ed9c l\u1eadp v\xe0 c\u1ea3 \u0111\u1ea5u tranh v\u0169 trang.\n\nAhn Jung-geun l\xe0 m\u1ed9t nh\xe0 ho\u1ea1t \u0111\u1ed9ng \u0111\u1ed9c l\u1eadp ti\xeau bi\u1ec3u. N\u0103m 1909 t\u1ea1i Harbin, Trung Qu\u1ed1c, \xf4ng b\u1eafn Ito Hirobumi, ng\u01b0\u1eddi \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng trong qu\xe1 tr\xecnh Nh\u1eadt B\u1ea3n x\xe2m l\u1ea5n H\xe0n Qu\u1ed1c. Sau \u0111\xf3 \xf4ng b\u1ecb b\u1eaft, x\xe9t x\u1eed v\xe0 hy sinh n\u0103m 1910.\n\nYu Gwan-sun l\xe0 m\u1ed9t trong nh\u1eefng nh\xe2n v\u1eadt ti\xeau bi\u1ec3u c\u1ee7a Phong tr\xe0o 1 th\xe1ng 3 n\u0103m 1919. Khi c\xf2n l\xe0 h\u1ecdc sinh, b\xe0 tham gia phong tr\xe0o \u0111\u1ed9c l\u1eadp v\xe0 sau \u0111\xf3 v\u1ec1 qu\xea tham gia cu\u1ed9c bi\u1ec3u t\xecnh t\u1ea1i ch\u1ee3 Aunae. Sau khi b\u1ecb b\u1eaft, b\xe0 v\u1eabn kh\xf4ng t\u1eeb b\u1ecf \xfd ch\xed \u0111\u1ed9c l\u1eadp v\xe0 qua \u0111\u1eddi trong nh\xe0 t\xf9 n\u0103m 1920.\n\nKim Gu l\xe0 m\u1ed9t nh\xe0 l\xe3nh \u0111\u1ea1o ti\xeau bi\u1ec3u \u0111\xe3 ho\u1ea1t \u0111\u1ed9ng l\xe2u d\xe0i cho phong tr\xe0o \u0111\u1ed9c l\u1eadp. Hi\u1ec7u c\u1ee7a \xf4ng l\xe0 Baekbeom. \xd4ng gi\u1eef vai tr\xf2 quan tr\u1ecdng trong Ch\xednh ph\u1ee7 L\xe2m th\u1eddi \u0110\u1ea1i H\xe0n D\xe2n Qu\u1ed1c v\xe0 ho\u1ea1t \u0111\u1ed9ng v\xec \u0111\u1ed9c l\u1eadp c\u1ee7a H\xe0n Qu\u1ed1c.\n\nAhn Chang-ho c\u0169ng l\xe0 m\u1ed9t nh\xe0 ho\u1ea1t \u0111\u1ed9ng \u0111\u1ed9c l\u1eadp ti\xeau bi\u1ec3u. \xd4ng cho r\u1eb1ng \u0111\u1ec3 \u0111\u1ea5t n\u01b0\u1edbc tr\u1edf n\xean m\u1ea1nh m\u1ebd, gi\xe1o d\u1ee5c ng\u01b0\u1eddi d\xe2n v\xe0 \u0111\xe0o t\u1ea1o nh\xe2n t\xe0i l\xe0 r\u1ea5t quan tr\u1ecdng. \xd4ng c\u0169ng t\u1ed5 ch\u1ee9c Heungsadan v\xe0 ti\u1ebfn h\xe0nh nhi\u1ec1u ho\u1ea1t \u0111\u1ed9ng x\xe3 h\u1ed9i v\xe0 \u0111\u1ed9c l\u1eadp.\n\nYun Bong-gil th\u1ef1c hi\u1ec7n m\u1ed9t h\xe0nh \u0111\u1ed9ng \u0111\u1ea5u tranh t\u1ea1i c\xf4ng vi\xean Hongkou \u1edf Th\u01b0\u1ee3ng H\u1ea3i, Trung Qu\u1ed1c v\xe0o n\u0103m 1932 nh\u1eb1m v\xe0o m\u1ed9t s\u1ef1 ki\u1ec7n c\u1ee7a ph\xeda Nh\u1eadt B\u1ea3n. Ho\u1ea1t \u0111\u1ed9ng c\u1ee7a \xf4ng c\u0169ng g\xf3p ph\u1ea7n khi\u1ebfn phong tr\xe0o \u0111\u1ed9c l\u1eadp H\xe0n Qu\u1ed1c \u0111\u01b0\u1ee3c qu\u1ed1c t\u1ebf ch\xfa \xfd h\u01a1n.\n\nNh\u1eefng nh\xe0 ho\u1ea1t \u0111\u1ed9ng n\xe0y ho\u1ea1t \u0111\u1ed9ng \u1edf nh\u1eefng n\u01a1i v\xe0 b\u1eb1ng nh\u1eefng ph\u01b0\u01a1ng ph\xe1p kh\xe1c nhau. Tuy nhi\xean, h\u1ecd c\xf3 \u0111i\u1ec3m chung l\xe0 mong mu\u1ed1n gi\xe0nh l\u1ea1i \u0111\u1ed9c l\u1eadp c\u1ee7a \u0111\u1ea5t n\u01b0\u1edbc v\xe0 t\u1ef1 do c\u1ee7a d\xe2n t\u1ed9c.\n\nNg\xe0y nay, H\xe0n Qu\u1ed1c ghi nh\u1edb c\xe1c ho\u1ea1t \u0111\u1ed9ng v\xe0 s\u1ef1 hy sinh c\u1ee7a nh\u1eefng nh\xe2n v\u1eadt n\xe0y.\n","\ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc640 \uc5c5\uc801 \uc5f0\uacb0\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \ub3c5\ub9bd\uc6b4\ub3d9\uac00 \uc774\ub984\ud558\uace0 \ud65c\ub3d9\uc744 \uac19\uc774 \uc678\uc6cc \ubcfc\uae4c\uc694?\n\n\ubbfc\uc218: \uc88b\uc544\uc694.\n\n\uc548: 1909\ub144 \ud558\uc5bc\ube48\uc5d0\uc11c \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8\ub97c \uc800\uaca9\ud55c \uc0ac\ub78c\uc740\uc694?\n\n\ubbfc\uc218: \uc548\uc911\uadfc\uc774\uc5d0\uc694.\n\n\uc548: 3\xb71 \uc6b4\ub3d9\uacfc \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9\uc73c\ub85c \uc720\uba85\ud55c \uc0ac\ub78c\uc740\uc694?\n\n\ubbfc\uc218: \uc720\uad00\uc21c\uc774\uc5d0\uc694.\n\n\uc548: \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\uace0 \ud638\uac00 \ubc31\ubc94\uc778 \uc0ac\ub78c\uc740 \ub204\uad6c\uc608\uc694?\n\n\ubbfc\uc218: \uae40\uad6c\uc608\uc694.\n\n\uc548: \uad50\uc721\uacfc \uc778\uc7ac \uc591\uc131\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uace0 \ud765\uc0ac\ub2e8\uc744 \uc870\uc9c1\ud55c \uc0ac\ub78c\uc740\uc694?\n\n\ubbfc\uc218: \uc548\ucc3d\ud638\uc608\uc694.\n\n\uc548: 1932\ub144\uc5d0 \uc0c1\ud558\uc774\uc5d0\uc11c \uc758\uac70\ub97c \uc77c\uc73c\ud0a8 \uc0ac\ub78c\uc740\uc694?\n\n\ubbfc\uc218: \uc724\ubd09\uae38\uc774\uc5d0\uc694.\n\n\uc548: \uc798 \uc678\uc6e0\ub124\uc694. \uadf8\ub7f0\ub370 \ub3c5\ub9bd\uc6b4\ub3d9\uc740 \ubb34\uc7a5\ud22c\uc7c1\ub9cc \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\uc9c0\uc694?\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \ub9cc\uc138\uc6b4\ub3d9\ub3c4 \uc788\uc5c8\uace0 \uad50\uc721, \uc678\uad50, \ubb38\ud654 \ud65c\ub3d9\ub3c4 \uc788\uc5c8\uc5b4\uc694.\n\n\uc548: \uadf8\ub7ec\uba74 \uc2dc\ud5d8\uc5d0\uc11c\ub294 \uc778\ubb3c\uacfc \ud65c\ub3d9\uc744 \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud558\ub294 \uac8c \uc911\uc694\ud558\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub124. \uc5f0\ub3c4\uc640 \uc7a5\uc18c\uae4c\uc9c0 \uac19\uc774 \uae30\uc5b5\ud558\uba74 \ub354 \uc88b\uc544\uc694.\n","An: Minsu, ch\xfang ta th\u1eed h\u1ecdc t\xean c\xe1c nh\xe0 ho\u1ea1t \u0111\u1ed9ng \u0111\u1ed9c l\u1eadp c\xf9ng v\u1edbi ho\u1ea1t \u0111\u1ed9ng c\u1ee7a h\u1ecd nh\xe9?\n\nMinsu: \u0110\u01b0\u1ee3c.\n\nAn: Ng\u01b0\u1eddi b\u1eafn Ito Hirobumi t\u1ea1i Harbin n\u0103m 1909 l\xe0 ai?\n\nMinsu: Ahn Jung-geun.\n\nAn: Ng\u01b0\u1eddi n\u1ed5i ti\u1ebfng v\u1edbi Phong tr\xe0o 1 th\xe1ng 3 v\xe0 cu\u1ed9c bi\u1ec3u t\xecnh t\u1ea1i ch\u1ee3 Aunae?\n\nMinsu: Yu Gwan-sun.\n\nAn: Ng\u01b0\u1eddi c\xf3 hi\u1ec7u Baekbeom v\xe0 gi\u1eef vai tr\xf2 quan tr\u1ecdng trong Ch\xednh ph\u1ee7 L\xe2m th\u1eddi \u0110\u1ea1i H\xe0n D\xe2n Qu\u1ed1c?\n\nMinsu: Kim Gu.\n\nAn: Ng\u01b0\u1eddi coi tr\u1ecdng gi\xe1o d\u1ee5c, \u0111\xe0o t\u1ea1o nh\xe2n t\xe0i v\xe0 t\u1ed5 ch\u1ee9c Heungsadan?\n\nMinsu: Ahn Chang-ho.\n\nAn: Ng\u01b0\u1eddi th\u1ef1c hi\u1ec7n h\xe0nh \u0111\u1ed9ng \u0111\u1ea5u tranh t\u1ea1i Th\u01b0\u1ee3ng H\u1ea3i v\xe0o n\u0103m 1932?\n\nMinsu: Yun Bong-gil.\n\nAn: Anh nh\u1edb t\u1ed1t r\u1ed3i. Nh\u01b0ng phong tr\xe0o \u0111\u1ed9c l\u1eadp kh\xf4ng ch\u1ec9 c\xf3 \u0111\u1ea5u tranh v\u0169 trang \u0111\xfang kh\xf4ng?\n\nMinsu: \u0110\xfang. C\xf2n c\xf3 bi\u1ec3u t\xecnh, gi\xe1o d\u1ee5c, ngo\u1ea1i giao v\xe0 c\xe1c ho\u1ea1t \u0111\u1ed9ng v\u0103n h\xf3a.\n\nAn: V\u1eady trong b\xe0i thi, vi\u1ec7c gh\xe9p nh\xe2n v\u1eadt v\u1edbi ho\u1ea1t \u0111\u1ed9ng t\u01b0\u01a1ng \u1ee9ng r\u1ea5t quan tr\u1ecdng nh\u1ec9.\n\nMinsu: V\xe2ng. N\u1ebfu nh\u1edb th\xeam n\u0103m v\xe0 \u0111\u1ecba \u0111i\u1ec3m n\u1eefa th\xec c\xe0ng t\u1ed1t.\n",A.lSO,A.jov,A.loU,A.kfw)
A.jCC=s(["Hi\u1ec3u c\xe1c h\xecnh th\u1ee9c mua s\u1eafm ph\u1ed5 bi\u1ebfn \u1edf H\xe0n Qu\u1ed1c.","Ph\xe2n bi\u1ec7t \uc804\ud1b5\uc2dc\uc7a5, \ub300\ud615\ub9c8\ud2b8, \ud3b8\uc758\uc810 v\xe0 \uc628\ub77c\uc778 \uc1fc\ud551.","H\u1ecdc t\u1eeb v\u1ef1ng th\u1ef1c t\u1ebf v\u1ec1 gi\xe1 c\u1ea3, thanh to\xe1n, \u0111\u1ed5i v\xe0 tr\u1ea3 h\xe0ng.","Bi\u1ebft c\xe1ch h\u1ecfi gi\xe1, s\u1ed1 l\u01b0\u1ee3ng v\xe0 khuy\u1ebfn m\xe3i khi mua h\xe0ng.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \uc601\uc218\uc99d v\xe0 \uc18c\ube44\uc790 trong giao d\u1ecbch.","Bi\u1ebft m\u1ed9t s\u1ed1 nguy\xean t\u1eafc ti\xeau d\xf9ng h\u1ee3p l\xfd v\xe0 b\u1ea3o v\u1ec7 quy\u1ec1n l\u1ee3i ng\u01b0\u1eddi ti\xeau d\xf9ng.","Luy\u1ec7n h\u1ed9i tho\u1ea1i mua s\u1eafm c\xf3 th\u1ec3 s\u1eed d\u1ee5ng tr\u1ef1c ti\u1ebfp trong \u0111\u1eddi s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c."],t.s)
A.m3v=s([u.Bw,"\uc804\ud1b5\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc2e0\uc120\ud55c \uc2dd\uc7ac\ub8cc\uc640 \ub2e4\uc591\ud55c \uc0dd\ud65c\uc6a9\ud488\uc744 \ud310\ub9e4\ud569\ub2c8\ub2e4.","\ub300\ud615\ub9c8\ud2b8\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \uc0c1\ud488\uc744 \ud55c\uacf3\uc5d0\uc11c \ud3b8\ub9ac\ud558\uac8c \uc0b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.O7,u.au,u.Zy,u.mn,u.Vf],t.s)
