A.hby=new B.an("\ud55c\uad6d\uc5d0\uc11c\ub294 \uc804\ud1b5\uc801\uc73c\ub85c \uac00\uc871\uacfc \uacf5\ub3d9\uccb4\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574 \uc654\uc2b5\ub2c8\ub2e4.","Trong truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c, gia \u0111\xecnh v\xe0 c\u1ed9ng \u0111\u1ed3ng \u0111\xe3 \u0111\u01b0\u1ee3c coi tr\u1ecdng.","-\uc544/\uc5b4 \uc624\ub2e4 = m\u1ed9t h\xe0nh \u0111\u1ed9ng ho\u1eb7c tr\u1ea1ng th\xe1i \u0111\xe3 ti\u1ebfp di\u1ec5n \u0111\u1ebfn hi\u1ec7n t\u1ea1i.")
A.hbj=new B.an("\ud6a8\ub294 \ubd80\ubaa8\ub97c \uc874\uc911\ud558\uace0 \ubcf4\uc0b4\ud53c\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.",u.Nb,"-\uc640/\uacfc \uad00\ub828\uc774 \uc788\ub2e4 = c\xf3 li\xean quan \u0111\u1ebfn.")
A.hcn=new B.an("\uc624\ub7ab\ub3d9\uc548 \ud568\uaed8 \uc9c0\ub0b4\ub2e4 \ubcf4\uba74 \uc11c\ub85c \uc815\uc774 \ub4e4\uae30\ub3c4 \ud569\ub2c8\ub2e4.","Khi \u1edf c\xf9ng nhau l\xe2u ng\xe0y, \u0111\xf4i khi m\u1ecdi ng\u01b0\u1eddi s\u1ebd n\u1ea3y sinh t\xecnh c\u1ea3m g\u1eafn b\xf3.","-\ub2e4 \ubcf4\uba74 = n\u1ebfu/c\u1ee9 l\xe0m l\xe2u th\xec. \uc815\uc774 \ub4e4\ub2e4 = tr\u1edf n\xean g\u1eafn b\xf3.")
A.hfw=new B.an("\ud608\uc5f0, \uc9c0\uc5f0, \ud559\uc5f0 \ub4f1\uc744 \uc5f0\uace0 \uad00\uacc4\ub77c\uace0 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Quan h\u1ec7 huy\u1ebft th\u1ed1ng, qu\xea qu\xe1n v\xe0 tr\u01b0\u1eddng h\u1ecdc c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 c\xe1c quan h\u1ec7 \uc5f0\uace0.","-(\uc774)\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4 = c\xf3 th\u1ec3 g\u1ecdi l\xe0.")
A.heS=new B.an("\uc5f0\uace0\ub9cc\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu ch\u1ec9 coi tr\u1ecdng c\xe1c m\u1ed1i quan h\u1ec7 th\xe2n quen th\xec c\xf3 th\u1ec3 l\xe0m t\u1ed5n h\u1ea1i t\xednh c\xf4ng b\u1eb1ng.","-\ub9cc = ch\u1ec9. \ud574\uce58\ub2e4 = l\xe0m t\u1ed5n h\u1ea1i.")
A.hf7=new B.an("\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uad00\uacc4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uac1c\uc778\uc758 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","Trong x\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i, kh\xf4ng ch\u1ec9 quan h\u1ec7 m\xe0 n\u0103ng l\u1ef1c c\xe1 nh\xe2n v\xe0 quy tr\xecnh c\xf4ng b\u1eb1ng c\u0169ng quan tr\u1ecdng.","N\ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9 N m\xe0 c\xf2n.")
A.jJL=s([A.hby,A.hbj,A.hcn,A.hfw,A.heS,A.hf7],t.L)
A.kOc=s(["\ud6a8 = l\xf2ng hi\u1ebfu th\u1ea3o; kh\xf4ng \u0111\u01a1n gi\u1ea3n ch\u1ec9 l\xe0 nghe l\u1eddi ng\u01b0\u1eddi l\u1edbn.","\uc815 = t\xecnh c\u1ea3m g\u1eafn b\xf3 \u0111\u01b0\u1ee3c h\xecnh th\xe0nh trong quan h\u1ec7 gi\u1eefa con ng\u01b0\u1eddi.","\uc5f0\uace0 = m\u1ed1i li\xean h\u1ec7 \u0111\u01b0\u1ee3c h\xecnh th\xe0nh qua gia \u0111\xecnh, qu\xea qu\xe1n, tr\u01b0\u1eddng h\u1ecdc ho\u1eb7c c\xe1c m\u1ed1i quan h\u1ec7 kh\xe1c.","\ud608\uc5f0 = quan h\u1ec7 huy\u1ebft th\u1ed1ng.","\uc9c0\uc5f0 = quan h\u1ec7 d\u1ef1a tr\xean qu\xea qu\xe1n ho\u1eb7c khu v\u1ef1c.","\ud559\uc5f0 = quan h\u1ec7 d\u1ef1a tr\xean tr\u01b0\u1eddng h\u1ecdc.","\uc778\ub9e5 = m\u1ea1ng l\u01b0\u1edbi c\xe1c m\u1ed1i quan h\u1ec7 c\xe1 nh\xe2n, kh\xf4ng ho\xe0n to\xe0n gi\u1ed1ng \uc5f0\uace0.","C\xf3 quan h\u1ec7 x\xe3 h\u1ed9i kh\xf4ng ph\u1ea3i l\xe0 \u0111i\u1ec1u x\u1ea5u; v\u1ea5n \u0111\u1ec1 ph\xe1t sinh khi quan h\u1ec7 \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng \u0111\u1ec3 t\u1ea1o l\u1ee3i \xedch kh\xf4ng c\xf4ng b\u1eb1ng.","\uacf5\uc815\ud558\ub2e4 = c\xf4ng b\u1eb1ng; \uacf5\uc815\uc131 = t\xednh c\xf4ng b\u1eb1ng."],t.s)
A.k0t=s(["\ud6a8 \u2192 l\xf2ng hi\u1ebfu th\u1ea3o.","\uc815 \u2192 t\xecnh c\u1ea3m, s\u1ef1 g\u1eafn b\xf3 gi\u1eefa ng\u01b0\u1eddi v\u1edbi ng\u01b0\u1eddi.","\uacf5\ub3d9\uccb4 \uc758\uc2dd \u2192 \xfd th\u1ee9c c\u1ed9ng \u0111\u1ed3ng.","\uc5f0\uace0 \u2192 m\u1ed1i li\xean h\u1ec7 ho\u1eb7c quan h\u1ec7 g\u1eafn k\u1ebft.","\ud608\uc5f0 \u2192 quan h\u1ec7 huy\u1ebft th\u1ed1ng.","\uc9c0\uc5f0 \u2192 quan h\u1ec7 d\u1ef1a tr\xean \u0111\u1ecba ph\u01b0\u01a1ng ho\u1eb7c qu\xea qu\xe1n.","\ud559\uc5f0 \u2192 quan h\u1ec7 d\u1ef1a tr\xean tr\u01b0\u1eddng h\u1ecdc.","\uc5f0\uace0 \uad00\uacc4\ub294 \uc11c\ub85c \ub3d5\ub294 \ub370 \uae0d\uc815\uc801\uc778 \uc5ed\ud560\uc744 \ud560 \uc218\ub3c4 \uc788\ub2e4.","\uc5f0\uace0\ub97c \uc9c0\ub098\uce58\uac8c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4."],t.s)
