A.a2O=s(["\uc548\uc804\uc218\uce59\uc744 \uc9c0\ud0a8\ub2e4.","\uc704\ud5d8 \ud45c\uc2dc\ub97c \ubb34\uc2dc\ud55c\ub2e4.","\ud654\uc7ac\uac00 \ub098\ub3c4 \ub300\ud53c\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc0ac\uace0\uac00 \ub098\ub3c4 \uc544\ubb34\uc5d0\uac8c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.h97=new B.S("\uc548\uc804\uc0ac\uace0\ub97c \uc904\uc774\uae30 \uc704\ud574 \ud544\uc694\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","H\xe0nh \u0111\u1ed9ng n\xe0o c\u1ea7n thi\u1ebft \u0111\u1ec3 gi\u1ea3m tai n\u1ea1n?",A.a2O,0,"Tu\xe2n th\u1ee7 c\xe1c quy t\u1eafc an to\xe0n gi\xfap ph\xf2ng tr\xe1nh tai n\u1ea1n.")
A.a7b=s(["119\ub294 \uc9c0\ud558\ucca0 \ud658\uc2b9 \ubb38\uc758 \ubc88\ud638\uc774\ub2e4.","\uc751\uae09\uc0c1\ud669\uc5d0\uc11c\ub294 \uc704\uce58\uc640 \uc0c1\ud669\uc744 \uc815\ud655\ud788 \uc54c\ub9ac\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\ucc98\ubc29\uc804\uc740 \uc740\ud589\uc5d0\uc11c \uc0ac\uc6a9\ud55c\ub2e4.","\uc548\uc804\uc218\uce59\uc740 \uc9c0\ud0ac \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.h3z=new B.S("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.a7b,1,"Trong t\xecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p, cung c\u1ea5p ch\xednh x\xe1c v\u1ecb tr\xed v\xe0 t\xecnh h\xecnh l\xe0 r\u1ea5t quan tr\u1ecdng.")
