A.exz=new B.br(15,5,"Religion in Korea","\ud55c\uad6d\uc758 \uc885\uad50","Understand religious life and freedom of religion in Korea and learn to respect people with different faiths or no religion.","\ud55c\uad6d \uc0ac\ud68c\uc640 \uc885\uad50",u.to,"\ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c\ub294 \uc885\uad50\uc758 \uc790\uc720\uac00 \ubcf4\uc7a5\ub429\ub2c8\ub2e4. \uc0ac\ub78c\uc740 \uc790\uc2e0\uc774 \uc6d0\ud558\ub294 \uc885\uad50\ub97c \ubbff\uc744 \uc218 \uc788\uace0 \uc885\uad50\ub97c \ubbff\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc5d0\ub294 \ubd88\uad50, \uac1c\uc2e0\uad50, \ucc9c\uc8fc\uad50 \ub4f1 \ub2e4\uc591\ud55c \uc885\uad50\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud2b9\uc815\ud55c \uc885\uad50\ub97c \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub3c4 \ub9ce\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubd88\uad50\ub294 \uc624\ub79c \uc5ed\uc0ac \ub3d9\uc548 \ud55c\uad6d\uc758 \ubb38\ud654\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4. \ud55c\uad6d\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c\ub294 \uc624\ub798\ub41c \uc808\uacfc \ubd88\uad50 \ubb38\ud654\uc720\uc0b0\uc744 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uac1c\uc2e0\uad50\uc640 \ucc9c\uc8fc\uad50\ub3c4 \ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c \uc911\uc694\ud55c \uc885\uad50 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ub3c4\uc2dc\uc640 \uc9c0\uc5ed\uc0ac\ud68c\uc5d0\uc11c \uad50\ud68c\uc640 \uc131\ub2f9\uc744 \uc27d\uac8c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\ud3b8 \uc720\uad50\ub294 \uc77c\ubc18\uc801\uc778 \uc885\uad50\uc758 \uc758\ubbf8\uc640\ub294 \uc870\uae08 \ub2e4\ub974\uc9c0\ub9cc \ud55c\uad6d\uc778\uc758 \uc804\ud1b5\uc801\uc778 \uac00\uc871\uad00\uacc4, \uc608\uc808, \uac00\uce58\uad00 \ub4f1\uc5d0 \ub9ce\uc740 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\ud604\ub300 \ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc885\uad50\uc640 \uac00\uce58\uad00\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0dd\ud65c\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc790\uc2e0\uc758 \ubbff\uc74c\ubfd0\ub9cc \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc885\uad50\uc640 \uc2e0\ub150\ub3c4 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.",u.to,A.ktn,A.jLK,A.keK,A.l1y,A.lW6,A.l9j)
