A.ey9=new B.br(20,5,"Korean politics and the development of democracy","\ud55c\uad6d\uc758 \uc815\uce58\uc640 \ubbfc\uc8fc\uc8fc\uc758\uc758 \ubc1c\uc804","Understand popular sovereignty, elections, civic rights and duties, and major events in the development of Korean democracy.","\ud55c\uad6d \ubbfc\uc8fc\uc8fc\uc758\uc758 \ubc1c\uc804",u.DC,"\ub300\ud55c\ubbfc\uad6d\uc740 \ubbfc\uc8fc\uacf5\ud654\uad6d\uc774\uba70 \uad6d\uac00\uc758 \uc8fc\uad8c\uc740 \uad6d\ubbfc\uc5d0\uac8c \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uad6d\ubbfc\uc8fc\uad8c\uc740 \ubbfc\uc8fc\uc8fc\uc758\uc758 \uc911\uc694\ud55c \uc6d0\ub9ac\uc785\ub2c8\ub2e4.\n\n\ubbfc\uc8fc\uc8fc\uc758 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uad6d\ubbfc\uc774 \uc120\uac70\ub97c \ud1b5\ud574 \ub300\ud45c\uc790\ub97c \uc120\ud0dd\ud558\uace0 \uc5ec\ub7ec \ubc29\ubc95\uc73c\ub85c \uc0ac\ud68c\uc640 \uc815\uce58\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc624\ub298\ub0a0 \ud55c\uad6d\uc758 \ubbfc\uc8fc\uc8fc\uc758\ub294 \ud55c \ubc88\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc5ed\uc0ac\uc801\uc778 \uc0ac\uac74\uacfc \uc2dc\ubbfc\ub4e4\uc758 \ucc38\uc5ec\ub97c \uac70\uce58\uba74\uc11c \ubc1c\uc804\ud574 \uc654\uc2b5\ub2c8\ub2e4.\n\n1960\ub144\uc5d0\ub294 \ubd80\uc815\uc120\uac70 \ub4f1\uc5d0 \ud56d\uc758\ud558\ub294 \uc2dc\ubbfc\uacfc \ud559\uc0dd\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c 4\xb719 \ud601\uba85\uc774 \uc77c\uc5b4\ub0ac\uc2b5\ub2c8\ub2e4.\n\n1980\ub144 5\uc6d4\uc5d0\ub294 \uad11\uc8fc\uc5d0\uc11c \ubbfc\uc8fc\ud654\ub97c \uc694\uad6c\ud558\ub294 \uc2dc\ubbfc\ub4e4\uc758 5\xb718 \ubbfc\uc8fc\ud654\uc6b4\ub3d9\uc774 \uc77c\uc5b4\ub0ac\uc2b5\ub2c8\ub2e4.\n\n1987\ub144\uc5d0\ub294 \ub300\ud1b5\ub839 \uc9c1\uc120\uc81c\uc640 \ubbfc\uc8fc\ud654\ub97c \uc694\uad6c\ud558\ub294 \uc2dc\ubbfc\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \uc804\uad6d\uc801\uc73c\ub85c \ud655\ub300\ub418\uc5c8\uace0 \uc774\ub97c 6\uc6d4 \ubbfc\uc8fc\ud56d\uc7c1\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\uadf8 \uacb0\uacfc \ub300\ud1b5\ub839 \uc9c1\uc120\uc81c\ub97c \ud3ec\ud568\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ud5cc\ubc95\uc774 \uac1c\uc815\ub418\uc5c8\uace0 \ubbfc\uc8fc\uc8fc\uc758 \ubc1c\uc804\uc5d0 \uc911\uc694\ud55c \uc804\ud658\uc810\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\ubbfc\uc8fc\uc8fc\uc758\ub294 \uc120\uac70\uc5d0 \ucc38\uc5ec\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc758\uacac\uc744 \uc874\uc911\ud558\uace0 \ubc95\uacfc \uc808\ucc28\ub97c \uc9c0\ud0a4\uba70 \uc790\uc2e0\uc758 \uad8c\ub9ac\ubfd0\ub9cc \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\n\n\ub610\ud55c \uc2dc\ubbfc\ub4e4\uc774 \uc0ac\ud68c \ubb38\uc81c\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c0\uace0 \ucc45\uc784 \uc788\uac8c \ucc38\uc5ec\ud558\ub294 \uac83\uc774 \ubbfc\uc8fc\uc0ac\ud68c\ub97c \ubc1c\uc804\uc2dc\ud0a4\ub294 \ub370 \uc911\uc694\ud569\ub2c8\ub2e4.",u.DC,A.kzi,A.kKX,A.laH,A.kZj,A.kXe,A.lQQ)
