A.iBO=new B.t("en-kiip-5-21-q1","What are the three powers in the separation of powers?","\u201c\uc0bc\uad8c\ubd84\ub9bd\u201d\uc5d0\uc11c \ub9d0\ud558\ub294 \uc138 \uad8c\ub825\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","They are the legislative, executive, and judicial powers.",A.WE,0)
A.iIF=new B.t("en-kiip-5-21-q2","Which institution represents the legislative branch?","\uc785\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","The National Assembly represents the legislative branch.",A.a2t,0)
A.iG7=new B.t("en-kiip-5-21-q3","What is a main role of the National Assembly?","\uad6d\ud68c\uc758 \uc8fc\uc694 \uc5ed\ud560\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","A major role of the National Assembly is making laws.",A.a2I,0)
A.iMf=new B.t("en-kiip-5-21-q4","Which branch implements laws and policies?","\ubc95\ub960\uacfc \uc815\ucc45\uc744 \uc2e4\uc81c\ub85c \uc9d1\ud589\ud558\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",u.Z,A.a0G,0)
A.iGm=new B.t("en-kiip-5-21-q5","Which state institution leads the executive branch?","\ud589\uc815\ubd80\ub97c \uc774\ub044\ub294 \uc911\uc694\ud55c \uad6d\uac00\uae30\uad00\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",u.u,A.a57,0)
A.iLJ=new B.t("en-kiip-5-21-q6","Which institution represents the judicial branch?","\uc0ac\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","The courts represent the judicial branch.",A.a0K,0)
A.iKy=new B.t("en-kiip-5-21-q7","What is a main role of the courts?","\ubc95\uc6d0\uc758 \uc8fc\uc694 \uc5ed\ud560\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Courts conduct trials and apply the law.",A.VJ,0)
