A.iIf=new B.t("en-kiip-5-22-q4","Which statement about the president's term is correct?","\ub300\ud55c\ubbfc\uad6d \ub300\ud1b5\ub839\uc758 \uc784\uae30\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","The president serves five years and may not serve an additional term.",A.a1R,0)
A.iDN=new B.t("en-kiip-5-22-q5","Who assists the president?","\ub300\ud1b5\ub839\uc744 \ubcf4\uc88c\ud558\ub294 \uc0ac\ub78c\uc740 \ub204\uad6c\uc785\ub2c8\uae4c?",u._,A.Vx,0)
A.iEf=new B.t("en-kiip-5-22-q6","What meeting deliberates on important government policies?","\uc815\ubd80\uc758 \uc911\uc694\ud55c \uc815\ucc45\uc744 \uc2ec\uc758\ud558\ub294 \ud68c\uc758\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?",u.RN,A.Wj,0)
A.iIE=new B.t("en-kiip-5-22-q7","Who appropriately belongs among State Council participants?","\ub2e4\uc74c \uc911 \uad6d\ubb34\ud68c\uc758\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc0ac\ub78c\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","The president, prime minister, and members of the State Council participate.",A.a1g,0)
