A.izw=new B.t("en-kiip-5-36-q1","What does \uc900\ubc95 mean?","\u201c\uc900\ubc95\u201d\uc758 \ub73b\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\uc900\ubc95 means observing laws and rules.",A.a6Y,0)
A.ixL=new B.t("en-kiip-5-36-q2","Which best explains \uc900\ubc95\uc758\uc2dd?","\u201c\uc900\ubc95\uc758\uc2dd\u201d\uc758 \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\uc900\ubc95\uc758\uc2dd is an attitude of respecting and voluntarily obeying the law.",A.Yl,0)
A.izb=new B.t("en-kiip-5-36-q3","Why should people obey the law?","\ubc95\uc744 \uc9c0\ud0a4\ub294 \uc774\uc720\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Law helps maintain order and protect people's rights.",A.V6,0)
A.iJ6=new B.t("en-kiip-5-36-q4","What result can be expected from obeying traffic laws?","\uad50\ud1b5\ubc95\uaddc\ub97c \uc9c0\ucf30\uc744 \ub54c \uae30\ub300\ud560 \uc218 \uc788\ub294 \ud6a8\uacfc\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Traffic-law compliance promotes safety and helps prevent accidents.",A.VO,0)
A.iE0=new B.t("en-kiip-5-36-q5","What may result from breaking the law?","\ubc95\uc744 \uc704\ubc18\ud588\uc744 \ub54c \uc0dd\uae38 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Breaking the law may result in legal liability.",A.XF,0)
A.iDT=new B.t("en-kiip-5-36-q6","What attitude is needed when exercising one's rights?","\uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \ub54c \ud544\uc694\ud55c \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Exercise your rights while respecting the rights of others.",A.a4N,0)
A.iFz=new B.t("en-kiip-5-36-q7","Which is NOT an example of a law-abiding life?","\uc900\ubc95\uc0dd\ud65c\uc758 \uc608\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","A person cannot simply ignore a law because it is inconvenient.",A.a4q,3)
A.iKw=new B.t("en-kiip-5-36-q8","What can result when people follow rules?","\uc0ac\ub78c\ub4e4\uc774 \uaddc\uce59\uc744 \uc798 \uc9c0\ud0ac \ub54c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub294 \ud6a8\uacfc\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Following common rules can strengthen trust in society.",A.a1e,0)
A.ix0=new B.t("en-kiip-5-36-q9","What is important in community life?","\uacf5\ub3d9\uccb4 \uc0dd\ud65c\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Community life requires balancing individual freedom with the rights of others.",A.a4G,0)
