A.exU=new B.br(43,5,"Representative figures in Korean history II","\ud55c\uad6d\uc758 \uc778\ubb3c\uc0ac \u2161","Learn major Korean independence activists and connect each person with the correct year, place, organization, and activity.","\ub3c5\ub9bd\uc744 \uc704\ud574 \ud65c\ub3d9\ud55c \uc0ac\ub78c\ub4e4",u.vZ,"\ud55c\uad6d\uc774 \uc77c\ubcf8\uc758 \uc9c0\ubc30\ub97c \ubc1b\ub358 \uc2dc\uae30\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub098\ub77c\uc758 \ub3c5\ub9bd\uc744 \ub418\ucc3e\uae30 \uc704\ud574 \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.\n\n\ub3c5\ub9bd\uc6b4\ub3d9\uc758 \ubc29\ubc95\uc740 \ud55c \uac00\uc9c0\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uac70\ub9ac\uc5d0\uc11c \ub3c5\ub9bd\uc744 \uc678\uce58\ub294 \ub9cc\uc138\uc6b4\ub3d9\ub3c4 \uc788\uc5c8\uace0 \uad50\uc721\uc744 \ud1b5\ud574 \ubbfc\uc871\uc758 \ud798\uc744 \ud0a4\uc6b0\ub824\ub294 \ud65c\ub3d9\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc678\uad6d\uc5d0\uc11c \ub3c5\ub9bd\uc758 \ud544\uc694\uc131\uc744 \uc54c\ub9ac\ub294 \uc678\uad50\ud65c\ub3d9\uacfc \ubb34\uc7a5\ud22c\uc7c1\ub3c4 \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.\n\n\uc548\uc911\uadfc\uc740 \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4. \uadf8\ub294 1909\ub144 \uc911\uad6d \ud558\uc5bc\ube48\uc5d0\uc11c \ud55c\uad6d \uce68\ub7b5\uc5d0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub358 \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8\ub97c \uc800\uaca9\ud588\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \uccb4\ud3ec\ub418\uc5b4 \uc7ac\ud310\uc744 \ubc1b\uace0 1910\ub144\uc5d0 \uc21c\uad6d\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc720\uad00\uc21c\uc740 1919\ub144 3\xb71 \uc6b4\ub3d9\uc744 \ub300\ud45c\ud558\ub294 \uc778\ubb3c \uc911 \ud55c \uba85\uc785\ub2c8\ub2e4. \uadf8\ub294 \ud559\uc0dd\uc73c\ub85c\uc11c \ub3c5\ub9bd\uc6b4\ub3d9\uc5d0 \ucc38\uc5ec\ud588\uace0 \uace0\ud5a5\uc73c\ub85c \ub0b4\ub824\uac00 \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9\uc5d0\ub3c4 \ucc38\uc5ec\ud588\uc2b5\ub2c8\ub2e4. \uccb4\ud3ec\ub41c \ud6c4\uc5d0\ub3c4 \ub3c5\ub9bd\uc758 \ub73b\uc744 \uad7d\ud788\uc9c0 \uc54a\uc558\uc73c\uba70 1920\ub144\uc5d0 \uac10\uc625\uc5d0\uc11c \uc138\uc0c1\uc744 \ub5a0\ub0ac\uc2b5\ub2c8\ub2e4.\n\n\uae40\uad6c\ub294 \uc624\ub7ab\ub3d9\uc548 \ub3c5\ub9bd\uc6b4\ub3d9\uc744 \ud55c \ub300\ud45c\uc801\uc778 \uc9c0\ub3c4\uc790\uc785\ub2c8\ub2e4. \uadf8\uc758 \ud638\ub294 \ubc31\ubc94\uc785\ub2c8\ub2e4. \uadf8\ub294 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\uba70 \ud55c\uad6d\uc758 \ub3c5\ub9bd\uc744 \uc704\ud574 \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc548\ucc3d\ud638\ub3c4 \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4. \uadf8\ub294 \ub098\ub77c\uac00 \uac15\ud574\uc9c0\uae30 \uc704\ud574\uc11c\ub294 \uad6d\ubbfc\uc758 \uad50\uc721\uacfc \uc778\uc7ac \uc591\uc131\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud588\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud765\uc0ac\ub2e8\uc744 \uc870\uc9c1\ud558\uc5ec \ub3c5\ub9bd\uc6b4\ub3d9\uacfc \uc0ac\ud68c\uc6b4\ub3d9\uc744 \uc804\uac1c\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc724\ubd09\uae38\uc740 1932\ub144 \uc911\uad6d \uc0c1\ud558\uc774 \ud6d9\ucee4\uc6b0\uacf5\uc6d0\uc5d0\uc11c \uc77c\ubcf8 \uce21 \ud589\uc0ac\uc7a5\uc744 \ub300\uc0c1\uc73c\ub85c \uc758\uac70\ub97c \uc77c\uc73c\ucf30\uc2b5\ub2c8\ub2e4. \uadf8\uc758 \ud65c\ub3d9\uc740 \ud55c\uad6d\uc758 \ub3c5\ub9bd\uc6b4\ub3d9\uc744 \uad6d\uc81c\uc0ac\ud68c\uc5d0 \uc54c\ub9ac\ub294 \ub370\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\uc774\ucc98\ub7fc \ub3c5\ub9bd\uc6b4\ub3d9\uac00\ub4e4\uc740 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc640 \ubc29\ubc95\uc73c\ub85c \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub098\ub77c\uc758 \ub3c5\ub9bd\uacfc \ubbfc\uc871\uc758 \uc790\uc720\ub97c \ub418\ucc3e\uc73c\ub824 \ud588\ub2e4\ub294 \uacf5\ud1b5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc624\ub298\ub0a0 \ud55c\uad6d\uc5d0\uc11c\ub294 \uc774\ub7ec\ud55c \uc778\ubb3c\ub4e4\uc758 \ud65c\ub3d9\uacfc \ud76c\uc0dd\uc744 \uae30\uc5b5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.",u.vZ,A.lZ3,A.jZa,A.kN9,A.lwi,A.k7_,A.lbT)
