A.nmo=new B.aP("Nam","\ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc740 \uc0ac\uc9c4\uacfc \uc601\uc0c1\uc73c\ub85c \ub9ce\uc774 \uae30\ub85d\ub418\uc9c0\ub9cc \uc18c\ub9ac\ub294 \uc27d\uac8c \uc0ac\ub77c\uc9d1\ub2c8\ub2e4. \uc624\ub798\ub41c \uc2dc\uc7a5\uc758 \uc0c1\uc778 \ubaa9\uc18c\ub9ac\ub098 \uace8\ubaa9\uc744 \uc9c0\ub098\ub358 \uae30\ucc28 \uc18c\ub9ac\ub3c4 \uadf8 \uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc790\ub8cc\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud2b9\ubcc4\ud55c \uacf5\uc5f0\ubfd0 \uc544\ub2c8\ub77c \uc77c\uc0c1\uc801\uc778 \ub3c4\uc2dc\uc758 \uc18c\ub9ac\ub3c4 \ubb38\ud654 \uc790\uc0b0\uc73c\ub85c \ubcf4\uace0 \uafb8\uc900\ud788 \uae30\ub85d\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.",!1)
A.a5R=s([A.nmo],t.J)
A.l7Q=s(["\ub3c4\uc2dc\uc5d0\uc11c\ub294 \ubd88\ud544\uc694\ud55c \uc18c\ub9ac\ub97c \ubaa8\ub450 \uc5c6\uc560\uc57c \ud55c\ub2e4.","\uc77c\uc0c1\uc801\uc778 \ub3c4\uc2dc\uc758 \uc18c\ub9ac\ub3c4 \ubb38\ud654 \uc790\ub8cc\ub85c \uae30\ub85d\ud574\uc57c \ud55c\ub2e4.","\uc0ac\uc9c4\ubcf4\ub2e4 \uc18c\ub9ac\ub97c \uae30\ub85d\ud558\ub294 \uc77c\uc774 \ud6e8\uc52c \uc27d\ub2e4.","\ub3c4\uc2dc\uc758 \uc18c\ub9ac\ub294 \uacf5\uc5f0\uc7a5\uc5d0\uc11c\ub9cc \ubcf4\uc874\ud560 \uc218 \uc788\ub2e4."],t.s)
A.nnI=new B.ca(35,"\ub0a8\uc790\uc758 \uc911\uc2ec \uc0dd\uac01\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn suy ngh\u0129 ch\xednh c\u1ee7a ng\u01b0\u1eddi \u0111\xe0n \xf4ng.",A.a5R,A.l7Q,A.a0,2,"Ng\u01b0\u1eddi n\xf3i nh\u1ea5n m\u1ea1nh \xe2m thanh \u0111\u1eddi th\u01b0\u1eddng c\u1ee7a th\xe0nh ph\u1ed1 c\u0169ng ph\u1ea3n \xe1nh \u0111\u1eddi s\u1ed1ng m\u1ed9t th\u1eddi v\xe0 c\u1ea7n \u0111\u01b0\u1ee3c l\u01b0u gi\u1eef nh\u01b0 t\xe0i s\u1ea3n v\u0103n h\xf3a.")
A.jAD=s(["\ub3c4\uc2dc\uc758 \uc18c\ub9ac\ub294 \uc0ac\uc9c4\ubcf4\ub2e4 \ub354 \uc624\ub798 \ub0a8\ub294\ub2e4.","\uc2dc\uc7a5 \uc0c1\uc778\uc758 \ubaa9\uc18c\ub9ac\ub294 \ubb38\ud654 \uc790\ub8cc\uac00 \ub420 \uc218 \uc5c6\ub2e4.","\uc624\ub798\ub41c \uc2dc\uc7a5\uacfc \uae30\ucc28 \uc18c\ub9ac\ub294 \ub2f9\uc2dc\uc758 \uc0dd\ud65c\uc744 \ubcf4\uc5ec \uc900\ub2e4.","\ud2b9\ubcc4\ud55c \uacf5\uc5f0\uc758 \uc18c\ub9ac\ub9cc \uae30\ub85d\ud560 \uac00\uce58\uac00 \uc788\ub2e4."],t.s)
A.nn8=new B.ca(36,"\ub4e4\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u1eeba nghe.",A.a5R,A.jAD,A.a0,3,"Gi\u1ecdng n\xf3i \u1edf khu ch\u1ee3 c\u0169 v\xe0 ti\u1ebfng t\xe0u trong ng\xf5 l\xe0 t\u01b0 li\u1ec7u cho th\u1ea5y \u0111\u1eddi s\u1ed1ng c\u1ee7a con ng\u01b0\u1eddi th\u1eddi \u0111\xf3.")
A.nmR=new B.aP("N\u1eef","\uc6b0\ub9ac\ub294 \uc7a0\uc744 \uc790\ub294 \ub3d9\uc548 \uc544\ubb34 \ud65c\ub3d9\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub1cc\ub294 \ub0ae\uc5d0 \ubc1b\uc544\ub4e4\uc778 \uc815\ubcf4\ub97c \ub2e4\uc2dc \uc815\ub9ac\ud558\uace0 \uc911\uc694\ud55c \uae30\uc5b5\uc744 \uac15\ud654\ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc2dc\ud5d8 \uc9c1\uc804\uc5d0 \ubc24\uc744 \uc0c8\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uc77c\uc815\ud55c \uc2dc\uac04\uc5d0 \ucda9\ubd84\ud788 \uc790\ub294 \uc2b5\uad00\uc774 \ud559\uc2b5 \ub0b4\uc6a9\uc744 \uc624\ub798 \uae30\uc5b5\ud558\ub294 \ub370 \ub354 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4.",!0)
A.a6i=s([A.nmR],t.J)
A.lQv=s(["\uaddc\uce59\uc801\uc774\uace0 \ucda9\ubd84\ud55c \uc218\uba74\uc740 \uae30\uc5b5\uacfc \ud559\uc2b5\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\uc2dc\ud5d8 \uc804\ub0a0\uc5d0\ub294 \ubc24\uc744 \uc0c8\uc6cc \uacf5\ubd80\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc88b\ub2e4.","\uc7a0\uc744 \uc790\ub294 \ub3d9\uc548 \ub1cc\uc758 \ubaa8\ub4e0 \ud65c\ub3d9\uc774 \uba48\ucd98\ub2e4.","\uacf5\ubd80 \uc2dc\uac04\uc740 \uc218\uba74 \uc2dc\uac04\ubcf4\ub2e4 \ud56d\uc0c1 \uae38\uc5b4\uc57c \ud55c\ub2e4."],t.s)
A.nn2=new B.ca(37,"\uc5ec\uc790\uc758 \uc911\uc2ec \uc0dd\uac01\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn suy ngh\u0129 ch\xednh c\u1ee7a ng\u01b0\u1eddi ph\u1ee5 n\u1eef.",A.a6i,A.lQv,A.a0,1,"Ng\u01b0\u1eddi ph\u1ee5 n\u1eef cho r\u1eb1ng ng\u1ee7 \u0111\u1ee7 v\xe0 \u0111\u1ec1u \u0111\u1eb7n gi\xfap n\xe3o c\u1ee7ng c\u1ed1 tr\xed nh\u1edb, nh\u1edd \u0111\xf3 vi\u1ec7c h\u1ecdc hi\u1ec7u qu\u1ea3 h\u01a1n.")
A.jxX=s(["\ubc24\uc744 \uc0c8\uc6b0\uba74 \ud559\uc2b5 \ub0b4\uc6a9\uc744 \ub354 \uc624\ub798 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4.","\ub1cc\ub294 \uc7a0\uc790\ub294 \ub3d9\uc548 \ub0ae\uc5d0 \ubc1b\uc740 \uc815\ubcf4\ub97c \uc815\ub9ac\ud55c\ub2e4.","\uc7a0\uc744 \uc790\ub294 \uc2dc\uac04\uc5d0\ub294 \uc911\uc694\ud55c \uae30\uc5b5\uc774 \uc57d\ud574\uc9c4\ub2e4.","\uc2dc\ud5d8 \uae30\uac04\uc5d0\ub9cc \uc218\uba74 \uc2dc\uac04\uc744 \uc77c\uc815\ud558\uac8c \ud574\uc57c \ud55c\ub2e4."],t.s)
A.nnq=new B.ca(38,"\ub4e4\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u1eeba nghe.",A.a6i,A.jxX,A.a0,2,"\u0110o\u1ea1n nghe n\xf3i n\xe3o s\u1eafp x\u1ebfp l\u1ea1i th\xf4ng tin \u0111\xe3 ti\u1ebfp nh\u1eadn ban ng\xe0y trong khi ch\xfang ta ng\u1ee7.")
A.nmH=new B.aP("Nam","\uc2dc\uc5d0\uc11c\ub294 \uc8fc\ubbfc\ub4e4\uc774 \uc2a4\ub9c8\ud2b8\ud3f0\uc73c\ub85c \uc678\ub798 \uc2dd\ubb3c\uc744 \ucd2c\uc601\ud574 \uc704\uce58\uc640 \ud568\uaed8 \ub4f1\ub85d\ud558\ub294 \uc2dc\ubbfc \uacfc\ud559 \uc870\uc0ac\ub97c \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4. \uc804\ubb38\uac00\ub4e4\uc740 \uc8fc\ubbfc\ub4e4\uc774 \uc62c\ub9b0 \uc0ac\uc9c4\uc744 \ud655\uc778\ud574 \uc2dd\ubb3c\uc758 \uc885\ub958\ub97c \ud310\ubcc4\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub807\uac8c \ubaa8\uc778 \uc790\ub8cc\ub294 \uc678\ub798 \uc2dd\ubb3c\uc774 \ud37c\uc9c4 \uc9c0\uc5ed\uc744 \ud30c\uc545\ud558\uace0 \uc81c\uac70 \uacc4\ud68d\uc744 \uc138\uc6b0\ub294 \ub370 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. \ucc38\uc5ec\uc790\ub294 \uc804\uc6a9 \uc571\uc5d0\uc11c \uac04\ub2e8\ud55c \uad50\uc721\uc744 \ubc1b\uc740 \ub4a4 \ub204\uad6c\ub098 \uc870\uc0ac\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",!1)
A.Uy=s([A.nmH],t.J)
A.jFa=s(["\uc804\uc6a9 \uc571\uc758 \uc624\ub958\uc5d0 \ub300\ud574 \uc0ac\uacfc\ud558\ub824\uace0","\uc0c8\ub85c\uc6b4 \uc678\ub798 \uc2dd\ubb3c\uc744 \ud310\ub9e4\ud558\ub824\uace0","\uc2dd\ubb3c \uc804\ubb38\uac00\ub97c \ucc44\uc6a9\ud558\ub824\uace0","\uc2dc\ubbfc \uacfc\ud559 \uc870\uc0ac \uc0ac\uc5c5\uc744 \uc18c\uac1c\ud558\ub824\uace0"],t.s)
A.nnH=new B.ca(39,"\uc774 \ub274\uc2a4\uc758 \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn m\u1ee5c \u0111\xedch ph\xf9 h\u1ee3p nh\u1ea5t c\u1ee7a b\u1ea3n tin.",A.Uy,A.jFa,A.a0,4,"B\u1ea3n tin gi\u1edbi thi\u1ec7u ch\u01b0\u01a1ng tr\xecnh khoa h\u1ecdc c\u1ed9ng \u0111\u1ed3ng: ng\u01b0\u1eddi d\xe2n ch\u1ee5p v\xe0 \u0111\u0103ng v\u1ecb tr\xed c\u1ee7a th\u1ef1c v\u1eadt ngo\u1ea1i lai.")
A.lmX=s(["\uc804\ubb38\uac00\ub4e4\uc740 \uc8fc\ubbfc\ub4e4\uc774 \ub4f1\ub85d\ud55c \uc0ac\uc9c4\uc744 \ud655\uc778\ud55c\ub2e4.","\uc2dd\ubb3c \uc804\ubb38\uac00\ub9cc \uc870\uc0ac\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\ub2e4.","\uc218\uc9d1\ud55c \uc790\ub8cc\ub294 \uc2dd\ubb3c \uc81c\uac70 \uacc4\ud68d\uc5d0 \uc0ac\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ucc38\uc5ec\uc790\ub294 \ubc18\ub4dc\uc2dc \ud604\uc7a5 \uad50\uc721\uc744 \ubc1b\uc544\uc57c \ud55c\ub2e4."],t.s)
A.nns=new B.ca(40,"\ub4e4\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u1eeba nghe.",A.Uy,A.lmX,A.a0,1,"C\xe1c chuy\xean gia ki\u1ec3m tra \u1ea3nh do ng\u01b0\u1eddi d\xe2n \u0111\u0103ng l\xean \u0111\u1ec3 x\xe1c \u0111\u1ecbnh lo\u1ea1i th\u1ef1c v\u1eadt.")
A.nmu=new B.aP("N\u1eef","\ub3c4\uc2ec\uc758 \uac74\ubb3c \uc625\uc0c1\uc740 \uc5ec\ub984\uc5d0 \ub9ce\uc740 \uc5f4\uc744 \ud761\uc218\ud574 \uc8fc\ubcc0 \uae30\uc628\uc744 \ub192\uc785\ub2c8\ub2e4. \uc625\uc0c1\uc5d0 \uc2dd\ubb3c\uc744 \uc2ec\uc73c\uba74 \ud759\uacfc \uc78e\uc774 \ud587\ube5b\uc744 \ud761\uc218\ud558\uace0 \uc218\ubd84\uc744 \ub0b4\ubcf4\ub0b4 \uac74\ubb3c\uc758 \uc628\ub3c4\ub97c \ub0ae\ucd9c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc625\uc0c1 \uc815\uc6d0\uc740 \uc124\uce58\ud558\ub294 \uac83\ubcf4\ub2e4 \uc9c0\uc18d\uc801\uc73c\ub85c \uad00\ub9ac\ud558\ub294 \uc77c\uc774 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4. \uc9c0\uc5ed\uc758 \uae30\ud6c4\uc5d0 \ub9de\ub294 \uc2dd\ubb3c\uc744 \uc120\ud0dd\ud558\uace0 \ube57\ubb3c\uc744 \ud65c\uc6a9\ud558\ub294 \uad00\ub9ac \uccb4\uacc4\uac00 \ud568\uaed8 \ub9c8\ub828\ub418\uc5b4\uc57c \ud6a8\uacfc\uac00 \uc624\ub798\uac11\ub2c8\ub2e4.",!0)
A.YG=s([A.nmu],t.J)
A.kRF=s(["\uc625\uc0c1 \uc815\uc6d0\uc740 \uc124\uce58 \ube44\uc6a9\uc774 \ub0ae\uc744\uc218\ub85d \ud6a8\uacfc\uac00 \ud06c\ub2e4.","\ub3c4\uc2dc\uc758 \ubaa8\ub4e0 \uac74\ubb3c\uc5d0\ub294 \uac19\uc740 \uc2dd\ubb3c\uc744 \uc2ec\uc5b4\uc57c \ud55c\ub2e4.","\uc625\uc0c1 \uc815\uc6d0\uc758 \ud6a8\uacfc\ub97c \uc720\uc9c0\ud558\ub824\uba74 \uc801\uc808\ud55c \uad00\ub9ac \uccb4\uacc4\uac00 \ud544\uc694\ud558\ub2e4.","\uc625\uc0c1\uc5d0 \ud759\uc744 \ub193\uc73c\uba74 \uc8fc\ubcc0 \uae30\uc628\uc774 \ub354 \ub192\uc544\uc9c4\ub2e4."],t.s)
A.nnt=new B.ca(41,"\uc5ec\uc790\uc758 \uc911\uc2ec \uc0dd\uac01\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn suy ngh\u0129 ch\xednh c\u1ee7a ng\u01b0\u1eddi ph\u1ee5 n\u1eef.",A.YG,A.kRF,A.a0,3,"Ng\u01b0\u1eddi ph\u1ee5 n\u1eef nh\u1ea5n m\u1ea1nh r\u1eb1ng ngo\xe0i vi\u1ec7c l\u1eafp \u0111\u1eb7t, c\u1ea7n ch\u1ecdn c\xe2y ph\xf9 h\u1ee3p v\xe0 c\xf3 h\u1ec7 th\u1ed1ng qu\u1ea3n l\xfd l\xe2u d\xe0i \u0111\u1ec3 v\u01b0\u1eddn m\xe1i ph\xe1t huy hi\u1ec7u qu\u1ea3.")
A.lS6=s(["\uc625\uc0c1 \uc815\uc6d0\uc740 \uac74\ubb3c\uc758 \uc628\ub3c4\ub97c \ub192\uc774\ub294 \uc6d0\uc778\uc774 \ub41c\ub2e4.","\uc625\uc0c1 \uc815\uc6d0\uc5d0\ub294 \uc9c0\uc5ed \uae30\ud6c4\uc5d0 \ub9de\ub294 \uc2dd\ubb3c\uc744 \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4.","\uc625\uc0c1 \uc815\uc6d0\uc5d0\uc11c\ub294 \ube57\ubb3c\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4.","\ub3c4\uc2ec\uc758 \uc625\uc0c1\uc740 \uc5ec\ub984\uc5d0\ub3c4 \uc5f4\uc744 \uac70\uc758 \ud761\uc218\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.nnz=new B.ca(42,"\ub4e4\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u1eeba nghe.",A.YG,A.lS6,A.a0,2,"\u0110o\u1ea1n nghe n\xf3i c\u1ea7n l\u1ef1a ch\u1ecdn lo\u1ea1i c\xe2y ph\xf9 h\u1ee3p v\u1edbi kh\xed h\u1eadu c\u1ee7a khu v\u1ef1c.")
A.nmZ=new B.aP("N\u1eef","\uc774\ubc88\uc5d0 \ub9c8\uc744 \uc8fc\ubbfc\ub4e4\uc758 \uc0dd\uc560 \uc774\uc57c\uae30\ub97c \uc601\uc0c1\uc73c\ub85c \uae30\ub85d\ud558\uc168\ub2e4\uace0 \ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uc720\uba85 \uc778\ubb3c\ub3c4 \uc544\ub2cc \ud3c9\ubc94\ud55c \uc8fc\ubbfc\ub4e4\uc758 \uc774\uc57c\uae30\ub97c \uae30\ub85d\ud55c \uc774\uc720\uac00 \uc788\uc2b5\ub2c8\uae4c?",!0)
A.nmD=new B.aP("Nam","\uac1c\uc778\uc758 \uae30\uc5b5\uc5d0\ub294 \uacf5\uc2dd \ubb38\uc11c\uc5d0\uc11c \ucc3e\uae30 \uc5b4\ub824\uc6b4 \uc9c0\uc5ed\uc758 \ubcc0\ud654\uac00 \ub2f4\uaca8 \uc788\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 \uae30\uc5b5\uc774 \ud56d\uc0c1 \uc815\ud655\ud55c \uac83\uc740 \uc544\ub2c8\ubbc0\ub85c \ub2f9\uc2dc\uc758 \uc0ac\uc9c4\uc774\ub098 \uc2e0\ubb38 \uc790\ub8cc\uc640 \ube44\uad50\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uadf8\ub807\uac8c \uc5ec\ub7ec \uc790\ub8cc\ub97c \ud568\uaed8 \uc0b4\ud53c\uba74 \ud3c9\ubc94\ud55c \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\ub3c4 \uc9c0\uc5ed \uc5ed\uc0ac\ub97c \uc774\ud574\ud558\ub294 \uc18c\uc911\ud55c \uae30\ub85d\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",!1)
A.a39=s([A.nmZ,A.nmD],t.J)
A.jzQ=s(["\uc8fc\ubbfc\ub4e4\uc758 \uae30\uc5b5\uc774 \ubd80\uc815\ud655\ud558\ub2e4\uba70 \ubb34\uc2dc\ud558\uace0 \uc788\ub2e4.","\uc601\uc0c1 \uae30\ub85d \uc0ac\uc5c5\uc758 \uacb0\uacfc\ub97c \uc9c0\ub098\uce58\uac8c \uc790\ub791\ud558\uace0 \uc788\ub2e4.","\uacf5\uc2dd \ubb38\uc11c\ub9cc\uc774 \uc5ed\uc0ac \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \uc8fc\uc7a5\ud558\uace0 \uc788\ub2e4.","\uac1c\uc778\uc758 \uae30\uc5b5\uc744 \ub2e4\ub978 \uc790\ub8cc\uc640 \ud568\uaed8 \uac80\ud1a0\ud560 \ud544\uc694\uc131\uc744 \uc124\uba85\ud558\uace0 \uc788\ub2e4."],t.s)
A.nn3=new B.ca(43,"\ub0a8\uc790\uc758 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",u.zr,A.a39,A.jzQ,A.a0,4,"Ng\u01b0\u1eddi \u0111\xe0n \xf4ng \u0111\xe1nh gi\xe1 k\xfd \u1ee9c c\xe1 nh\xe2n l\xe0 c\xf3 gi\xe1 tr\u1ecb nh\u01b0ng c\u1ea7n \u0111\u1ed1i chi\u1ebfu v\u1edbi \u1ea3nh v\xe0 b\xe1o ch\xed c\xf9ng th\u1eddi.")
A.jBS=s(["\uc8fc\ubbfc\ub4e4\uc758 \uae30\uc5b5\uc740 \uc0ac\uc9c4\uc774\ub098 \uc2e0\ubb38 \uc790\ub8cc\uc640 \ube44\uad50\ud560 \ud544\uc694\uac00 \uc788\ub2e4.","\uc774 \uc0ac\uc5c5\uc740 \uc720\uba85 \uc778\ubb3c\uc758 \uc0dd\uc560\ub9cc \uc601\uc0c1\uc73c\ub85c \uae30\ub85d\ud588\ub2e4.","\uac1c\uc778\uc758 \uae30\uc5b5\uc5d0\ub294 \uc9c0\uc5ed\uc758 \ubcc0\ud654\uac00 \ub2f4\uae30\uae30 \uc5b4\ub835\ub2e4.","\ub0a8\uc790\ub294 \uacf5\uc2dd \ubb38\uc11c\ub97c \ubaa8\ub450 \uc5c6\uc560\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.nn9=new B.ca(44,"\ub4e4\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u1eeba nghe.",A.a39,A.jBS,A.a0,1,"Ng\u01b0\u1eddi \u0111\xe0n \xf4ng n\xf3i k\xfd \u1ee9c c\u1ee7a c\u01b0 d\xe2n c\u1ea7n \u0111\u01b0\u1ee3c so s\xe1nh v\u1edbi \u1ea3nh ho\u1eb7c t\u01b0 li\u1ec7u b\xe1o ch\xed l\xfac b\u1ea5y gi\u1edd.")
A.nmg=new B.aP("Nam","\uacfc\ud559 \uc5f0\uad6c\uc5d0\uc11c\ub294 \uc131\uacf5\ud55c \uc2e4\ud5d8 \uacb0\uacfc\uac00 \uc8fc\ub85c \ubc1c\ud45c\ub418\uace0 \uc2e4\ud328\ud55c \uacb0\uacfc\ub294 \uacf5\uac1c\ub418\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc2e4\ud5d8\uc774 \uc2e4\ud328\ud588\ub294\uc9c0\ub97c \uc54c\uba74 \ub2e4\ub978 \uc5f0\uad6c\uc790\uac00 \uac19\uc740 \uc2dc\ud589\ucc29\uc624\ub97c \ubc18\ubcf5\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\ud328 \uc790\ub8cc\ub97c \uacf5\uc720\ud558\uba74 \uc5f0\uad6c\uc758 \uc2e0\ub8b0\uc131\uc744 \ub192\uc774\uace0 \uc2dc\uac04\uacfc \ube44\uc6a9\ub3c4 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2e4\ud328\ub97c \ub2e8\uc21c\ud788 \uc228\uaca8\uc57c \ud560 \uacb0\uacfc\uac00 \uc544\ub2c8\ub77c \ub2e4\uc74c \uc5f0\uad6c\ub97c \uc704\ud55c \uc9c0\uc2dd\uc73c\ub85c \ubc14\ub77c\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.",!1)
A.a1H=s([A.nmg],t.J)
A.k4c=s(["\uc2e4\ud328\ud55c \uc5f0\uad6c\ub294 \uc2e0\ub8b0\uc131\uc774 \uc5c6\uc73c\ubbc0\ub85c \ubaa8\ub450 \uc911\ub2e8\ud574\uc57c \ud55c\ub2e4.","\uc5f0\uad6c \ube44\uc6a9\uc744 \uc904\uc774\ub824\uba74 \uc2e4\ud5d8 \ud69f\uc218\ub97c \uc81c\ud55c\ud574\uc57c \ud55c\ub2e4.","\uc2e4\ud328\ud55c \uc2e4\ud5d8 \uacb0\uacfc\ub3c4 \uc5f0\uad6c\uc5d0 \ub3c4\uc6c0\uc774 \ub418\ubbc0\ub85c \uacf5\uc720\ud560 \ud544\uc694\uac00 \uc788\ub2e4.","\uc131\uacf5\ud55c \uc5f0\uad6c \uacb0\uacfc\ub294 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc5d0\uac8c \uacf5\uac1c\ud558\uba74 \uc548 \ub41c\ub2e4."],t.s)
