p=B.a([B.dw("\uc5b4\ub514\uac00 \ubd88\ud3b8\ud574\uc11c \uc624\uc168\uc5b4\uc694?","\uac04\ud638\uc0ac","B\u1ea1n th\u1ea5y kh\xf3 ch\u1ecbu \u1edf \u0111\xe2u n\xean \u0111\u1ebfn kh\xe1m?"),B.dw("\uc0ac\ud758 \uc804\ubd80\ud130 \uc5f4\uc774 \ub098\uace0 \uae30\uce68\ud560 \ub54c \uac00\uc2b4\uc774 \uc544\ud30c\uc694.",i,"T\xf4i b\u1ecb s\u1ed1t ba ng\xe0y nay v\xe0 \u0111au ng\u1ef1c khi ho."),B.dw("\uc9c4\ub8cc \uc608\uc57d\uc740 \ud558\uc168\uc5b4\uc694?","\uac04\ud638\uc0ac","B\u1ea1n \u0111\xe3 \u0111\u1eb7t l\u1ecbch kh\xe1m ch\u01b0a?"),B.dw("\uc544\ub2c8\uc694, \uc624\ub298 \ucc98\uc74c \uc654\uc5b4\uc694.",i,"Ch\u01b0a, h\xf4m nay t\xf4i \u0111\u1ebfn l\u1ea7n \u0111\u1ea7u."),B.dw("\uc774 \uc11c\ub958\ub97c \uc791\uc131\ud558\uace0 \ub300\uae30\uc2e4\uc5d0\uc11c \uae30\ub2e4\ub824 \uc8fc\uc138\uc694.","\uac04\ud638\uc0ac","H\xe3y \u0111i\u1ec1n gi\u1ea5y n\xe0y r\u1ed3i \u0111\u1ee3i \u1edf ph\xf2ng ch\u1edd."),B.dw("\ub124, \uac74\uac15\ubcf4\ud5d8\ub3c4 \uc801\uc6a9\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.",i,"V\xe2ng, h\xe3y ki\u1ec3m tra gi\xfap t\xf4i c\xf3 \xe1p d\u1ee5ng b\u1ea3o hi\u1ec3m kh\xf4ng.")],a4)
a3=B.vq(B.a(["\uc544\ud504\ub2e4 \u0111i v\u1edbi b\u1ed9 ph\u1eadn c\u01a1 th\u1ec3 d\xf9ng \uc774/\uac00: \uba38\ub9ac\uac00 \uc544\ud30c\uc694, \ubc30\uac00 \uc544\ud30c\uc694.","\ubcd1\uc6d0\uc5d0 \uac00\ub2e4 l\xe0 \u0111i b\u1ec7nh vi\u1ec7n; \uc9c4\ub8cc\ub97c \ubc1b\ub2e4 l\xe0 \u0111\u01b0\u1ee3c b\xe1c s\u0129 kh\xe1m v\xe0 \u0111i\u1ec1u tr\u1ecb.","V-(\uc73c)\u3134 \uc9c0 \u0111i v\u1edbi kho\u1ea3ng th\u1eddi gian, v\xed d\u1ee5 \uc544\ud508 \uc9c0 \uc774\ud2c0 \ub410\uc5b4\uc694."],c),p,24,a2,a5,B.a([B.e0(1,"\ub300\uae30\uc2e4 l\xe0 n\u01a1i b\u1ec7nh nh\xe2n ng\u1ed3i ch\u1edd \u0111\u1ebfn l\u01b0\u1ee3t kh\xe1m.",B.a(["\uc57d\uad6d","\ub300\uae30\uc2e4","\ubd80\ub3d9\uc0b0","\ucc3d\uad6c"],c),"\ubcd1\uc6d0\uc5d0\uc11c \uc9c4\ub8cc\ub97c \uae30\ub2e4\ub9ac\ub294 \uc7a5\uc18c\ub294 \uc5b4\ub514\uc785\ub2c8\uae4c?"),B.e0(2,"\ub0b4\uacfc v\xe0 \uc815\ud615\uc678\uacfc l\xe0 c\xe1c \uc9c4\ub8cc\uacfc, t\u1ee9c khoa kh\xe1m.",B.a(["\ucc98\ubc29\uc804","\uc9c4\ub8cc\ube44","\uc9c4\ub8cc\uacfc","\ubcf4\ud5d8\ub8cc"],c),"\uc99d\uc0c1\uc5d0 \ub530\ub77c \ub0b4\uacfc\ub098 \uc815\ud615\uc678\uacfc\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc740 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc785\ub2c8\uae4c?"),B.e0(0,"\uae30\uce68\ud560 \ub54c ngh\u0129a l\xe0 khi ho.",B.a(["\ub54c","\uc9c0","\ub7ec","\uace0"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uae30\uce68\ud560 ___ \uac00\uc2b4\uc774 \uc544\ud30c\uc694."),B.e0(3,"B\u1ea3o hi\u1ec3m \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn kho\u1ea3n chi ph\xed ng\u01b0\u1eddi b\u1ec7nh ph\u1ea3i thanh to\xe1n.",B.a(["\ub0a0\uc528\ub97c \uc54c\uae30 \uc704\ud574","\uc608\uc57d \uc2dc\uac04\uc744 \ubc14\uafb8\uae30 \uc704\ud574","\uc758\uc0ac \uc774\ub984\uc744 \uc54c\uae30 \uc704\ud574","\uc9c4\ub8cc\ube44 \ubd80\ub2f4\uc744 \ud655\uc778\ud558\uae30 \uc704\ud574"],c),"\uac74\uac15\ubcf4\ud5d8\uc774 \uc801\uc6a9\ub418\ub294\uc9c0 \ubb3b\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.e0(1,"K\u1ebft qu\u1ea3 c\xf3 v\xe0o ng\xe0y mai n\xean b\u1ec7nh nh\xe2n c\u1ea7n quay l\u1ea1i b\u1ec7nh vi\u1ec7n.",B.a(["\uc624\ub298 \uacb0\uacfc\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.","\ub0b4\uc77c \ub2e4\uc2dc \ubcd1\uc6d0\uc5d0 \uac00\uc57c \ud569\ub2c8\ub2e4.","\uac80\uc0ac\ub97c \ucde8\uc18c\ud588\uc2b5\ub2c8\ub2e4.","\uc57d\uad6d\uc5d0\uc11c \uacb0\uacfc\ub97c \ubc1b\uc2b5\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uac04\ud638\uc0ac: \uac80\uc0ac \uacb0\uacfc\ub294 \ub0b4\uc77c \ub098\uc624\ub2c8\uae4c \ub2e4\uc2dc \ubc29\ubb38\ud574 \uc8fc\uc138\uc694.")],a6),"\u0110\xf3ng vai b\u1ec7nh nh\xe2n: tr\xecnh b\xe0y tri\u1ec7u ch\u1ee9ng, th\u1eddi \u0111i\u1ec3m b\u1eaft \u0111\u1ea7u, m\u1ee9c \u0111\u1ed9 \u0111au v\xe0 h\u1ecfi c\u1ea7n kh\xe1m khoa n\xe0o.",q,a3,"Vi\u1ebft 5\u20136 c\xe2u ghi l\u1ea1i tri\u1ec7u ch\u1ee9ng \u0111\u1ec3 \u0111\u01b0a b\xe1c s\u0129 xem, g\u1ed3m th\u1eddi gian, v\u1ecb tr\xed \u0111au, m\u1ee9c \u0111\u1ed9 v\xe0 thu\u1ed1c \u0111\xe3 d\xf9ng.")
q=B.a(["M\xf4 t\u1ea3 \u0111\u01b0\u1ee3c tri\u1ec7u ch\u1ee9ng \u0111\u1ec3 mua thu\u1ed1c kh\xf4ng k\xea \u0111\u01a1n.","H\u1ecfi v\xe0 hi\u1ec3u \u0111\u01b0\u1ee3c li\u1ec1u l\u01b0\u1ee3ng, th\u1eddi \u0111i\u1ec3m c\xf9ng s\u1ed1 ng\xe0y d\xf9ng thu\u1ed1c.","Nh\u1eadn bi\u1ebft \u0111\u01b0\u1ee3c c\u1ea3nh b\xe1o v\u1ec1 bu\u1ed3n ng\u1ee7 v\xe0 t\xe1c d\u1ee5ng ph\u1ee5.","Ph\xe2n bi\u1ec7t \u0111\u01b0\u1ee3c thu\u1ed1c u\u1ed1ng v\u1edbi thu\u1ed1c b\xf4i trong t\xecnh hu\u1ed1ng c\u01a1 b\u1ea3n."],c)
