a5=B.vq(B.a(["\uc57d\uc744 \uba39\ub2e4 d\xf9ng cho thu\u1ed1c u\u1ed1ng; \uc5f0\uace0\ub97c \ubc14\ub974\ub2e4 d\xf9ng cho thu\u1ed1c b\xf4i.","\uc2dd\uc804 l\xe0 tr\u01b0\u1edbc b\u1eefa \u0103n; \uc2dd\ud6c4 l\xe0 sau b\u1eefa \u0103n.","\ud558\ub8e8 \uc138 \ubc88 ngh\u0129a l\xe0 ba l\u1ea7n trong m\u1ed9t ng\xe0y, kh\xf4ng ph\u1ea3i u\u1ed1ng ba vi\xean c\xf9ng l\xfac."],c),o,22,a2,q,B.a([B.e0(1,"\uc5f0\uace0 l\xe0 thu\u1ed1c d\u1ea1ng b\xf4i d\xf9ng ngo\xe0i da.",B.a(["\uc54c\uc57d","\uc5f0\uace0","\uac10\uae30\uc57d","\ucc98\ubc29\uc804"],c),"\uc0c1\ucc98\uac00 \ub09c \ud53c\ubd80\uc5d0 \uc0ac\uc6a9\ud558\ub294 \uc57d\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.e0(2,"Khi thu\u1ed1c g\xe2y bu\u1ed3n ng\u1ee7 c\u1ea7n tr\xe1nh l\xe1i xe.",B.a(["\uc26c\uae30","\ubb3c \ub9c8\uc2dc\uae30","\uc6b4\uc804\ud558\uae30","\uc124\uba85 \uc77d\uae30"],c),"\uc57d\uc744 \uba39\uc740 \ub4a4 \uc878\ub9b4 \uc218 \uc788\uc744 \ub54c \ud53c\ud574\uc57c \ud560 \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.e0(0,"V-\uc9c0 \ub9c8\uc138\uc694 d\xf9ng \u0111\u1ec3 c\u1ea3nh b\xe1o \u0111\u1eebng th\u1ef1c hi\u1ec7n h\xe0nh \u0111\u1ed9ng.",B.a(["\ub9c8\uc138\uc694","\uc788\uc5b4\uc694","\uc2f6\uc5b4\uc694","\ubd24\uc5b4\uc694"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc57d\uc744 \uba39\uace0 \uc6b4\uc804\ud558\uc9c0 ___."),B.e0(3,"S\u1ed1 xe bu\xfdt kh\xf4ng li\xean quan \u0111\u1ebfn vi\u1ec7c s\u1eed d\u1ee5ng thu\u1ed1c.",B.a(["\ubcf5\uc6a9 \ud69f\uc218","\uc720\ud1b5\uae30\ud55c","\ubd80\uc791\uc6a9","\ubc84\uc2a4 \ubc88\ud638"],c),"\uc57d\uc744 \uc548\uc804\ud558\uac8c \uc0ac\uc6a9\ud558\uae30 \uc704\ud574 \ud655\uc778\ud560 \ub0b4\uc6a9\uc774 \uc544\ub2cc \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.e0(1,"\uc2dd\ud6c4\uc5d0 \ud558\ub8e8 \uc138 \ubc88 ngh\u0129a l\xe0 u\u1ed1ng ba l\u1ea7n m\u1ed7i ng\xe0y sau b\u1eefa \u0103n.",B.a(["\uc2dd\uc0ac \uc804\uc5d0 \ud55c \ubc88 \uba39\uc2b5\ub2c8\ub2e4.","\uc2dd\uc0ac \ud6c4\uc5d0 \ud558\ub8e8 \uc138 \ubc88 \uba39\uc2b5\ub2c8\ub2e4.","\uc7a0\uc790\uae30 \uc804\uc5d0\ub9cc \uba39\uc2b5\ub2c8\ub2e4.","\uc544\ud50c \ub54c\ub9c8\ub2e4 \uacc4\uc18d \uba39\uc2b5\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc57d\uc0ac: \uc774 \uc57d\uc740 \uc2dd\ud6c4\uc5d0 \ud558\ub8e8 \uc138 \ubc88 \ub4dc\uc138\uc694.")],a6),"\u0110\xf3ng vai mua thu\u1ed1c: n\xf3i hai tri\u1ec7u ch\u1ee9ng r\u1ed3i h\u1ecfi li\u1ec1u d\xf9ng, th\u1eddi \u0111i\u1ec3m u\u1ed1ng v\xe0 \u0111i\u1ec1u c\u1ea7n tr\xe1nh.",p,a5,"Vi\u1ebft h\u01b0\u1edbng d\u1eabn s\u1eed d\u1ee5ng thu\u1ed1c 5 c\xe2u g\u1ed3m s\u1ed1 l\u1ea7n, th\u1eddi \u0111i\u1ec3m, th\u1eddi gian d\xf9ng v\xe0 hai \u0111i\u1ec1u c\u1ea7n ch\xfa \xfd.")
p=B.a(["Y\xeau c\u1ea7u \u0111\u01b0\u1ee3c m\u1edf t\xe0i kho\u1ea3n v\xe0 chu\u1ea9n b\u1ecb gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft.","Th\u1ef1c hi\u1ec7n \u0111\u01b0\u1ee3c y\xeau c\u1ea7u chuy\u1ec3n ti\u1ec1n, ki\u1ec3m tra h\u1ea1n m\u1ee9c v\xe0 ph\xed.","H\u1ecfi \u0111\u01b0\u1ee3c l\u1ecbch s\u1eed giao d\u1ecbch v\xe0 \u0111\u0103ng k\xfd chuy\u1ec3n kho\u1ea3n t\u1ef1 \u0111\u1ed9ng.","Bi\u1ebft c\xe1ch x\u1eed l\xfd an to\xe0n khi qu\xean ho\u1eb7c b\u1ecb h\u1ecfi m\u1eadt kh\u1ea9u."],c)
