k=B.a([B.dw("\ubbfc \uc528\ub294 \uc624\ub298\ubd80\ud130 \uc81c\ud488 \uac80\uc0ac\ub97c \ub2f4\ub2f9\ud574 \uc8fc\uc138\uc694.",e,"T\u1eeb h\xf4m nay anh Min h\xe3y ph\u1ee5 tr\xe1ch ki\u1ec3m tra s\u1ea3n ph\u1ea9m."),B.dw("\ub124, \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \ud655\uc778\ud558\uba74 \ub429\ub2c8\uae4c?",i,"V\xe2ng, t\xf4i c\u1ea7n ki\u1ec3m tra theo ti\xeau chu\u1ea9n n\xe0o?"),B.dw("\uc774 \uc790\ub8cc\ub97c \uba3c\uc800 \uc77d\uace0 \ubd88\ub7c9 \uc81c\ud488\uc744 \ub530\ub85c \uc815\ub9ac\ud558\uc138\uc694.",e,"H\xe3y \u0111\u1ecdc t\xe0i li\u1ec7u n\xe0y tr\u01b0\u1edbc r\u1ed3i ph\xe2n lo\u1ea1i ri\xeang s\u1ea3n ph\u1ea9m l\u1ed7i."),B.dw("\uac80\uc0ac\uac00 \ub05d\ub09c \ud6c4\uc5d0 \ubc14\ub85c \ubcf4\uace0\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.",i,"Sau khi ki\u1ec3m tra xong t\xf4i s\u1ebd b\xe1o c\xe1o ngay."),B.dw("\ubb38\uc81c\uac00 \uc788\uc73c\uba74 \ud63c\uc790 \ucc98\ub9ac\ud558\uc9c0 \ub9d0\uace0 \uc800\uc5d0\uac8c \uc54c\ub824 \uc8fc\uc138\uc694.",e,"N\u1ebfu c\xf3 v\u1ea5n \u0111\u1ec1, \u0111\u1eebng t\u1ef1 x\u1eed l\xfd m\xe0 h\xe3y b\xe1o cho t\xf4i."),B.dw("\ub124, \uc9c4\ud589 \uc0c1\ud669\ub3c4 \uc624\ud6c4\uc5d0 \uacf5\uc720\ud558\uaca0\uc2b5\ub2c8\ub2e4.",i,"V\xe2ng, bu\u1ed5i chi\u1ec1u t\xf4i c\u0169ng s\u1ebd chia s\u1ebb ti\u1ebfn \u0111\u1ed9.")],a4)
n=B.vq(B.a(["\uc5c5\ubb34 l\xe0 c\xf4ng vi\u1ec7c n\xf3i chung; \uc791\uc5c5 th\u01b0\u1eddng ch\u1ec9 thao t\xe1c ho\u1eb7c nhi\u1ec7m v\u1ee5 c\u1ee5 th\u1ec3.","\ubcf4\uace0\ud558\ub2e4 c\u1ea7n ng\u01b0\u1eddi nh\u1eadn: \ud300\uc7a5\ub2d8\uaed8 \ubcf4\uace0\ud558\ub2e4 t\u1ef1 nhi\xean v\xe0 l\u1ecbch s\u1ef1.","\ud655\uc778\ud558\ub2e4 l\xe0 ki\u1ec3m tra/x\xe1c nh\u1eadn; \uc218\uc815\ud558\ub2e4 l\xe0 thay \u0111\u1ed5i n\u1ed9i dung sai ho\u1eb7c ch\u01b0a ph\xf9 h\u1ee3p."],c),k,25,a2,m,B.a([B.e0(0,"\ub2f4\ub2f9\ud558\ub2e4 ngh\u0129a l\xe0 \u0111\u1ea3m nh\u1eadn v\xe0 ph\u1ee5 tr\xe1ch m\u1ed9t c\xf4ng vi\u1ec7c.",B.a(["\ub2f4\ub2f9\ud558\ub2e4","\uc774\uc0ac\ud558\ub2e4","\ubcf5\uc6a9\ud558\ub2e4","\uc1a1\uae08\ud558\ub2e4"],c),"\uc790\uc2e0\uc774 \ub9e1\uc544\uc11c \ucc45\uc784\uc9c0\uace0 \ud558\ub294 \uc77c\uc744 \ud45c\ud604\ud558\ub294 \ub3d9\uc0ac\ub97c \uace0\ub974\uc2ed\uc2dc\uc624."),B.e0(1,"\ub9c8\uac10 l\xe0 h\u1ea1n cu\u1ed1i c\u1ea7n ho\xe0n th\xe0nh c\xf4ng vi\u1ec7c.",B.a(["\uc790\ub8cc","\ub9c8\uac10","\ub3d9\ub8cc","\ud68c\uc758\uc2e4"],c),"\uc77c\uc744 \ub05d\ub0b4\uc57c \ud558\ub294 \ub9c8\uc9c0\ub9c9 \ub0a0\uc9dc\ub098 \uc2dc\uac04\uc744 \ubb34\uc5c7\uc774\ub77c\uace0 \ud569\ub2c8\uae4c?"),B.e0(2,"\ud655\uc778\ud55c \ud6c4\uc5d0 ngh\u0129a l\xe0 sau khi \u0111\xe3 ki\u1ec3m tra.",B.a(["\ub3d9\uc548","\uc804\uc5d0\ub9cc","\ud6c4\uc5d0","\ubcf4\ub2e4"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc790\ub8cc\ub97c \ud655\uc778\ud55c ___ \ubcf4\uace0\ud574 \uc8fc\uc138\uc694."),B.e0(3,"C\u1ea7n x\xe1c nh\u1eadn t\xecnh h\xecnh v\xe0 b\xe1o ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch thay v\xec che gi\u1ea5u ho\u1eb7c \u0111o\xe1n.",B.a(["\uc228\uae41\ub2c8\ub2e4.","\uadf8\ub0e5 \ud1f4\uadfc\ud569\ub2c8\ub2e4.","\ud63c\uc790 \ucd94\uce21\ud569\ub2c8\ub2e4.","\uc0c1\ud669\uc744 \ud655\uc778\ud558\uace0 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\uace0\ud569\ub2c8\ub2e4."],c),"\uc5c5\ubb34 \uc911 \ubb38\uc81c\ub97c \ubc1c\uacac\ud588\uc744 \ub54c \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.e0(0,"Y\xeau c\u1ea7u b\xe1o k\u1ebft qu\u1ea3 v\xe0 ti\u1ebfn \u0111\u1ed9 tr\u01b0\u1edbc 3 gi\u1edd chi\u1ec1u.",B.a(["\uc624\ud6c4 \uc138 \uc2dc\uae4c\uc9c0 \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\ub2e4.","\uac80\uc0ac\ub97c \ud558\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4.","\ub0b4\uc77c \uc790\ub8cc\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud68c\uc758\ub97c \ub2f4\ub2f9\ud569\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ud300\uc7a5: \uac80\uc0ac \uacb0\uacfc\uc640 \uc9c4\ud589 \uc0c1\ud669\uc744 \uc624\ud6c4 \uc138 \uc2dc\uae4c\uc9c0 \uc54c\ub824 \uc8fc\uc138\uc694.")],a6),"B\xe1o c\xe1o m\u1ed9t nhi\u1ec7m v\u1ee5 theo b\u1ed1n \xfd: vi\u1ec7c ph\u1ee5 tr\xe1ch, ti\u1ebfn \u0111\u1ed9 hi\u1ec7n t\u1ea1i, v\u1ea5n \u0111\u1ec1 v\xe0 th\u1eddi gian d\u1ef1 ki\u1ebfn ho\xe0n th\xe0nh.",l,n,"Vi\u1ebft b\xe1o c\xe1o c\xf4ng vi\u1ec7c 6 c\xe2u g\u1ed3m nhi\u1ec7m v\u1ee5, vi\u1ec7c \u0111\xe3 l\xe0m, k\u1ebft qu\u1ea3, v\u1ea5n \u0111\u1ec1 v\xe0 b\u01b0\u1edbc ti\u1ebfp theo.")
l=B.a(["S\u1eed d\u1ee5ng \u0111\u01b0\u1ee3c c\xe1ch ch\xe0o h\u1ecfi v\xe0 x\u01b0ng h\xf4 ph\xf9 h\u1ee3p \u1edf n\u01a1i l\xe0m vi\u1ec7c.","Nh\u1edd v\u1ea3, xin ph\xe9p v\xe0 t\u1eeb ch\u1ed1i m\u1ed9t c\xe1ch l\u1ecbch s\u1ef1.","Xin l\u1ed7i v\xe0 gi\u1ea3i th\xedch \u0111\u01b0\u1ee3c khi g\xe2y b\u1ea5t ti\u1ec7n ho\u1eb7c m\u1eafc sai s\xf3t.","Nh\u1eadn bi\u1ebft \u0111\u01b0\u1ee3c h\xe0nh vi n\xean tr\xe1nh trong kh\xf4ng gian l\xe0m vi\u1ec7c chung."],c)
m=B.a([B.dx("\ud68c\uc758\uc2e4\uc5d0\uc11c\ub294 \ud734\ub300\uc804\ud654\ub97c \uc870\uc6a9\ud788 \ud574 \uc8fc\uc138\uc694.","Trong ph\xf2ng h\u1ecdp h\xe3y \u0111\u1ec3 \u0111i\u1ec7n tho\u1ea1i im l\u1eb7ng.","\ud68c\uc758\uc2e4","Ph\xf2ng h\u1ecdp"),B.dx("\ub2e4\ub978 \uc0ac\ub78c \uc790\ub9ac\uc5d0 \uc549\uae30 \uc804\uc5d0 \ubb3c\uc5b4\ubcf4\uc138\uc694.","H\xe3y h\u1ecfi tr\u01b0\u1edbc khi ng\u1ed3i v\xe0o ch\u1ed7 ng\u01b0\u1eddi kh\xe1c.","\uc790\ub9ac","Ch\u1ed7 ng\u1ed3i, v\u1ecb tr\xed l\xe0m vi\u1ec7c"),B.dx("\uc11c\ub85c \ubc30\ub824\ud558\uba74 \ud3b8\ud558\uac8c \uc77c\ud560 \uc218 \uc788\uc5b4\uc694.","N\u1ebfu quan t\xe2m l\u1eabn nhau th\xec c\xf3 th\u1ec3 l\xe0m vi\u1ec7c tho\u1ea3i m\xe1i.","\ubc30\ub824\ud558\ub2e4","Quan t\xe2m, \u0111\u1ec3 \xfd \u0111\u1ebfn ng\u01b0\u1eddi kh\xe1c"),B.dx("\ud070 \uc18c\ub9ac\ub85c \ub3d9\ub8cc\uc758 \uc5c5\ubb34\ub97c \ubc29\ud574\ud558\uc9c0 \ub9c8\uc138\uc694.","\u0110\u1eebng n\xf3i l\u1edbn l\xe0m phi\u1ec1n c\xf4ng vi\u1ec7c c\u1ee7a \u0111\u1ed3ng nghi\u1ec7p.","\ubc29\ud574\ud558\ub2e4","L\xe0m phi\u1ec1n, c\u1ea3n tr\u1edf"),B.dx("\ub2a6\uc744 \uac83 \uac19\uc73c\uba74 \ubbf8\ub9ac \uc5f0\ub77d\ud558\uc138\uc694.","N\u1ebfu c\xf3 v\u1ebb s\u1ebd mu\u1ed9n, h\xe3y li\xean l\u1ea1c tr\u01b0\u1edbc.","\ubbf8\ub9ac","Tr\u01b0\u1edbc, t\u1eeb tr\u01b0\u1edbc"),B.dx("\ubd80\ud0c1\ud560 \ub54c\ub294 \uc815\uc911\ud558\uac8c \ub9d0\ud574\uc57c \ud574\uc694.","Khi nh\u1edd v\u1ea3 c\u1ea7n n\xf3i l\u1ecbch s\u1ef1.","\uc815\uc911\ud558\ub2e4","L\u1ecbch s\u1ef1, trang tr\u1ecdng")],a)
a2=B.a([B.ub("\ud68c\uc0ac\uc5d0\uc11c\ub294 \uc874\ub313\ub9d0\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\uc544\uc694.","D\xf9ng \u0111\u1ec3 \u0111\u01b0a ra l\u1eddi khuy\xean nh\u1eb9 nh\xe0ng v\u1ec1 h\xe0nh vi ph\xf9 h\u1ee3p.","N\xean l\xe0m V","V-\ub294 \uac83\uc774 \uc88b\uc544\uc694","\u1ede c\xf4ng ty n\xean s\u1eed d\u1ee5ng k\xednh ng\u1eef.")],a1)
