j=B.a([B.dw("\ud300\uc7a5\ub2d8, \uc7a0\uae50 \ub9d0\uc500\ub4dc\ub824\ub3c4 \ub420\uae4c\uc694?",i,u.eN),B.dw("\ub124, \ubb34\uc2a8 \uc77c\uc774\uc5d0\uc694?",e,"\u0110\u01b0\u1ee3c, c\xf3 vi\u1ec7c g\xec v\u1eady?"),B.dw("\ub0b4\uc77c \ubcd1\uc6d0 \uc608\uc57d\uc774 \uc788\uc5b4\uc11c \ud55c \uc2dc\uac04 \uc77c\ucc0d \ud1f4\uadfc\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.",i,"Ng\xe0y mai t\xf4i c\xf3 l\u1ecbch b\u1ec7nh vi\u1ec7n n\xean mu\u1ed1n tan l\xe0m s\u1edbm m\u1ed9t gi\u1edd."),B.dw("\ub9e1\uc740 \uc5c5\ubb34\ub97c \uba3c\uc800 \ub9c8\uce60 \uc218 \uc788\uc5b4\uc694?",e,"B\u1ea1n c\xf3 th\u1ec3 ho\xe0n th\xe0nh c\xf4ng vi\u1ec7c \u0111\u01b0\u1ee3c giao tr\u01b0\u1edbc kh\xf4ng?"),B.dw("\ub124, \uc624\ub298 \ubbf8\ub9ac \uc815\ub9ac\ud574 \ub193\uaca0\uc2b5\ub2c8\ub2e4.",i,"V\xe2ng, h\xf4m nay t\xf4i s\u1ebd chu\u1ea9n b\u1ecb xong tr\u01b0\u1edbc."),B.dw("\uadf8\ub7fc \ub3d9\ub8cc\uc5d0\uac8c\ub3c4 \uc77c\uc815\uc744 \uacf5\uc720\ud574 \uc8fc\uc138\uc694.",e,"V\u1eady h\xe3y chia s\u1ebb l\u1ecbch v\u1edbi \u0111\u1ed3ng nghi\u1ec7p n\u1eefa.")],a4)
m=B.vq(B.a(["\uc0c1\uc0ac ho\u1eb7c \ud300\uc7a5\ub2d8 c\u1ea7n \u0111\u01b0\u1ee3c x\u01b0ng h\xf4 b\u1eb1ng ch\u1ee9c danh v\xe0 \ub2d8 trong giao ti\u1ebfp tr\u1ef1c ti\u1ebfp.","\ubd80\ud0c1\ud558\ub2e4 kh\xf4ng \u0111\u1ed3ng ngh\u0129a ra l\u1ec7nh; h\xe3y d\xf9ng -\uc544/\uc5b4 \uc8fc\uc138\uc694 ho\u1eb7c -(\uc73c)\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?.","Xin l\u1ed7i n\xean k\xe8m v\u1ea5n \u0111\u1ec1 v\xe0 c\xe1ch kh\u1eafc ph\u1ee5c, kh\xf4ng ch\u1ec9 n\xf3i \uc8c4\uc1a1\ud569\ub2c8\ub2e4 r\u1ed3i k\u1ebft th\xfac."],c),j,25,a2,l,B.a([B.e0(0,"\ubc30\ub824\ud558\ub2e4 l\xe0 quan t\xe2m v\xe0 h\xe0nh \u0111\u1ed9ng c\xf3 c\xe2n nh\u1eafc \u0111\u1ebfn ng\u01b0\u1eddi kh\xe1c.",B.a(["\ubc30\ub824\ud558\ub2e4","\ubc29\ud574\ud558\ub2e4","\uc2e4\uc218\ud558\ub2e4","\uac70\uc808\ud558\ub2e4"],c),"\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\uace0 \ud589\ub3d9\ud558\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.e0(1,"Khi c\xf3 th\u1ec3 mu\u1ed9n n\xean b\xe1o tr\u01b0\u1edbc \u0111\u1ec3 n\u01a1i l\xe0m vi\u1ec7c ch\u1ee7 \u0111\u1ed9ng s\u1eafp x\u1ebfp.",B.a(["\ub3c4\ucc29\ud55c \ud6c4 \uc228\uae41\ub2c8\ub2e4.","\ubbf8\ub9ac \uc5f0\ub77d\ud569\ub2c8\ub2e4.","\uc544\ubb34 \ub9d0\ub3c4 \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ub3d9\ub8cc \ud0d3\uc744 \ud569\ub2c8\ub2e4."],c),"\ub2a6\uc744 \uac83 \uac19\uc744 \ub54c \uc9c1\uc7a5 \uc608\uc808\uc5d0 \ub9de\ub294 \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.e0(2,"V-\ub294 \uac83\uc774 \uc88b\uc544\uc694 d\xf9ng \u0111\u1ec3 \u0111\u01b0a l\u1eddi khuy\xean.",B.a(["\uac70\ub098","\uc9c0\ub9cc","\ub294 \uac83\uc774","\ub294 \ub3d9\uc548"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ud68c\uc0ac\uc5d0\uc11c\ub294 \uc874\ub313\ub9d0\uc744 \uc0ac\uc6a9\ud558___ \uc88b\uc544\uc694."),B.e0(3,"G\u1ecdi \u0111i\u1ec7n c\xe1 nh\xe2n l\u1edbn ti\u1ebfng l\xe0m \u1ea3nh h\u01b0\u1edfng cu\u1ed9c h\u1ecdp v\xe0 ng\u01b0\u1eddi kh\xe1c.",B.a(["\ubc1c\ud45c\ub97c \ub4e3\uc2b5\ub2c8\ub2e4.","\ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \uae30\ub85d\ud569\ub2c8\ub2e4.","\uc9c8\ubb38\ud560 \ub54c \uc21c\uc11c\ub97c \uae30\ub2e4\ub9bd\ub2c8\ub2e4.","\ud070 \uc18c\ub9ac\ub85c \uac1c\uc778 \uc804\ud654\ub97c \ud569\ub2c8\ub2e4."],c),"\ud68c\uc758 \uc911\uc5d0 \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.e0(1,"Ng\u01b0\u1eddi n\xf3i \u0111ang xin ph\xe9p tan l\xe0m s\u1edbm m\u1ed9t gi\u1edd.",B.a(["\ubbfc\uc740 \ud734\uac00\ub97c \ucde8\uc18c\ud569\ub2c8\ub2e4.","\ubbfc\uc740 \uc870\ud1f4 \ud5c8\ub77d\uc744 \uad6c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\ubbfc\uc740 \ub3d9\ub8cc\uc5d0\uac8c \ud654\ub97c \ub0c5\ub2c8\ub2e4.","\ubbfc\uc740 \ud68c\uc758 \uc2dc\uac04\uc744 \uc815\ud569\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc: \ub0b4\uc77c \ubcd1\uc6d0 \uc608\uc57d \ub54c\ubb38\uc5d0 \ud55c \uc2dc\uac04 \uc77c\ucc0d \ud1f4\uadfc\ud574\ub3c4 \ub420\uae4c\uc694?")],a6),"\u0110\xf3ng vai xin ph\xe9p v\u1ec1 s\u1edbm: ch\xe0o h\u1ecfi, n\xf3i l\xfd do, tr\xecnh b\xe0y c\xe1ch x\u1eed l\xfd c\xf4ng vi\u1ec7c v\xe0 c\u1ea3m \u01a1n c\u1ea5p tr\xean.",k,m,"Vi\u1ebft tin nh\u1eafn c\xf4ng vi\u1ec7c 5\u20136 c\xe2u \u0111\u1ec3 xin l\u1ed7i v\xec \u0111\u1ebfn mu\u1ed9n v\xe0 th\xf4ng b\xe1o th\u1eddi gian d\u1ef1 ki\u1ebfn c\xf3 m\u1eb7t.")
k=B.a(["\u0110\u1ecdc v\xe0 ch\u1ecdn \u0111\u01b0\u1ee3c th\xf4ng tin ch\xednh trong m\u1ed9t th\xf4ng b\xe1o tuy\u1ec3n d\u1ee5ng.","Gi\u1edbi thi\u1ec7u \u0111\u01b0\u1ee3c kinh nghi\u1ec7m, k\u1ef9 n\u0103ng, \u01b0u \u0111i\u1ec3m v\xe0 \u0111i\u1ec3m c\u1ea7n c\u1ea3i thi\u1ec7n.","H\u1ecfi v\xe0 hi\u1ec3u \u0111\u01b0\u1ee3c \u0111i\u1ec1u ki\u1ec7n, th\u1eddi gian c\xf9ng n\u1ed9i dung c\xf4ng vi\u1ec7c.","Tr\u1ea3 l\u1eddi \u0111\u01b0\u1ee3c c\xe1c c\xe2u h\u1ecfi ph\u1ecfng v\u1ea5n c\u01a1 b\u1ea3n b\u1eb1ng c\xe2u ho\xe0n ch\u1ec9nh."],c)
a=B.a([B.dx("\uc778\ud130\ub137\uc5d0\uc11c \ucc44\uc6a9 \uacf5\uace0\ub97c \ud655\uc778\ud588\uc5b4\uc694.","T\xf4i \u0111\xe3 xem th\xf4ng b\xe1o tuy\u1ec3n d\u1ee5ng tr\xean m\u1ea1ng.","\ucc44\uc6a9 \uacf5\uace0","Th\xf4ng b\xe1o tuy\u1ec3n d\u1ee5ng"),B.dx("\uc9c0\uc6d0 \uc804\uc5d0 \uc790\uae30\uc18c\uac1c\uc11c\ub97c \uc791\uc131\ud588\uc5b4\uc694.","T\xf4i \u0111\xe3 vi\u1ebft b\xe0i t\u1ef1 gi\u1edbi thi\u1ec7u tr\u01b0\u1edbc khi \u1ee9ng tuy\u1ec3n.","\uc790\uae30\uc18c\uac1c\uc11c","B\xe0i t\u1ef1 gi\u1edbi thi\u1ec7u xin vi\u1ec7c"),B.dx("\uba74\uc811\uad00\uc774 \uacbd\ub825\uc5d0 \ub300\ud574 \uc9c8\ubb38\ud588\uc5b4\uc694.","Ng\u01b0\u1eddi ph\u1ecfng v\u1ea5n h\u1ecfi v\u1ec1 kinh nghi\u1ec7m l\xe0m vi\u1ec7c.",d,"Ng\u01b0\u1eddi ph\u1ecfng v\u1ea5n"),B.dx("\uc81c \uc7a5\uc810\uc740 \ucc45\uc784\uac10\uc774 \uac15\ud55c \uac83\uc785\ub2c8\ub2e4.","\u01afu \u0111i\u1ec3m c\u1ee7a t\xf4i l\xe0 c\xf3 tinh th\u1ea7n tr\xe1ch nhi\u1ec7m cao.","\uc7a5\uc810","\u01afu \u0111i\u1ec3m"),B.dx("\ub2e8\uc810\uc744 \uace0\uce58\uae30 \uc704\ud574 \ub178\ub825\ud558\uace0 \uc788\uc5b4\uc694.","T\xf4i \u0111ang c\u1ed1 g\u1eafng kh\u1eafc ph\u1ee5c nh\u01b0\u1ee3c \u0111i\u1ec3m.","\ub2e8\uc810","Nh\u01b0\u1ee3c \u0111i\u1ec3m"),B.dx("\uc9c0\uc6d0 \uc804\uc5d0 \uadfc\ubb34 \uc870\uac74\uc744 \ud655\uc778\ud558\uc138\uc694.","H\xe3y ki\u1ec3m tra \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c tr\u01b0\u1edbc khi \u1ee9ng tuy\u1ec3n.","\uadfc\ubb34 \uc870\uac74","\u0110i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c")],a)
a1=B.a([B.ub("\uc800\ub294 \uc0c8\ub85c\uc6b4 \uc77c\uc744 \ube68\ub9ac \ubc30\uc6b0\ub294 \ud3b8\uc774\uc5d0\uc694.","D\xf9ng \u0111\u1ec3 m\xf4 t\u1ea3 xu h\u01b0\u1edbng ho\u1eb7c \u0111\u1eb7c \u0111i\u1ec3m t\u01b0\u01a1ng \u0111\u1ed1i c\u1ee7a b\u1ea3n th\xe2n.","Kh\xe1, thu\u1ed9c ki\u1ec3u th\u01b0\u1eddng V/A","A/V-(\uc73c)\u3134/\ub294 \ud3b8\uc774\uc5d0\uc694","T\xf4i thu\u1ed9c ki\u1ec3u h\u1ecdc vi\u1ec7c m\u1edbi kh\xe1 nhanh.")],a1)
