m=B.a([B.fT("\uc2dc\uc5d0\uc11c \uc2dc\ubbfc\ub4e4\uc758 \uac78\uc74c \uc218 \uc790\ub8cc\ub97c \ub3c4\uc2dc \uacc4\ud68d\uc5d0 \ud65c\uc6a9\ud558\uaca0\ub2e4\uace0 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4."),B.fw("\uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc774 \uac77\ub294 \uae38\uc744 \ucc3e\uc544 \ubcf4\ud589\ub85c\ub97c \uac1c\uc120\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uaca0\ub124\uc694. \ud558\uc9c0\ub9cc \uac1c\uc778\uc758 \uc774\ub3d9 \uc815\ubcf4\uac00 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub3c4\ub85d \ud574\uc57c \ud569\ub2c8\ub2e4."),B.fT("\ub9de\uc2b5\ub2c8\ub2e4. \uc774\ub984\uacfc \uc704\uce58\ub97c \uc54c \uc218 \uc5c6\uac8c \ucc98\ub9ac\ud55c \ud1b5\uacc4 \uc790\ub8cc\ub9cc \uc0ac\uc6a9\ud55c\ub2e4\uace0 \ud569\ub2c8\ub2e4.")],c0)
A.e.k(c2,B.a([B.e2(2,"Ng\u01b0\u1eddi n\u1eef th\u1ea5y d\u1eef li\u1ec7u h\u1eefu \xedch nh\u01b0ng ph\u1ea3i b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n.","\uc5ec\uc790\uc758 \uc0dd\uac01\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",31,m,A.lbJ,"Ch\u1ecdn suy ngh\u0129 c\u1ee7a ng\u01b0\u1eddi n\u1eef.",A.a0),B.e2(1,"Ng\u01b0\u1eddi nam \u0111\u1ed3ng t\xecnh v\xe0 gi\u1ea3i th\xedch bi\u1ec7n ph\xe1p \u1ea9n danh d\u1eef li\u1ec7u.",b2,32,m,A.lwH,b3,A.a0)],c1))
l=B.a([B.fw("\uc800\ud76c \uc5f0\uad6c\ud300\uc740 \uc0ac\ub77c\uc9c8 \uc704\ud5d8\uc774 \uc788\ub294 \uc9c0\uc5ed \ub9d0\uc744 \uae30\ub85d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub2e8\uc5b4\ub9cc \uc218\uc9d1\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc8fc\ubbfc\ub4e4\uc758 \uc2e4\uc81c \ub300\ud654\ub97c \ub179\uc74c\ud574 \ub9d0\uc758 \uc4f0\uc784\uacfc \uc9c0\uc5ed\uc758 \uc0dd\ud65c \ubb38\ud654\uae4c\uc9c0 \ub0a8\uae30\ub824\uace0 \ud569\ub2c8\ub2e4."),B.fT("\uc80a\uc740 \uc8fc\ubbfc\ub4e4\ub3c4 \uc870\uc0ac\uc5d0 \ucc38\uc5ec\ud569\ub2c8\uae4c?"),B.fw("\ub124. \ub179\uc74c \ubc29\ubc95\uc744 \ubc30\uc6b4 \uccad\ub144\ub4e4\uc774 \uc5b4\ub974\uc2e0\ub4e4\uc744 \ub9cc\ub098 \uc774\uc57c\uae30\ub97c \uae30\ub85d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.")],c0)
A.e.k(c2,B.a([B.e2(1,"Ng\u01b0\u1eddi n\u1eef \u0111ang gi\u1edbi thi\u1ec7u n\u1ed9i dung v\xe0 c\xe1ch ti\u1ebfn h\xe0nh d\u1ef1 \xe1n nghi\xean c\u1ee9u.","\uc5ec\uc790\ub294 \ubb34\uc5c7\uc744 \ud558\uace0 \uc788\ub294\uc9c0 \uace0\ub974\uc2ed\uc2dc\uc624.",33,l,A.jk_,"Ch\u1ecdn vi\u1ec7c ng\u01b0\u1eddi n\u1eef \u0111ang l\xe0m.",A.a0),B.e2(3,"Thanh ni\xean \u0111\u01b0\u1ee3c h\u1ecdc c\xe1ch ghi \xe2m r\u1ed3i ghi l\u1ea1i c\xe2u chuy\u1ec7n c\u1ee7a ng\u01b0\u1eddi cao tu\u1ed5i.",b0,34,l,A.jMr,b1,A.a0)],c1))
k=B.a([B.fT("\uc804\ud1b5 \uc2dc\uc7a5\uc744 \uc0b4\ub9ac\uae30 \uc704\ud574 \uac74\ubb3c\uc744 \uc0c8\ub85c \uafb8\ubbf8\ub294 \uc0ac\uc5c5\uc774 \ub9ce\uc774 \uc9c4\ud589\ub429\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uac89\ubaa8\uc2b5\ub9cc \ubc14\uafb8\uba74 \uc7a0\uc2dc \uad00\uc2ec\uc744 \ub04c \uc218\ub294 \uc788\uc5b4\ub3c4 \ubc29\ubb38\uc774 \uc624\ub798 \uc774\uc5b4\uc9c0\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc0c1\uc778\ub4e4\uc774 \ud568\uaed8 \uc0c1\ud488\uc744 \uac1c\ubc1c\ud558\uace0 \uc628\ub77c\uc778 \uc8fc\ubb38\uc774\ub098 \ubc30\uc1a1 \uac19\uc740 \uc0c8\ub85c\uc6b4 \ud310\ub9e4 \ubc29\uc2dd\ub3c4 \uc775\ud600\uc57c \ud569\ub2c8\ub2e4.")],c0)
A.e.k(c2,B.a([B.e2(4,"Ph\u1ea3i k\u1ebft h\u1ee3p c\u1ea3i thi\u1ec7n c\u01a1 s\u1edf v\u1eadt ch\u1ea5t v\u1edbi \u0111\u1ed5i m\u1edbi c\xe1ch b\xe1n h\xe0ng.","\ub0a8\uc790\uc758 \uc8fc\uc7a5\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",35,k,A.lJw,"Ch\u1ecdn l\u1eadp lu\u1eadn c\u1ee7a ng\u01b0\u1eddi nam.",A.a0),B.e2(2,"Ng\u01b0\u1eddi n\xf3i cho r\u1eb1ng ti\u1ec3u th\u01b0\u01a1ng c\u1ea7n c\xf9ng ph\xe1t tri\u1ec3n s\u1ea3n ph\u1ea9m.",b0,36,k,A.jLd,b1,A.a0)],c1))
j=B.a([B.fw("\uadf8\ub9bc\uc744 \ubcf5\uc6d0\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \uc0c8\uac83\ucc98\ub7fc \ubcf4\uc774\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc791\ud488\uc774 \uc5b4\ub5a4 \uc7ac\ub8cc\uc640 \ubc29\ubc95\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \ucda9\ubd84\ud788 \uc870\uc0ac\ud558\uace0, \uc6d0\ub798 \ubd80\ubd84\uc744 \ucd5c\ub300\ud55c \ubcf4\uc874\ud574\uc57c \ud569\ub2c8\ub2e4. \ub098\uc911\uc5d0 \ub354 \uc88b\uc740 \uae30\uc220\uc774 \ub098\uc624\uba74 \ub2e4\uc2dc \ucc98\ub9ac\ud560 \uc218 \uc788\ub3c4\ub85d \ub418\ub3cc\ub9b4 \uc218 \uc788\ub294 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.")],c0)
A.e.k(c2,B.a([B.e2(1,"Ng\u01b0\u1eddi n\u1eef n\xf3i v\u1ec1 nguy\xean t\u1eafc v\xe0 v\u1eadt li\u1ec7u d\xf9ng \u0111\u1ec3 ph\u1ee5c ch\u1ebf tranh.","\uc5ec\uc790\uc758 \uc9c1\uc5c5\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",37,j,A.lmx,"Ch\u1ecdn ngh\u1ec1 nghi\u1ec7p ph\xf9 h\u1ee3p c\u1ee7a ng\u01b0\u1eddi n\u1eef.",A.a0),B.e2(2,"Ng\u01b0\u1eddi n\u1eef th\u1eadn tr\u1ecdng v\xe0 coi tr\u1ecdng vi\u1ec7c b\u1ea3o t\u1ed3n ph\u1ea7n nguy\xean g\u1ed1c.",b4,38,j,A.jIp,b5,A.a0)],c1))
i=B.a([B.fT("\uc6b0\ub9ac\ub294 \uae30\uc5b5\ub825\uc774 \uc88b\ub2e4\ub294 \ub9d0\uc744 \ubaa8\ub4e0 \uac83\uc744 \uc624\ub798 \uae30\uc5b5\ud558\ub294 \ub2a5\ub825\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub1cc\ub294 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub97c \uc801\uc808\ud788 \uc78a\uc5b4\uc57c \uc0c8\ub85c\uc6b4 \uc815\ubcf4\ub97c \ud6a8\uacfc\uc801\uc73c\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc78a\ub294 \uac83\uc740 \uae30\uc5b5\uc758 \uc2e4\ud328\uac00 \uc544\ub2c8\ub77c \uae30\uc5b5 \uccb4\uacc4\uac00 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\uae30 \uc704\ud55c \uacfc\uc815\uc778 \uc148\uc785\ub2c8\ub2e4.")],c0)
A.e.k(c2,B.a([B.e2(3,"Qu\xean th\xedch h\u1ee3p l\xe0 m\u1ed9t ph\u1ea7n c\u1ea7n thi\u1ebft \u0111\u1ec3 h\u1ec7 th\u1ed1ng tr\xed nh\u1edb ho\u1ea1t \u0111\u1ed9ng.",b6,39,i,A.ltx,b7,A.a0),B.e2(1,"N\xe3o c\u0169ng qu\xean th\xf4ng tin kh\xf4ng c\u1ea7n thi\u1ebft \u0111\u1ec3 t\u1ed5 ch\u1ee9c th\xf4ng tin m\u1edbi.",b0,40,i,A.lZf,b1,A.a0)],c1))
h=B.a([B.fw("\ubc24\uae38\uc758 \uc548\uc804\uc744 \uc704\ud574 \uc870\uba85\uc744 \ubc1d\uac8c \uc124\uce58\ud574\uc57c \ud55c\ub2e4\ub294 \uc758\uacac\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubaa8\ub4e0 \uacf5\uac04\uc744 \uac19\uc740 \ubc1d\uae30\ub85c \ube44\ucd94\uba74 \uc5d0\ub108\uc9c0\uac00 \ub0ad\ube44\ub418\uace0 \uc57c\uc0dd \ub3d9\ubb3c\uc758 \uc0dd\ud65c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \uc6c0\uc9c1\uc784\uacfc \uc2dc\uac04\ub300\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \uacf3\uc758 \ubc1d\uae30\ub97c \uc870\uc808\ud558\ub294 \ubc29\uc2dd\uc774 \ub354 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4.")],c0)
